// 웹 대시보드 JavaScript

// 봇 프로그램이 꺼져 있으면 브라우저는 영어로 'Failed to fetch'만 알려 줌 → 무슨 뜻인지 한국어로 바꿔 모든 오류 문구에 씀
(() => {
    const original = window.fetch.bind(window);
    window.fetch = (...args) => original(...args).catch((e) => {
        if (e instanceof TypeError) {
            const err = new TypeError('봇 프로그램에 연결하지 못했습니다 (프로그램이 꺼졌거나 다시 켜지는 중). 다시 켠 뒤 이 화면을 새로 고쳐 주십시오');
            err.cause = e;
            throw err;
        }
        throw e;
    });
})();

// Socket.IO 연결
const socket = io();

// 지금 보는 모드: 'upbit' · 'bithumb'(실제 계좌) | 'sim'(가상 계좌) — 상단 토글로 바꾸면 화면을 새로 불러옴
const APP_MODE = ['sim', 'bithumb'].includes(document.body.dataset.appMode) ? document.body.dataset.appMode : 'upbit';
const IS_SIM = APP_MODE === 'sim';
const MODE_NAMES = { upbit: '업비트', bithumb: '빗썸', sim: '시뮬레이션' };
const EX_NAME = document.body.dataset.exName || (APP_MODE === 'bithumb' ? '빗썸' : '업비트');     // 이 모드의 거래소 (시뮬레이션은 업비트 시세)
const OTHER_MODES = ['upbit', 'bithumb', 'sim'].filter(m => m !== APP_MODE);
// 다른 모드 둘 중 하나 고르기 (확인 창 두 단추) → 고른 모드 · 그만두면 null
async function pickOtherMode(title, modes, message = '') {
    if (!modes.length) return null;
    if (modes.length === 1) return modes[0];
    const r = await uiConfirm({ title, message, okText: MODE_NAMES[modes[0]], cancelText: MODE_NAMES[modes[1]], cancelAs: modes[1], tone: 'primary', icon: 'bi-arrow-left-right' });
    return r === true ? modes[0] : (typeof r === 'string' ? r : null);
}

// 상태 관리
let currentStatus = {
    status: '중지됨',
    mode: 'simulation',
    is_running: false
};

// 손익 색상: 업비트 방식 (수익 빨강, 손실 파랑, 0은 기본색)
function pnlClass(value) {
    const n = Number(value) || 0;
    return n > 0 ? 'pnl-up' : n < 0 ? 'pnl-down' : '';
}

// 초기화
document.addEventListener('DOMContentLoaded', function() {
    initializeDashboard();
    setupEventListeners();
    startStatusPolling();
});

// 대시보드 초기화
function initializeDashboard() {
    loadConfig();
    updateStatus();

    // URL 해시 처리 (트레이 메뉴에서 특정 섹션으로 이동)
    handleUrlHash();
    restoreViewAfterModeSwitch();

    // URL 해시 변경 감지
    window.addEventListener('hashchange', handleUrlHash);

    // Socket.IO 이벤트
    socket.on('connect', function() {
        console.log('✅ 서버 연결됨');
        updateConnectionStatus(true);
    });

    socket.on('disconnect', function() {
        console.log('❌ 서버 연결 끊김');
        updateConnectionStatus(false);
    });

    socket.on('status_update', function(data) {
        currentStatus.status = data.status;
        updateStatusDisplay();
    });

    socket.on('bot_activity', function(data) {
        addActivityMessage(data.message, data.level, data.icon, data.time);
    });
}

// 활동 로그에 메시지 추가
function addActivityMessage(message, level, icon, time) {
    const log = document.getElementById('bot-activity-log');
    if (!log) return;

    const item = document.createElement('div');
    item.className = `activity-item activity-${level || 'info'}`;
    item.innerHTML = `<i class="bi ${icon || 'bi-info-circle'}"></i>` +
        `<span class="flex-fill">${message}</span>` +
        `<span class="activity-time">${time || ''}</span>`;

    log.appendChild(item);

    // 최대 50개 유지
    while (log.children.length > 50) {
        log.removeChild(log.firstChild);
    }

    // 자동 스크롤
    log.scrollTop = log.scrollHeight;
}

// URL 해시 처리 (특정 탭으로 이동)
function handleUrlHash() {
    const hash = window.location.hash.substring(1); // # 제거

    if (!hash) return;

    // 해시에 해당하는 탭 찾기
    const tabMap = {
        'status': 'bots',      // 봇 상태는 봇 제작/관리 탭
        'bots': 'bots',
        'logs': 'trades',  // 시스템 로그 탭은 삭제됨 → 트레이 '거래 내역 & 로그' 메뉴는 거래 내역으로
        'settings': 'settings',
        'trades': 'trades',
        'positions': 'positions',
        'markets': 'markets',
        'screen': 'markets'   // 조건 검색은 전체코인 분석 안의 탭
    };

    const targetTab = tabMap[hash.toLowerCase()];
    if (hash.toLowerCase() === 'screen') setScreenOn(true);
    if (targetTab) {
        // Bootstrap 탭 활성화
        const tabButton = document.querySelector(`#${targetTab}-tab`);
        if (tabButton) {
            const tab = new bootstrap.Tab(tabButton);
            tab.show();

            // 스크롤 이동 (약간의 딜레이)
            setTimeout(() => {
                const tabPane = document.querySelector(`#${targetTab}`);
                if (tabPane) {
                    tabPane.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }, 100);
        }
    }
}

// 이벤트 리스너 설정
function setupEventListeners() {
    // 봇 제어 버튼
    document.getElementById('btn-start').addEventListener('click', startBot);
    document.getElementById('btn-stop').addEventListener('click', stopBot);
    document.getElementById('btn-restart')?.addEventListener('click', restartBot);
    // 거래소 연동 버튼
    // (버튼이 없더라도 아래 리스너 등록이 중단되지 않도록 ?. 사용)
    document.getElementById('btn-test-connection')?.addEventListener('click', testConnection);
    document.getElementById('btn-reset-exchange')?.addEventListener('click', resetExchangeKeys);
    document.getElementById('btn-check-update')?.addEventListener('click', checkForUpdate);
    setupKeyAutoSave();

    // 업비트 보유 코인: 탭을 열 때 / 새로고침 버튼
    document.getElementById('positions-tab')?.addEventListener('shown.bs.tab', loadHoldings);
    // 주소(#positions)로 이미 열린 상태면 바로 조회
    if (document.getElementById('positions')?.classList.contains('active')) loadHoldings();
    document.getElementById('btn-refresh-holdings')?.addEventListener('click', loadHoldings);
    document.getElementById('btn-dust-open')?.addEventListener('click', openDustSweep);
    refreshUpbitNotices();
    setInterval(refreshUpbitNotices, 5 * 60 * 1000);
    setupSortableTables();
    setupPnlChartTab();
    setupHoldingsSearch();
    setupTooltips();
    setupSellModal();
    setupMarketsTab();
    setupMarketOrders();
    setupBatchOrders();
    setupScreenTab();
    setupTradesTab();

    // 거래 모드 변경
    document.querySelectorAll('input[name="trading-mode"]').forEach(radio => {
        radio.addEventListener('change', function() {
            toggleExchangeSettings(this.value === 'live');
        });
    });

    // 설정 자동 저장: 값 변경 시 디바운스로 자동 저장
    setupAutoSave();


}

// 상태 폴링 (주기적 업데이트)
function startStatusPolling() {
    setInterval(updateStatus, 2000); // 2초마다 업데이트
}

// 상태 업데이트
async function updateStatus() {
    try {
        const response = await fetch('/api/status');
        const data = await response.json();

        currentStatus = data;
        updateConnectionStatus(true);
        updateStatusDisplay();
        renderStallBand(data.stalled);
    } catch (error) {
        console.error('상태 업데이트 오류:', error);
        updateConnectionStatus(false);
    }
}

// 상태 표시 업데이트
// 서버 일부가 멈췄을 때 (gui/watchdog.py): 맨 위 빨간 띠 — 프로그램을 다시 켜야 풀림
function renderStallBand(st) {
    let band = document.getElementById('stall-band');
    if (!st) { band?.remove(); return; }
    if (!band) {
        document.querySelector('.navbar')?.insertAdjacentHTML('afterend', '<div class="stall-band" id="stall-band" role="alert"></div>');
        band = document.getElementById('stall-band');
    }
    if (band) band.innerHTML = `<i class="bi bi-exclamation-octagon-fill"></i><span><b>프로그램 일부가 멈췄습니다.</b> ${escapeHtml((st.problems || [])[0] || '')} — 봇이 사고팔지 못할 수 있으니 프로그램을 다시 켜 주십시오.</span>`;
}

function updateStatusDisplay() {
    const statusEl = document.getElementById('bot-status');
    const statusBadge = document.getElementById('status-badge');
    const modeEl = document.getElementById('bot-mode');

    // (봇 현황의 상태·모드는 고른 봇의 상세가 채움 — renderBotDetail)
    void statusEl; void modeEl;
    // 상단 막대: 모든 봇 요약 (몇 개 실행 중)
    const running = Number(currentStatus.bots_running || 0), total = Number(currentStatus.bots_total || 0);
    if (statusBadge) { statusBadge.textContent = running ? `${running}/${total} 실행 중` : (currentStatus.status?.includes('끊김') ? currentStatus.status : '봇 중지');
        statusBadge.title = running ? `이 모드 봇 ${total}개 중 ${running}개 실행 중` : ''; }
    // 다른 모드에서도 봇이 돌고 있으면 작게 알려 줌 (모드마다 따로 실행)
    const navMode = document.getElementById('nav-mode');
    if (navMode) {
        const other = Number(currentStatus.bots_running_other || 0);
        navMode.textContent = other ? `다른 모드 ${other}` : '';
        navMode.title = other ? `다른 모드(업비트 · 빗썸 · 시뮬레이션)에서 봇 ${other}개가 돌고 있습니다` : '';
        navMode.classList.toggle('d-none', !other);
    }
    if (currentStatus.sim_account) renderSimAccount(currentStatus.sim_account);
    if (statusBadge) statusBadge.classList.toggle('is-running', !!currentStatus.is_running);


    // 버튼 상태 업데이트
    const startBtn = document.getElementById('btn-start');
    const stopBtn = document.getElementById('btn-stop');

    // 모두 시작 / 모두 중지: 실행 중인 봇이 있으면 [모두 중지][재시작], 없으면 [모두 시작]
    const anyRunning = running > 0;
    startBtn.disabled = anyRunning;
    stopBtn.disabled = !anyRunning;
    startBtn.classList.toggle('d-none', anyRunning);
    stopBtn.classList.toggle('d-none', !anyRunning);
    document.getElementById('btn-restart')?.classList.toggle('d-none', !anyRunning);

    // 마스코트 상태 업데이트
    const mascot = document.getElementById('bot-mascot-inner');
    const bubble = document.getElementById('mascot-bubble-text');
    if (mascot) {
        if (currentStatus.is_running) {
            mascot.className = 'bot-mascot analyzing';
            if (bubble) bubble.textContent = '분석 중..';
        } else {
            mascot.className = 'bot-mascot sleeping';
            if (bubble) bubble.textContent = 'Zzz...';
        }
    }
}

// 전략 정보 로드 (활성 전략 섹션에 표시)
// 통계 업데이트: 성과(시뮬레이션), 봇 포지션(여러 코인), 최근 판단, 매매 규칙 요약
function updateStatistics(data) {
    const sim = data.simulation;
    const stats = sim?.statistics || {};
    const profitRateEl = document.getElementById('total-profit');
    if (profitRateEl) {
        const rate = sim ? (sim.total_profit_rate || 0) : null;
        profitRateEl.textContent = rate === null ? '-' : `${rate >= 0 ? '+' : ''}${rate.toFixed(2)}%`;
        profitRateEl.className = `stat-value mb-1 ${rate === null ? '' : pnlClass(rate)}`;
    }
    const winRateEl = document.getElementById('win-rate');
    if (winRateEl) winRateEl.textContent = sim ? `${Number(stats.win_rate || 0).toFixed(1)}%` : '-';
    const tradesEl = document.getElementById('total-trades');
    if (tradesEl) tradesEl.textContent = sim ? (stats.total_trades || 0) : '-';
    const positions = data.positions || [];
    const positionsEl = document.getElementById('active-positions');
    if (positionsEl) positionsEl.textContent = positions.length;
    updatePositionsTable(positions);
    renderDecisions(data.decisions || []);
    if (data.rules) renderBotRulesSummary(data.rules);
    renderSpikeActive(data.spike, data.surge);
}

// 봇 포지션 표 (봇이 조건으로 산 코인)
function updatePositionsTable(positions) {
    const tbody = document.getElementById('positions-tbody');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (!positions.length) {
        tbody.innerHTML = '<tr><td colspan="7" class="text-center py-4 text-muted"><i class="bi bi-wallet fs-3 d-block mb-2 opacity-25"></i>봇이 산 코인이 없습니다</td></tr>';
        return;
    }
    for (const pos of positions) {
        const profit = pos.profit || 0;
        const rate = pos.profit_rate || 0;
        const cls = pnlClass(profit);
        const coin = marketCoins.find(c => `KRW-${c.currency}` === pos.symbol);
        const row = document.createElement('tr');
        row.innerHTML = `
            <td class="text-nowrap"><strong class="pn"></strong> <small class="text-muted">${pos.symbol.replace('KRW-', '')}</small></td>
            <td class="text-end">${formatPrice(pos.entry_price)}</td>
            <td class="text-end">${formatPrice(pos.current_price)}</td>
            <td class="text-end">${Number(pos.quantity).toLocaleString(undefined, { maximumFractionDigits: 4 })}</td>
            <td class="text-end ${cls}">${profit > 0 ? '+' : ''}${formatKrw(profit)}</td>
            <td class="text-end ${cls}">${formatChangeRate(rate)}</td>
            <td class="small text-muted"></td>`;
        row.querySelector('.pn').textContent = coin?.korean_name || pos.symbol;
        row.lastElementChild.textContent = pos.condition || '';
        tbody.appendChild(row);
    }
}

// 최근 판단 (기준 잡기·매수·매도·보류 이유)
function renderDecisions(list) {
    const ul = document.getElementById('bot-decisions');
    if (!ul) return;
    if (!list.length) {
        ul.innerHTML = '<li class="text-muted">봇을 시작하면 무엇을 왜 사고팔았는지 여기에 적힙니다 (실행 중일 때만 보입니다)</li>';
        return;
    }
    ul.innerHTML = '';
    const icon = { buy: 'bi-bag-check-fill text-danger', sell: 'bi-cash-coin text-primary', warning: 'bi-exclamation-triangle text-warning', info: 'bi-dot text-muted' };
    list.slice(0, 15).forEach(d => {
        const li = document.createElement('li');
        li.innerHTML = `<span class="bd-time"></span><i class="bi ${icon[d.kind] || icon.info}"></i><span class="bd-msg"></span>`;
        li.querySelector('.bd-time').textContent = new Date(d.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        li.querySelector('.bd-msg').textContent = d.message;
        ul.appendChild(li);
    });
}

// 코인 로고 (업비트 공개 이미지, 없으면 첫 글자 동그라미로 대체)
function createCoinLogo(currency, dimmed = false) {
    const size = '22px';
    const fallback = () => {
        const span = document.createElement('span');
        span.textContent = currency.charAt(0);
        span.className = 'd-inline-flex align-items-center justify-content-center rounded-circle bg-secondary text-white me-2 align-middle';
        Object.assign(span.style, { width: size, height: size, fontSize: '11px', fontWeight: '600' });
        return span;
    };

    const img = document.createElement('img');
    img.src = `https://static.upbit.com/logos/${encodeURIComponent(currency)}.png`;
    img.alt = '';
    img.loading = 'lazy';
    img.className = 'rounded-circle me-2 align-middle';
    Object.assign(img.style, { width: size, height: size, objectFit: 'contain' });
    if (dimmed) img.style.filter = 'grayscale(1)';
    img.onerror = () => img.replaceWith(fallback());
    return img;
}

// 업비트 보유 코인 표 상태
let holdingsAssets = [];
// 저점수익률 탭용 기간 최저가(오늘 제외): { 'KRW-ETH': { d1, w1, m1, y1 }, ... } (새로고침해도 유지)
let periodLows = {};
let periodLowsLoading = false;
let periodLowsDay = Math.floor(Date.now() / 86400000);   // UTC 날짜 = 업비트 일봉(한국 09시 시작)
setInterval(() => {
    const d = Math.floor(Date.now() / 86400000);
    if (d === periodLowsDay) return;
    periodLowsDay = d;
    periodLows = {};                                       // 어제 받은 일봉: 새 종가가 생겼으니 버리고 다시 받음
    if (typeof condDataVersion !== 'undefined') condDataVersion++;
    try { loadMarketPeriodLowsNow(); } catch (e) { /* 다음 화면 갱신 때 받음 */ }
}, 60000);
let condDataVersion = 0;     // 조건 계산에 쓰는 자료(기간 시세 · 1시간봉 · 실시간 체결)가 바뀔 때마다 +1 → 조건 계산 캐시를 새로
// 최근 24시간 1시간봉 { 'KRW-ETH': { t: [시작 unix초], c: [종가], l: [저가] } } (서버 10분 캐시)
let hourlyData = {};
let hourlyLoadedAt = 0;

// 최근 24시간 안의 1시간봉만 (거래가 드문 코인은 빈 시간이 있어 봉 개수로 자르면 안 됨)
// 마지막(진행 중인) 봉 종가는 지금 가격으로 바꿔 씀
function recentHourly(a) {
    const h = hourlyData[`KRW-${a.currency}`];
    if (!h || !h.t.length) return null;
    const since = Date.now() / 1000 - 24 * 3600;
    const idx = h.t.map((t, i) => (t + 3600 > since ? i : -1)).filter(i => i >= 0);
    if (!idx.length) return null;
    const closes = idx.map(i => h.c[i]);
    const lows = idx.map(i => h.l[i]);
    const times = idx.map(i => h.t[i]);
    closes[closes.length - 1] = a.current_price;
    return { times, closes, lows };
}

// 1시간봉 받기 (50개씩, 받는 대로 onChunk 호출). 10분 지나면 새로
async function loadHourlyFor(markets, onChunk) {
    const stale = Date.now() - hourlyLoadedAt > 10 * 60 * 1000;
    const todo = stale ? markets : markets.filter(m => !hourlyData[m]);
    for (let i = 0; i < todo.length; i += 50) {
        const chunk = todo.slice(i, i + 50);
        const data = await (await fetch(`/api/holdings/hourly?markets=${encodeURIComponent(chunk.join(','))}`)).json();
        if (data.success) { Object.assign(hourlyData, data.hourly); condDataVersion++; }
        if (onChunk) onChunk();
    }
    if (todo.length) hourlyLoadedAt = Date.now();
}

// 정렬 가능한 표: 표마다 정렬 상태와 다시 그리는 함수
const sortableTables = {
    holdings: { table: 'holdings-table', tbody: 'holdings-tbody', sort: { key: 'current_value', dir: 'desc' }, render: () => renderHoldingsRows(), hasData: () => holdingsAssets.length > 0 },
    botHold: { table: 'bd-hold-table', tbody: 'bd-hold-tbody', sort: { key: 'current_value', dir: 'desc' }, render: () => renderBotHoldRows(), hasData: () => bdHoldAssets.length > 0 },
    // 전체코인 분석은 거래대금 큰 순부터
    markets: { table: 'markets-table', tbody: 'markets-tbody', sort: { key: 'trade_value_24h', dir: 'desc' }, render: () => renderMarketsRows(), hasData: () => marketCoins.length > 0 },
};

// 목록 검색어 (보유 현황·저점수익률 탭 공통)
let holdingsQuery = '';

// 한글 초성 (예: '이더리움' → 'ㅇㄷㄹㅇ')
const CHOSUNG = 'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ';
function toChosung(text) {
    return [...text].map(ch => {
        const code = ch.charCodeAt(0) - 0xAC00;
        return code >= 0 && code < 11172 ? CHOSUNG[Math.floor(code / 588)] : ch;
    }).join('');
}

// 코인 한글명·심볼(대소문자 무시)·초성으로 검색
// 보유 비중 도넛의 '기타'처럼 여러 코인만 골라 보기 { label, set } (검색어를 치거나 × 를 누르면 풀림)
let holdingsOnly = null;
function matchesHoldingsQuery(a) {
    if (holdingsOnly) return holdingsOnly.set.has(a.currency);   // 그래프에서 고른 코인은 조건 · 검색과 상관없이 보여 줌
    if (!matchesQuery(a, holdingsQuery)) return false;
    const hits = screenHitSet();   // 조건 검색이 켜져 있으면 조건에 맞는 코인만
    return !hits || hits.has(a.currency);
}

// 코인 한글명·심볼(대소문자 무시)·초성 검색 (보유코인·전체코인 공통)
function matchesQuery(a, query) {
    const q = String(query || '').trim().toLowerCase().replace(/\s+/g, '');
    if (!q) return true;
    const name = String(a.korean_name || '').replace(/\s+/g, '');
    return String(a.currency).toLowerCase().includes(q)
        || name.toLowerCase().includes(q)
        || toChosung(name).includes(q);
}

function setupHoldingsSearch() {
    const input = document.getElementById('holdings-search');
    if (!input) return;
    input.addEventListener('input', () => {
        holdingsQuery = input.value;
        if (holdingsQuery.trim() && holdingsOnly) setHoldingsOnly(null, false);   // 검색어를 치면 여러 코인 골라 보기는 풀림
        if (holdingsAssets.length === 0) return;
        renderHoldingsRows();
    });
}

// 아래 보유 표에서 몇 개 코인만 보기 (하나면 검색 칸에 심볼, 여러 개면 '기타 N개만 보는 중' 표시)
function focusHoldingsCoins(currencies, label) {
    const input = document.getElementById('holdings-search');
    if (!input || !currencies.length) return;
    input.value = '';
    holdingsQuery = '';
    setHoldingsOnly({ label: label || currencies[0], set: new Set(currencies) });
    document.getElementById('holdings-table')?.scrollIntoView({ block: 'start', behavior: 'smooth' });
}
function setHoldingsOnly(v, render = true) {
    holdingsOnly = v;
    let chip = document.getElementById('holdings-only');
    const input = document.getElementById('holdings-search');
    if (!chip && input) {
        chip = document.createElement('span');
        chip.id = 'holdings-only';
        chip.className = 'hold-only-chip d-none';
        input.before(chip);
    }
    if (chip) {
        chip.classList.toggle('d-none', !v);
        chip.innerHTML = v ? `<i class="bi bi-funnel-fill"></i>${escapeHtml(v.label)}${v.set.size > 1 ? ` ${v.set.size}개` : ''}만 보는 중 <small>(조건과 상관없이)</small><button type="button" data-hold-only-clear title="모두 보기" aria-label="모두 보기"><i class="bi bi-x-lg"></i></button>` : '';
    }
    if (render && holdingsAssets.length) renderHoldingsRows();
}
document.addEventListener('click', (e) => { if (e.target.closest('[data-hold-only-clear]')) setHoldingsOnly(null); });

function appendNoMatchRow(tbody, colspan) {
    const row = document.createElement('tr');
    row.innerHTML = `<td colspan="${colspan}" class="text-center py-4 text-muted"></td>`;
    row.firstElementChild.textContent = screenOn && !holdingsQuery.trim()
        ? '보유 코인 중 지금 이 조건에 맞는 코인이 없습니다.' : `'${holdingsQuery.trim()}' 검색 결과가 없습니다`;
    tbody.appendChild(row);
}

// 저점수익률 기간: [칸 key, periodLows 속 key]
const LOW_PERIODS = [['low_d1_rate', 'd1'], ['low_w1_rate', 'w1'], ['low_m1_rate', 'm1'], ['low_h6_rate', 'h6'], ['low_y1_rate', 'y1']];

// 음수는 정식 마이너스 기호(−, 숫자와 같은 폭)로: 숫자 폭을 맞춘 표에서 '-'가 숫자와 떨어져 보이지 않게
const withMinus = (text) => String(text).replace(/^-/, '−');
const formatKrw = (v) => withMinus(`${Math.round(Number(v) || 0).toLocaleString()}원`);
// 등락률: 업비트처럼 부호 + 소수 둘째 자리 (예: +24.38%)
const formatChangeRate = (v) => {
    if (v === null || v === undefined) return '-';
    const n = Number(v);
    return withMinus(`${n > 0 ? '+' : ''}${n.toFixed(2)}%`);
};

// 거래대금: 업비트처럼 백만 원 단위 (예: 104,177백만)
const formatTradeValue = (v) => {
    if (v === null || v === undefined) return '-';
    const m = Number(v) / 1e6;
    return m < 1 ? '1백만 미만' : `${Math.round(m).toLocaleString()}백만`;
};

// 가격: 업비트처럼 큰 값은 원 단위, 작은 값만 소수점 표시 (3,832,761원 / 96.52원 / 0.0123원)
const formatPrice = (v) => {
    const n = Number(v) || 0;
    const digits = n >= 1000 ? 0 : n >= 1 ? 2 : 8;
    return `${n.toLocaleString(undefined, { maximumFractionDigits: digits })}원`;
};

// 업비트 경고·알림 배지: 상폐(거래지원 종료 예정) · 유(투자유의) · 주(투자주의) · 입출(입출금 중단) · 공지
// 누르면 새 창: 공지가 있으면 업비트 공지, 없으면(주, 공지 없는 유) 업비트 거래 화면(투자주의·유의 사유 표시)
function createMarketBadges(a) {
    const badges = [];
    const notices = a.notices || [];
    const first = (type) => notices.find(n => n.type === type);
    const exchangeUrl = APP_MODE === 'bithumb' ? `https://www.bithumb.com/react/trade/order/${a.currency}-KRW` : `https://upbit.com/exchange?code=CRIX.UPBIT.KRW-${a.currency}`;   // 거래소 거래 화면
    const make = (text, cls, title, url) => {
        const b = document.createElement(url ? 'a' : 'span');
        b.className = `mk-badge ${cls}`;
        b.textContent = text;
        b.title = url ? `${title}\n(누르면 ${url === exchangeUrl ? `${EX_NAME} 거래 화면` : '업비트 공지'} 보기)` : title;
        if (url) {
            b.href = url;
            b.target = '_blank';
            b.rel = 'noopener';
        }
        badges.push(b);
    };

    const delist = first('delisting');
    if (delist) make('상폐', 'mk-delist', `거래지원 종료 예정${delist.ends_at ? `\n종료 일시: ${delist.ends_at}` : ''}\n${delist.title}`, delist.url);
    if (a.warning) {
        const n = first('warning');
        make('유', 'mk-warning', `투자유의 종목\n업비트가 거래 유의 종목으로 지정했습니다${n ? `\n${n.title}` : ''}`, n ? n.url : exchangeUrl);
    }
    if (a.cautions && a.cautions.length) make('주', 'mk-caution', `투자주의 종목\n사유: ${a.cautions.join(', ')}`, exchangeUrl);
    const suspend = first('suspend');
    if (suspend) make('입출', 'mk-suspend', `입출금 일시 중단\n${suspend.title}`, suspend.url);
    const infos = notices.filter(n => n.type === 'info');
    if (infos.length) make('공지', 'mk-info', `최근 공지 ${infos.length}건\n` + infos.map(n => `${n.date} ${n.title}`).join('\n'), infos[0].url);
    return badges;
}

// 알림 열 정렬용 위험도 점수: 상폐 > 유 > 입출 > 주 > 공지 (여러 개면 합산)
function alertLevel(a) {
    const notices = a.notices || [];
    const has = (type) => notices.some(n => n.type === type);
    return (has('delisting') ? 16 : 0) + (a.warning ? 8 : 0) + (has('suspend') ? 4 : 0)
        + (a.cautions && a.cautions.length ? 2 : 0) + (has('info') ? 1 : 0);
}

// 읽은 공지 기억 (이 PC 브라우저): 공지 주소(없으면 제목)로 구분, 지금 떠 있는 공지만 남김
const NOTICE_READ_KEY = 'strabot_notice_read';
function noticeKey(n, text) { return String(n?.url || n?.title || text || ''); }
function noticeReadSet() {
    try { return new Set(JSON.parse(localStorage.getItem(NOTICE_READ_KEY) || '[]')); } catch (e) { return new Set(); }
}
function saveNoticeRead(set) {
    try { localStorage.setItem(NOTICE_READ_KEY, JSON.stringify([...set])); } catch (e) { /* 무시 */ }
}
let lastNoticeHoldings = null;

// 제목 줄의 '업비트 공지' 버튼 목록: 내 코인의 상폐 예정·입출금 중단(위) + 업비트 전체 입출금 점검(아래)
// 숫자 배지 = 안 읽은 공지 수 (누르면 읽음), 안 읽은 것이 있으면 빨강
function renderHoldingsAlerts(holdings) {
    lastNoticeHoldings = holdings;
    const menu = document.getElementById('upbit-notice-menu');
    const list = document.getElementById('upbit-notice-list');
    const count = document.getElementById('upbit-notice-count');
    if (!menu || !list || !count) return;

    // 공지는 모드와 상관없이 업비트 전체 코인 기준 (지금 모드 계좌에 있는 코인만 보면 시뮬레이션 · 업비트에서 달라짐)
    // — 지금 모드에서 가진 코인 것은 '내 보유 코인'으로 위에, 나머지는 '다른 코인'으로
    const mine = [], others = [], general = [];
    const held = new Set((holdings.assets || []).filter(a => !a.is_delisted).map(a => a.currency));
    const coins = new Map();
    for (const a of holdings.assets || []) if (!a.is_delisted) coins.set(a.currency, a);
    for (const c of marketCoins) if (!coins.has(c.currency)) coins.set(c.currency, c);
    for (const a of coins.values()) {
        const into = held.has(a.currency) ? mine : others;
        for (const n of a.notices || []) {
            if (n.type === 'delisting') into.push(['상폐', 'mk-delist', `${a.korean_name}(${a.currency}) 거래지원 종료 예정 ${n.ends_at || ''}`, n]);
            if (n.type === 'suspend') into.push(['입출', 'mk-suspend', n.title, n]);
        }
    }
    const seenNotice = new Set();                                 // 같은 공지(여러 코인 묶음 입출금 중단 등)는 한 번만
    const dedupe = (arr) => arr.filter(([, , text, n]) => { const k = noticeKey(n, text); if (seenNotice.has(k)) return false; seenNotice.add(k); return true; });
    mine.splice(0, mine.length, ...dedupe(mine));
    others.splice(0, others.length, ...dedupe(others));
    for (const n of holdings.global_notices || []) general.push(['점검', 'mk-info', n.title, n]);

    const total = mine.length + others.length + general.length;
    // 읽음 기록은 지금 떠 있는 공지만 남겨 계속 커지지 않게
    const stored = noticeReadSet();
    const keys = new Set([...mine, ...others, ...general].map(([, , text, n]) => noticeKey(n, text)));
    const read = new Set([...stored].filter(k => keys.has(k)));
    if (read.size !== stored.size && total) saveNoticeRead(read);
    const unread = (items) => items.filter(([, , text, n]) => !read.has(noticeKey(n, text)));
    const unreadAll = unread(mine).length + unread(others).length + unread(general).length;
    count.textContent = unreadAll;
    count.className = `nav-icon-count${unreadAll ? ' is-hot' : ' d-none'}`;   // 안 읽은 공지가 있으면 빨강 (알림 종과 같게)

    list.innerHTML = '';
    const section = (title, items) => {
        if (!items.length) return;
        const h = document.createElement('div');
        h.className = 'notice-menu-header';
        h.textContent = title;
        list.appendChild(h);
        for (const [label, cls, text, n] of items) {
            // 제목 끝의 일정 '(09/30 20:00 ~)'은 따로 떼어 눈에 띄게
            const m = text.match(/\s*\(([^()]*(?:\d{1,2}\/\d{1,2}|\d{1,2}:\d{2})[^()]*)\)\s*$/);
            const title = (m ? text.slice(0, m.index) : text).replace(/\s*안내$/, '');
            const item = document.createElement('a');
            item.className = 'dropdown-item notice-menu-item';
            item.href = n.url;
            item.target = '_blank';
            item.rel = 'noopener';
            const key = noticeKey(n, text);
            item.dataset.noticeKey = key;
            item.classList.toggle('is-read', read.has(key));
            item.innerHTML = `<div class="notice-menu-top"><span class="notice-kind ${cls}"></span><span class="notice-menu-date"></span>
                <i class="bi bi-box-arrow-up-right notice-menu-go"></i></div>
                <div class="notice-menu-text"></div>${m ? '<div class="notice-menu-when"><i class="bi bi-clock"></i><span></span></div>' : ''}`;
            item.querySelector('.notice-kind').textContent = label;
            item.querySelector('.notice-menu-date').textContent = n.date ? `${n.date} 공지` : '';
            item.querySelector('.notice-menu-text').textContent = title;
            if (m) item.querySelector('.notice-menu-when span').textContent = m[1].trim();
            list.appendChild(item);
        }
    };
    section('내 보유 코인', mine);
    section('다른 코인', others);
    section('업비트 전체', general);
    if (!total) list.insertAdjacentHTML('beforeend', '<div class="text-muted small px-3 py-3">지금 확인할 공지가 없습니다</div>');
    const foot = document.createElement('div');
    foot.className = 'notice-menu-foot';
    foot.innerHTML = `<span>업비트 공지사항에서 가져온 내용입니다 · 누르면 공지로 이동</span>${unreadAll ? '<button type="button" class="notice-read-all" data-notice-read-all>모두 읽음</button>' : ''}`;
    list.appendChild(foot);
}

// 공지를 누르면 읽음 · '모두 읽음'은 지금 공지 전부 읽음 → 숫자 다시 셈
document.addEventListener('click', (e) => {
    const item = e.target.closest('#upbit-notice-list [data-notice-key]');
    const all = e.target.closest('[data-notice-read-all]');
    if (!item && !all) return;
    const read = noticeReadSet();
    if (item) read.add(item.dataset.noticeKey);
    else {
        e.preventDefault();
        e.stopPropagation();   // 메뉴는 열어 둔 채로
        document.querySelectorAll('#upbit-notice-list [data-notice-key]').forEach(el => read.add(el.dataset.noticeKey));
    }
    saveNoticeRead(read);
    if (lastNoticeHoldings) renderHoldingsAlerts(lastNoticeHoldings);
});

// 보유 코인 수익 · 손실 비율 막대 (전체코인 분석 '오늘 상승 · 보합 · 하락' 막대와 같은 모양) — 빨강 수익 · 회색 0 · 파랑 손실 · 진회색 상폐
function pnlCountBar(up, flat, down, gone = 0) {
    const n = up + flat + down + gone;
    if (!n) return '';
    const pct = (v) => (v / n * 100).toFixed(2);
    return `<span class="breadth-bar mk-bar pnl-count-bar" role="img" aria-label="수익 ${up}개, 손실 ${down}개${gone ? `, 상폐 ${gone}개` : ''}">`
        + (up ? `<span class="breadth-up" style="width:${pct(up)}%" title="수익 ${up}개 (${pct(up).replace(/\.\d+/, '')}%)"></span>` : '')
        + (flat ? `<span class="breadth-flat" style="width:${pct(flat)}%" title="손익 0 · ${flat}개"></span>` : '')
        + (down ? `<span class="breadth-down" style="width:${pct(down)}%" title="손실 ${down}개 (${pct(down).replace(/\.\d+/, '')}%)"></span>` : '')
        + (gone ? `<span class="breadth-gone" style="width:${pct(gone)}%" title="상장폐지 ${gone}개"></span>` : '')
        + '</span>';
}

function showTableMessage(tbodyId, colspan, msg) {
    const tbody = document.getElementById(tbodyId);
    tbody.innerHTML = `<tr><td colspan="${colspan}" class="text-center py-4 text-muted"></td></tr>`;
    tbody.querySelector('td').textContent = msg;
}

function showHoldingsMessage(msg) {
    showTableMessage('holdings-tbody', 17, msg);
}

// 상단 바 '공지'만 새로 (보유코인 화면을 열지 않아도)
async function refreshUpbitNotices() {
    try {
        const data = await fetchHoldingsShared();
        if (data.success) renderHoldingsAlerts(data.holdings);
        else renderHoldingsAlerts({ assets: [], global_notices: [] });
    } catch (e) { /* 다음에 다시 */ }
}

// /api/holdings 를 여러 곳(보유 현황 · 알림 · 전체코인의 '보유' 칸)이 처음에 함께 불러 2번 받던 것을 한 번으로
let holdingsShared = { at: 0, promise: null };
// 내 계좌의 매수평균가 (가진 코인이면, 보유코인 분석과 같은 값) — 아직 안 불러온 화면에서도 한 번 불러와 씀
async function myAvgBuy(sym) {
    const cur = String(sym || '').replace('KRW-', '');
    const find = (list) => (list || []).find(a => a.currency === cur && !a.is_delisted && Number(a.balance) > 0);
    let a = find(holdingsAssets);
    if (!a) {
        try { const d = await fetchHoldingsShared(30000); if (d.success) a = find(d.holdings?.assets); } catch (e) { /* 없음 */ }
    }
    return a ? Number(a.avg_buy_price) || 0 : 0;
}
// 캔들 위 매수평균가 녹색 가로선 (오른쪽 눈금에 이름표)
function addAvgBuyLine(series, price, title) {
    if (!(price > 0) || !series) return null;
    try { return series.createPriceLine({ price, color: '#16a34a', lineWidth: 1, lineStyle: 0, axisLabelVisible: true, title: `${title || '매수평균'} ${formatPrice(price)}` }); } catch (e) { return null; }
}

function fetchHoldingsShared(maxAgeMs = 4000) {
    if (holdingsShared.promise && Date.now() - holdingsShared.at < maxAgeMs) return holdingsShared.promise;
    holdingsShared = { at: Date.now(), promise: fetch('/api/holdings').then(r => r.json()) };
    holdingsShared.promise.catch(() => { holdingsShared = { at: 0, promise: null }; });
    return holdingsShared.promise;
}

// 주문 뒤 보유 목록 새로: 함께 쓰는 조회(4초 기억)를 버리고 새로 받음. 체결이 잔고에 늦게 반영되면 1.5초마다 몇 번 더
// changed(새 보유 목록) → 주문한 코인의 수량이 바뀌었으면 true (없으면 한 번만)
async function reloadHoldingsAfterOrder(changed) {
    for (let i = 0; i < 4; i++) {
        await new Promise(r => setTimeout(r, 1500));
        holdingsShared = { at: 0, promise: null };
        try {
            const d = await fetchHoldingsShared();
            if (!changed || !d.success || changed(d.holdings.assets)) break;
        } catch (e) { break; }
    }
    if (document.getElementById('holdings-tbody')) loadHoldings();       // 방금 받은 것을 그대로 씀
}
// 주문한 코인의 수량이 주문 전과 달라졌는지 (다 팔았으면 목록에서 빠짐)
const qtyChanged = (cur, before) => (assets) => Math.abs((assets.find(x => x.currency === cur)?.balance || 0) - before) > before * 1e-6 + 1e-12;

// 업비트 실제 보유 코인 조회
async function loadHoldings() {
    if (!document.getElementById('holdings-tbody')) return;

    showHoldingsMessage('불러오는 중...');

    try {
        const data = await fetchHoldingsShared();

        if (!data.success) {
            showHoldingsMessage(data.error === 'NO_API_KEY'
                ? `${EX_NAME} API 키가 없습니다. 설정 탭에서 API 키를 저장해 주십시오.`
                : `보유 코인 조회 실패: ${data.error || '알 수 없는 오류'}`);
            return;
        }

        const h = data.holdings;
        renderHoldingsStrip(h);
        renderHoldingsAlerts(h);
        holdingsAssets = h.assets;
        holdingsAssets.forEach(a => { a.alert_level = alertLevel(a); });
        if (holdingsAssets.length === 0) {
            showHoldingsMessage(IS_SIM ? '가상 계좌에 보유 중인 코인이 없습니다' : `${EX_NAME}에 보유 중인 코인이 없습니다`);
            return;
        }
        updatePnlCoinOptions();
        renderHoldingsRows();
        loadPeriodLows();
    } catch (error) {
        showHoldingsMessage('보유 코인 조회 오류: ' + error.message);
    }
}

// 보유코인 분석: 보유 비중 도넛 (업비트 투자내역과 같은 모양) — 평가금액 기준 상위 9개 + 기타, 주문가능 원화는 KRW 조각
const SHARE_COLORS = ['#93ad55', '#1b7db3', '#6d5c9e', '#b469a6', '#f07c2f', '#f5a742', '#e3b54f', '#cfa968', '#5d86a8'];
const SHARE_ETC = '#b9bdc4', SHARE_KRW = '#d8dde4';
const hdShareState = { chart: null, key: '' };
const sharePctPlugin = {                                          // 조각 안에 % 숫자 (좁은 조각은 생략 · 목록에는 다 나옴)
    id: 'sharePct',
    afterDatasetsDraw(chart) {
        const ds = chart.data.datasets[0], total = ds.data.reduce((a, b) => a + b, 0);
        if (!total) return;
        const ctx = chart.ctx;
        ctx.save();
        ctx.font = `500 ${bigPx(chart, 12)}px Pretendard, sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = '#1f2937';
        chart.getDatasetMeta(0).data.forEach((arc, i) => {
            const pct = ds.data[i] / total * 100;
            if (pct < 3.5) return;
            const { x, y } = arc.tooltipPosition();
            ctx.fillText(pct.toFixed(1).replace(/\.0$/, ''), x, y);
        });
        ctx.restore();
    },
};
function renderHoldingsShare(h) {
    const box = document.getElementById('hd-share'), canvas = document.getElementById('hd-share-chart');
    if (!box || !canvas || typeof Chart === 'undefined') return;
    const rows = (h.assets || []).filter(a => !a.is_delisted && Number(a.current_value) > 0)
        .map(a => ({ sym: a.currency, v: Number(a.current_value) })).sort((a, b) => b.v - a.v);
    const slices = rows.slice(0, 9).map((r, i) => ({ ...r, color: SHARE_COLORS[i] }));
    if (rows.length > 9) slices.push({ sym: '기타', v: rows.slice(9).reduce((s, r) => s + r.v, 0), color: SHARE_ETC });
    const krw = Number(h.krw_balance) || 0, coinSum = slices.reduce((s, r) => s + r.v, 0);
    if (krw > 0 && krw / (coinSum + krw) >= 0.0005) slices.push({ sym: 'KRW', v: krw, color: SHARE_KRW });   // 0.1% 아래로 반올림되면 빼기
    const etc = rows.slice(9).map(r => r.sym);
    drawShareDonut(hdShareState, { box, canvas, legend: document.getElementById('hd-share-legend'),
        // 조각 · 목록을 누르면 아래 보유 표에서 그 코인만 ('기타'는 묶인 코인들)
        onPick: (r) => { if (r.sym === '기타') focusHoldingsCoins(etc, '기타'); else if (r.sym !== 'KRW') focusHoldingsCoins([r.sym]); } }, slices,
        (r) => (r.sym === '기타' ? `나머지 ${etc.length}개 코인: ${etc.slice(0, 12).join(', ')}${etc.length > 12 ? ' …' : ''} (누르면 아래 표에서)` : r.sym === 'KRW' ? '주문가능 원화' : `${coinKoreanName(r.sym)} (누르면 아래 표에서)`));
}

// 비중 도넛 (보유 비중 · 거래대금 비중 공통): 왼쪽 목록(심볼 · %) + 도넛(조각 안 %) — 비중이 0.1%p 안쪽으로만 바뀌면 다시 그리지 않음
function drawShareDonut(st, els, slices, titleOf) {
    const total = slices.reduce((s, r) => s + r.v, 0);
    els.box.classList.toggle('d-none', !total);
    if (!total) return;
    const pct = (v) => `${(v / total * 100).toFixed(1)}%`;
    els.legend.innerHTML = slices.map((r, i) =>
        `<div title="${escapeHtml(titleOf(r))} · ${formatKrw(r.v)}"${els.onPick && r.sym !== 'KRW' ? ` class="is-pick" data-share-i="${i}" role="button" tabindex="0"` : ''}><span style="background:${r.color}"></span><b>${escapeHtml(r.sym)}</b><em>${pct(r.v)}</em></div>`).join('');
    st.slices = slices;
    st.onPick = els.onPick || null;
    if (els.onPick && !els.legend.dataset.pickBound) {
        els.legend.dataset.pickBound = '1';
        els.legend.addEventListener('click', (e) => { const d = e.target.closest('[data-share-i]'); if (d && st.onPick) st.onPick(st.slices[Number(d.dataset.shareI)]); });
        els.legend.addEventListener('keydown', (e) => { const d = e.target.closest('[data-share-i]'); if (d && st.onPick && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); st.onPick(st.slices[Number(d.dataset.shareI)]); } });
    }
    const key = slices.map(r => `${r.sym}:${(r.v / total * 1000).toFixed(0)}`).join(',');
    if (key === st.key && st.chart) return;
    st.key = key;
    const data = { labels: slices.map(r => r.sym), datasets: [{ data: slices.map(r => r.v), backgroundColor: slices.map(r => r.color), borderWidth: 1, borderColor: '#ffffff' }] };
    if (st.chart) { st.chart.data = data; st.chart.update('none'); return; }
    st.chart = new Chart(els.canvas, {
        type: 'doughnut', data, plugins: [sharePctPlugin],
        options: { responsive: true, maintainAspectRatio: false, cutout: '42%', animation: false,
                   onClick: (_e, act) => { if (act.length && st.onPick && st.slices?.[act[0].index]) st.onPick(st.slices[act[0].index]); },
                   onHover: (e, act) => { e.native.target.style.cursor = act.length && st.onPick && st.slices?.[act[0].index]?.sym !== 'KRW' ? 'pointer' : 'default'; },
                   plugins: { legend: { display: false },
                              tooltip: { callbacks: { label: (c) => ` ${c.label} ${formatKrw(c.parsed)} (${pct(c.parsed)})` } } } },
    });
}

// ── 코인별 손익 그래프 (수익률 변화 그래프와 보유 비중 사이) ──
const UP_C = '#c84a31', DOWN_C = '#1261c4';
let hdInsCoins = null, hdInsKey = '', hdInsLast = null;
// 코인별 손익: 'krw' 금액 · 'pct' 수익률 (고른 것은 이 PC에 기억)
let hdInsMode = 'krw';
try { if (localStorage.getItem('hdInsMode') === 'pct') hdInsMode = 'pct'; } catch (e) { /* 저장소 없음 */ }
document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-ins-mode]');
    if (!b || b.dataset.insMode === hdInsMode) return;
    hdInsMode = b.dataset.insMode;
    try { localStorage.setItem('hdInsMode', hdInsMode); } catch (err) { /* 저장소 없음 */ }
    document.querySelectorAll('[data-ins-mode]').forEach(x => x.classList.toggle('active', x.dataset.insMode === hdInsMode));
    hdInsKey = '';
    if (hdInsCoins) { hdInsCoins.destroy(); hdInsCoins = null; }       // 눈금(원 ↔ %)이 바뀌어 새로 그림
    if (hdInsLast) renderHoldingsInsights(hdInsLast);
});
const krwTick = (v) => { const a = Math.abs(v); return `${v < 0 ? '−' : ''}${a >= 1e8 ? (a / 1e8).toFixed(1) + '억' : a >= 1e4 ? Math.round(a / 1e4).toLocaleString() + '만' : Math.round(a).toLocaleString()}`; };
const insOpts = (extra = {}) => ({ responsive: true, maintainAspectRatio: false, animation: false, ...extra });

function renderHoldingsInsights(h) {
    const box = document.getElementById('hd-coins');
    if (!box || typeof Chart === 'undefined') return;
    const assets = (h.assets || []).filter(a => Number(a.buy_amount) > 0);
    box.classList.toggle('d-none', !assets.length);
    if (!assets.length) return;
    hdInsLast = h;
    const pct = hdInsMode === 'pct';
    document.querySelectorAll('[data-ins-mode]').forEach(x => x.classList.toggle('active', x.dataset.insMode === hdInsMode));
    const val = (a) => (pct ? Number(a.pnl_rate) || 0 : Number(a.pnl) || 0);
    const key = hdInsMode + assets.map(a => `${a.currency}:${Math.round(a.pnl / 500)}`).join(',');
    if (key === hdInsKey) return;                                 // 손익이 거의 그대로면 다시 그리지 않음
    hdInsKey = key;

    // ① 코인별 손익: 손해 큰 10개 (맨 위가 가장 큰 손해) + 수익 큰 5개 — 상장폐지는 평가 0원이라 산 돈 전부가 손해
    //    % 로 보면 수익률 기준 (작게 산 코인도 크게 잃었으면 위로)
    const live = assets.filter(a => !a.is_delisted);                    // 상장폐지 코인은 이 그래프에서 뺌 (다 잃은 막대가 다른 코인을 가림)
    const delisted = assets.length - live.length;
    const byPnl = [...live].sort((a, b) => val(a) - val(b));
    const losers = byPnl.filter(a => val(a) < 0).slice(0, 10);
    const gainers = byPnl.filter(a => val(a) > 0).slice(-5);
    const items = [...losers, ...gainers];
    document.getElementById('hd-ins-coins-sub').textContent = `${pct ? '수익률' : '금액'} 기준 손해 큰 ${losers.length}개 · 수익 큰 ${gainers.length}개 (전체 ${live.length}개 중${delisted ? ` · 상장폐지 ${delisted}개 뺌` : ''})`;
    const cData = { labels: items.map(a => a.currency),
                    datasets: [{ data: items.map(a => (pct ? Math.round(val(a) * 100) / 100 : Math.round(val(a)))), backgroundColor: items.map(a => val(a) >= 0 ? UP_C : DOWN_C), borderRadius: 3, barPercentage: 0.75 }] };
    if (hdInsCoins) { hdInsCoins.data = cData; hdInsCoins.$items = items; hdInsCoins.update('none'); }
    else {
        hdInsCoins = new Chart(document.getElementById('hd-ins-coins'), { type: 'bar', data: cData, options: insOpts({
            indexAxis: 'y',
            scales: { x: { ticks: { callback: pct ? pctTick : krwTick, font: { size: 12 } }, grid: { color: '#f1f5f9' } }, y: { ticks: { autoSkip: false, font: { size: 12, weight: 600 } }, grid: { display: false } } },
            plugins: { legend: { display: false }, tooltip: { callbacks: {
                title: (c) => { const a = hdInsCoins.$items[c[0].dataIndex]; return `${a.korean_name || a.currency} ${a.currency}`; },
                label: (c) => { const a = hdInsCoins.$items[c.dataIndex]; return hdInsMode === 'pct'
                    ? ` ${formatChangeRate(a.pnl_rate)} (${a.pnl > 0 ? '+' : ''}${formatKrw(a.pnl)}) · 투자 ${formatKrw(a.buy_amount)}`
                    : ` ${a.pnl > 0 ? '+' : ''}${formatKrw(a.pnl)} (${formatChangeRate(a.pnl_rate)}) · 투자 ${formatKrw(a.buy_amount)}`; } } } },
            onClick: (_e, els) => {                               // 막대 → 아래 표에서 그 코인만
                const a = els.length ? hdInsCoins.$items[els[0].index] : null;
                if (a) focusHoldingsCoins([a.currency]);
            },
            onHover: (e, els) => { e.native.target.style.cursor = els.length ? 'pointer' : 'default'; } }) });
        hdInsCoins.$items = items;
    }

}

// ── 전체코인 분석 '시장 현황': ① 시장 분위기 추이(1분 기록) ② 등락률 분포 ③ 상승 · 하락 상위 ④ 거래대금 비중 ──
const mkOv = { dist: null, movers: null, breadth: null, key: '', share: { chart: null, key: '' }, interval: '15m', timer: null, folded: false, metric: 'change_rate' };
// 상승 · 하락 상위 그래프의 기준: 오늘 등락률 또는 표의 저점 칸(저점 대비 %) — 고른 기준은 이 PC에 기억
const MOVER_METRICS = { change_rate: ['오늘 등락률', '오늘'], low_d1_rate: ['전일저점', '전일저점 대비'], low_w1_rate: ['주간저점', '주간저점 대비'],
                        low_m1_rate: ['월간저점', '월간저점 대비'], low_h6_rate: ['6개월저점', '6개월저점 대비'], low_y1_rate: ['연간저점', '연간저점 대비'] };
try { const m = localStorage.getItem('mkMoversMetric'); if (MOVER_METRICS[m]) mkOv.metric = m; } catch (e) { /* 저장소 없음 */ }
mkOv.distMetric = 'change_rate';
try { const m = localStorage.getItem('mkDistMetric'); if (MOVER_METRICS[m]) mkOv.distMetric = m; } catch (e) { /* 저장소 없음 */ }
// 저점 기준 분포: 저점 대비 % (늘 0 이상) — 초록(저점 근처) → 빨강(많이 오름)
const LOW_DIST_BUCKETS = [['0~2', 2], ['2~5', 5], ['5~10', 10], ['10~20', 20], ['20~30', 30], ['30~50', 50], ['50~100', 100], ['≥100', Infinity]];
const LOW_DIST_COLORS = ['#0f766e', '#2a9d8f', '#8fcfc4', '#cbd5e1', '#eeb3a6', '#dd7a63', '#c84a31', '#9f2f1a'];
const DIST_BUCKETS = [['≤−10', -Infinity, -10], ['−10~−5', -10, -5], ['−5~−2', -5, -2], ['−2~0', -2, 0], ['0', 0, 0],
                      ['0~2', 0, 2], ['2~5', 2, 5], ['5~10', 5, 10], ['≥10', 10, Infinity]];   // 축 이름은 짧게 (단위 %는 축 제목에)
const DIST_COLORS = ['#0b3d91', '#1261c4', '#4a8ad8', '#9bbde8', '#cbd5e1', '#eeb3a6', '#dd7a63', '#c84a31', '#9f2f1a'];
const pctTick = (v) => `${v > 0 ? '+' : ''}${Number(v).toFixed(Math.abs(v) < 10 ? 1 : 0)}%`;

function renderMarketOverview() {
    if (typeof Chart === 'undefined' || !document.getElementById('mk-overview')) return;
    const coins = marketCoins.filter(c => c.change_rate !== null && c.change_rate !== undefined);
    if (!coins.length) return;
    const lows = [...new Set([mkOv.metric, mkOv.distMetric])].filter(m => m !== 'change_rate');
    lows.forEach(m => ensureLowRates(coins, m));
    const key = coins.map(c => `${c.currency}:${Math.round(c.change_rate * 10)}:${Math.round((c.trade_value_24h || 0) / 1e8)}${lows.map(m => `:${Math.round((c[m] ?? -1) * 10)}`).join('')}`).join(',');
    if (key === mkOv.key) return;                                 // 거의 그대로면 다시 그리지 않음 (30초마다 옴)
    mkOv.key = key;

    renderMarketDist(coins);
    renderMarketMovers(coins);

    // ④ 거래대금 비중 (24시간, 상위 9개 + 기타)
    const rows = coins.filter(c => Number(c.trade_value_24h) > 0).map(c => ({ sym: c.currency, v: Number(c.trade_value_24h), name: c.korean_name }))
        .sort((a, b) => b.v - a.v);
    const slices = rows.slice(0, 9).map((r, i) => ({ ...r, color: SHARE_COLORS[i] }));
    if (rows.length > 9) slices.push({ sym: '기타', v: rows.slice(9).reduce((s, r) => s + r.v, 0), color: SHARE_ETC });
    const total = rows.reduce((s, r) => s + r.v, 0);
    document.getElementById('mk-share-sub').textContent = `24시간 ${formatKrwShort(total)}원`;
    drawShareDonut(mkOv.share, { box: document.getElementById('mk-share'), canvas: document.getElementById('mk-share-chart'), legend: document.getElementById('mk-share-legend') },
        slices, (r) => (r.sym === '기타' ? `나머지 ${rows.length - 9}개 코인` : r.name || r.sym));
}

// 가로 막대 끝에 값(%) 적기 — 한쪽이 아주 커서 짧은 막대가 안 보일 때도 숫자는 보이게
const barValuePlugin = {
    id: 'barValue',
    afterDatasetsDraw(chart) {
        const ctx = chart.ctx, ds = chart.data.datasets[0], area = chart.chartArea;
        ctx.save();
        ctx.font = `700 ${bigPx(chart, 12)}px Pretendard, sans-serif`;
        ctx.textBaseline = 'middle';
        chart.getDatasetMeta(0).data.forEach((bar, i) => {
            const v = ds.data[i];
            const text = pctTick(v);
            const w = ctx.measureText(text).width, right = v >= 0;
            let x = right ? bar.x + 4 : bar.x - 4 - w;
            if (x + w > area.right) x = bar.x - 4 - w;                 // 오른쪽 끝을 넘으면 막대 안쪽으로
            if (x < area.left) x = bar.x + 4;
            ctx.fillStyle = (x + w <= bar.x && right) || (x >= bar.x && !right) ? '#ffffff' : '#475569';
            ctx.fillText(text, x, bar.y);
        });
        ctx.restore();
    },
};

// ② 분포 — 오늘 등락률: −10% 이하 ~ +10% 이상 / 저점 기준: 저점 대비 0~2% ~ 100% 이상 (스테이블코인은 조건 목록의 '스테이블코인 포함'을 따름)
function renderMarketDist(coins = marketCoins) {
    const canvas = document.getElementById('mk-dist-chart');
    if (!canvas || typeof Chart === 'undefined') return;
    const m = mkOv.distMetric, today = m === 'change_rate';
    ensureLowRates(coins, m);
    const has = today ? coins : coins.filter(c => c[m] !== null && c[m] !== undefined && isFinite(c[m]) && (screenIncludeStable || !isStableCoin(c)));
    const buckets = today ? DIST_BUCKETS.map(b => b[0]) : LOW_DIST_BUCKETS.map(b => b[0]);
    const groups = buckets.map(() => []);
    for (const c of has) {
        const r = Number(c[m]);
        const i = today ? (r === 0 ? 4 : r <= -10 ? 0 : r <= -5 ? 1 : r <= -2 ? 2 : r < 0 ? 3 : r <= 2 ? 5 : r <= 5 ? 6 : r <= 10 ? 7 : 8)
                        : LOW_DIST_BUCKETS.findIndex(([, hi]) => r < hi);
        groups[i >= 0 ? i : groups.length - 1].push(c);
    }
    const sub = document.getElementById('mk-dist-sub');
    if (sub) {
        if (today) {
            const up = coins.filter(c => c.change_rate > 0).length, down = coins.filter(c => c.change_rate < 0).length;
            sub.textContent = `상승 ${up} · 하락 ${down} · 보합 ${coins.length - up - down} · 단위 %`;
        } else {
            const vals = has.map(c => Number(c[m])).sort((x, y) => x - y), med = vals.length ? vals[Math.floor(vals.length / 2)] : null;
            sub.textContent = has.length ? `${MOVER_METRICS[m][1]} % · 가운데값 ${pctTick(med)} · ${has.length}/${coins.length}개` : `${MOVER_METRICS[m][0]} 시세를 불러오는 중입니다`;
        }
    }
    const dData = { labels: buckets, datasets: [{ data: groups.map(g => g.length), backgroundColor: today ? DIST_COLORS : LOW_DIST_COLORS, borderRadius: 3 }] };
    mkOv.groups = groups;
    if (mkOv.dist) { mkOv.dist.data = dData; mkOv.dist.update('none'); return; }
    mkOv.dist = new Chart(canvas, { type: 'bar', data: dData, options: insOpts({
        scales: { x: { ticks: { font: { size: 11 }, maxRotation: 0, autoSkip: false }, grid: { display: false } }, y: { beginAtZero: true, ticks: { precision: 0, font: { size: 12 } }, grid: { color: '#f1f5f9' } } },
        plugins: { legend: { display: false }, tooltip: { callbacks: {
            title: (c) => {
                const t = c[0].label;
                if (mkOv.distMetric !== 'change_rate') return `${MOVER_METRICS[mkOv.distMetric][1]} ${t.startsWith('≥') ? '+100% 이상' : `+${t}%`}`;
                return t === '0' ? '보합 (0%)' : t.startsWith('≤') ? '−10% 이하' : t.startsWith('≥') ? '+10% 이상' : `${t}%`;
            },
            label: (c) => ` ${c.parsed.y}개`,
            afterLabel: (c) => { const g = (mkOv.groups || [])[c.dataIndex] || []; return g.slice(0, 12).map(x => x.currency).join(', ') + (g.length > 12 ? ` 외 ${g.length - 12}개` : ''); } } } } }) });
}

// ③ 상위 · 하위 7개씩 — 오늘 등락률: 많이 오른 7 + 많이 내린 7 / 저점 기준: 저점 대비 가장 많이 오른 7 + 저점에 가장 가까운 7
// 저점 대비 값 채우기: 시세를 새로 받으면 코인 목록이 통째로 바뀌어 이 값이 비므로, 그래프를 그릴 때마다 (받아 둔 기간 시세로) 다시 셈
function ensureLowRates(coins, m) {
    if (m === 'change_rate') return;
    for (const c of coins) if (c[m] === undefined && periodLows[`KRW-${c.currency}`]) computeLowRates(c);
}

function renderMarketMovers(coins = marketCoins) {
    const canvas = document.getElementById('mk-movers-chart');
    if (!canvas || typeof Chart === 'undefined') return;
    const m = mkOv.metric, today = m === 'change_rate', [label, short] = MOVER_METRICS[m];
    ensureLowRates(coins, m);
    // 스테이블코인은 값이 거의 안 움직여 '저점에 가까운' 쪽을 차지하므로, 조건 목록의 '스테이블코인 포함'을 따름
    const has = coins.filter(c => c[m] !== null && c[m] !== undefined && isFinite(c[m]) && (screenIncludeStable || !isStableCoin(c)));
    const sorted = [...has].sort((a, b) => b[m] - a[m]);
    const items = today
        ? [...sorted.filter(c => c[m] > 0).slice(0, 7), ...sorted.filter(c => c[m] < 0).slice(-7)]
        : [...sorted.slice(0, 7), ...sorted.slice(Math.max(7, sorted.length - 7))];
    const sub = document.getElementById('mk-movers-sub'), empty = document.getElementById('mk-movers-empty');
    if (sub) sub.textContent = today ? '많이 오른 7 · 많이 내린 7' : `저점 대비 많이 오른 7 · 저점에 가까운 7 (${has.length}/${coins.length}개)`;
    empty?.classList.toggle('d-none', items.length > 0);
    if (empty && !items.length) empty.textContent = today ? '시세를 받는 중입니다' : `${label} 시세를 불러오는 중입니다`;
    const top = today ? null : new Set(sorted.slice(0, 7));
    const colors = items.map(c => (today ? (c[m] >= 0 ? UP_C : DOWN_C) : (top.has(c) ? UP_C : '#0f766e')));
    const mData = { labels: items.map(c => c.currency), datasets: [{ data: items.map(c => +Number(c[m]).toFixed(2)), backgroundColor: colors, borderRadius: 3, barPercentage: 0.75 }] };
    mkOv.items = items;
    // 가로축은 정해진 단위(2 · 5 · 10 · 20 · 50 …%)로만 바뀌게 — 값이 조금 바뀔 때마다 축 · 막대 자리가 출렁이지 않게
    const nice = (v) => { if (v <= 0) return 0; for (const st of [2, 5, 10, 15, 20, 30, 50, 100, 200, 300, 500, 1000, 2000, 5000]) if (v <= st * 0.92) return st; return Math.ceil(v / 1000) * 1000; };
    const vals = items.map(c => Number(c[m]));
    const xr = { min: -nice(-Math.min(0, ...vals)), max: nice(Math.max(0, ...vals)) };
    if (mkOv.movers) { Object.assign(mkOv.movers.options.scales.x, xr); mkOv.movers.data = mData; mkOv.movers.update('none'); return; }
    mkOv.movers = new Chart(canvas, { type: 'bar', data: mData, plugins: [barValuePlugin], options: insOpts({
        indexAxis: 'y',
        layout: { padding: { right: 42, left: 4 } },
        scales: { x: { ...xr, ticks: { callback: pctTick, font: { size: 12 }, maxTicksLimit: 7 }, grid: { color: '#f1f5f9' } },
                  y: { ticks: { autoSkip: false, font: { size: 12, weight: 600 } }, grid: { display: false },
                       afterFit: (sc) => { sc.width = 74; } } },              // 코인 이름 칸 폭 고정 (긴 이름이 와도 막대 자리가 그대로)
        plugins: { legend: { display: false }, tooltip: { callbacks: {
            title: (c) => { const x = mkOv.items[c[0].dataIndex]; return `${x.korean_name || x.currency} ${x.currency}`; },
            label: (c) => {
                const x = mkOv.items[c.dataIndex], k = mkOv.metric, [, s2] = MOVER_METRICS[k];
                const low = k === 'change_rate' ? '' : ` (저점 ${formatPrice(x[k.replace('_rate', '')])})`;
                return ` ${s2} ${formatChangeRate(x[k])}${low} · 현재가 ${formatPrice(x.current_price)}`;
            } } } },
        onClick: (_e, els) => {                                   // 막대 → 아래 표에서 그 코인만
            const x = els.length ? mkOv.items[els[0].index] : null, input = document.getElementById('markets-search');
            if (!x || !input) return;
            input.value = x.currency;
            input.dispatchEvent(new Event('input'));
            document.getElementById('markets-table')?.scrollIntoView({ block: 'start', behavior: 'smooth' });
        },
        onHover: (e, els) => { e.native.target.style.cursor = els.length ? 'pointer' : 'default'; } }) });
}
document.addEventListener('change', (e) => {
    if (e.target.id === 'mk-dist-metric') {
        mkOv.distMetric = e.target.value;
        try { localStorage.setItem('mkDistMetric', mkOv.distMetric); } catch (err) { /* 저장 불가: 무시 */ }
        renderMarketDist();
        return;
    }
    if (e.target.id !== 'mk-movers-metric') return;
    mkOv.metric = e.target.value;
    try { localStorage.setItem('mkMoversMetric', mkOv.metric); } catch (err) { /* 저장 불가: 무시 */ }
    renderMarketMovers();
});

// ① 시장 분위기 추이: 상승 코인 비율(왼쪽 축) · 평균 등락률(오른쪽 축) — 전체코인 분석이 보이고 펼쳐져 있을 때만 1분마다
async function loadMarketBreadth() {
    let d;
    try { d = await (await fetch(`/api/market-breadth?interval=${mkOv.interval}`)).json(); } catch (e) { return; }
    if (!d?.success || typeof Chart === 'undefined') return;
    const pts = d.points || [];
    const info = document.getElementById('mk-breadth-info'), empty = document.getElementById('mk-breadth-empty');
    const first = d.stats?.first_ts;
    if (info) info.textContent = first ? `1분마다 기록 중 · 첫 기록 ${formatPnlLabel(first, '1m')} · 매일 9시(전일 종가)에 등락률이 0 근처로 다시 시작` : '1분마다 기록을 시작했습니다 — 1~2분 뒤부터 선이 그려집니다';
    empty?.classList.toggle('d-none', pts.length > 1);
    const labels = pts.map(p => formatPnlLabel(p.ts, mkOv.interval));
    const data = { labels, datasets: [
        { label: '상승 코인 비율', data: pts.map(p => +p.up_ratio.toFixed(1)), borderColor: UP_C, backgroundColor: 'rgba(200,74,49,0.08)', fill: true, yAxisID: 'y', pointRadius: 0, borderWidth: 1.6, tension: 0.15 },
        { label: '평균 등락률', data: pts.map(p => +p.avg_rate.toFixed(2)), borderColor: '#0f766e', yAxisID: 'y1', pointRadius: 0, borderWidth: 1.6, tension: 0.15 }] };
    // 평균 등락률 축은 최소 2%p 폭 (기록이 짧을 때 0.01% 움직임이 크게 출렁여 보이지 않게)
    const avgs = pts.map(p => p.avg_rate), lo = Math.min(...avgs, 0), hi = Math.max(...avgs, 0), mid = (lo + hi) / 2, half = Math.max(1, (hi - lo) / 2 + 0.3);
    const y1 = { min: Math.floor((mid - half) * 2) / 2, max: Math.ceil((mid + half) * 2) / 2 };
    if (mkOv.breadth) { Object.assign(mkOv.breadth.options.scales.y1, y1); mkOv.breadth.data = data; mkOv.breadth.update('none'); return; }
    mkOv.breadth = new Chart(document.getElementById('mk-breadth-chart'), { type: 'line', data, options: insOpts({
        interaction: { mode: 'index', intersect: false },
        scales: { x: { ticks: { maxRotation: 0, autoSkipPadding: 14, font: { size: 12 } }, grid: { display: false } },
                  y: { min: 0, max: 100, position: 'left', ticks: { callback: (v) => `${v}%`, font: { size: 12 } }, grid: { color: '#f1f5f9' } },
                  y1: { ...y1, position: 'right', ticks: { callback: pctTick, font: { size: 12 } }, grid: { display: false } } },
        plugins: { legend: { position: 'top', align: 'end', labels: { boxWidth: 12, font: { size: 12 } } },   // 범례는 위로 (아래엔 눈금만 → 옆 그래프와 X축 선 높이가 같게)
                   tooltip: { callbacks: { label: (c) => ` ${c.dataset.label} ${c.datasetIndex === 0 ? `${c.parsed.y}%` : pctTick(c.parsed.y)}` } } } }) });
}
function refreshMarketBreadth() {
    clearInterval(mkOv.timer);
    if (mkOv.folded || !document.getElementById('markets')?.classList.contains('active')) return;
    loadMarketBreadth();
    mkOv.timer = setInterval(loadMarketBreadth, 60000);
}
(function setupMarketOverview() {
    const sec = document.getElementById('mk-overview'), head = document.getElementById('mk-overview-head');
    if (!sec) return;
    try { mkOv.folded = localStorage.getItem('marketOverviewFolded') === '1'; } catch (e) { /* 저장소 없음 */ }
    const metricSel = document.getElementById('mk-movers-metric');
    if (metricSel) metricSel.value = mkOv.metric;               // 전에 고른 기준
    const distSel = document.getElementById('mk-dist-metric');
    if (distSel) distSel.value = mkOv.distMetric;
    const setFolded = (f) => {
        mkOv.folded = f;
        sec.classList.toggle('is-folded', f);
        head?.setAttribute('aria-expanded', String(!f));
        const fold = document.getElementById('mk-overview-fold');
        if (fold) fold.innerHTML = `<span>${f ? '펼치기' : '접기'}</span><i class="bi bi-chevron-${f ? 'down' : 'up'}"></i>`;
        try { localStorage.setItem('marketOverviewFolded', f ? '1' : '0'); } catch (e) { /* 저장 불가: 무시 */ }
        refreshMarketBreadth();
    };
    head?.addEventListener('click', () => setFolded(!mkOv.folded));
    head?.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setFolded(!mkOv.folded); } });
    document.getElementById('mk-breadth-units')?.addEventListener('click', (e) => {
        const b = e.target.closest('[data-mk-interval]');
        if (!b) return;
        mkOv.interval = b.dataset.mkInterval;
        document.querySelectorAll('[data-mk-interval]').forEach(x => x.classList.toggle('active', x === b));
        loadMarketBreadth();
    });
    document.getElementById('markets-tab')?.addEventListener('shown.bs.tab', refreshMarketBreadth);
    document.getElementById('markets-tab')?.addEventListener('hidden.bs.tab', () => clearInterval(mkOv.timer));
    setFolded(mkOv.folded);
})();

// 보유코인 분석 맨 위: 판 손익 · 누적 수수료 (업비트 '투자손익'처럼, 30초에 한 번) — 총 매수에 안 들어가고 원화에서만 빠진 돈
let realizedAt = 0;
async function loadHoldingsRealized() {
    if (Date.now() - realizedAt < 30000) return;
    realizedAt = Date.now();
    const stat = document.getElementById('holdings-realized-stat'), el = document.getElementById('holdings-realized');
    if (!stat || !el) return;
    try {
        const d = await (await fetch('/api/holdings/realized')).json();
        if (!d.success || !(d.buys + d.sells)) { stat.classList.add('d-none'); return; }
        const r = d.realized;
        el.innerHTML = `<span class="${pnlClass(r)}">${r > 0 ? '+' : ''}${formatKrw(r)}</span><small> · 수수료 ${formatKrw(d.fees)}</small>`;
        const from = d.since ? stampText(d.since * 1000).slice(0, 10) : '';
        stat.title = `${d.mode === 'sim' ? `가상 계좌를 연 때(${from})부터` : `받아 둔 ${EX_NAME} 거래(${from}부터) 기준`} · 매수 ${d.buys.toLocaleString()}번 · 매도 ${d.sells.toLocaleString()}번\n`
            + `판 손익 = 판 금액 − 매수평균가 × 판 수량 (수수료 빼기 전, 업비트와 같은 매수평균가)\n`
            + `수수료 = 사고팔 때 낸 수수료 합계\n`
            + `둘 다 총 매수에는 들어가지 않고 주문가능 원화에서만 빠집니다`
            + (d.mode === 'sim' ? ` (처음 자본 − 주문가능 − 총 매수 = 수수료 − 판 손익)` : '')
            + (d.partial ? '\n※ 기록 앞쪽에서 산 코인을 판 것은 아는 수량만 셌습니다' : '');
        stat.classList.remove('d-none');
    } catch (e) { /* 다음에 다시 */ }
}

// 보유코인 분석 맨 위 요약 줄 (봇 화면 요약 줄과 같은 계산 · 같은 실시간 시세)
function renderHoldingsStrip(h) {
        // '상장폐지 보기'를 켜면 상장폐지 코인도 합계에 넣음: 산 돈은 그대로, 지금 값은 0원 (팔 수 없으니 손실, 2026-10-15)
        const goneBuy = holdingsShowDelisted() ? (h.assets || []).filter(a => a.is_delisted).reduce((s, a) => s + (Number(a.buy_amount) || 0), 0) : 0;
        h = { ...h, total_buy_amount: (Number(h.total_buy_amount) || 0) + goneBuy };
        const totalPnl = h.total_value - h.total_buy_amount;
        document.getElementById('holdings-krw').textContent = formatKrw(h.krw_balance);
        loadHoldingsRealized();
        renderHoldingsShare(h);
        renderHoldingsInsights(h);
        // 보유 코인 수 (상장폐지는 따로) · 수익 중 / 손실 중
        const live = (h.assets || []).filter(a => !a.is_delisted);
        const gone = (h.assets || []).length - live.length;
        document.getElementById('holdings-count').textContent = `${(live.length + gone).toLocaleString()}개`;   // 상장폐지 코인도 가진 코인이라 함께 셈
        const up = live.filter(a => a.pnl > 0).length, down = live.filter(a => a.pnl < 0).length;
        document.getElementById('holdings-count-sub').innerHTML = `<span class="pnl-up">수익 ${up}</span> · <span class="pnl-down">손실 ${down}</span>`
            + (gone ? ` · 상폐 ${gone}` : '') + pnlCountBar(up, live.length - up - down, down, gone);
        document.getElementById('holdings-buy').textContent = formatKrw(h.total_buy_amount);
        document.getElementById('holdings-value').textContent = formatKrw(h.total_value);
        const pnlEl = document.getElementById('holdings-pnl');
        pnlEl.textContent = `${totalPnl >= 0 ? '+' : ''}${formatKrw(totalPnl)}`;
        pnlEl.className = `hd-pnl ${pnlClass(totalPnl)}`;
        // 총 평가수익률 = 평가손익 / 총 매수 ('상장폐지 보기'를 끄면 업비트처럼 상장폐지 제외)
        const totalRate = h.total_buy_amount > 0 ? totalPnl / h.total_buy_amount * 100 : 0;
        const rateEl = document.getElementById('holdings-pnl-rate');
        rateEl.textContent = formatChangeRate(totalRate);
        rateEl.className = `hd-rate ${pnlClass(totalRate)}`;
}
// 보유코인 분석 탭이 보이는 동안 요약 줄만 5초마다 새로 (표는 그대로 — 새로고침 단추로)
setInterval(async () => {
    if (document.hidden || !document.getElementById('positions')?.classList.contains('active')) return;
    try {
        const data = await fetchHoldingsShared(3000);
        if (data.success) renderHoldingsStrip(data.holdings);
    } catch (e) { /* 다음에 다시 */ }
}, 5000);

// 기간 최저가를 따로 받아와 저점수익률 탭을 채움 (처음엔 수십 초 걸려서 표를 먼저 띄움)
async function loadPeriodLows() {
    const markets = holdingsAssets.filter(a => !a.is_delisted).map(a => `KRW-${a.currency}`);
    if (markets.length === 0 || periodLowsLoading) return;
    const status = document.getElementById('lows-loading');
    const missing = markets.some(m => !periodLows[m]);
    periodLowsLoading = true;
    if (status && missing) status.textContent = '⏳ 기간별 시세 불러오는 중… (하루 첫 조회는 30초 정도 걸립니다)';
    renderLowsRows();
    try {
        const response = await fetch(`/api/holdings/period-lows?markets=${encodeURIComponent(markets.join(','))}`);
        const data = await response.json();
        if (data.success) { Object.assign(periodLows, data.lows); condDataVersion++; }
        await loadHourlyFor(markets, renderLowsRows);
        if (status) status.textContent = '';
    } catch (error) {
        console.error('기간 최저가 조회 오류:', error);
        if (status) status.textContent = '⚠ 기간별 시세를 불러오지 못했습니다. 새로고침을 눌러 다시 시도하십시오.';
    } finally {
        periodLowsLoading = false;
        renderLowsRows();
    }
}

// 열 이름 클릭 정렬: 같은 열을 다시 누르면 오름/내림 전환
function setupSortableTables() {
    Object.values(sortableTables).forEach(t => {
        document.querySelectorAll(`#${t.table} th[data-sort]`).forEach(th => {
            th.style.cursor = 'pointer';
            th.style.userSelect = 'none';
            if (!th.title) th.title = '클릭하여 정렬';
            th.addEventListener('click', () => {
                const key = th.dataset.sort;
                if (t.sort.key === key) {
                    t.sort.dir = t.sort.dir === 'asc' ? 'desc' : 'asc';
                } else {
                    // 이름은 가나다순부터, 숫자는 큰 값부터
                    t.sort.key = key;
                    t.sort.dir = key === 'korean_name' ? 'asc' : 'desc';
                }
                if (t.hasData()) t.render();
                updateSortIcons(t);
            });
        });
        updateSortIcons(t);
    });
}

function updateSortIcons(t) {
    document.querySelectorAll(`#${t.table} th[data-sort]`).forEach(th => {
        let icon = th.querySelector('.sort-icon');
        if (!icon) {
            icon = document.createElement('i');
            th.appendChild(icon);
        }
        const active = th.dataset.sort === t.sort.key;
        th.classList.toggle('fw-bold', active);
        th.classList.toggle('text-dark', active);
        icon.className = 'sort-icon ms-1 bi ' + (active
            ? (t.sort.dir === 'asc' ? 'bi-caret-up-fill' : 'bi-caret-down-fill')
            : 'bi-chevron-expand opacity-25');
    });
}

// 정렬 기준 열의 칸을 굵게 표시 (구분 줄처럼 칸이 합쳐진 행은 제외)
// 큰 표 그리기 (291줄을 한 번에 그리면 0.1~0.3초 화면이 멈춤)
// - 보이지 않는 곳에서 잘게 나눠(쉬는 틈에) 새 줄을 다 만든 뒤 한 번에 바꿔 끼움 → 그동안 클릭 · 스크롤은 바로 반응
// - 줄이 40 → 140 → 290개로 늘며 열 너비가 넓어졌다 좁아졌다 하던 것 없앰 (처음 열 때도 같게)
// beginRows(tbody) → 줄을 넣을 곳, appendRowsChunked(그곳, …, done), done 안에서 finishRows(tbody, 그곳)
const rowChunkTokens = new WeakMap(), rowChunkFlush = new WeakMap();
function beginRows(tbody) {
    const token = (rowChunkTokens.get(tbody) || 0) + 1;          // 새로 그리기 시작 → 이전에 나눠 그리던 것은 멈춤
    rowChunkTokens.set(tbody, token);
    rowChunkFlush.delete(tbody);
    const stage = document.createElement('tbody');
    stage._owner = tbody;
    stage._token = token;
    return stage;
}
function finishRows(tbody, out) {
    if (out === tbody || out._token !== rowChunkTokens.get(tbody)) return;
    tbody.replaceChildren(...out.childNodes);
}
function appendRowsChunked(target, items, makeRow, done) {
    const owner = target._owner || target;
    if (!rowChunkTokens.has(owner)) rowChunkTokens.set(owner, 1);
    const token = target._owner ? target._token : rowChunkTokens.get(owner);
    const alive = () => rowChunkTokens.get(owner) === token;
    const FIRST = 40, CHUNK = 60, n = items.length;
    const put = (from, to) => {
        const f = document.createDocumentFragment();
        for (let k = from; k < to; k++) f.appendChild(makeRow(items[k]));
        target.appendChild(f);
    };
    let i = Math.min(FIRST, n), finished = false;
    put(0, i);
    const finish = () => { if (finished) return; finished = true; rowChunkFlush.delete(owner); done?.(); };
    const more = () => {
        if (!alive() || finished) return;
        if (i < n) { put(i, Math.min(i + CHUNK, n)); i += CHUNK; setTimeout(more, 0); return; }
        finish();
    };
    // 나눠 그리는 중에 '더 보기' 등이 오면 남은 줄을 한 번에 마저 그림
    rowChunkFlush.set(owner, () => { if (!alive()) return; if (i < n) { put(i, n); i = n; } finish(); });
    if (i < n) setTimeout(more, 0); else finish();
}
function flushRows(tbody) { rowChunkFlush.get(tbody)?.(); }

function highlightSortedColumn(t) {
    const headers = [...document.querySelectorAll(`#${t.table} thead th`)];
    const index = headers.findIndex(th => th.dataset.sort === t.sort.key);
    document.querySelectorAll(`#${t.tbody} tr`).forEach(row => {
        if (row.cells.length !== headers.length) return;
        [...row.cells].forEach((td, i) => td.classList.toggle('fw-bold', i === index));
    });
}

// 값이 없는 칸(null)은 방향과 상관없이 항상 맨 아래
function sortAssets(list, sort) {
    const { key, dir } = sort;
    const sign = dir === 'asc' ? 1 : -1;
    return [...list].sort((a, b) => {
        if (key === 'korean_name') return sign * String(a[key]).localeCompare(String(b[key]), 'ko');
        const x = a[key], y = b[key];
        if (x === null || x === undefined) return (y === null || y === undefined) ? 0 : 1;
        if (y === null || y === undefined) return -1;
        return sign * ((Number(x) || 0) - (Number(y) || 0));
    });
}

// 0 중심 막대: 가운데 선 기준 수익은 오른쪽 빨강, 손실은 왼쪽 파랑
// fraction: -1 ~ +1 (눈금 끝 = ±1), 범위를 넘으면 끝에 ▸ 표시
function createCenterBar(fraction, title) {
    const f = Number(fraction) || 0;
    const half = Math.min(Math.abs(f), 1) * 50;

    const wrap = document.createElement('div');
    wrap.className = f > 0 ? 'rbar frame-up' : 'rbar';  // 수익이면 틀도 빨강
    wrap.setAttribute('aria-hidden', 'true');
    if (title) wrap.title = title;
    if (f !== 0) {
        const bar = document.createElement('div');
        bar.className = f > 0 ? 'rbar-fill hbar-up' : 'rbar-fill hbar-down';
        bar.style.width = `${half}%`;
        // 0 선에 붙여서 바깥쪽으로 늘어나게 (최소 3px이어도 선을 넘지 않음)
        if (f > 0) bar.style.left = '50%';
        else bar.style.right = '50%';
        wrap.appendChild(bar);
    }
    if (f > 1) {
        const more = document.createElement('span');
        more.className = 'rbar-more pnl-up';
        more.textContent = '▸';
        wrap.appendChild(more);
    }
    return wrap;
}

// 수익률 막대: 눈금 -100% ~ +100% 고정
function createReturnBar(rate) {
    return createCenterBar((Number(rate) || 0) / 100);
}

// 보유코인 분석: 상장폐지 코인 보기 · 안 보기 (브라우저에 기억, 처음은 보기)
function holdingsShowDelisted() {
    try { return localStorage.getItem('holdingsShowDelisted') !== '0'; } catch (e) { return true; }
}
document.addEventListener('change', (e) => {
    if (e.target.id !== 'holdings-show-delisted') return;
    try { localStorage.setItem('holdingsShowDelisted', e.target.checked ? '1' : '0'); } catch (err) { /* 무시 */ }
    renderHoldingsRows();
    fetchHoldingsShared(3000).then(d => { if (d?.success) renderHoldingsStrip(d.holdings); }).catch(() => {});   // 위 합계도 같이
});

function renderHoldingsRows() {
    const t = sortableTables.holdings;
    const realTbody = document.getElementById(t.tbody);
    const tbody = beginRows(realTbody);
    holdingsAssets.filter(a => !a.is_delisted).forEach(computeLowRates);
    const columns = metricColumnsFor('holdings', 'holdings-spark-header');
    const colCount = 17 + columns.length;
    // 조건이 켜져 있으면 조건 계산값(최고가까지 등)을 붙여서 정렬·표시
    const withMetrics = (a) => {
        const hit = columns.length ? screenHitMemo.map?.get(a.currency) : null;
        if (!hit) return a;
        const m = { ...a };
        columns.forEach(([k]) => { m[k] = hit[k]; });
        return m;
    };
    const listed = sortAssets(holdingsAssets.filter(a => !a.is_delisted && matchesHoldingsQuery(a)).map(withMetrics), t.sort);
    // 상장폐지 코인은 현재가·손익이 없으므로 항상 맨 아래 (이름·수량·매수가·투자금 기준으로만 정렬)
    const allDelisted = holdingsAssets.filter(a => a.is_delisted);
    const toggle = document.getElementById('holdings-delist-toggle');
    if (toggle) {                                           // 상장폐지 코인이 있을 때만 '상장폐지 보기' 칸
        toggle.classList.toggle('d-none', !allDelisted.length);
        const n = document.getElementById('holdings-delisted-n');
        if (n) n.textContent = allDelisted.length ? `${allDelisted.length}` : '';
        const box = document.getElementById('holdings-show-delisted');
        if (box) box.checked = holdingsShowDelisted();
    }
    const delisted = holdingsShowDelisted() ? allDelisted.filter(a => matchesHoldingsQuery(a)) : [];
    const delistedKeys = ['korean_name', 'balance', 'avg_buy_price', 'buy_amount'];
    const delistedSorted = delistedKeys.includes(t.sort.key) ? sortAssets(delisted, t.sort) : delisted;
    // 추이 그래프 기간: 정렬 중인 열 기준 (저점 열로 정렬하면 그 기간)
    const spark = SPARK_BY_SORT[t.sort.key] || SPARK_DEFAULT;
    // 수량은 소수 4자리까지만 (정확한 값은 마우스를 올리면)
    const qty = (a) => `<span title="${Number(a.balance).toLocaleString(undefined, { maximumFractionDigits: 8 })} ${a.currency}">${Number(a.balance).toLocaleString(undefined, { maximumFractionDigits: 4 })}개</span>`;

    // 보유 현황 + 저점수익률을 한 표로: 관련 값은 한 칸에 두 줄 (위 = 주된 값, 아래 = 작은 보조 값)
    const makeRow = (a) => {
        const cls = pnlClass(a.pnl);
        const row = document.createElement('tr');
        row.innerHTML = `
            <td class="sel-cell"><input type="checkbox" class="form-check-input row-sel" data-currency="${a.currency}" aria-label="선택"></td>
            <td class="alert-cell"></td>
            <td class="text-nowrap"><div><strong class="coin-name"></strong> <small class="text-muted coin-code"></small></div><div class="cell-sub">${qty(a)}</div>${spikeStateHtml(a.currency)}</td>
            <td class="spark-cell"></td>
            ${metricCellsHtml(columns, a)}
            <td class="text-end text-nowrap">${formatPrice(a.current_price)}</td>
            <td class="text-end text-nowrap buy-price-cell" title="내 평균 매수가">${formatPrice(a.avg_buy_price)}</td>
            <td class="text-end ${pnlClass(a.change_rate)}">${formatChangeRate(a.change_rate)}</td>
            <td class="text-end text-nowrap grp">${formatKrw(a.current_value)}<div class="cell-sub" title="투자금(매수금액)">투자 ${formatKrw(a.buy_amount)}</div></td>
            <td class="text-end text-nowrap ${cls}"><span class="rate-text">${formatChangeRate(a.pnl_rate)}</span><div class="cell-sub ${cls}">${a.pnl > 0 ? '+' : ''}${formatKrw(a.pnl)}</div></td>
            ${lowRateCells(a, periodLowsLoading)}
            <td class="text-end text-muted grp">${formatTradeValue(a.trade_value_24h)}</td>
            ${buyTimeCell(a)}
            <td class="text-end order-cell">
                <button type="button" class="btn btn-sm btn-outline-danger btn-market-buy" data-currency="${a.currency}" title="추가 매수">매수</button>
                <button type="button" class="btn btn-sm btn-outline-primary btn-sell" data-currency="${a.currency}">매도</button>
            </td>
        `;
        row.querySelector('.rate-text').after(createReturnBar(a.pnl_rate));
        row.querySelector('.coin-name').textContent = a.korean_name;
        row.querySelector('.alert-cell').append(...createMarketBadges(a));
        row.querySelector('.coin-code').textContent = a.currency;
        row.querySelector('.coin-name').parentElement.prepend(createCoinLogo(a.currency));
        fillTrendCell(row.querySelector('.spark-cell'), a, spark, periodLowsLoading);
        return row;
    };
    setTrendHeader('holdings-spark-header', spark);
    // 보유 줄은 나눠 그리고, 다 그린 뒤 상장폐지 줄 · 선택 표시 · 정렬 열
    appendRowsChunked(tbody, listed, makeRow, () => {
        appendDelistedRows();
        if (listed.length === 0 && delisted.length === 0) appendNoMatchRow(tbody, colCount);
        finishRows(realTbody, tbody);
        syncSelection('holdings');
        highlightSortedColumn(t);
    });
    syncSelection('holdings');
    highlightSortedColumn(t);

    // 상장폐지 코인: 맨 아래에 구분선과 함께 흐리게 표시 (합계에는 포함 안 됨)
    function appendDelistedRows() {
    if (delistedSorted.length > 0) {
        const delistedBuy = delistedSorted.reduce((sum, a) => sum + a.buy_amount, 0);
        const header = document.createElement('tr');
        header.className = 'table-secondary';
        header.innerHTML = `<td colspan="${colCount}" class="small fw-semibold">
            <i class="bi bi-exclamation-triangle me-1"></i>
            상장폐지 (거래 불가) ${delistedSorted.length}개 · 산 돈 ${formatKrw(delistedBuy)} → 지금 0원
            <span class="text-muted fw-normal">(팔 수 없어 0원으로 칩니다 · 위 합계에 들어 있습니다 · '상장폐지 보기'를 끄면 업비트처럼 합계에서 뺍니다)</span></td>`;
        tbody.appendChild(header);

        for (const a of delistedSorted) {
            const row = document.createElement('tr');
            row.className = 'text-muted';
            row.innerHTML = `
                <td class="sel-cell"><input type="checkbox" class="form-check-input" disabled aria-label="거래 불가"></td>
                <td class="alert-cell"><span class="mk-badge mk-delist">상장폐지</span></td>
                <td class="text-nowrap"><div><span class="coin-name"></span> <small class="coin-code"></small></div><div class="cell-sub">${qty(a)}</div></td>
                <td>-</td>
                ${metricCellsHtml(columns, null)}
                <td class="text-end">거래 불가</td>
                <td class="text-end">${formatPrice(a.avg_buy_price)}</td>
                <td class="text-end">-</td>
                <td class="text-end grp">-<div class="cell-sub">투자 ${formatKrw(a.buy_amount)}</div></td>
                <td class="text-end">-</td>
                <td class="text-end grp">-</td><td class="text-end">-</td><td class="text-end">-</td><td class="text-end">-</td><td class="text-end">-</td>
                <td class="text-end grp">-</td>
                ${buyTimeCell(a)}
                <td class="text-end order-cell">
                    <button type="button" class="btn btn-sm btn-outline-secondary" disabled>매수</button>
                    <button type="button" class="btn btn-sm btn-outline-secondary" disabled>매도</button>
                </td>
            `;
            row.querySelector('.coin-name').textContent = a.korean_name;
            row.querySelector('.coin-code').textContent = a.currency;
            row.querySelector('.coin-name').parentElement.prepend(createCoinLogo(a.currency, true));
            tbody.appendChild(row);
        }
    }
    }
}

// 매수일 칸: 위 = 지금 보유분을 처음 산 때 (KST 'MM-DD HH:mm', 올해가 아니면 연도까지) · 아래 = 그 뒤 더 산 마지막 때 / 며칠째
function buyTimeText(ts) {
    const d = new Date((ts + 9 * 3600) * 1000), p = (n) => String(n).padStart(2, '0');
    const y = d.getUTCFullYear() !== new Date().getFullYear() ? `${d.getUTCFullYear()}-` : '';
    return `${y}${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;
}
function buyTimeCell(a) {
    if (!a.first_buy_ts) return '<td class="text-end text-muted buy-time-cell" title="거래 기록에서 산 기록을 찾지 못했습니다 (입금 받은 코인이거나 기록을 받기 전에 산 코인)">-</td>';
    const days = Math.floor((Date.now() / 1000 - a.first_buy_ts) / 86400);
    const held = days >= 1 ? `${days}일째` : '오늘';
    const more = a.last_buy_ts && a.last_buy_ts - a.first_buy_ts >= 60;
    const tip = `처음 산 때 ${buyTimeText(a.first_buy_ts)}${more ? `\n마지막으로 산 때 ${buyTimeText(a.last_buy_ts)} (모두 ${a.buy_count}번 삼)` : ''}`;
    return `<td class="text-end text-nowrap buy-time-cell" title="${tip}">${buyTimeText(a.first_buy_ts)}`
        + `<div class="cell-sub">${more ? `마지막 ${buyTimeText(a.last_buy_ts).slice(-11)}` : held}</div></td>`;
}

// 기간 최저가 = min(지난 기간 최저가, 오늘 최저가, 현재가) → 현재가가 그보다 몇 % 위인지
function computeLowRates(a) {
    const past = periodLows[`KRW-${a.currency}`];
    const todayLow = Math.min(a.today_low || Infinity, a.current_price || Infinity);
    for (const [rateKey, lowKey] of LOW_PERIODS) {
        const low = past && past[lowKey] ? Math.min(past[lowKey], todayLow) : null;
        a[rateKey.replace('_rate', '')] = low;
        a[rateKey] = low ? (a.current_price / low - 1) * 100 : null;
    }
    // 전일저점 = 최근 24시간 최저가 (1시간봉 저가 + 지금 가격)
    const recent = recentHourly(a);
    if (recent) {
        a.low_d1 = Math.min(...recent.lows, a.current_price);
        a.low_d1_rate = (a.current_price / a.low_d1 - 1) * 100;
    }
    // 24시간 전 가격 = 최근 24시간 1시간봉 중 가장 오래된 봉의 종가 (봉이 하나뿐이면 지금 봉이라 없음) — '하루 급등' 조건용
    a.close_24h = recent && recent.closes.length > 1 ? recent.closes[0] : null;
}

// 저점수익률 표의 추이 그래프 기간: 정렬 중인 열을 따라감 [종가 종류, 개수, 이름]
const SPARK_BY_SORT = {
    change_rate: ['today', 0, '오늘'], low_d1_rate: ['hour', 24, '24시간'],
    low_w1_rate: ['day', 7, '7일'], low_m1_rate: ['day', 30, '30일'],
    low_h6_rate: ['week', 26, '26주'], low_y1_rate: ['week', 52, '52주'],
};
const SPARK_DEFAULT = ['day', 30, '30일'];

// 작은 선 그래프 (SVG): 저점 이전은 회색, 저점에서 지금까지(반등 구간)는 빨강. 저점에 점
// (저점수익률 표의 숫자 = "저점에서 몇 % 올랐나"와 같은 이야기를 하도록)
function createSparkline(values, title) {
    const W = 110, H = 28, PAD = 3;
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('width', W);
    svg.setAttribute('height', H);
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.setAttribute('class', 'sparkline');
    svg.setAttribute('aria-hidden', 'true');

    const min = Math.min(...values), max = Math.max(...values);
    const x = (i) => PAD + i * (W - PAD * 2) / Math.max(values.length - 1, 1);
    const y = (v) => max === min ? H / 2 : PAD + (max - v) * (H - PAD * 2) / (max - min);
    setChartScale(svg, min, max, PAD, H, 'price');
    const lowIndex = values.lastIndexOf(min);

    const addLine = (from, to, color) => {
        if (to <= from) return;
        const line = document.createElementNS(ns, 'polyline');
        const pts = [];
        for (let i = from; i <= to; i++) pts.push(`${x(i).toFixed(1)},${y(values[i]).toFixed(1)}`);
        line.setAttribute('points', pts.join(' '));
        line.setAttribute('fill', 'none');
        line.setAttribute('stroke', color);
        line.setAttribute('stroke-width', '1.5');
        line.setAttribute('stroke-linejoin', 'round');
        svg.appendChild(line);
    };
    // 마지막 한 칸(가장 최근 종가 → 지금)은 따로: 일봉이면 전일대비와 같은 색 (오르면 빨강, 내리면 파랑, 같으면 회색)
    const last = values.length - 1;
    addLine(0, Math.min(lowIndex, last - 1), '#adb5bd');   // 저점 이전
    if (lowIndex < last - 1) addLine(lowIndex, last - 1, PNL_UP);  // 저점 → 최근 종가 (반등)
    const lastColor = values[last] > values[last - 1] ? PNL_UP : values[last] < values[last - 1] ? PNL_DOWN : '#868e96';
    addLine(last - 1, last, lastColor);

    const dot = document.createElementNS(ns, 'circle');
    dot.setAttribute('cx', x(lowIndex).toFixed(1));
    dot.setAttribute('cy', y(min).toFixed(1));
    dot.setAttribute('r', '2.5');
    dot.setAttribute('fill', '#495057');
    svg.appendChild(dot);

    const tip = document.createElementNS(ns, 'title');
    tip.textContent = title;
    svg.appendChild(tip);
    return svg;
}

// 기간별 저점 대비 칸들 (전일·주간·월간·6개월·연간). loading이면 아직 못 받은 칸은 '…'
// 저점 대비는 항상 0% 이상이라 오르내림 색(빨강/파랑) 대신 노랑 한 가지 색의 진하기로 3단계
// 기간마다 '높다'의 기준이 달라서 열마다 경계를 따로 둠: [낮음 상한, 중간 상한] (%)
//   낮음 = 바닥 근처(가장 진한 노랑·굵게), 중간 = 중간 노랑, 높음 = 저점에서 멀리(가장 옅은 노랑)
const LOW_BANDS = { d1: [1, 5], w1: [3, 15], m1: [5, 30], h6: [10, 60], y1: [15, 100] };
function lowBand(lowKey, rate) {
    const [lowMax, midMax] = LOW_BANDS[lowKey];
    if (rate <= lowMax) return ['band-low', `낮음 (바닥 근처) · 이 열 기준 ~${lowMax}%`];
    if (rate <= midMax) return ['band-mid', `중간 · 이 열 기준 ${lowMax}~${midMax}%`];
    return ['band-high', `높음 (저점에서 멀리) · 이 열 기준 ${midMax}% 초과`];
}

function lowRateCells(a, loading) {
    return LOW_PERIODS.map(([rateKey, lowKey], i) => {
        const grp = i === 0 ? ' grp' : '';  // 저점 묶음 시작 구분선
        const low = a[rateKey.replace('_rate', '')];
        if (a[rateKey] === null) {
            return loading
                ? `<td class="text-end${grp}"><span class="text-muted">…</span></td>`
                : `<td class="text-end text-muted${grp}">-</td>`;
        }
        const [band, bandText] = lowBand(lowKey, a[rateKey]);
        const tip = `최저가 ${formatPrice(low)}\n${bandText}`;
        return `<td class="text-end low-cell ${band}${grp}" title="${tip}"><span class="band-val">${formatChangeRate(a[rateKey])}</span></td>`;
    }).join('');
}

// 추이 그래프 칸 채우기: 기간 종가 + 현재가 ([종류, 개수, 이름]은 정렬 중인 열 기준)
function fillSparkCell(cell, a, [kind, count, label], loading) {
    if (kind === 'hour' || kind === 'today') {
        const recent = recentHourly(a);
        if (!recent) {
            cell.innerHTML = loading ? '<span class="text-muted">…</span>' : '<span class="text-muted">-</span>';
            return;
        }
        if (kind === 'hour') {
            const low = Math.min(...recent.lows, a.current_price);
            const prev = recent.closes[recent.closes.length - 2];
            cell.appendChild(createSparkline(recent.closes,
                `최근 24시간 추이 (1시간 간격)\n`
                + `24시간 최저 ${formatPrice(low)} → 현재 ${formatPrice(a.current_price)} (저점에서 ${formatChangeRate((a.current_price / low - 1) * 100)})`
                + (prev ? `\n마지막 한 칸: 1시간 전 종가 대비 ${formatChangeRate((a.current_price / prev - 1) * 100)}` : '')));
            return;
        }
        // 오늘: 업비트 하루 시작(오전 9시)부터, 어제 종가에서 출발
        const now = new Date(Date.now() + 9 * 3600 * 1000);  // KST를 UTC 필드로
        const sessionStart = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) / 1000
            - (now.getUTCHours() < 9 ? 24 * 3600 : 0);  // KST 09:00 = UTC 00:00
        const today = recent.times.map((t, i) => (t >= sessionStart ? recent.closes[i] : null)).filter(v => v !== null);
        if (!a.prev_close) {
            cell.innerHTML = '<span class="text-muted">-</span>';
            return;
        }
        const values = [a.prev_close, ...(today.length ? today : [a.current_price])];
        cell.appendChild(createBaselineSparkline(values, a.prev_close,
            `오늘 추이 (오전 9시부터, 1시간 간격)\n`
            + `어제 종가 ${formatPrice(a.prev_close)} → 현재 ${formatPrice(a.current_price)}\n`
            + `전일대비 ${formatChangeRate(a.change_rate ?? (a.current_price / a.prev_close - 1) * 100)} (점선 = 어제 종가)`));
        return;
    }
    const past = periodLows[`KRW-${a.currency}`];
    const closes = past && past[`${kind}_closes`];
    if (closes && closes.length > 0) {
        const values = [...closes.slice(-count), a.current_price];
        const min = Math.min(...values);
        const prevClose = values[values.length - 2];
        cell.appendChild(createSparkline(values,
            `${label} 추이\n`
            + `최저 ${formatPrice(min)} → 현재 ${formatPrice(a.current_price)} (저점에서 ${formatChangeRate((a.current_price / min - 1) * 100)})\n`
            + `마지막 한 칸: ${kind === 'day' ? '어제' : '지난주'} 종가 대비 ${formatChangeRate((a.current_price / prevClose - 1) * 100)}`));
    } else {
        cell.innerHTML = loading ? '<span class="text-muted">…</span>' : '<span class="text-muted">-</span>';
    }
}

// 기준선 그래프: 점선 = 기준(어제 종가), 검은 점 = 기준점. 기준보다 위 구간은 빨강, 아래는 파랑
function createBaselineSparkline(values, baseline, title) {
    const W = 110, H = 28, PAD = 3;
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('width', W);
    svg.setAttribute('height', H);
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.setAttribute('class', 'sparkline');
    svg.setAttribute('aria-hidden', 'true');

    const min = Math.min(...values, baseline), max = Math.max(...values, baseline);
    const x = (i) => PAD + i * (W - PAD * 2) / Math.max(values.length - 1, 1);
    const y = (v) => max === min ? H / 2 : PAD + (max - v) * (H - PAD * 2) / (max - min);
    setChartScale(svg, min, max, PAD, H, 'price');
    const colorOf = (v) => (v > baseline ? PNL_UP : v < baseline ? PNL_DOWN : '#868e96');

    const base = document.createElementNS(ns, 'line');
    base.setAttribute('x1', PAD);
    base.setAttribute('x2', W - PAD);
    base.setAttribute('y1', y(baseline).toFixed(1));
    base.setAttribute('y2', y(baseline).toFixed(1));
    base.setAttribute('stroke', '#adb5bd');
    base.setAttribute('stroke-width', '1');
    base.setAttribute('stroke-dasharray', '2 2');
    svg.appendChild(base);

    for (let i = 1; i < values.length; i++) {
        const seg = document.createElementNS(ns, 'line');
        seg.setAttribute('x1', x(i - 1).toFixed(1));
        seg.setAttribute('y1', y(values[i - 1]).toFixed(1));
        seg.setAttribute('x2', x(i).toFixed(1));
        seg.setAttribute('y2', y(values[i]).toFixed(1));
        seg.setAttribute('stroke', colorOf(values[i]));
        seg.setAttribute('stroke-width', '1.5');
        seg.setAttribute('stroke-linecap', 'round');
        svg.appendChild(seg);
    }

    // 다른 추이 그래프와 같은 규칙: 검은 점 = 비교 기준(어제 종가)
    const dot = document.createElementNS(ns, 'circle');
    dot.setAttribute('cx', x(0).toFixed(1));
    dot.setAttribute('cy', y(baseline).toFixed(1));
    dot.setAttribute('r', '2.5');
    dot.setAttribute('fill', '#495057');
    svg.appendChild(dot);

    const tip = document.createElementNS(ns, 'title');
    tip.textContent = title;
    svg.appendChild(tip);
    return svg;
}

// 저점수익률 탭 (상장폐지 코인은 현재가가 없어서 제외)
function renderLowsRows() {
    // 저점수익률은 보유 현황 표에 합쳐졌습니다 (기간 시세가 오면 합친 표를 다시 그림)
    if (holdingsAssets.length) renderHoldingsRows();
}

// ── 수익률 그래프 탭: 1분마다 서버가 기록한 수익률을 간격별로 ──
let pnlChart = null;
let pnlInterval = '1m';
let pnlCurrency = 'ALL';
let pnlRefreshTimer = null;

const PNL_UP = '#c84a31';
const PNL_DOWN = '#1261c4';

function setupPnlChartTab() {
    document.querySelectorAll('#pnl-interval-group [data-interval]').forEach(btn => {
        btn.addEventListener('click', () => setPnlInterval(btn.dataset.interval));
    });
    document.getElementById('pnl-coin-select')?.addEventListener('change', (e) => {
        pnlCurrency = e.target.value;
        loadPnlHistory();
    });

    // 포트폴리오 현황: 제목 줄을 누르면 접기 · 펼치기 (이 PC에 기억) — 보유코인 분석이 보이고 펼쳐져 있을 때만 그래프를 1분마다 새로
    const pfSection = document.getElementById('pnl-chart-section'), pfHead = document.getElementById('portfolio-head');
    let pfFolded = false;
    try { pfFolded = localStorage.getItem('portfolioFolded') === '1'; } catch (e) { /* 저장소 없음 */ }
    const refresh = () => {
        clearInterval(pnlRefreshTimer);
        if (pfFolded || !document.getElementById('positions')?.classList.contains('active')) return;
        loadPnlHistory();
        pnlRefreshTimer = setInterval(loadPnlHistory, 60000);
    };
    const setFolded = (f) => {
        pfFolded = f;
        pfSection?.classList.toggle('is-folded', f);
        pfHead?.setAttribute('aria-expanded', String(!f));
        const fold = document.getElementById('portfolio-fold');
        if (fold) fold.innerHTML = `<span>${f ? '펼치기' : '접기'}</span><i class="bi bi-chevron-${f ? 'down' : 'up'}"></i>`;
        try { localStorage.setItem('portfolioFolded', f ? '1' : '0'); } catch (e) { /* 저장 불가: 무시 */ }
        refresh();
    };
    // 봇 성과: 수익률 변화 · 운용 한도 접기 · 펼치기 (이 PC에 기억)
    {
        const sec = document.getElementById('bd-chart-sec'), head = document.getElementById('bd-chart-fold-head');
        let folded = false;
        try { folded = localStorage.getItem('bdChartFolded') === '1'; } catch (e) { /* 저장소 없음 */ }
        const setBdFolded = (f) => {
            folded = f;
            sec?.classList.toggle('is-folded', f);
            head?.setAttribute('aria-expanded', String(!f));
            const fold = document.getElementById('bd-chart-fold');
            if (fold) fold.innerHTML = `<span>${f ? '펼치기' : '접기'}</span><i class="bi bi-chevron-${f ? 'down' : 'up'}"></i>`;
            try { localStorage.setItem('bdChartFolded', f ? '1' : '0'); } catch (e) { /* 저장 불가: 무시 */ }
            if (!f) requestAnimationFrame(() => window.dispatchEvent(new Event('resize')));   // 숨었다 나온 그래프 크기 다시 맞춤
        };
        head?.addEventListener('click', () => setBdFolded(!folded));
        head?.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setBdFolded(!folded); } });
        setBdFolded(folded);
    }
    pfHead?.addEventListener('click', () => setFolded(!pfFolded));
    pfHead?.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setFolded(!pfFolded); } });
    setFolded(pfFolded);

    document.getElementById('positions-tab')?.addEventListener('shown.bs.tab', refresh);
    document.getElementById('positions-tab')?.addEventListener('hidden.bs.tab', () => clearInterval(pnlRefreshTimer));
}

// 코인 선택 목록: 지금 보유한 코인(평가금액 순). 고른 값은 유지
function updatePnlCoinOptions() {
    const select = document.getElementById('pnl-coin-select');
    if (!select) return;
    const coins = holdingsAssets.filter(a => !a.is_delisted)
        .sort((a, b) => b.current_value - a.current_value);
    select.innerHTML = '';
    select.appendChild(new Option('전체 (총 수익률)', 'ALL'));
    coins.forEach(a => select.appendChild(new Option(`${a.korean_name} (${a.currency})`, a.currency)));
    select.value = coins.some(a => a.currency === pnlCurrency) ? pnlCurrency : 'ALL';
    pnlCurrency = select.value;
    renderPnlCoinsMenu(coins);
}

// ── 보유 코인 겹쳐 보기: 고른 코인(최대 5개)의 수익률을 코인마다 색 선으로 ──
const PNL_COIN_COLORS = ['#f97316', '#06b6d4', '#ec4899', '#84cc16', '#a16207'];   // 빨강 · 파랑은 보유코인 손익 색이라 뺌
const PNL_COINS_MAX = 5;
let pnlOverlayCoins = [];
try { pnlOverlayCoins = JSON.parse(localStorage.getItem('pnlOverlayCoins') || '[]').slice(0, PNL_COINS_MAX); } catch (e) { pnlOverlayCoins = []; }
function savePnlOverlayCoins() { try { localStorage.setItem('pnlOverlayCoins', JSON.stringify(pnlOverlayCoins)); } catch (e) { /* 무시 */ } }
function renderPnlCoinsMenu(coins) {
    const held = new Set(coins.map(a => a.currency));
    const before = pnlOverlayCoins.length;
    pnlOverlayCoins = pnlOverlayCoins.filter(c => held.has(c));             // 판 코인은 빼기
    if (pnlOverlayCoins.length !== before) savePnlOverlayCoins();
    // 화면 · 크게 보기 창 두 곳 (같은 선택)
    [['pnl-coins-menu', 'pnl-coins-btn'], ['pnl-big-coins-menu', 'pnl-big-coins-btn']].forEach(([m, b]) => fillPnlCoinsMenu(coins, document.getElementById(m), document.getElementById(b)));
}
function fillPnlCoinsMenu(coins, menu, btn) {
    if (!menu || !btn) return;
    btn.textContent = pnlOverlayCoins.length ? `코인 겹쳐 보기 ${pnlOverlayCoins.length}` : '코인 겹쳐 보기';
    btn.classList.toggle('is-on', pnlOverlayCoins.length > 0);
    if (menu.contains(document.activeElement)) return;                     // 고르는 중엔 다시 그리지 않음
    const full = pnlOverlayCoins.length >= PNL_COINS_MAX;
    menu.innerHTML = `<div class="pcm-head"><b>보유 코인 겹쳐 보기</b><small>최대 ${PNL_COINS_MAX}개 · 평가금액 순</small>`
        + `${pnlOverlayCoins.length ? '<button type="button" class="pcm-clear" data-pcm-clear>모두 지우기</button>' : ''}</div>`
        + `<div class="pcm-list">${coins.map(a => {
            const on = pnlOverlayCoins.includes(a.currency);
            const color = on ? PNL_COIN_COLORS[pnlOverlayCoins.indexOf(a.currency) % PNL_COIN_COLORS.length] : '';
            return `<label class="pcm-item${!on && full ? ' is-disabled' : ''}"><input type="checkbox" class="form-check-input" data-pcm-coin="${escapeHtml(a.currency)}"${on ? ' checked' : ''}${!on && full ? ' disabled' : ''}>`
                + `<i class="pcm-dot" style="${on ? `background:${color}` : ''}"></i><span>${escapeHtml(a.korean_name)} <small>${escapeHtml(a.currency)}</small></span>`
                + `<b class="${pnlClass(a.pnl_rate)}">${formatChangeRate(a.pnl_rate)}</b></label>`;
        }).join('')}</div>`;
}
document.addEventListener('change', (e) => {
    const cb = e.target.closest('[data-pcm-coin]');
    if (!cb) return;
    const c = cb.dataset.pcmCoin;
    pnlOverlayCoins = cb.checked ? [...new Set([...pnlOverlayCoins, c])].slice(0, PNL_COINS_MAX) : pnlOverlayCoins.filter(x => x !== c);
    savePnlOverlayCoins();
    document.activeElement?.blur?.();
    updatePnlCoinOptions();
    loadPnlHistory();
});
document.addEventListener('click', (e) => {
    if (!e.target.closest('[data-pcm-clear]')) return;
    pnlOverlayCoins = [];
    savePnlOverlayCoins();
    updatePnlCoinOptions();
    loadPnlHistory();
});

// x축 이름: 간격에 맞는 시각 표시 (KST)
function formatPnlLabel(ts, interval) {
    const d = new Date((ts + 9 * 3600) * 1000);  // KST를 UTC 필드로 읽기
    const p = (n) => String(n).padStart(2, '0');
    const md = `${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}`;
    const hm = `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;
    if (['1m', '10m', '15m', '30m', '1h', '4h'].includes(interval)) return `${md} ${hm}`;
    if ((ts + 9 * 3600) % 86400) return `${md} ${hm}`;          // 일 · 주 · 월 그래프 맨 끝의 '지금' 점은 시각까지
    if (interval === '1d') return md;
    if (interval === '1w') return `${md} 주`;
    if (interval === '1M') return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}`;
    return `${d.getUTCFullYear()}년`;
}

let pnlAlign = false;
try { pnlAlign = localStorage.getItem('pnlAlign') === '1'; } catch (e) { /* 무시 */ }
const PNL_HOLD = { chart: null, get interval() { return pnlInterval; }, get align() { return pnlAlign; }, canvasId: 'pnl-chart', emptyId: 'pnl-chart-empty', legendId: 'pnl-legend', overlay: null };
// 출발점 맞추기 단추 (화면 · 크게 보기 창 같이)
function syncPnlAlignBtns() {
    document.querySelectorAll('[data-pnl-align]').forEach(b => { b.classList.toggle('is-on', pnlAlign); b.setAttribute('aria-pressed', String(pnlAlign)); });
}
document.addEventListener('click', (e) => {
    if (!e.target.closest('[data-pnl-align]')) return;
    pnlAlign = !pnlAlign;
    try { localStorage.setItem('pnlAlign', pnlAlign ? '1' : '0'); } catch (err) { /* 무시 */ }
    syncPnlAlignBtns();
    loadPnlHistory();
});
// 비교 코인: 같은 기간 내 코인들이 이 코인처럼 움직였다면 (그래프 처음 값에서 출발) — 이 PC에 기억
const BENCH_NAMES = { MARKET: '시장 전체 평균', TOP10: '대형 코인 10개', 'KRW-BTC': '비트코인', 'KRW-ETH': '이더리움' };
let pnlBench = 'MARKET';             // 기본: 업비트 원화 코인 전부를 같은 금액씩 샀다면
try { const b = localStorage.getItem('pnlBench'); if (b !== null) pnlBench = b; } catch (e) { /* 무시 */ }
document.getElementById('pnl-bench-select')?.addEventListener('change', (e) => {
    pnlBench = e.target.value;
    try { localStorage.setItem('pnlBench', pnlBench); } catch (err) { /* 무시 */ }
    loadPnlHistory();
});
(function () {
    const sel = document.getElementById('pnl-bench-select');
    if (!sel) return;
    if (![...sel.options].some(o => o.value === pnlBench)) pnlBench = 'MARKET';   // 예전에 고른 비트코인 · 이더리움은 대형 코인 10개에 들어 있어 뺐음
    sel.value = pnlBench;
})();
// 비교 코인 값 → 그래프 처음 점에서 출발한 수익률 선 [{rate, price} | null]
function benchOverlayRows(points, prices, anchor) {
    if (!prices || !prices.length) return null;
    const i0 = prices.findIndex((p, i) => p && points[i]);
    if (i0 < 0) return null;
    // 출발점: 서버가 준 고정 시점(첫 기록 · 모든 코인)이 있으면 그것 — 간격을 바꿔도 같은 시각은 같은 값. 없으면 그래프 왼쪽 끝
    const base = 1 + (anchor ? anchor.rate : points[i0].rate) / 100, p0 = anchor ? anchor.price : prices[i0];
    return prices.map((p, i) => (p && i >= i0 ? { rate: (base * p / p0 - 1) * 100, price: p } : null));
}
function showPnlChartMessage(msg, st = PNL_HOLD) {
    const empty = document.getElementById(st.emptyId);
    if (!empty) return;
    empty.textContent = msg || '';
    empty.classList.toggle('d-none', !msg);
}

let pnlReqSeq = 0;                    // 마지막 요청 번호: 고른 값을 빨리 바꿀 때 늦게 온 옛 답은 버림
async function loadPnlHistory() {
    const seq = ++pnlReqSeq;
    try {
        const params = new URLSearchParams({ interval: pnlInterval, currency: pnlCurrency });
        if (pnlBench) params.set('bench', pnlBench);
        if (pnlOverlayCoins.length) params.set('coins', pnlOverlayCoins.join(','));
        if (pnlCmpCoins.length) params.set('cmp', pnlCmpCoins.join(','));
        const response = await fetch(`/api/pnl/history?${params}`);
        const data = await response.json();
        if (seq !== pnlReqSeq) return;
        if (!data.success) throw new Error(data.error || '조회 실패');
        pnlLastData = data;
        applyPnlData(data);
    } catch (error) {
        showPnlChartMessage('수익률 기록 조회 오류: ' + error.message);
    }
}

function applyPnlData(data) {
    {

        const info = document.getElementById('pnl-history-info');
        if (info) {
            const s = data.stats;
            info.textContent = s.count
                ? `1분마다 기록 중 · 첫 기록 ${formatPnlLabel(s.first_ts, '1m')} · ${s.count.toLocaleString()}개 (프로그램이 켜져 있을 때만 기록)`
                : '1분마다 기록 중 (프로그램이 켜져 있을 때만 기록)';
        }
        const rows = pnlBench ? benchOverlayRows(data.points, data.bench, data.bench_anchor) : null;
        const name = BENCH_NAMES[pnlBench] || pnlBench.replace('KRW-', '');
        const isMarket = pnlBench === 'MARKET', isTop = pnlBench === 'TOP10';
        const topList = (data.bench_coins || []).join(', ');
        const i0 = rows ? rows.findIndex(Boolean) : -1;
        const from = data.bench_anchor ? formatPnlLabel(data.bench_anchor.ts, '1m') : i0 >= 0 ? formatPnlLabel(data.points[i0].ts, pnlInterval) : '';
        PNL_HOLD.overlay = rows ? { rows, from, label: isMarket ? '모든 코인' : name, mine: pnlCurrency === 'ALL' ? '보유코인' : pnlCurrency,
                                    color: isMarket ? '#8b5cf6' : isTop ? '#10b981' : '#f59e0b',
                                    note: (r) => (isMarket ? '업비트 원화 코인 전부를 같은 금액씩 샀다면'
                                        : isTop ? `대형 코인 10개(${topList})를 같은 금액씩 샀다면`
                                        : `${name} ${formatPrice(r.price)}원 기준`) } : null;
        // 겹쳐 볼 코인: 같은 구간 시각끼리 맞춰 코인마다 선
        PNL_HOLD.extra = pnlOverlayCoins.filter(c => data.coins?.[c]).map((c, i) => {
            const by = new Map(data.coins[c].map(p => [p.ts, p]));
            return { label: c, color: PNL_COIN_COLORS[pnlOverlayCoins.indexOf(c) % PNL_COIN_COLORS.length], rows: data.points.map(p => by.get(p.ts) || null) };
        }).concat(cmpExtras(data));                                    // 다른 코인 비교: 묶음 선 · 고른 코인 선
        renderCmpBox(data);
        renderCmpBot();
        renderPnlChart(data.points);
        PNL_BIG.overlay = PNL_HOLD.overlay;
        PNL_BIG.extra = PNL_HOLD.extra;
        if (pnlBigOpen()) {
            drawPnlChart(PNL_BIG, data.points);
            const bi = document.getElementById('pnl-big-info');
            if (bi) bi.textContent = document.getElementById('pnl-history-info')?.textContent || '';
        }
    }
}

function renderPnlChart(points) { drawPnlChart(PNL_HOLD, points); }

// ── 다른 코인 비교: 보고 있는 구간(그래프 맨 왼쪽 ~ 지금)에 다른 코인들을 같은 금액씩 샀다면 ──
// 선 = 그래프 맨 왼쪽에서 보유코인과 같은 값에서 출발 · 묶음 선(같은 금액씩) + 고른 코인 선 · 아래 표 = 구간 수익률 · 내 보유 대비 · 최대 하락폭
const CMP_MAX = 20, CMP_LINES_MAX = 8, CMPBOT_MAX = 10;
const CMP_COLORS = ['#7c3aed', '#0891b2', '#db2777', '#65a30d', '#ca8a04', '#475569', '#9333ea', '#0f766e'];
const CMP_BASKET_COLOR = '#0d9488';
let pnlCmpCoins = [], pnlCmpLines = [];
try { pnlCmpCoins = JSON.parse(localStorage.getItem('pnlCmpCoins') || '[]').slice(0, CMP_MAX); } catch (e) { pnlCmpCoins = []; }
try { pnlCmpLines = JSON.parse(localStorage.getItem('pnlCmpLines') || '[]'); } catch (e) { pnlCmpLines = []; }
let pnlLastData = null;               // 마지막 수익률 기록 응답 (점 · 비교 코인 값)
function saveCmp() {
    try {
        localStorage.setItem('pnlCmpCoins', JSON.stringify(pnlCmpCoins));
        localStorage.setItem('pnlCmpLines', JSON.stringify(pnlCmpLines));
    } catch (e) { /* 무시 */ }
}
function cmpName(c) {
    const m = (typeof marketCoins !== 'undefined' ? marketCoins : []).find(x => x.currency === c);
    return m?.korean_name || cmpScan?.coins?.find(x => x.c === c)?.name || c;
}
const fmtPp = (v) => (v === null || v === undefined || !isFinite(v) ? '-' : `${v >= 0 ? '+' : ''}${v.toFixed(2)}%p`);
const fmtPct = (v) => (v === null || v === undefined || !isFinite(v) ? '-' : `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`);
// 보유코인의 구간 수익률: 그래프 맨 왼쪽 → 지금 (평가 ÷ 투자 비율이 변한 만큼)
function cmpMineRet(points) {
    if (!points?.length) return null;
    const a = points[0].rate, b = points[points.length - 1].rate;
    return ((1 + b / 100) / (1 + a / 100) - 1) * 100;
}
// 코인 값 [점마다] → 구간 수익률 · 최대 하락폭 · 점마다 출발 대비 배율
function cmpCoinStats(vals) {
    const i0 = vals.findIndex(v => v);
    if (i0 < 0) return null;
    const base = vals[i0];
    let peak = base, mdd = 0, last = base;
    vals.forEach((v, i) => {
        if (!v || i < i0) return;
        peak = Math.max(peak, v);
        mdd = Math.max(mdd, (peak - v) / peak * 100);
        last = v;
    });
    return { i0, ret: (last / base - 1) * 100, mdd, ratio: vals.map((v, i) => (v && i >= i0 ? v / base : null)) };
}
// 비교 선 (drawPnlChart 의 extra 모양): 보유코인의 그래프 맨 왼쪽 수익률에서 출발
function cmpExtras(data) {
    const pts = data.points || [], cmp = data.cmp || {};
    if (!pts.length || !pnlCmpCoins.length) return [];
    const base = 1 + pts[0].rate / 100;
    const stats = {};
    pnlCmpCoins.forEach(c => { if (cmp[c]) stats[c] = cmpCoinStats(cmp[c]); });
    const out = [];
    // 묶음: 점마다 고른 코인들의 출발 대비 배율 평균 (그 점에 값이 있는 코인만)
    const rows = pts.map((p, i) => {
        const rs = Object.values(stats).filter(Boolean).map(s => s.ratio[i]).filter(Boolean);
        return rs.length ? { rate: (base * rs.reduce((x, y) => x + y, 0) / rs.length - 1) * 100, n: rs.length } : null;
    });
    if (rows.some(Boolean)) {
        out.push({ label: `고른 코인 ${Object.values(stats).filter(Boolean).length}개`, color: CMP_BASKET_COLOR, dash: true, width: 2, rows,
                   note: (r) => `${r.n}개를 그래프 맨 왼쪽에 같은 금액씩 샀다면` });
    }
    pnlCmpLines.filter(c => stats[c]).forEach((c, k) => {
        const s = stats[c], color = CMP_COLORS[k % CMP_COLORS.length];
        out.push({ label: cmpName(c), color, rows: s.ratio.map((r, i) => (r ? { rate: (base * r - 1) * 100, price: cmp[c][i] } : null)),
                   note: (r) => `${c} ${formatPrice(r.price)}원` });
    });
    return out;
}
// 그래프 아래 표: 고른 코인마다 구간 수익률 · 내 보유 대비 · 최대 하락폭 (선 보기 켜고 끄기)
function renderCmpBox(data) {
    const box = document.getElementById('pnl-cmp-box');
    if (!box) return;
    const pts = data?.points || [];
    document.getElementById('cmp-row')?.classList.toggle('d-none', !pnlCmpCoins.length || !pts.length);
    if (!pnlCmpCoins.length || !pts.length) { box.innerHTML = ''; return; }
    const cmp = data.cmp || {};
    const mine = cmpMineRet(pts);
    const rows = pnlCmpCoins.map(c => ({ c, s: cmp[c] ? cmpCoinStats(cmp[c]) : null }));
    const ok = rows.filter(r => r.s);
    const avg = ok.length ? ok.reduce((x, r) => x + r.s.ret, 0) / ok.length : null;
    rows.sort((a, b) => (b.s?.ret ?? -1e9) - (a.s?.ret ?? -1e9));
    const lineIdx = (c) => pnlCmpLines.filter(x => cmp[x]).indexOf(c);
    box.innerHTML = `<div class="pcb-head"><b>다른 코인 비교</b><small>${escapeHtml(formatPnlLabel(pts[0].ts, pnlInterval))} ~ 지금 · 그래프 맨 왼쪽에 샀다면</small>`
        + `<span class="pcb-sum">내 보유코인 <b class="${pnlClass(mine)}">${fmtPct(mine)}</b> · 고른 코인 ${ok.length}개 평균 <b class="${pnlClass(avg)}">${fmtPct(avg)}</b>`
        + `${avg !== null && mine !== null ? ` · <span class="${pnlClass(avg - mine)}">${avg > mine ? '다른 코인이 나았습니다' : '내 보유코인이 나았습니다'} (${fmtPp(avg - mine)})</span>` : ''}</span>`
        + `<button type="button" class="btn btn-sm cmp-mini-btn ms-auto" data-cmp-open><i class="bi bi-pencil"></i> 코인 고르기</button>`
        + `<button type="button" class="btn btn-sm cmp-mini-btn" data-cmp-clear>모두 지우기</button></div>`
        + `<div class="pcb-table"><table class="table table-sm cmp-table mb-0"><thead><tr><th class="text-center" title="그래프에 선으로 보기 (최대 ${CMP_LINES_MAX}개)">선</th><th>코인</th><th class="text-end">구간 수익률</th><th class="text-end" title="+ 면 이 코인을 샀으면 내 보유코인보다 더 벌었음">내 보유 대비</th><th class="text-end" title="구간 안에서 가장 높았던 값에서 가장 많이 내려간 폭">최대 하락폭</th><th></th></tr></thead><tbody>`
        + rows.map(({ c, s }) => {
            const on = pnlCmpLines.includes(c), k = lineIdx(c);
            const full = !on && pnlCmpLines.length >= CMP_LINES_MAX;
            return `<tr><td class="text-center"><input type="checkbox" class="form-check-input" data-cmp-line="${escapeHtml(c)}"${on ? ' checked' : ''}${full || !s ? ' disabled' : ''} aria-label="${escapeHtml(c)} 선 보기"></td>`
                + `<td><i class="pcm-dot" style="${on && k >= 0 ? `background:${CMP_COLORS[k % CMP_COLORS.length]}` : ''}"></i>${escapeHtml(cmpName(c))} <small class="text-muted">${escapeHtml(c)}</small>${(data.points[0] && s && s.i0 > 0) ? ' <small class="cmp-late">구간 중 상장</small>' : ''}</td>`
                + `<td class="text-end"><b class="${pnlClass(s?.ret)}">${s ? fmtPct(s.ret) : '값 없음'}</b></td>`
                + `<td class="text-end ${pnlClass(s && mine !== null ? s.ret - mine : null)}">${s && mine !== null ? fmtPp(s.ret - mine) : '-'}</td>`
                + `<td class="text-end text-muted">${s ? `−${s.mdd.toFixed(2)}%` : '-'}</td>`
                + `<td class="text-end"><button type="button" class="btn btn-sm cmp-x" data-cmp-remove="${escapeHtml(c)}" aria-label="${escapeHtml(c)} 빼기"><i class="bi bi-x"></i></button></td></tr>`;
        }).join('') + '</tbody></table></div>';
}
document.addEventListener('change', (e) => {
    const cb = e.target.closest('[data-cmp-line]');
    if (!cb) return;
    const c = cb.dataset.cmpLine;
    pnlCmpLines = cb.checked ? [...new Set([...pnlCmpLines, c])].slice(0, CMP_LINES_MAX) : pnlCmpLines.filter(x => x !== c);
    saveCmp();
    if (pnlLastData) { applyPnlData(pnlLastData); }
});
document.addEventListener('click', (e) => {
    if (e.target.closest('[data-cmp-open]') || e.target.closest('#pnl-cmp-btn')) { openCmpModal(); return; }
    if (e.target.closest('[data-cmp-clear]')) {
        pnlCmpCoins = []; pnlCmpLines = [];
        saveCmp(); syncCmpBtn(); renderCmpBot(); loadPnlHistory();
        return;
    }
    const rm = e.target.closest('[data-cmp-remove]');
    if (rm) {
        const c = rm.dataset.cmpRemove;
        pnlCmpCoins = pnlCmpCoins.filter(x => x !== c); pnlCmpLines = pnlCmpLines.filter(x => x !== c);
        saveCmp(); syncCmpBtn(); renderCmpBot(); loadPnlHistory();
    }
});
function syncCmpBtn() {
    const b = document.getElementById('pnl-cmp-btn');
    if (!b) return;
    b.classList.toggle('is-on', pnlCmpCoins.length > 0);
    b.innerHTML = `<i class="bi bi-ui-checks-grid"></i> 다른 코인 비교${pnlCmpCoins.length ? ` ${pnlCmpCoins.length}` : ''}`;
}
syncCmpBtn();

// ── 코인 고르기 창 ──
let cmpScan = null, cmpPick = new Set(), cmpSort = { key: 'ret', dir: -1 }, cmpScanSeq = 0;
async function openCmpModal() {
    const modal = document.getElementById('cmp-modal');
    const pts = pnlLastData?.points || [];
    if (!modal) return;
    if (!pts.length) return;                                         // 수익률 기록이 아직 없음
    cmpPick = new Set(pnlCmpCoins);
    const start = Math.floor(pts[0].at || pts[0].ts), iv = pnlInterval;
    const mine = cmpMineRet(pts);
    document.getElementById('cmp-window').innerHTML = `보고 있는 구간 ${escapeHtml(formatPnlLabel(pts[0].ts, iv))} ~ 지금 · 이 구간 내 보유코인 <b class="${pnlClass(mine)}">${fmtPct(mine)}</b>`;
    document.getElementById('cmp-search').value = '';
    bootstrap.Modal.getOrCreateInstance(modal).show();
    if (!cmpScan || cmpScan.interval !== iv || Math.abs(cmpScan.start - start) > 60 * 30) cmpScan = null;
    renderCmpPick();
    if (cmpScan) return;
    const seq = ++cmpScanSeq;
    const prog = document.getElementById('cmp-progress');
    prog.classList.remove('d-none');
    const setProg = (p, t) => { prog.querySelector('i').style.width = `${Math.round(p * 100)}%`; prog.querySelector('small').textContent = t; };
    setProg(0, '코인 목록 받는 중');
    try {
        const r = await (await fetch('/api/compare/scan', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ interval: iv, start }) })).json();
        if (!r.success) throw new Error(r.error || '시작하지 못했습니다');
        for (;;) {
            const j = await (await fetch(`/api/compare/job/${r.job}`)).json();
            if (seq !== cmpScanSeq) return;
            if (!j.success) throw new Error(j.error || '작업을 찾지 못했습니다');
            if (j.stage === 'done') { cmpScan = { ...j.result, mine }; break; }
            if (j.stage === 'error') throw new Error(j.error);
            setProg(j.progress || 0, `${j.text || ''} · 처음 한 번만 오래 걸리고, 받은 값은 이 PC에 저장됩니다`);
            await new Promise(res => setTimeout(res, 800));
        }
        prog.classList.add('d-none');
        renderCmpPick();
    } catch (err) {
        setProg(0, `값을 계산하지 못했습니다: ${err.message}`);
    }
}
function renderCmpPick() {
    const tb = document.getElementById('cmp-table');
    if (!tb) return;
    document.getElementById('cmp-count').innerHTML = `고른 코인 <b>${cmpPick.size}</b>/${CMP_MAX}개${cmpPick.size > CMPBOT_MAX ? ` · 봇 적용 비교는 앞의 ${CMPBOT_MAX}개만 계산합니다` : ''}`;
    if (!cmpScan) { tb.innerHTML = '<tbody><tr><td class="text-muted p-3">코인마다 구간 값을 계산하는 중입니다…</td></tr></tbody>'; return; }
    const q = (document.getElementById('cmp-search').value || '').trim().toLowerCase();
    const held = new Set(holdingsAssets.filter(a => !a.is_delisted).map(a => a.currency));
    const mine = cmpScan.mine;
    const k = cmpSort.key, d = cmpSort.dir;
    const val = (x) => (k === 'name' ? x.name : k === 'diff' ? x.ret : x[k]);
    const list = cmpScan.coins.filter(x => !q || x.c.toLowerCase().includes(q) || x.name.toLowerCase().includes(q))
        .sort((a, b) => (k === 'name' ? a.name.localeCompare(b.name) : val(a) - val(b)) * d);       // d = 1 오름차순 · −1 내림차순
    const arrow = (key) => (cmpSort.key === key ? (cmpSort.dir < 0 ? ' ▼' : ' ▲') : '');
    const full = cmpPick.size >= CMP_MAX;
    tb.innerHTML = `<thead><tr><th></th><th role="button" data-cmp-sort="name">코인${arrow('name')}</th>`
        + `<th class="text-end" role="button" data-cmp-sort="ret">구간 수익률${arrow('ret')}</th>`
        + `<th class="text-end" role="button" data-cmp-sort="diff" title="+ 면 이 코인을 샀으면 내 보유코인보다 더 벌었음">내 보유 대비${arrow('diff')}</th>`
        + `<th class="text-end" role="button" data-cmp-sort="mdd" title="구간 안에서 가장 높았던 값에서 가장 많이 내려간 폭">최대 하락폭${arrow('mdd')}</th>`
        + `<th class="text-end" role="button" data-cmp-sort="value24h" title="최근 24시간 거래대금">거래대금${arrow('value24h')}</th></tr></thead><tbody>`
        + list.map(x => {
            const on = cmpPick.has(x.c);
            return `<tr class="${on ? 'is-on' : ''}"><td><input type="checkbox" class="form-check-input" data-cmp-pick="${escapeHtml(x.c)}"${on ? ' checked' : ''}${!on && full ? ' disabled' : ''} aria-label="${escapeHtml(x.name)} 고르기"></td>`
                + `<td>${escapeHtml(x.name)} <small class="text-muted">${escapeHtml(x.c)}</small>${held.has(x.c) ? ' <small class="cmp-held">보유</small>' : ''}${x.late ? ' <small class="cmp-late">구간 중 상장</small>' : ''}</td>`
                + `<td class="text-end"><b class="${pnlClass(x.ret)}">${fmtPct(x.ret)}</b></td>`
                + `<td class="text-end ${pnlClass(mine === null ? null : x.ret - mine)}">${mine === null ? '-' : fmtPp(x.ret - mine)}</td>`
                + `<td class="text-end text-muted">−${x.mdd.toFixed(2)}%</td>`
                + `<td class="text-end text-muted">${formatKrwShort(x.value24h)}</td></tr>`;
        }).join('') + '</tbody>';
}
document.getElementById('cmp-search')?.addEventListener('input', renderCmpPick);
document.getElementById('cmp-modal')?.addEventListener('click', (e) => {
    const th = e.target.closest('[data-cmp-sort]');
    if (th) {
        const key = th.dataset.cmpSort;
        cmpSort = cmpSort.key === key ? { key, dir: -cmpSort.dir } : { key, dir: key === 'name' || key === 'mdd' ? 1 : -1 };
        renderCmpPick();
        return;
    }
    const q = e.target.closest('[data-cmp-quick]');
    if (q) {
        const how = q.dataset.cmpQuick, coins = cmpScan?.coins || [];
        const by = (f, dir, n) => [...coins].sort((a, b) => (f(b) - f(a)) * dir).slice(0, n).map(x => x.c);
        const pick = how === 'clear' ? [] : how === 'top5' ? by(x => x.ret, 1, 5) : how === 'bottom5' ? by(x => x.ret, -1, 5)
            : how === 'value10' ? by(x => x.value24h, 1, 10) : how === 'top10' ? (cmpScan?.top10 || [])
            : holdingsAssets.filter(a => !a.is_delisted).sort((a, b) => b.current_value - a.current_value).map(a => a.currency).slice(0, CMP_MAX);
        if (how !== 'clear' && !cmpScan && how !== 'held') return;
        cmpPick = new Set(pick);
        renderCmpPick();
    }
});
document.getElementById('cmp-modal')?.addEventListener('change', (e) => {
    const cb = e.target.closest('[data-cmp-pick]');
    if (!cb) return;
    if (cb.checked && cmpPick.size < CMP_MAX) cmpPick.add(cb.dataset.cmpPick); else cmpPick.delete(cb.dataset.cmpPick);
    renderCmpPick();
});
document.getElementById('cmp-apply')?.addEventListener('click', () => {
    // 표에서 고른 순서: 구간 수익률 높은 순 (봇 적용 비교는 앞의 10개)
    const order = new Map((cmpScan?.coins || []).map(x => [x.c, x.ret]));
    pnlCmpCoins = [...cmpPick].sort((a, b) => (order.get(b) ?? -1e9) - (order.get(a) ?? -1e9)).slice(0, CMP_MAX);
    pnlCmpLines = pnlCmpLines.filter(c => pnlCmpCoins.includes(c));
    if (!pnlCmpLines.length) pnlCmpLines = pnlCmpCoins.slice(0, 3);       // 처음에는 위 3개만 선으로
    saveCmp(); syncCmpBtn(); renderCmpBot();
    bootstrap.Modal.getInstance(document.getElementById('cmp-modal'))?.hide();
    loadPnlHistory();
});

// ── 고른 코인에 봇을 적용했다면 (구간 처음에 같은 금액씩 산 뒤 봇 규칙 vs 그냥 들고 있기) ──
let cmpBotChart = null, cmpBotSeq = 0, cmpBotLast = null;
function renderCmpBot() {
    const card = document.getElementById('cmpbot-card');
    if (!card) return;
    const sel = document.getElementById('cmpbot-bot');
    const keep = sel.value || (() => { try { return localStorage.getItem('cmpBotId'); } catch (e) { return null; } })();
    const bots = (typeof botsList !== 'undefined' ? botsList : []).filter(b => !b.example || APP_MODE === 'sim');
    sel.innerHTML = bots.length ? bots.map(b => `<option value="${escapeHtml(b.id)}">${escapeHtml(b.name || b.id)}</option>`).join('') : '<option value="">봇이 없습니다</option>';
    if (bots.some(b => b.id === keep)) sel.value = keep;
    const pts = pnlLastData?.points || [];
    const coins = pnlCmpCoins.slice(0, CMPBOT_MAX);
    const info = document.getElementById('cmpbot-info');
    const run = document.getElementById('cmpbot-run');
    run.disabled = !coins.length || !pts.length || !bots.length;
    info.innerHTML = !coins.length ? "위 수익률 추이의 '다른 코인 비교'에서 코인을 고르시면, 그 코인들에 봇을 적용했을 때와 안 했을 때를 비교합니다."
        : `코인 ${coins.length}개 (${escapeHtml(coins.join(', '))})${pnlCmpCoins.length > CMPBOT_MAX ? ` · 고른 ${pnlCmpCoins.length}개 중 앞의 ${CMPBOT_MAX}개` : ''}`
          + ` · 구간 ${pts.length ? escapeHtml(formatPnlLabel(pts[0].ts, pnlInterval)) : '-'} ~ 지금 · 코인마다 ${formatKrw(1000000)}씩`
          + (cmpBotLast && cmpBotLast.key !== cmpBotKey() ? ' · <b>코인이나 구간이 바뀌었습니다. 다시 계산해 주십시오</b>' : '');
}
function cmpBotKey() {
    const pts = pnlLastData?.points || [];
    return JSON.stringify([document.getElementById('cmpbot-bot')?.value, pnlCmpCoins.slice(0, CMPBOT_MAX), pnlInterval, pts[0]?.ts]);
}
document.getElementById('cmpbot-bot')?.addEventListener('change', (e) => { try { localStorage.setItem('cmpBotId', e.target.value); } catch (err) { /* 무시 */ } renderCmpBot(); });
document.getElementById('cmpbot-run')?.addEventListener('click', async () => {
    const pts = pnlLastData?.points || [];
    const botId = document.getElementById('cmpbot-bot').value;
    if (!pts.length || !botId) return;
    const seq = ++cmpBotSeq, key = cmpBotKey();
    const prog = document.getElementById('cmpbot-progress'), run = document.getElementById('cmpbot-run');
    const setProg = (p, t) => { prog.querySelector('i').style.width = `${Math.round(p * 100)}%`; prog.querySelector('small').textContent = t; };
    prog.classList.remove('d-none');
    run.disabled = true;
    setProg(0, '준비 중…');
    try {
        const r = await (await fetch('/api/compare/bot', { method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ bot_id: botId, coins: pnlCmpCoins.slice(0, CMPBOT_MAX), interval: pnlInterval, start: Math.floor(pts[0].at || pts[0].ts) }) })).json();
        if (!r.success) throw new Error(r.error || '시작하지 못했습니다');
        for (;;) {
            const j = await (await fetch(`/api/compare/job/${r.job}`)).json();
            if (seq !== cmpBotSeq) return;
            if (!j.success) throw new Error(j.error || '작업을 찾지 못했습니다');
            if (j.stage === 'done') { cmpBotLast = { key, result: j.result }; break; }
            if (j.stage === 'error') throw new Error(j.error);
            setProg(j.progress || 0, j.text || '');
            await new Promise(res => setTimeout(res, 800));
        }
        prog.classList.add('d-none');
        drawCmpBot(cmpBotLast.result);
    } catch (err) {
        setProg(0, `계산하지 못했습니다: ${err.message}`);
    } finally {
        run.disabled = false;
        renderCmpBot();
    }
});
function drawCmpBot(res) {
    const box = document.getElementById('cmpbot-result');
    box.classList.remove('d-none');
    const curve = res.curve || [];
    const last = curve[curve.length - 1] || { bot: 0, hold: 0 };
    const diff = last.bot - last.hold;
    document.getElementById('cmpbot-legend').innerHTML = `<span class="pl-bot"><i style="border-top-color:#1e40af"></i>봇 적용 (${escapeHtml(res.bot_name)}) <b class="${pnlClass(last.bot)}">${fmtPct(last.bot)}</b></span>`
        + `<span class="pl-hold"><i style="border-top-color:#64748b"></i>봇 미적용 <b class="${pnlClass(last.hold)}">${fmtPct(last.hold)}</b></span>`
        + `<span class="pl-diff">차이 <b class="${pnlClass(diff)}">${fmtPp(diff)}</b> · ${diff >= 0 ? '봇을 적용한 쪽이 나았습니다' : '그냥 들고 있는 쪽이 나았습니다'}</span>`;
    const labels = curve.map(p => formatPnlLabel(p.t, /^\d+$/.test(res.unit) ? '1m' : '1d'));     // 분 · 시간봉은 시각까지, 일 · 주봉은 날짜
    const ds = [
        { label: '봇 적용', data: curve.map(p => p.bot), borderColor: '#1e40af', borderWidth: 2, pointRadius: 0, tension: 0, fill: false },
        { label: '봇 미적용', data: curve.map(p => p.hold), borderColor: '#64748b', borderDash: [5, 4], borderWidth: 1.6, pointRadius: 0, tension: 0, fill: false },
    ];
    if (cmpBotChart) { cmpBotChart.destroy(); cmpBotChart = null; }
    cmpBotChart = new Chart(document.getElementById('cmpbot-chart'), {
        type: 'line', data: { labels, datasets: ds },
        options: { responsive: true, maintainAspectRatio: false, animation: false, interaction: { mode: 'index', intersect: false },
            plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => `${c.dataset.label} ${fmtPct(c.parsed.y)}` } } },
            scales: { x: { grid: { display: false }, ticks: { color: '#6c757d', maxTicksLimit: 8, maxRotation: 0 } },
                      y: { grid: { color: (c) => (c.tick && c.tick.value === 0 ? '#adb5bd' : '#eef0f3') }, ticks: { color: '#6c757d', callback: (v) => `${Number(v).toFixed(1)}%` } } } },
    });
    const coins = [...(res.coins || [])].sort((a, b) => (b.bot - b.hold) - (a.bot - a.hold));
    document.getElementById('cmpbot-table').innerHTML = `<thead><tr><th>코인</th><th class="text-end">봇 적용</th><th class="text-end">봇 미적용</th><th class="text-end">차이</th><th class="text-end" title="구간 처음에 산 것은 빼고 센 횟수">봇이 사고판 횟수</th></tr></thead><tbody>`
        + coins.map(c => `<tr><td>${escapeHtml(c.name)} <small class="text-muted">${escapeHtml(c.c)}</small>${c.open ? '' : ' <small class="cmp-late" title="구간 끝에 이 코인을 들고 있지 않음 (판 돈은 원화로)">지금은 팔고 없음</small>'}</td>`
            + `<td class="text-end"><b class="${pnlClass(c.bot)}">${fmtPct(c.bot)}</b></td><td class="text-end ${pnlClass(c.hold)}">${fmtPct(c.hold)}</td>`
            + `<td class="text-end ${pnlClass(c.bot - c.hold)}">${fmtPp(c.bot - c.hold)}</td>`
            + `<td class="text-end text-muted" title="${escapeHtml((c.trades || []).map(t => `${t.time.slice(5, 16).replace('T', ' ')} ${t.side === 'buy' ? '매수' : '매도'} · ${t.reason}`).join('\n'))}">매수 ${c.buys} · 매도 ${c.sells}</td></tr>`).join('')
        + '</tbody>';
    const notes = [];
    if (res.clipped) notes.push(`이 봇은 이 봉 단위로 최대 ${res.limit_days}일까지 계산할 수 있어 최근 ${res.limit_days}일만 계산했습니다.`);
    (res.skipped || []).forEach(s => notes.push(`빠진 규칙 · ${escapeHtml(s.title || '')}: ${escapeHtml(s.why || '')}`));
    (res.notes || []).filter(n => n.title !== '매매대상').forEach(n => notes.push(`${escapeHtml(n.title || '')}: ${escapeHtml(n.note || '')}`));
    (res.failed || []).forEach(f => notes.push(`${escapeHtml(f.c)}는 계산하지 못했습니다 (${escapeHtml(f.why)})`));
    notes.push('수수료 0.05% · 미끄러짐 0.1%를 넣어 계산했으며, 봇이 다 판 뒤 다시 살 때는 판 돈 전부로 삽니다.');
    document.getElementById('cmpbot-notes').innerHTML = notes.map(n => `<div>· ${n}</div>`).join('');
}


// ── 수익률 추이 크게 보기 (새 창): 화면의 간격 · 코인 · 비교와 함께 바뀜 ──
const PNL_BIG = { chart: null, get interval() { return pnlInterval; }, get align() { return pnlAlign; }, canvasId: 'pnl-big-chart', emptyId: 'pnl-big-empty', legendId: 'pnl-big-legend', overlay: null };
function pnlBigOpen() { return document.getElementById('pnl-big-modal')?.classList.contains('show'); }
function syncPnlBigControls() {
    document.querySelectorAll('[data-pnl-big-interval]').forEach(b => b.classList.toggle('active', b.dataset.pnlBigInterval === pnlInterval));
    const copy = (fromId, toId) => {
        const from = document.getElementById(fromId), to = document.getElementById(toId);
        if (!from || !to) return;
        to.innerHTML = from.innerHTML;
        to.value = from.value;
    };
    copy('pnl-coin-select', 'pnl-big-coin');
    copy('pnl-bench-select', 'pnl-big-bench');
}
function setPnlInterval(iv) {
    pnlInterval = iv;
    document.querySelectorAll('#pnl-interval-group [data-interval]').forEach(b => b.classList.toggle('active', b.dataset.interval === iv));
    document.querySelectorAll('[data-pnl-big-interval]').forEach(b => b.classList.toggle('active', b.dataset.pnlBigInterval === iv));
    loadPnlHistory();
}
(function setupPnlBig() {
    const modal = document.getElementById('pnl-big-modal');
    if (!modal) return;
    document.getElementById('pnl-expand')?.addEventListener('click', () => {
        syncPnlBigControls();
        bootstrap.Modal.getOrCreateInstance(modal).show();
    });
    modal.addEventListener('shown.bs.modal', () => loadPnlHistory());
    modal.addEventListener('hidden.bs.modal', () => { if (PNL_BIG.chart) { PNL_BIG.chart.destroy(); PNL_BIG.chart = null; } });
    modal.addEventListener('click', (e) => {
        const b = e.target.closest('[data-pnl-big-interval]');
        if (b) setPnlInterval(b.dataset.pnlBigInterval);
        // 전체 화면: 창을 화면 가득 / 축소: 원래 크기 · 가운데 (제목 줄 두 번 누르기와 같음)
        const dlg = modal.querySelector('.modal-dialog'), content = modal.querySelector('.modal-content');
        if (e.target.closest('[data-pnl-big-max]')) {
            dlg.classList.add('is-free', 'is-sized', 'is-max');
            Object.assign(dlg.style, { left: '8px', top: '8px', width: `${window.innerWidth - 16}px` });
            content.style.height = `${window.innerHeight - 16}px`;
        }
        if (e.target.closest('[data-pnl-big-restore]')) {
            dlg.classList.remove('is-max');
            modal.querySelector('.modal-header')?.dispatchEvent(new MouseEvent('dblclick', { bubbles: true }));
        }
    });
    modal.addEventListener('hidden.bs.modal', () => modal.querySelector('.modal-dialog')?.classList.remove('is-max'));
    document.getElementById('pnl-big-coin')?.addEventListener('change', (e) => {
        const main = document.getElementById('pnl-coin-select');
        if (main) { main.value = e.target.value; main.dispatchEvent(new Event('change')); }
    });
    document.getElementById('pnl-big-bench')?.addEventListener('change', (e) => {
        const main = document.getElementById('pnl-bench-select');
        if (main) { main.value = e.target.value; main.dispatchEvent(new Event('change')); }
    });
    makeModalMovable(modal, 'strabot.pnlBigBox');
})();

// 수익률 변화 그래프 (보유코인 분석 · 봇 성과 탭 공통): 0% 위 빨강 · 아래 파랑
function drawPnlChart(st, points) {
    const canvas = document.getElementById(st.canvasId);
    if (!canvas) return;
    if (typeof Chart === 'undefined') {
        showPnlChartMessage('그래프 라이브러리를 불러오지 못했습니다. 인터넷 연결을 확인해 주십시오.', st);
        return;
    }
    if (points.length === 0) {
        if (st.chart) { st.chart.destroy(); st.chart = null; }
        const legend = st.legendId && document.getElementById(st.legendId);
        if (legend) legend.innerHTML = '';             // 기록 없는 봇: 앞서 보던 봇의 수익률 숫자가 남지 않게 (2026-10-15)
        showPnlChartMessage('아직 기록이 없습니다. 프로그램이 켜져 있으면 1분마다 쌓입니다.', st);
        return;
    }
    showPnlChartMessage('', st);

    const labels = points.map(pt => formatPnlLabel(pt.ts, st.interval));
    // 출발점 맞추기: 선마다 그래프에서 처음 나온 값을 0으로 → 그 뒤 오르고 내린 만큼(%p)만 (모양 비교용)
    const align = !!st.align;
    const shift = (arr) => {
        if (!align) return arr;
        const b = arr.find(v => v !== null && v !== undefined);
        return arr.map(v => (v === null || v === undefined ? null : v - b));
    };
    const fmtV = (v) => (align ? `${v >= 0 ? '+' : ''}${Number(v).toFixed(2)}%` : formatChangeRate(v));
    const rates = shift(points.map(pt => pt.rate));
    const fewPoints = points.length <= 30;

    const dataset = {
        data: rates,
        borderWidth: 2,
        pointRadius: fewPoints ? 3 : 0,
        pointHoverRadius: 5,
        pointBackgroundColor: rates.map(r => (r >= 0 ? PNL_UP : PNL_DOWN)),
        // 선 색: 수익 구간 빨강, 손실 구간 파랑
        segment: { borderColor: ctx => (ctx.p1.parsed.y >= 0 ? PNL_UP : PNL_DOWN) },
        borderColor: rates[rates.length - 1] >= 0 ? PNL_UP : PNL_DOWN,
        // 0% 위는 옅은 빨강, 아래는 옅은 파랑으로 채움
        fill: { target: 'origin', above: 'rgba(200, 74, 49, 0.10)', below: 'rgba(18, 97, 196, 0.10)' },
        tension: 0,
    };

    // 비교선 (점선): 봇 화면 = 들고만 있었으면, 보유코인 분석 = 비트코인 등이었다면
    const ov = st.overlay && st.overlay.rows.some(Boolean) ? st.overlay : null;
    const hold = ov ? ov.rows : null;
    const datasets = [dataset];
    if (ov) datasets.push({
        label: ov.label, data: shift(hold.map(p => (p ? p.rate : null))), spanGaps: true,
        borderColor: ov.color, borderWidth: 1.6, borderDash: [5, 4], pointRadius: 0, pointHoverRadius: 4,
        pointBackgroundColor: ov.color, fill: false, tension: 0,
    });
    // 겹쳐 볼 코인 (얇은 실선, 코인마다 색)
    const extra = (st.extra || []).filter(x => x.rows.some(Boolean));
    extra.forEach(x => datasets.push({
        label: x.label, data: shift(x.rows.map(p => (p ? p.rate : null))), spanGaps: true,
        borderColor: x.color, borderWidth: x.width || 1.4, borderDash: x.dash ? [6, 4] : undefined,
        pointRadius: 0, pointHoverRadius: 4, pointBackgroundColor: x.color, fill: false, tension: 0,
    }));
    dataset.label = ov ? ov.mine : (extra.length ? (st.mineLabel || '보유코인') : '수익률');
    // 다른 선과 함께 볼 때(코인 겹쳐 보기 · 출발점 맞추기)는 보유코인 선을 한 색으로 — 빨강/파랑(손익 색)이 코인 선 색과 섞이지 않게
    const MINE = '#1e293b';
    if (extra.length || align) {
        dataset.segment = undefined;
        dataset.borderColor = MINE;
        dataset.pointBackgroundColor = MINE;
        dataset.borderWidth = 2.2;
        dataset.fill = { target: 'origin', above: 'rgba(30, 41, 59, 0.06)', below: 'rgba(30, 41, 59, 0.06)' };
    }
    const mineIcon = (extra.length || align) ? ` style="border-top-color:${MINE}"` : '';
    const legend = document.getElementById(st.legendId || '');
    const lastOf = (arr) => [...arr].reverse().find(v => v !== null && v !== undefined);
    const extraHtml = extra.map(x => {
        const last = lastOf(shift(x.rows.map(p => (p ? p.rate : null))));
        return `<span class="pl-coin"><i style="border-top-color:${x.color}${x.dash ? ';border-top-style:dashed' : ''}"></i>${escapeHtml(x.label)} <b class="${pnlClass(last)}">${last === undefined ? '-' : fmtV(last)}</b></span>`;
    }).join('');
    if (legend && !ov && extra.length) {
        const lastBot = rates[rates.length - 1];
        legend.classList.remove('d-none');
        legend.innerHTML = `<span class="pl-bot"><i${mineIcon}></i>${escapeHtml(dataset.label)} <b class="${pnlClass(lastBot)}">${fmtV(lastBot)}</b></span>` + extraHtml;
    } else if (legend) {
        legend.classList.toggle('d-none', !ov);
        if (ov) {
            const lastBot = rates[rates.length - 1], lastHold = lastOf(shift(hold.map(p => (p ? p.rate : null))));
            const diff = lastHold === undefined ? null : lastBot - lastHold;
            legend.innerHTML = `<span class="pl-bot"><i${mineIcon}></i>${escapeHtml(ov.mine)} <b class="${pnlClass(lastBot)}">${fmtV(lastBot)}</b></span>`
                + `<span class="pl-hold"><i style="border-top-color:${ov.color}"></i>${escapeHtml(ov.label)} <b class="${pnlClass(lastHold)}">${lastHold === undefined ? '-' : fmtV(lastHold)}</b></span>`
                + (diff === null ? '' : `<span class="pl-diff" title="비교선은 ${ov.from ? escapeHtml(ov.from) : '그래프 맨 왼쪽 시각'}에 ${escapeHtml(ov.mine)}와 같은 값에서 출발 → 차이 = 그때부터 지금까지 ${escapeHtml(ov.mine)} − ${escapeHtml(ov.label)}">${ov.from ? `${escapeHtml(ov.from)}부터 ` : ''}차이 <b class="${pnlClass(diff)}">${diff >= 0 ? '+' : ''}${diff.toFixed(2)}%p</b></span>`)
                + extraHtml;
        }
    }

    if (st.chart) {
        st.chart.data.labels = labels;
        st.chart.data.datasets = datasets;
        st.chart.$points = points;
        st.chart.$overlay = ov;
        st.chart.$extra = extra;
        st.chart.$align = align;
        st.chart.update('none');
        return;
    }

    st.chart = new Chart(canvas, {
        type: 'line',
        data: { labels, datasets },
        options: bigIf(canvas.id === 'pnl-big-chart', {
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
                legend: { display: false },
                tooltip: {
                    displayColors: false,
                    callbacks: {
                        label: (ctx) => `${ctx.dataset.label} ${ctx.chart.$align ? `${ctx.parsed.y >= 0 ? '+' : ''}${ctx.parsed.y.toFixed(2)}%` : formatChangeRate(ctx.parsed.y)}`,
                        afterLabel: (ctx) => {
                            if (ctx.datasetIndex > 0) {
                                const ov = ctx.chart.$overlay;
                                if (ov && ctx.datasetIndex === 1) {
                                    const r = ov.rows?.[ctx.dataIndex];
                                    return r && ov.note ? ov.note(r) : '';
                                }
                                const x = (ctx.chart.$extra || [])[ctx.datasetIndex - (ov ? 2 : 1)];
                                const r = x?.rows?.[ctx.dataIndex];
                                if (r && x.note) return x.note(r);
                                return r ? `평가 ${formatKrw(r.value)} / 투자 ${formatKrw(r.buy)}` : '';
                            }
                            const pt = ctx.chart.$points[ctx.dataIndex];
                            return pt ? `평가 ${formatKrw(pt.value)} / 투자 ${formatKrw(pt.buy)}` : '';
                        },
                    },
                },
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { color: '#6c757d', maxTicksLimit: 8, maxRotation: 0, autoSkip: true },
                },
                y: {
                    // 0% 선만 진하게
                    grid: { color: (ctx) => (ctx.tick && ctx.tick.value === 0 ? '#adb5bd' : '#eef0f3') },
                    // 눈금 간격에 맞춘 자릿수로 통일 (간격 0.05 → 소수 2자리, 최대 3자리)
                    // 그대로 쓰면 -29.450000000000003% 같은 계산 오차가 보임
                    ticks: {
                        color: '#6c757d',
                        callback: function (v, i, ticks) {
                            const step = ticks.length > 1 ? Math.abs(ticks[1].value - ticks[0].value) : 1;
                            const digits = Math.min(3, Math.max(0, Math.ceil(-Math.log10(step) - 1e-9)));
                            return this.chart.$align ? `${v > 0 ? '+' : ''}${Number(v).toFixed(digits)}%` : `${Number(v).toFixed(digits)}%`;
                        },
                    },
                },
            },
        }),
    });
    st.chart.$points = points;
    st.chart.$overlay = ov;
    st.chart.$extra = extra;
    st.chart.$align = align;
}

// ── 전용 툴팁: 브라우저 기본 말풍선(title) 대신, 보유 코인 탭 안의 설명을 크고 보기 좋게 ──
// title 속성(또는 SVG <title>)을 가진 요소에 마우스를 올리면 그 내용을 툴팁으로 보여줌
// 내용 형식: 첫 줄 = 제목(굵게), 나머지 = 내용, '(누르면 …)'으로 시작하는 줄 = 안내(작게)
function setupTooltips() {
    const scopes = ['positions', 'markets'].map(id => document.getElementById(id)).filter(Boolean);
    if (scopes.length === 0) return;
    const tip = document.createElement('div');
    tip.className = 'ui-tip';
    tip.setAttribute('role', 'tooltip');
    document.body.appendChild(tip);
    let current = null;

    // title은 브라우저 말풍선이 같이 뜨지 않도록 data-tip으로 옮김
    const takeText = (el) => {
        if (el.hasAttribute('title')) {
            el.dataset.tip = el.getAttribute('title');
            el.removeAttribute('title');
        }
        const svgTitle = el.tagName.toLowerCase() === 'svg' && el.querySelector('title');
        if (svgTitle) {
            el.dataset.tip = svgTitle.textContent;
            svgTitle.remove();
        }
        return el.dataset.tip;
    };

    const show = (el) => {
        const text = takeText(el);
        if (!text) return;
        current = el;
        tip.innerHTML = '';
        text.split('\n').filter(Boolean).forEach((line, i) => {
            const div = document.createElement('div');
            div.className = line.startsWith('(누르면') ? 'ui-tip-hint' : i === 0 ? 'ui-tip-title' : 'ui-tip-line';
            div.textContent = line;
            tip.appendChild(div);
        });
        // 배지면 왼쪽 띠를 배지 색으로 (검정 상폐 배지는 어두운 툴팁에 묻혀서 중간 회색)
        const accent = el.classList.contains('mk-delist') ? '#9ca3af'
            : el.classList.contains('mk-badge') ? getComputedStyle(el).backgroundColor : '';
        tip.style.setProperty('--tip-accent', accent || '#6b7280');

        // 위치: 요소 아래 가운데. 아래 공간이 모자라고 위가 더 넓으면 위. 화면 밖으로 나가지 않게
        tip.classList.add('show');
        const r = el.getBoundingClientRect();
        const w = tip.offsetWidth, h = tip.offsetHeight, gap = 8;
        const spaceBelow = window.innerHeight - r.bottom, spaceAbove = r.top;
        const below = spaceBelow >= h + gap || spaceBelow >= spaceAbove;
        const left = Math.min(Math.max(8, r.left + r.width / 2 - w / 2), window.innerWidth - w - 8);
        tip.style.left = `${left}px`;
        tip.style.top = `${below ? r.bottom + gap : Math.max(8, r.top - gap - h)}px`;
        tip.classList.toggle('above', !below);
        tip.style.setProperty('--arrow-x', `${Math.min(Math.max(12, r.left + r.width / 2 - left), w - 12)}px`);
    };

    const hide = () => {
        current = null;
        tip.classList.remove('show');
    };

    scopes.forEach(scope => {
        scope.addEventListener('mouseover', (e) => {
            const el = e.target.closest('[title], [data-tip], svg.sparkline');
            if (!el || !scope.contains(el)) return;
            if (el !== current) show(el);
        });
        scope.addEventListener('mouseout', (e) => {
            if (current && !current.contains(e.relatedTarget)) hide();
        });
    });
    window.addEventListener('scroll', hide, true);
}

// ── 보유 현황 매도: 확인 창에서 비율/수량을 고르고 시장가로 판다 (실제 업비트 계좌) ──
const UPBIT_FEE = Number(document.body.dataset.exFee) || 0.0005;       // 이 모드 거래소 수수료 (업비트 0.05% · 빗썸은 설정 값)
const MIN_ORDER_KRW = 5000;     // 업비트 최소 주문금액
let sellTarget = null;          // 확인 창에 띄운 코인
let sellRatio = null;           // 비율 버튼으로 고른 값 (1이면 전량 → 서버가 실제 잔고 전부)

function setupSellModal() {
    const modalEl = document.getElementById('sell-modal');
    if (!modalEl) return;
    // 보유 현황·저점수익률 표의 [매수][매도] 버튼 (같은 확인 창)
    const onHoldingsOrderClick = (e) => {
        const sellBtn = e.target.closest('.btn-sell');
        const buyBtn = e.target.closest('.btn-market-buy');
        const btn = sellBtn || buyBtn;
        if (!btn) return;
        const asset = holdingsAssets.find(a => a.currency === btn.dataset.currency);
        if (!asset) return;
        if (sellBtn) openSellModal(asset);
        else openBuyModal(asset);  // 추가 매수: 전체코인 분석과 같은 매수 확인 창
    };
    document.getElementById('holdings-tbody')?.addEventListener('click', onHoldingsOrderClick);
    modalEl.querySelectorAll('[data-ratio]').forEach(btn => {
        btn.addEventListener('click', () => setSellQuantity(Number(btn.dataset.ratio)));
    });
    document.getElementById('sell-qty').addEventListener('input', () => {
        sellRatio = null;
        modalEl.querySelectorAll('[data-ratio]').forEach(b => b.classList.remove('active'));
        updateSellPreview();
    });
    document.getElementById('sell-confirm').addEventListener('click', submitSell);
}

function sellAvailable(a) {
    return Math.max(Number(a.balance) - Number(a.locked || 0), 0);
}

function openSellModal(a) {
    sellTarget = a;
    document.getElementById('sell-title').textContent = `${a.korean_name}(${a.currency}) 매도`;
    document.getElementById('sell-available').textContent = `${sellAvailable(a).toLocaleString(undefined, { maximumFractionDigits: 8 })} ${a.currency}`;
    document.getElementById('sell-price').textContent = formatPrice(a.current_price);
    document.getElementById('sell-error').textContent = '';
    setSellQuantity(1);
    bootstrap.Modal.getOrCreateInstance(document.getElementById('sell-modal')).show();
}

function setSellQuantity(ratio) {
    sellRatio = ratio;
    const qty = sellAvailable(sellTarget) * ratio;
    // 소수 8자리까지 (업비트 수량 단위), 버림으로 보유량을 넘지 않게
    document.getElementById('sell-qty').value = String(Math.floor(qty * 1e8) / 1e8);
    document.querySelectorAll('#sell-modal [data-ratio]').forEach(b => b.classList.toggle('active', Number(b.dataset.ratio) === ratio));
    updateSellPreview();
}

// 예상 금액·손익과 주문 가능 여부
function updateSellPreview() {
    const a = sellTarget;
    const qty = Number(document.getElementById('sell-qty').value) || 0;
    const gross = qty * a.current_price;
    const net = gross * (1 - UPBIT_FEE);
    const pnl = net - qty * a.avg_buy_price;
    const pnlRate = a.avg_buy_price > 0 ? pnl / (qty * a.avg_buy_price) * 100 : 0;

    document.getElementById('sell-amount').textContent = qty > 0 ? `약 ${formatKrw(net)}` : '-';
    const pnlEl = document.getElementById('sell-pnl');
    pnlEl.textContent = qty > 0 ? `${pnl > 0 ? '+' : ''}${formatKrw(pnl)} (${formatChangeRate(pnlRate)})` : '-';
    pnlEl.className = `fw-bold ${pnlClass(pnl)}`;

    let problem = '';
    if (qty <= 0) problem = '매도할 수량을 입력해 주십시오.';
    else if (qty > sellAvailable(a) * (1 + 1e-9)) problem = '주문 가능 수량보다 많습니다.';
    else if (gross < MIN_ORDER_KRW) problem = `최소 주문금액은 5,000원입니다 (지금 약 ${formatKrw(gross)}).`;
    document.getElementById('sell-hint').textContent = problem;
    document.getElementById('sell-confirm').disabled = !!problem;
}

async function submitSell() {
    const a = sellTarget;
    const btn = document.getElementById('sell-confirm');
    const errorEl = document.getElementById('sell-error');
    const qty = Number(document.getElementById('sell-qty').value) || 0;
    const body = sellRatio === 1 ? { currency: a.currency, ratio: 1 } : { currency: a.currency, quantity: qty };

    btn.disabled = true;
    btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span> 주문 중...';
    errorEl.textContent = '';
    try {
        const response = await fetch('/api/holdings/sell', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body),
        });
        const data = await response.json();
        if (!data.success) throw new Error(data.error || '매도 실패');

        bootstrap.Modal.getOrCreateInstance(document.getElementById('sell-modal')).hide();
        showNotification(`${a.korean_name} ${Number(data.quantity).toLocaleString(undefined, { maximumFractionDigits: 8 })}개 시장가 매도 주문을 보냈습니다`, 'success');
        reloadHoldingsAfterOrder(qtyChanged(a.currency, Number(a.balance) || 0));   // 체결이 잔고에 반영될 때까지
    } catch (error) {
        errorEl.textContent = error.message;
    } finally {
        btn.innerHTML = '시장가 매도';
        updateSellPreview();
    }
}

// ── 전체코인 분석 탭: 업비트 원화 마켓 전체 (API 키 필요 없음) ──
let marketCoins = [];
let marketsQuery = '';
let marketsLoadedAt = 0;
let marketLowsLoading = false;
let marketsRefreshTimer = null;
let heldCurrencies = null;   // 내 보유 코인 (보유코인 분석을 안 열었으면 한 번 따로 조회)

function setupMarketsTab() {
    document.getElementById('markets-tab')?.addEventListener('shown.bs.tab', () => {
        // 30초 지났으면 새로 (조건 검색 탭을 보고 있으면 조건 검색이 시세까지 함께 불러옴)
        if (screenPaneActive()) loadScreen();
        else if (Date.now() - marketsLoadedAt > 30000) loadMarkets();
        // 탭이 보이는 동안 30초마다 시세 갱신 (전일대비 등이 업비트 화면과 맞게)
        clearInterval(marketsRefreshTimer);
        marketsRefreshTimer = setInterval(async () => {
            await loadMarkets(true);
        }, 30000);
    });
    document.getElementById('markets-tab')?.addEventListener('hidden.bs.tab', () => clearInterval(marketsRefreshTimer));
    // 새로고침: 보고 있는 하위 탭 기준
    document.getElementById('btn-refresh-markets')?.addEventListener('click', () => (screenPaneActive() ? loadScreen(true) : loadMarkets()));
    // 주소(#markets)로 이미 열린 상태면 바로 조회 (탭 전환 이벤트가 연결보다 먼저 지나감)
    if (document.getElementById('markets')?.classList.contains('active')) loadMarkets();
    [['markets-table', 'markets'], ['holdings-table', 'holdings']].forEach(([tableId, name]) => {
        document.querySelector(`#${tableId} thead`)?.addEventListener('click', (e) => {
            const th = e.target.closest('th.metric-th[data-sort]');
            if (!th) return;
            const t = sortableTables[name];
            const key = th.dataset.sort;
            t.sort = t.sort.key === key ? { key, dir: t.sort.dir === 'asc' ? 'desc' : 'asc' } : { key, dir: 'desc' };
            if (t.hasData()) t.render();
        });
    });
    document.getElementById('markets-search')?.addEventListener('input', (e) => {
        marketsQuery = e.target.value;
        if (marketCoins.length) renderMarketsRows();
    });
}

async function getHeldCurrencies() {
    if (holdingsAssets.length) return new Set(holdingsAssets.filter(a => !a.is_delisted).map(a => a.currency));
    if (heldCurrencies) return heldCurrencies;
    try {
        const data = await fetchHoldingsShared();
        heldCurrencies = new Set(data.success ? data.holdings.assets.filter(a => !a.is_delisted).map(a => a.currency) : []);
    } catch (e) {
        heldCurrencies = new Set();  // API 키가 없는 등: 보유 표시만 빠짐
    }
    return heldCurrencies;
}

async function loadMarkets(quiet = false) {
    const summary = document.getElementById('markets-summary');
    if (!summary) return;
    if (!marketCoins.length) showTableMessage('markets-tbody', 14, '불러오는 중...');
    if (!quiet) summary.textContent = '불러오는 중...';
    try {
        const [data, held] = await Promise.all([(await fetch('/api/markets')).json(), getHeldCurrencies()]);
        if (!data.success) throw new Error(data.error || '조회 실패');

        marketCoins = data.coins.map(c => ({
            ...c,
            alert_level: alertLevel(c),
            held: held.has(c.currency) ? 1 : 0,
        }));
        // '거래대금 상위' 조건용 순위 (파이썬 get_market_data 와 같은 방식)
        [...marketCoins].filter(c => c.trade_value_24h).sort((x, y) => y.trade_value_24h - x.trade_value_24h)
            .forEach((c, i) => { c.value_rank = i + 1; });
        marketsLoadedAt = Date.now();

        renderMarketsSummary(summary);
        renderMarketOverview();
        renderMarketsRows();
        if (lastNoticeHoldings) renderHoldingsAlerts(lastNoticeHoldings);   // 공지는 전체 코인 기준이라 시세가 오면 다시
        loadMarketPeriodLows();
    } catch (error) {
        summary.textContent = '';
        showTableMessage('markets-tbody', 14, '전체 코인 조회 오류: ' + error.message);
    }
}

// 이미 받는 중이면 그 작업이 끝날 때까지 기다림 (조건 검색 탭이 완전한 데이터로 계산하도록)
let marketLowsPromise = null;
function loadMarketPeriodLows() {
    if (marketLowsLoading && marketLowsPromise) return marketLowsPromise;
    marketLowsPromise = loadMarketPeriodLowsNow();
    return marketLowsPromise;
}

async function loadMarketPeriodLowsNow() {
    if (marketLowsLoading) return;
    const status = document.getElementById('markets-lows-status');
    const all = marketCoins.map(c => `KRW-${c.currency}`);
    const missing = all.filter(m => !periodLows[m]);
    const hourlyStale = Date.now() - hourlyLoadedAt > 10 * 60 * 1000 || all.some(m => !hourlyData[m]);
    if (missing.length === 0 && !hourlyStale) return;

    marketLowsLoading = true;
    renderMarketsRows();
    try {
        for (let i = 0; i < missing.length; i += 50) {
            if (status) status.textContent = `⏳ 기간 시세 ${all.length - missing.length + i}/${all.length}개 불러옴 (하루 첫 조회만 느립니다)`;
            const chunk = missing.slice(i, i + 50);
            const data = await (await fetch(`/api/holdings/period-lows?markets=${encodeURIComponent(chunk.join(','))}`)).json();
            if (data.success) { Object.assign(periodLows, data.lows); condDataVersion++; }
            renderMarketsRows();
        }
        if (status && hourlyStale) status.textContent = '⏳ 24시간 시세 불러오는 중…';
        await loadHourlyFor(all, renderMarketsRows);
        if (status) status.textContent = '';
    } catch (error) {
        console.error('전체 코인 기간 시세 오류:', error);
        if (status) status.textContent = '⚠ 일부 기간 시세를 불러오지 못했습니다. 새로고침을 눌러 다시 시도하십시오.';
    } finally {
        marketLowsLoading = false;
        renderMarketsRows();
    }
}

// 전체코인 요약 한 줄: 상승·보합·하락 + 비율 막대 | 전체 · 알림 있는 코인 · 내 보유
function renderMarketsSummary(summary) {
    const total = marketCoins.length;
    const up = marketCoins.filter(c => c.change_rate > 0).length;
    const down = marketCoins.filter(c => c.change_rate < 0).length;
    const flat = total - up - down;
    const pct = (n) => (total ? n / total * 100 : 0);
    summary.innerHTML = `
        <div class="mk-breadth" title="전일 종가(오전 9시) 대비">
            <span class="mk-label">오늘</span>
            <span class="mk-num pnl-up">상승 ${up}</span><span class="mk-dot">·</span>
            <span class="mk-num text-secondary">보합 ${flat}</span><span class="mk-dot">·</span>
            <span class="mk-num pnl-down">하락 ${down}</span>
            <div class="breadth-bar mk-bar" role="img" aria-label="상승 ${up}개, 보합 ${flat}개, 하락 ${down}개">
                <span class="breadth-up" style="width:${pct(up)}%" title="상승 ${up}개 (${pct(up).toFixed(0)}%)"></span><span class="breadth-flat" style="width:${pct(flat)}%" title="보합 ${flat}개"></span><span class="breadth-down" style="width:${pct(down)}%" title="하락 ${down}개 (${pct(down).toFixed(0)}%)"></span>
            </div>
        </div>
        <div class="mk-stat"><span class="mk-label">전체</span><b>${total}</b>개</div>
        <div class="mk-stat"><span class="mk-label">알림 있는 코인</span><b>${marketCoins.filter(c => c.alert_level > 0).length}</b>개</div>
        <div class="mk-stat"><span class="mk-label">내 보유</span><b>${marketCoins.filter(c => c.held).length}</b>개</div>`;
}

// 전체코인 표의 조건별 칸: 조건 검색이 켜져 있으면 그 조건의 칸(급등일·RSI 등)을 추이 칸 뒤에 넣음
// 표마다 정렬을 조건 기본값으로 맞춘 조건 (조건이 바뀌면 그 조건의 기본 정렬로, 끄면 표 기본 정렬로)
const metricSortPreset = { markets: null, holdings: null };
const TABLE_DEFAULT_SORT = { markets: { key: 'trade_value_24h', dir: 'desc' }, holdings: { key: 'current_value', dir: 'desc' } };
function marketsMetricColumns() {
    return metricColumnsFor('markets', 'markets-spark-header');
}
// 조건 검색이 켜져 있으면 추이 칸 뒤에 그 조건의 칸(급등일·RSI·최고가까지 등) 머리줄을 넣고 칸 목록을 돌려줌
function metricColumnsFor(name, sparkThId) {
    const t = sortableTables[name];
    const preset = screenOn && marketCoins.length ? (SCREEN_PRESETS.find(x => x.id === screenPresetId) || SCREEN_PRESETS[0]) : null;
    const presetId = preset ? preset.id : null;
    if (presetId !== metricSortPreset[name]) {
        t.sort = preset ? { key: preset.sortKey, dir: preset.sortDir } : { ...TABLE_DEFAULT_SORT[name] };
        metricSortPreset[name] = presetId;
    }
    const sparkTh = document.getElementById(sparkThId);
    sparkTh?.parentElement.querySelectorAll('.metric-th').forEach(th => th.remove());
    const columns = preset ? preset.columns : [];
    let after = sparkTh;
    columns.forEach(([key, label], i) => {
        const th = document.createElement('th');
        th.className = `text-end metric-th${i === 0 ? ' grp' : ''}`;
        th.dataset.sort = key;
        th.textContent = label;
        th.style.cursor = 'pointer';
        th.title = '조건 검색 칸 · 클릭하여 정렬';
        after.after(th);
        after = th;
    });
    updateSortIcons(t);
    return columns;
}

// 조건별 칸 값 (퍼센트는 오르면 빨강·내리면 파랑)
function metricCellsHtml(columns, c) {
    return columns.map(([k], i) => {
        const v = c ? c[k] : null;
        const cls = /rate|drop|dip|rebound|gap|over|from_high|__pct/.test(k) ? pnlClass(v) : '';
        return `<td class="text-end text-nowrap metric-cell ${cls}${i === 0 ? ' grp' : ''}">${v === null || v === undefined ? '-' : (SCREEN_FORMAT[k] ? SCREEN_FORMAT[k](v) : v)}</td>`;
    }).join('');
}

function renderMarketsRows() {
    applyTradeFlow(marketCoins);
    if (mkOv.metric !== 'change_rate' || mkOv.distMetric !== 'change_rate') renderMarketOverview();   // 저점 기준을 보고 있으면 기간 시세가 들어올 때 같이
    const t = sortableTables.markets;
    const realTbody = document.getElementById(t.tbody);
    const hits = screenHitSet();
    const columns = marketsMetricColumns();
    const colCount = 15 + columns.length;
    // 조건이 켜져 있으면 조건 계산값(급등일 등)이 붙은 코인으로
    const source = hits ? marketCoins.map(c => screenHitMemo.map.get(c.currency)).filter(Boolean) : marketCoins;
    const shown = source.filter(c => matchesQuery(c, marketsQuery));
    const tbody = beginRows(realTbody);
    if (shown.length === 0) {
        const row = document.createElement('tr');
        row.innerHTML = `<td colspan="${colCount}" class="text-center py-4 text-muted"></td>`;
        row.firstElementChild.textContent = hits && !hits.size ? '지금은 이 조건에 맞는 코인이 없습니다. 조건 숫자를 바꿔 보십시오.'
            : `'${marketsQuery.trim()}' 검색 결과가 없습니다`;
        tbody.appendChild(row);
    }
    marketCoins.forEach(computeLowRates);
    // 추이 그래프 기간 (정렬 중인 열 기준) → 열 이름에도 표시
    const spark = SPARK_BY_SORT[t.sort.key] || SPARK_DEFAULT;
    const sparkHeader = document.getElementById('markets-spark-header');
    if (sparkHeader) sparkHeader.textContent = trendLabel(spark);

    const makeRow = (c) => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td class="sel-cell"><input type="checkbox" class="form-check-input row-sel" data-currency="${c.currency}" aria-label="선택"></td>
            <td class="alert-cell"></td>
            <td class="text-nowrap"><strong class="coin-name"></strong> <small class="text-muted coin-code"></small></td>
            <td class="spark-cell"></td>
            ${metricCellsHtml(columns, c)}
            <td class="text-end">${formatPrice(c.current_price)}</td>
            <td class="text-end ${pnlClass(c.change_rate)}">${formatChangeRate(c.change_rate)}</td>
            ${lowRateCells(c, marketLowsLoading)}
            <td class="text-end text-muted grp">${formatTradeValue(c.trade_value_24h)}</td>
            ${flowCellHtml(c)}
            <td class="text-center">${c.held ? '<i class="bi bi-star-fill text-warning" title="내가 보유한 코인"></i>' : ''}</td>
            <td class="text-end order-cell">
                <button type="button" class="btn btn-sm btn-outline-danger btn-market-buy" data-currency="${c.currency}">매수</button>
                ${c.held
                    ? `<button type="button" class="btn btn-sm btn-outline-primary btn-market-sell" data-currency="${c.currency}">매도</button>`
                    : '<span class="d-inline-block" title="보유하지 않은 코인입니다"><button type="button" class="btn btn-sm btn-outline-secondary" disabled>매도</button></span>'}
            </td>
        `;
        row.querySelector('.coin-name').textContent = c.korean_name;
        row.querySelector('.coin-code').textContent = c.currency;
        row.querySelector('.alert-cell').append(...createMarketBadges(c));
        row.querySelector('.coin-name').parentElement.prepend(createCoinLogo(c.currency));
        fillTrendCell(row.querySelector('.spark-cell'), c, spark, marketLowsLoading);
        return row;
    };
    appendRowsChunked(tbody, sortAssets(shown, t.sort), makeRow, () => { finishRows(realTbody, tbody); syncSelection('markets'); highlightSortedColumn(t); });
    syncSelection('markets');
    highlightSortedColumn(t);
    // 조건 카드와 조건 목록(개수)도 같은 데이터로
    renderScreenResults();
    renderScreenList();
}

// ── 거래 내역 탭: 매수·매도 체결 한 건마다 한 줄 + 입금·출금 ──
// 매수·매도는 프로그램의 거래 기록 저장소에서 기간 · 종류 · 코인으로 걸러 최신 500건씩(쪽) 받고, 아래로 내리면 다음 쪽 — 기록이 아무리 많아도 빠름
// 입금·출금은 기간 전체를 한 번에 (몇 건 안 됨)
let tradeRows = [];             // 받은 매수·매도 줄 (최신순)
let tradeTotal = 0;             // 조건에 맞는 매수·매도 전체 수 (서버가 셈)
let tradeNext = null;           // 다음 쪽 커서 (null = 끝)
let tradeDays = 7;              // 처음엔 최근 1주일
let tradeKind = 'ALL';
let tradeQuery = '';
let tradeBot = 'ALL';           // 'ALL' · 봇 id · 'none'(직접 주문)
let tradesLoading = false;
let tradeReasonsOn = true;      // 프로그램이 봇 · 이유를 붙여 주는지 (예전 프로그램이 돌고 있으면 false)
let tradeReqId = 0;             // 마지막 요청 번호 (조건을 빨리 바꿀 때 늦게 온 옛 답은 버림)
let transferRows = [];
let transfersLoadedDays = 0;
const TRADE_PAGE = 500;

function setupTradesTab() {
    // 탭을 열 때마다 새로 (처음 연 뒤 봇이 사고판 것이 안 보이던 문제) — 보던 표는 그대로 두고 바꿔 끼움
    document.getElementById('trades-tab')?.addEventListener('shown.bs.tab', () => loadTradeHistory(tradeRows.length + transferRows.length > 0));
    document.getElementById('btn-refresh-trades')?.addEventListener('click', () => loadTradeHistory(true));
    document.getElementById('btn-trades-csv')?.addEventListener('click', downloadTradesCsv);
    // 시뮬레이션 거래 내역 지우기 (지금부터만 보이게)
    document.getElementById('btn-trades-clear')?.addEventListener('click', async () => {
        if (!IS_SIM) return;
        if (!(await uiConfirm({ title: '시뮬레이션 거래 내역을 지우시겠습니까?', okText: '지우기', tone: 'danger', icon: 'bi-eraser', message: ''
            + '· 거래 내역 화면이 비고, 지금부터 새로 쌓입니다\n'
            + '· 가상 계좌 잔고 · 보유 코인 · 실행 중인 봇은 그대로입니다\n'
            + '· 봇 성적 · 매매 내역 · 수익률 그래프도 그대로입니다 (봇마다 처음부터 하려면 봇 화면의 [모두 팔고 새로 시작])' }))) return;
        try {
            const d = await (await fetch('/api/trade-history/clear', { method: 'POST' })).json();
            showNotification(d.message || d.error, d.success ? 'success' : 'error');
            if (!d.success) return;
            try { localStorage.removeItem(TRADE_CACHE_KEY); } catch (e) { /* 무시 */ }
            tradeRows = []; transferRows = []; transfersLoadedDays = 0;
            loadTradeHistory(true);
        } catch (e) { showNotification('지우지 못했습니다: ' + e.message, 'error'); }
    });
    document.querySelectorAll('#trades-period [data-days]').forEach(btn => btn.addEventListener('click', () => {
        document.querySelectorAll('#trades-period [data-days]').forEach(b => b.classList.toggle('active', b === btn));
        tradeDays = Number(btn.dataset.days);
        loadTradeHistory();
    }));
    document.querySelectorAll('#trades-kind [data-kind]').forEach(btn => btn.addEventListener('click', () => {
        document.querySelectorAll('#trades-kind [data-kind]').forEach(b => b.classList.toggle('active', b === btn));
        tradeKind = btn.dataset.kind;
        loadTradeHistory();
    }));
    // 봇 태그: 누르면 그 봇이 사고판 것만 (전체 · 봇마다 · 직접 주문)
    document.getElementById('trades-bot')?.addEventListener('click', (e) => {
        const b = e.target.closest('[data-trade-bot]');
        if (!b || b.dataset.tradeBot === tradeBot) return;
        tradeBot = b.dataset.tradeBot;
        renderTradeBotTags();
        loadTradeHistory();
    });
    let typing = null;                                            // 입력이 0.3초 멈추면 서버에서 다시 거름
    document.getElementById('trades-search')?.addEventListener('input', (e) => {
        tradeQuery = e.target.value;
        clearTimeout(typing);
        typing = setTimeout(() => loadTradeHistory(), 300);
    });
    if (document.getElementById('trades')?.classList.contains('active')) loadTradeHistory();
}

// 거래 내역 '봇' 태그 줄 (봇 목록이 바뀌어도 맞게 — 내역을 받을 때마다 다시 그림)
function renderTradeBotTags() {
    const box = document.getElementById('trades-bot');
    if (!box) return;
    const bots = botsList.filter(b => !(b.example && !IS_SIM));
    if (tradeBot !== 'ALL' && tradeBot !== 'none' && !bots.some(b => b.id === tradeBot)) tradeBot = 'ALL';   // 지운 봇
    const tag = (id, label, color = '', tip = '') => `<button type="button" class="tb-tag${tradeBot === id ? ' active' : ''}" data-trade-bot="${escapeHtml(id)}"${color ? ` style="--c:${color}"` : ''}${tip ? ` title="${escapeHtml(tip)}"` : ''} aria-pressed="${tradeBot === id}">${color ? '<i class="tb-dot"></i>' : ''}${escapeHtml(label)}</button>`;
    box.innerHTML = tag('ALL', '전체')
        + bots.map(b => tag(b.id, b.name || '봇', botColorByName(b.name), `${b.name} 이 사고판 것만`)).join('')
        + tag('none', '직접 주문', '', '봇 기록에 없는 주문 (업비트 앱이나 이 화면에서 직접 사고판 것 등)');
}

// 2026.09.25 04:32 (KST)
function formatKstTime(iso) {
    if (!iso) return '-';
    const d = new Date(new Date(iso).getTime() + 9 * 3600 * 1000);
    const p = (n) => String(n).padStart(2, '0');
    return `${d.getUTCFullYear()}.${p(d.getUTCMonth() + 1)}.${p(d.getUTCDate())} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;
}

// 지금 조건 → 서버에 보낼 값 (코인 검색: 이름 · 초성으로 맞는 심볼들 + 입력한 글자 그대로)
function tradeQueryParams() {
    const p = new URLSearchParams({ days: tradeDays, limit: TRADE_PAGE });
    if (tradeKind === '매수' || tradeKind === '매도') p.set('kind', tradeKind);
    if (tradeBot !== 'ALL') p.set('bot', tradeBot);
    const q = tradeQuery.trim();
    if (q) {
        const codes = new Set();
        for (const c of [...marketCoins, ...holdingsAssets]) if (c?.currency && matchesQuery(c, q)) codes.add(c.currency);
        p.set('coins', [...codes].slice(0, 300).join(','));
        p.set('q', q);
    }
    return p;
}

// 이 PC에 저장해 둔 첫 쪽 (모드마다 · 조건이 같을 때만) — 다음에 탭을 열면 이것부터 바로 보여 줌. 최대 500건이라 브라우저 저장 한도 걱정 없음
const TRADE_CACHE_KEY = `strabot.tradePage.${APP_MODE}`;
function saveTradeCache(key) {
    try { localStorage.setItem(TRADE_CACHE_KEY, JSON.stringify({ at: Date.now(), key, rows: tradeRows.slice(0, TRADE_PAGE), total: tradeTotal, next: tradeNext, transfers: transferRows, tdays: transfersLoadedDays })); } catch (e) { /* 저장 못 해도 화면은 그대로 */ }
}
function readTradeCache(key) {
    try {
        const c = JSON.parse(localStorage.getItem(TRADE_CACHE_KEY) || 'null');
        return c && c.key === key && Array.isArray(c.rows) ? c : null;
    } catch (e) { return null; }
}
try { localStorage.removeItem('strabot.tradeRows.sim'); localStorage.removeItem('strabot.tradeRows.upbit'); } catch (e) { /* 예전 저장본(2만 줄) 정리 */ }

// 거래내역을 마지막으로 새로 받은 때 (오른쪽 위 '업데이트' 시각) — 저장본을 보여 줄 땐 저장한 때
let tradesUpdatedAt = null;
function stampText(ms) {
    const d = new Date(ms), p = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}.${p(d.getMonth() + 1)}.${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}
// 오른쪽 위: [건수] [🕘 업데이트 오늘 02:39:56] (+ 상태) — 건수와 시각을 따로 묶어 한눈에
function tradesSummaryHtml(n, tail = '') {
    let when = '';
    if (tradesUpdatedAt) {
        const d = new Date(tradesUpdatedAt), today = new Date();
        const p = (x) => String(x).padStart(2, '0');
        const day = d.toDateString() === today.toDateString() ? '오늘' : `${d.getMonth() + 1}월 ${d.getDate()}일`;
        when = `<span class="ts-upd" title="${stampText(tradesUpdatedAt)}에 마지막으로 받은 내역이며, [새로고침]을 누르면 새로 받습니다."><i class="bi bi-clock-history"></i><small>업데이트</small><span>${day}</span><b>${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}</b></span>`;
    }
    return `<span class="ts-count"><b>${n.toLocaleString()}</b>건</span>${when}${tail ? `<span class="ts-state">${escapeHtml(tail)}</span>` : ''}`;
}

// 거래 내역 받기: force = 새로고침 · 탭 다시 열기 (보던 표를 그대로 두고 새로 받아 바꿔 끼움), 아니면 조건이 바뀐 것 (첫 쪽부터)
async function loadTradeHistory(force = false) {
    const id = ++tradeReqId;
    renderTradeBotTags();
    tradesLoading = true;
    const note = document.getElementById('trades-note');
    const range = document.getElementById('trades-range');
    const summary = document.getElementById('trades-summary');
    const end = new Date();
    const start = new Date(end.getTime() - tradeDays * 86400000);
    if (range) range.textContent = `${formatKstTime(start.toISOString()).slice(0, 10)} ~ ${formatKstTime(end.toISOString()).slice(0, 10)}`;
    const params = tradeQueryParams(), key = params.toString();
    if (force && tradeRows.length + transferRows.length) {
        if (summary) summary.innerHTML = tradesSummaryHtml(tradeCountTotal(), '새로 불러오는 중…');
    } else {
        const c = readTradeCache(key);
        if (c) {                                                  // 같은 조건의 저장본부터 바로
            tradeRows = c.rows; tradeTotal = c.total || c.rows.length; tradeNext = c.next || null;
            transferRows = c.transfers || []; transfersLoadedDays = c.tdays || 0;
            tradesUpdatedAt = c.at || null;
            renderTradeRows(true);
            if (summary) summary.innerHTML = tradesSummaryHtml(tradeCountTotal(), '저장본 · 새 거래 확인 중…');
        } else {
            tradeRows = []; tradeTotal = 0; tradeNext = null;
            showTableMessage('trades-tbody', 12, '불러오는 중…');
            if (summary) summary.innerHTML = '';
        }
    }
    try {
        // 입출금은 기간 전체를 한 번에 (권한이 없으면 안내만)
        if (force || transfersLoadedDays < tradeDays) {
            const t = await (await fetch(`/api/transfer-history?days=${tradeDays}`)).json();
            if (id !== tradeReqId) return;
            if (!t.success) throw new Error(t.error === 'NO_API_KEY' ? `${EX_NAME} API 키가 없습니다. 설정 탭에서 API 키를 저장해 주십시오.` : (t.error || '조회 실패'));
            transferRows = t.rows;
            transfersLoadedDays = tradeDays;
            if (note) {
                note.textContent = (t.notes || []).includes('NO_DEPOSIT_SCOPE')
                    ? 'ⓘ 입금·출금 내역은 업비트 Open API 키에 \'입출금 조회\' 권한을 켜야 보입니다. (업비트 > 마이페이지 > Open API 관리)'
                    : '';
            }
        }
        // 매수·매도: 첫 쪽 (입금 · 출금만 볼 땐 받지 않음)
        if (tradeKind === '입금' || tradeKind === '출금') {
            tradeRows = []; tradeTotal = 0; tradeNext = null;
        } else {
            const d = await (await fetch(`/api/trade-history/page?${params}`)).json();
            if (id !== tradeReqId) return;
            if (!d.success) throw new Error(d.error === 'NO_API_KEY' ? `${EX_NAME} API 키가 없습니다. 설정 탭에서 API 키를 저장해 주십시오.` : (d.error || '조회 실패'));
            tradeRows = d.rows; tradeTotal = d.total; tradeNext = d.next || null;
            tradeReasonsOn = d.with_reasons !== false;
        }
        tradesUpdatedAt = Date.now();                              // 다 받은 때 = 업데이트 시각
        renderTradeRows(false, force);                             // 새로고침이면 내려 본 만큼은 그대로
        saveTradeCache(key);
    } catch (error) {
        if (id !== tradeReqId) return;
        if (!tradeRows.length) showTableMessage('trades-tbody', 12, '거래내역 조회 오류: ' + error.message);
        else showNotification('거래내역을 새로 받지 못했습니다: ' + error.message, 'error');
    } finally {
        if (id === tradeReqId) tradesLoading = false;
    }
}

// 다음 쪽 (표 맨 아래 '더 보기'가 보이면)
let tradeMoreLoading = false;
async function loadMoreTrades() {
    if (!tradeNext || tradeMoreLoading) return;
    tradeMoreLoading = true;
    const id = tradeReqId, p = tradeQueryParams();
    p.set('before', tradeNext);
    try {
        const d = await (await fetch(`/api/trade-history/page?${p}`)).json();
        if (id !== tradeReqId || !d.success) return;
        tradeRows = tradeRows.concat(d.rows);
        tradeTotal = d.total;
        tradeNext = d.next || null;
        txShownRows = filteredTradeRows();
        showMoreTradeRows();
    } catch (e) {
        showNotification('거래내역을 더 받지 못했습니다: ' + e.message, 'error');
    } finally {
        tradeMoreLoading = false;
    }
}

// 표에 보일 줄: 받은 매수·매도 + 입출금 (다음 쪽이 남아 있으면, 받은 가장 오래된 매수·매도보다 새것만 — 순서가 뒤섞이지 않게)
function filteredTradeRows() {
    const since = Date.now() - tradeDays * 86400000;
    const tr = transferRows.filter(r => tradeBot === 'ALL' && (tradeKind === 'ALL' || r.kind === tradeKind) && new Date(r.time).getTime() >= since
        && matchesQuery({ currency: r.currency, korean_name: coinKoreanName(r.currency) }, tradeQuery));
    if (tradeKind === '입금' || tradeKind === '출금') return tr;
    if (tradeKind !== 'ALL') return tradeRows;
    const oldest = tradeNext && tradeRows.length ? new Date(tradeRows[tradeRows.length - 1].time).getTime() : -Infinity;
    return tradeRows.concat(tr.filter(r => new Date(r.time).getTime() >= oldest)).sort((x, y) => new Date(y.time) - new Date(x.time));
}
// 조건에 맞는 전체 건수 = 매수·매도(서버가 셈) + 입출금
function tradeCountTotal() {
    const since = Date.now() - tradeDays * 86400000;
    const tr = transferRows.filter(r => tradeBot === 'ALL' && (tradeKind === 'ALL' || r.kind === tradeKind) && new Date(r.time).getTime() >= since
        && matchesQuery({ currency: r.currency, korean_name: coinKoreanName(r.currency) }, tradeQuery)).length;
    return (tradeKind === '입금' || tradeKind === '출금') ? tr : tradeTotal + (tradeKind === 'ALL' ? tr : 0);
}

// 코인 한글명: 보유·전체코인 목록에서 찾음 (없으면 심볼)
function coinKoreanName(currency) {
    const hit = holdingsAssets.find(a => a.currency === currency) || marketCoins.find(c => c.currency === currency);
    return hit ? hit.korean_name : currency;
}

// 봇 이름 → 색 (전체 봇 보드 · 배분 도넛과 같은 봇 색). 지운 봇처럼 목록에 없으면 이름으로 색을 고정해 고름
function botColorByName(name) {
    const list = botsList.filter(b => !(b.example && !IS_SIM));
    const i = list.findIndex(b => b.name === name);
    if (i >= 0) return BOARD_COLORS[i % BOARD_COLORS.length];
    let h = 0;
    for (const ch of String(name || '')) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
    return BOARD_COLORS[h % BOARD_COLORS.length];
}

// 봇 · 이유 칸: 봇 기록과 짝지어진 매수·매도는 봇 이름 + 조건(판 것은 손익도), 봇 기록에 없으면 '직접 주문'
function tradeReasonHtml(r) {
    if (r.kind !== '매수' && r.kind !== '매도') return '<span class="text-muted">-</span>';
    if (!r.reason && !r.bot && !tradeReasonsOn) return '<span class="tx-manual" title="StraBot을 껐다 켜면 어느 봇이 어떤 조건으로 사고팔았는지 보입니다">껐다 켜면 보입니다</span>';
    if (!r.reason && !r.bot) return '<span class="tx-manual" title="봇 기록에 없는 주문입니다 (업비트 앱이나 이 화면에서 직접 사고판 것 등)">직접 주문</span>';
    const tip = [r.bot && `봇: ${r.bot}`, r.reason && `${r.kind} 이유: ${r.reason}`, r.kind === '매도' && r.buy_reason && `산 이유: ${r.buy_reason}`]
        .filter(Boolean).join('\n');
    return `<div class="tx-why" title="${escapeHtml(tip)}">${r.bot ? `<span class="tx-bot" style="--c:${botColorByName(r.bot)}">${escapeHtml(r.bot)}</span>` : ''}<span class="tx-why-t">${escapeHtml(r.reason || '-')}</span></div>`;
}

// 결과 칸: 판 줄 = 평균 → 판 값 · 손익 · 수익률, 산 줄 = 산 값 · 산 뒤 평균 (얼마에 사서 얼마에 팔아 얼마 남았는지 한눈에)
function txResultHtml(r, avg, dec) {
    if ((r.kind !== '매수' && r.kind !== '매도') || !r.price) return '<span class="text-muted">-</span>';
    const f = (v) => Number(v).toLocaleString(undefined, { minimumFractionDigits: dec, maximumFractionDigits: dec });
    const w = (v) => `${f(v)}<span class="txrs-won">원</span>`;
    // 늘 같은 틀: [평균 매수단가] [거래단가] [손익] [수익률] — 평균 매수단가는 산 줄 = 산 뒤 평균, 판 줄 = 손익의 기준
    const cell = (cls, html) => `<span class="txrs-c ${cls}">${html}</span>`;
    const buy = r.kind === '매수';
    const hasPnl = !buy && avg && r.profit !== null && r.profit !== undefined && r.profit !== '';
    let pnlHtml = '', pctHtml = '';
    if (hasPnl) {
        const pnl = Number(r.profit), pct = Number(r.settle) - pnl > 0 ? pnl / (Number(r.settle) - pnl) * 100 : null;
        pnlHtml = `<span class="${pnlClass(pnl)}">${pnl > 0 ? '+' : ''}${formatKrw(pnl)}</span>`;
        if (pct !== null && isFinite(pct)) pctHtml = `<span class="tx-pct ${pct >= 0 ? 'is-up' : 'is-down'}">${pct >= 0 ? '▲' : '▼'} ${Math.abs(pct).toFixed(1)}%</span>`;
    }
    return '<span class="txrs-grid">' + cell('txrs-from', avg ? w(avg) : '-') + cell(`txrs-to ${buy ? 'is-buy' : 'is-sell'}`, w(r.price))
        + cell('txrs-pnl', pnlHtml) + cell('txrs-pct', pctHtml) + '</span>';
}

// 결과 칸 틀의 폭: 표에 들어온 숫자 중 가장 긴 것에 맞춤 (남는 빈칸 없이, 큰 가격도 잘리지 않게)
function fitTxResult(table) {
    if (!table || !table.offsetParent) return;          // 숨어 있으면 폭을 못 잼 → 보일 때 다시 (탭 열 때)
    const cols = ['txrs-from', 'txrs-to', 'txrs-pnl', 'txrs-pct'];
    const w = {};
    table.classList.add('txrs-measure');                // 잠깐 칸마다 내용 폭 그대로
    for (const c of cols) w[c] = Math.max(0, ...[...table.querySelectorAll(`.${c}`)].map(e => Math.ceil(e.scrollWidth) + 3));   // +3: 반올림 · 배지 여백
    table.classList.remove('txrs-measure');
    table.style.setProperty('--txrs-cols', `${w['txrs-from']}px ${w['txrs-to'] * 2 + 32}px ${w['txrs-pnl']}px ${w['txrs-pct']}px`);
}

// 거래 내역 한 줄의 칸들 (거래 내역 탭 · 봇 현황 매매 내역이 같은 모양)
const TX_HEAD = `<tr><th>체결시간</th><th>코인</th><th>마켓</th><th>종류</th><th class="txrs-head"><span class="txrs-grid">${['txrs-from|평균 매수단가', 'txrs-to|거래단가', 'txrs-pnl|손익', 'txrs-pct|수익률'].map(x => { const [c, t] = x.split('|'); return `<span class="txrs-c ${c}">${t}</span>`; }).join('')}</span></th><th class="text-end">거래금액</th><th class="text-end">수수료</th><th class="text-end">정산금액</th>
    <th>봇 · 이유</th><th class="text-end">거래수량</th><th class="text-end" title="손익을 셀 때 기준이 되는 값 · 지금까지 산 값의 평균 (업비트 매수평균가와 같은 방식)">매수평균가</th><th class="text-end">주문시간</th></tr>`;
function txRowCells(r) {
    const num = (v, digits) => (v === null || v === undefined) ? '-' : Number(v).toLocaleString(undefined, { maximumFractionDigits: digits });
    const unit = (text, u) => `${text}<span class="trade-unit">${u === 'KRW' ? '원' : escapeHtml(u)}</span>`;   // 원화는 '원'으로
    const kindClass = { '매수': 'pnl-up', '매도': 'pnl-down', '입금': 'pnl-up', '출금': 'pnl-down' };
    const kname = r.currency === 'KRW' ? '원화' : coinKoreanName(r.currency);
    // 매수평균가: 판 줄은 손익의 기준값 (받은 돈 − 손익) ÷ 수량, 산 줄은 봇 기록으로 센 산 뒤 평균 (없으면 -)
    const hasPnl = r.kind === '매도' && r.profit !== null && r.profit !== undefined && r.profit !== '' && Number(r.volume) > 0;
    // 소수점 자릿수는 이 줄 거래단가와 같게 (3.84 → 3.02, 171 → 157)
    const priceTxt = r.price ? Number(r.price).toLocaleString(undefined, { maximumFractionDigits: r.price >= 100 ? 1 : 8 }) : '';
    const avgDec = r.price ? (priceTxt.split('.')[1] || '').length : 2;
    const avg = r.avg_cost || (hasPnl ? (Number(r.settle) - Number(r.profit)) / Number(r.volume) : null);
    return `
        <td class="text-nowrap">${formatKstTime(r.time)}</td>
        <td class="text-nowrap"><span class="tr-logo" data-logo="${escapeHtml(r.currency)}"></span><strong class="coin-code-strong">${escapeHtml(kname)}</strong> <small class="text-muted coin-sym">${kname !== r.currency && r.currency !== 'KRW' ? escapeHtml(r.currency) : ''}</small></td>
        <td>${r.market === 'KRW' ? '원화' : (r.market || '-')}</td>
        <td class="${kindClass[r.kind] || ''} fw-semibold text-nowrap">${r.kind}${r.state && r.state !== 'DONE' && r.state !== 'ACCEPTED' ? ` <small class="text-muted">(${r.state})</small>` : ''}${Number(r.fills) > 1 ? `<div class="tx-fills" title="한 주문이 ${r.fills}번에 나눠 체결돼 한 줄로 합쳤습니다 (수량 · 금액 · 수수료는 합, 단가는 평균)">${r.fills}회 나눠 체결</div>` : ''}</td>
        <td class="tx-res-cell">${txResultHtml(r, avg, avgDec)}</td>
        <td class="text-end">${r.amount === null ? '-' : unit(num(r.amount, 0), 'KRW')}</td>
        <td class="text-end">${unit(num(r.fee, 2), r.kind === '입금' || r.kind === '출금' ? r.currency : 'KRW')}</td>
        <td class="text-end">${unit(num(r.settle, r.currency === 'KRW' || r.kind === '매수' || r.kind === '매도' ? 0 : 8), r.kind === '매수' || r.kind === '매도' ? 'KRW' : r.currency)}</td>
        <td class="tx-why-cell">${tradeReasonHtml(r)}</td>
        <td class="text-end">${unit(num(r.volume, 8), r.currency)}</td>
        <td class="text-end tx-avg">${avg ? unit(Number(avg).toLocaleString(undefined, { minimumFractionDigits: avgDec, maximumFractionDigits: avgDec }), 'KRW') : '-'}</td>
        <td class="text-end text-nowrap text-muted">${r.order_time ? formatKstTime(r.order_time) : '-'}</td>`;
}

const TX_PAGE = 200;
let txShown = TX_PAGE;          // 지금 표에 그린 줄 수
let txShownRows = [];           // 지금 표의 (필터 적용된) 전체 줄

function tradeRowEl(r) {
    const row = document.createElement('tr');
    row.innerHTML = txRowCells(r);
    fillTradeLogos(row);
    if (isChartTrade(r)) {
        row.dataset.txKey = txKey(r);
        row.tabIndex = 0;
        row.title = '누르면 창이 떠서 이 코인의 캔들차트에 이 거래를 보여 줍니다';
        if (row.dataset.txKey === txState.sel) row.classList.add('tx-sel');
    }
    return row;
}

function renderTradeRows(stillLoading = false, keepShown = false) {
    const tbody = document.getElementById('trades-tbody');
    if (!tbody) return;
    const rows = filteredTradeRows();
    const summary = document.getElementById('trades-summary');
    if (summary && !stillLoading) summary.innerHTML = tradeRows.length + transferRows.length ? tradesSummaryHtml(tradeCountTotal()) : '';
    txShownRows = rows;
    if (!keepShown) txShown = TX_PAGE;
    renderTxChart();
    if (!rows.length) {
        beginRows(tbody);                                    // 나눠 그리던 이전 것은 멈춤
        showTableMessage('trades-tbody', 12, stillLoading ? '불러오는 중…'
            : (tradeQuery.trim() || tradeKind !== 'ALL') ? '조건에 맞는 거래내역이 없습니다' : '이 기간에 거래내역이 없습니다');
        return;
    }
    // 처음 열 때는 40줄 먼저, 이미 내용이 있으면 다 만든 뒤 한 번에 바꿔 끼움 (appendRowsChunked)
    const tbl = document.getElementById('trades-table');
    if (tbl) tbl.dataset.total = String(tradeCountTotal());          // 표 위 '총 N건 · M건 표시'
    const out = beginRows(tbody);
    appendRowsChunked(out, rows.slice(0, Math.min(txShown, rows.length)), tradeRowEl, () => {
        finishRows(tbody, out);
        addTradeMoreRow(tbody);
        fitTxResult(document.getElementById('trades-table'));
    });
    fitTxResult(document.getElementById('trades-table'));
}

// 표 맨 아래 '더 보기' 줄: 화면에 들어오면(아래로 내리면) 다음 200줄을 이어 그림
let txMoreObserver = null;
function addTradeMoreRow(tbody) {
    txMoreObserver?.disconnect();
    const left = txShownRows.length - txShown;
    if (left <= 0 && !tradeNext) return;
    const tr = document.createElement('tr');
    tr.className = 'tx-more';
    tr.innerHTML = `<td colspan="12" class="text-center py-3"><button type="button" class="btn btn-sm btn-outline-secondary">아래로 내리면 더 보입니다 · ${Math.min(txShown, txShownRows.length).toLocaleString()} / ${tradeCountTotal().toLocaleString()}건</button></td>`;
    tr.querySelector('button').addEventListener('click', () => showMoreTradeRows());
    tbody.appendChild(tr);
    txMoreObserver = new IntersectionObserver((es) => { if (es.some(e => e.isIntersecting)) showMoreTradeRows(); },
        { root: tbody.closest('.table-scroll'), rootMargin: '300px' });
    txMoreObserver.observe(tr);
}

function showMoreTradeRows(upto) {
    const tbody = document.getElementById('trades-tbody');
    if (!tbody) return;
    flushRows(tbody);
    const from = txShown;
    if (from >= txShownRows.length && tradeNext) { loadMoreTrades(); return; }   // 받은 것은 다 그림 → 다음 쪽
    txShown = Math.min(txShownRows.length, Math.max(upto || 0, txShown + TX_PAGE));
    if (txShown <= from) return;
    tbody.querySelector('tr.tx-more')?.remove();
    const frag = document.createDocumentFragment();
    for (const r of txShownRows.slice(from, txShown)) frag.appendChild(tradeRowEl(r));
    tbody.appendChild(frag);
    addTradeMoreRow(tbody);
    fitTxResult(document.getElementById('trades-table'));
}

// ── 거래 차트: 고른 코인의 캔들 위에 매수 ▲ · 매도 ▼. 화살표를 누르면 표의 그 줄로, 표의 줄을 누르면 차트에서 크게 ──
const txState = { sym: null, unit: null, unitAuto: true, sel: null, chart: null, series: null, data: null, loadKey: null, center: null, priceLine: null };
const TX_KST = 9 * 3600;

const isChartTrade = (r) => (r.kind === '매수' || r.kind === '매도') && r.currency && r.currency !== 'KRW' && r.price;
const txKey = (r) => `${r.time}|${r.kind}|${r.currency}|${r.volume}|${r.price}`;
const txSec = (r) => Math.floor(new Date(r.time).getTime() / 1000) + TX_KST;   // 차트 시각(한국 시간 기준 초)
const txMins = () => TC_UNITS.find(([u]) => u === txState.unit)[2];
const txNum = (v) => Number(v).toLocaleString(undefined, { maximumFractionDigits: 8 });
const txPrice = (p) => formatPrice(p).replace('원', '');

// 지금 표에 보이는 매수·매도 중 차트에 올릴 것
function txChartRows() {
    return (txState.rows || filteredTradeRows()).filter(isChartTrade);
}
// 창 뒤의 표: 봇 매매 내역에서 열었으면 그 표, 아니면 거래 내역 탭의 표
const txTableSel = () => txState.table || '#trades-tbody';

function renderTxChart() {
    if (!txModalOpen) return;                                     // 창이 닫혀 있으면 캔들을 받지 않음
    const rows = txChartRows();
    if (!rows.length) {
        txState.chart?.remove();
        Object.assign(txState, { chart: null, series: null, data: null, loadKey: null, priceLine: null });
        document.getElementById('tx-units').innerHTML = '';
        document.getElementById('tx-name').textContent = '-';
        document.getElementById('tx-sym').textContent = '';
        const logo = document.getElementById('tx-logo');
        logo.innerHTML = ''; logo.dataset.cur = '';
        document.getElementById('tx-chart').innerHTML = `<div class="db-empty">${tradesLoading && !tradeRows.length ? '<span class="spinner-border spinner-border-sm"></span> 불러오는 중…' : '이 조건에 매수·매도 거래가 없습니다'}</div>`;
        return;
    }
    if (!rows.some(r => r.currency === txState.sym)) {
        txState.sym = rows[0].currency;   // 가장 최근에 거래한 코인
        txState.unitAuto = true;
        txState.center = null;
    }
    const mine = rows.filter(r => r.currency === txState.sym);
    // 단위: 거래가 모두 들어가는 가장 촘촘한 것, 다만 15분보다 짧게는 안 함 (거래 한두 건이면 1분봉은 비어 보임)
    if (txState.unitAuto) {
        const u = autoTradeUnit(mine), ord = TC_UNITS.map(([x]) => x);
        txState.unit = ord.indexOf(u) < ord.indexOf('15') ? '15' : u;
    }
    document.getElementById('tx-units').innerHTML = TC_UNITS.map(([u, t]) => `<button type="button" class="${u === txState.unit ? 'active' : ''}" data-tx-unit="${u}">${t}</button>`).join('');
    document.getElementById('tx-name').textContent = coinKoreanName(txState.sym);
    document.getElementById('tx-sym').textContent = `${txState.sym} · ${mine.length}건`;
    const logo = document.getElementById('tx-logo');
    if (logo.dataset.cur !== txState.sym) { logo.innerHTML = ''; logo.appendChild(createCoinLogo(txState.sym)); logo.dataset.cur = txState.sym; }

    // 캔들 끝 시각: 고른 거래가 있으면 그 거래가 가운데쯤, 아니면 마지막 거래 뒤로 여유를 두되 지금보다 늦지 않게
    const mins = txMins();
    const anchorMs = txState.center ?? Math.max(...mine.map(r => new Date(r.time).getTime()));
    const step = mins * 60e3 * 20;
    const end = Math.min(Date.now(), Math.ceil((anchorMs + 200 * mins * 60e3 * (txState.center ? 0.5 : 0.3)) / step) * step);
    const to = Date.now() - end > mins * 60e3 ? new Date(end).toISOString().slice(0, 19) + 'Z' : '';
    renderTxMini(mine);
    const loadKey = `${txState.sym}|${txState.unit}|${to}`;
    if (loadKey === txState.loadKey) { if (txState.series) setTxMarkers(); return; }
    txState.loadKey = loadKey;
    loadTxCandles(loadKey, to);
}

async function loadTxCandles(loadKey, to) {
    const el = document.getElementById('tx-chart');
    if (!txState.chart) el.innerHTML = '<div class="db-empty"><span class="spinner-border spinner-border-sm"></span> 캔들 불러오는 중…</div>';
    let candles = null;
    try {
        const r = await (await fetch(`/api/candles?market=KRW-${encodeURIComponent(txState.sym)}&unit=${txState.unit}${to ? `&to=${to}` : ''}`)).json();
        if (r.success) candles = r.candles;
    } catch (e) { /* 아래에서 안내 */ }
    if (txState.loadKey !== loadKey) return;                     // 그 사이 다른 코인 · 단위를 고름
    if (!candles?.length || typeof LightweightCharts === 'undefined') {
        txState.chart?.remove();
        Object.assign(txState, { chart: null, series: null, data: null, priceLine: null, loadKey: null });
        el.innerHTML = '<div class="db-empty">캔들을 받지 못했습니다. 새로고침을 눌러 다시 시도해 주십시오</div>';
        return;
    }
    txState.data = candles.map(c => ({ time: c[0] + TX_KST, open: c[1], high: c[2], low: c[3], close: c[4] }));
    if (!txState.chart) {
        el.innerHTML = '';
        const chart = LightweightCharts.createChart(el, {
            height: el.clientHeight || 340, layout: { background: { color: '#ffffff' }, textColor: '#475569', fontSize: 11 },
            grid: { vertLines: { color: '#f1f5f9' }, horzLines: { color: '#f1f5f9' } },
            timeScale: { secondsVisible: false, borderColor: '#e2e8f0', rightOffset: 4 }, rightPriceScale: { borderColor: '#e2e8f0' },
            crosshair: { mode: 0 }, localization: { priceFormatter: txPrice },
        });
        txState.chart = chart;
        txState.series = chart.addCandlestickSeries({ upColor: '#c84a31', downColor: '#1261c4', borderVisible: false, wickUpColor: '#c84a31', wickDownColor: '#1261c4' });
        chart.subscribeClick(onTxChartClick);
        chart.timeScale().subscribeVisibleLogicalRangeChange(() => requestAnimationFrame(placeTxGlow));   // 끌거나 확대하면 빛 화살표도 따라감
        new ResizeObserver(() => { if (el.clientWidth) { chart.applyOptions({ width: el.clientWidth, height: el.clientHeight }); requestAnimationFrame(placeTxGlow); } }).observe(el);
    }
    txState.chart.applyOptions({ timeScale: { timeVisible: txState.unit !== 'day' } });
    if (txState.priceLine) { txState.series.removePriceLine(txState.priceLine); txState.priceLine = null; }
    txState.series.setData(txState.data);
    txState.chart.timeScale().fitContent();
    setTxMarkers();
    // 가진 코인이면 매수평균가 녹색선
    if (txState.avgLine) { try { txState.series.removePriceLine(txState.avgLine); } catch (e) { /* 이미 없음 */ } txState.avgLine = null; }
    const series = txState.series, sym = txState.sym;
    myAvgBuy(sym).then(avg => { if (txState.series === series && txState.sym === sym && !txState.avgLine) txState.avgLine = addAvgBuyLine(series, avg); });
}

// 거래 시각이 들어가는 봉의 시작 시각 (차트 범위 앞이면 null)
function txSnap(x) {
    const d = txState.data;
    if (!d?.length || x < d[0].time) return null;
    let lo = 0, hi = d.length - 1;
    while (lo < hi) { const m = (lo + hi + 1) >> 1; if (d[m].time <= x) lo = m; else hi = m - 1; }
    return d[lo].time;
}

// 화살표: 고른 거래는 크게 + 가격 글씨 + 점선, 나머지는 고른 게 있으면 흐리게
function setTxMarkers() {
    const st = txState;
    if (!st.series || !st.data?.length) return;
    const first = st.data[0].time, lastBar = st.data[st.data.length - 1].time + txMins() * 60;
    const mine = txChartRows().filter(r => r.currency === st.sym);
    const sel = mine.find(r => txKey(r) === st.sel);
    let hidden = 0;
    const markers = [];
    for (const r of mine) {
        const x = txSec(r);
        if (x < first || x >= lastBar) { hidden += 1; continue; }
        const buy = r.kind === '매수', key = txKey(r), on = key === st.sel;
        if (on) continue;                                         // 고른 거래는 placeTxGlow 가 크게 + 빛으로 그림
        const color = buy ? (sel ? '#eab3a7' : '#c84a31') : (sel ? '#a9c3e8' : '#1261c4');
        markers.push({ id: key, time: txSnap(x), position: buy ? 'belowBar' : 'aboveBar', color, shape: buy ? 'arrowUp' : 'arrowDown', size: 1, text: '' });
    }
    // 같은 봉 안에서는 고른 화살표를 맨 뒤에 (위에 그려지게)
    markers.sort((a, b) => a.time - b.time || (a.id === st.sel) - (b.id === st.sel));
    st.series.setMarkers(markers);
    if (st.priceLine) { st.series.removePriceLine(st.priceLine); st.priceLine = null; }
    if (sel) {
        st.priceLine = st.series.createPriceLine({ price: sel.price, color: sel.kind === '매수' ? '#c84a31' : '#1261c4', lineWidth: 1, lineStyle: 2, axisLabelVisible: true, title: `${sel.kind}가` });
    }
    const hint = document.getElementById('tx-hint');
    if (hint) {
        if (sel) {
            hint.innerHTML = `<b></b><span class="tx-hint-why"></span>`;
            hint.querySelector('b').textContent = `${formatKstTime(sel.time)} ${sel.kind} ${txNum(sel.volume)} ${sel.currency} · ${txPrice(sel.price)}원 · ${Math.round(sel.amount).toLocaleString()}원`;
            hint.querySelector('.tx-hint-why').textContent = sel.reason ? ` · ${sel.bot ? sel.bot + ': ' : ''}${sel.reason}` : ' · 직접 주문';
        } else {
            hint.textContent = hidden ? `이 단위로는 ${hidden}건이 차트 범위 밖입니다 — 더 긴 단위를 고르거나 아래 목록에서 그 줄을 눌러 보십시오`
                : '화살표를 누르면 아래 목록에서 그 거래를 찾아 줍니다 · 목록의 줄을 누르면 차트에 크게 표시됩니다';
        }
    }
    renderTxMini(mine);
    // 고른 거래가 화면 밖이면 그 봉이 보이게 옮김
    if (sel) {
        const t = txSnap(txSec(sel));
        const i = t === null ? -1 : st.data.findIndex(d => d.time === t);
        const ts = st.chart.timeScale(), vr = ts.getVisibleLogicalRange();
        if (i >= 0 && vr && (i < vr.from + 2 || i > vr.to - 2)) {
            const w = Math.max(30, vr.to - vr.from);
            ts.setVisibleLogicalRange({ from: i - w * 0.6, to: i + w * 0.4 });
        }
    }
    requestAnimationFrame(placeTxGlow);
}

// 고른 거래 화살표: 다른 화살표와 같은 크기 + 둘레로 빛이 퍼지며 은은하게 깜빡임 (차트 위에 겹친 그림, 봉을 따라 자리 잡음)
function placeTxGlow() {
    const st = txState;
    const sel = st.sel && st.series && st.data?.length ? txChartRows().find(r => txKey(r) === st.sel && r.currency === st.sym) : null;
    placeTradeGlow(document.getElementById('tx-chart'), st.chart, st.series, st.data, sel, st.sel);
}

// 고른 거래 화살표 (거래 차트 창 · 크게 보기 창 공통): 차트 화살표와 같은 크기 + 둘레로 빛이 퍼지며 은은하게 깜빡임
// sel = { kind: '매수'|'매도', price, time } · key 가 바뀔 때만 다시 만듦 (빛 애니메이션이 끊기지 않게)
function placeTradeGlow(box, chart, series, data, sel, key) {
    if (!box) return;
    let g = box.querySelector(':scope > .tx-glow');
    let t = null;
    if (sel && chart && series && data?.length) {
        const x = Math.floor(new Date(sel.time).getTime() / 1000) + 9 * 3600;
        if (x >= data[0].time) {
            let lo = 0, hi = data.length - 1;
            while (lo < hi) { const m = (lo + hi + 1) >> 1; if (data[m].time <= x) lo = m; else hi = m - 1; }
            t = data[lo].time;
        }
    }
    const bar = t === null ? null : data.find(d => d.time === t);
    const buy = sel?.kind === '매수';
    const x = bar ? chart.timeScale().timeToCoordinate(t) : null;
    const y = bar ? series.priceToCoordinate(buy ? bar.low : bar.high) : null;
    const paneW = box.clientWidth - (chart?.priceScale('right').width() || 0);
    if (x === null || y === null || x < 0 || x > paneW) { g?.remove(); return; }
    if (!g) {
        g = document.createElement('div');
        g.setAttribute('aria-hidden', 'true');
        box.appendChild(g);
    }
    if (g.dataset.key !== String(key)) {
        g.dataset.key = String(key);
        g.className = `tx-glow ${buy ? 'is-buy' : 'is-sell'}`;
        g.innerHTML = `<span class="tx-glow-arrow"><svg viewBox="0 0 24 24"><path d="${buy ? 'M12 1.5 22.5 13H16v9.5H8V13H1.5Z' : 'M12 22.5 1.5 11H8V1.5h8V11h6.5Z'}"/></svg></span><b></b>`;
        g.querySelector('b').textContent = `${sel.kind} ${txPrice(sel.price)}`;
    }
    // 크기 · 간격은 차트 화살표와 같게 (봉 간격에 따라 12~30px)
    const size = Math.round(Math.min(30, Math.max(12, chart.timeScale().options().barSpacing || 6)));
    g.style.setProperty('--sz', `${size}px`);
    g.style.left = `${x}px`;
    g.style.top = `${buy ? y + 3 : y - 3}px`;
}

// 차트를 누름: 화살표를 눌렀으면 그 거래, 아니면 누른 봉 안의 거래 (여러 건이면 누를 때마다 다음 것)
function onTxChartClick(param) {
    if (!param || !txState.data) return;
    const mine = txChartRows().filter(r => r.currency === txState.sym);
    let key = typeof param.hoveredObjectId === 'string' && mine.some(r => txKey(r) === param.hoveredObjectId) ? param.hoveredObjectId : null;
    if (!key && param.time !== undefined) {
        const inBar = mine.filter(r => txSnap(txSec(r)) === param.time).reverse();   // 오래된 것부터
        if (inBar.length) {
            const at = inBar.findIndex(r => txKey(r) === txState.sel);
            key = txKey(inBar[(at + 1) % inBar.length]);
        }
    }
    if (key) selectTrade(key, 'chart');
}

// 거래 하나 고르기 — 'table': 창을 열어 그 거래를 · 'chart': 화살표 → 창 목록의 그 줄로 · 'mini': 창 목록의 줄 → 차트에 크게
function selectTrade(key, from) {
    const r = (txState.rows || tradeRows).find(x => txKey(x) === key);
    if (!r) return;
    if (from === 'mini' && txState.sel === key) key = null;     // 창 목록의 같은 줄을 다시 누르면 해제
    txState.sel = key;
    const tbl = txTableSel();
    document.querySelectorAll(`${tbl} tr.tx-sel`).forEach(tr => tr.classList.remove('tx-sel', 'tx-flash'));
    if (key && from === 'chart' && tbl === '#trades-tbody') {        // 받아 둔 줄 중 아직 안 그린 곳이면 거기까지 그림
        const i = txShownRows.findIndex(x => txKey(x) === key);
        if (i >= txShown) showMoreTradeRows(i + 20);
    }
    const tr = key ? document.querySelector(`${tbl} tr[data-tx-key="${CSS.escape(key)}"]`) : null;
    if (tr) {
        tr.classList.add('tx-sel');
        if (from !== 'table') tr.scrollIntoView({ block: 'center' });   // 창 뒤의 표도 그 줄로 (창을 닫으면 바로 보이게)
    }
    if (!key) { setTxMarkers(); return; }
    if (from === 'table' || from === 'mini') {
        if (r.currency !== txState.sym) { txState.sym = r.currency; txState.unitAuto = true; txState.center = null; txState.data = null; }
        // 지금 캔들 범위 밖이면 그 거래가 가운데 오게 다시 받음
        const d = txState.data, x = txSec(r);
        if (!(d?.length && x >= d[0].time && x < d[d.length - 1].time + txMins() * 60)) txState.center = new Date(r.time).getTime();
        if (from === 'table' && !txModalOpen) openTxModal();                 // 창을 열면서 바로 캔들을 받기 시작 (열리는 동안 기다리지 않게)
        renderTxChart();
        return;
    }
    setTxMarkers();
    // 화살표를 눌렀으면 창 목록의 그 줄을 깜빡여 보여 줌
    const mini = document.querySelector(`#tx-mini tr[data-tx-mini="${CSS.escape(key)}"]`);
    if (mini) { mini.classList.remove('tx-flash'); void mini.offsetWidth; mini.classList.add('tx-flash'); mini.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); }
}

// ── 거래 차트 창 ──
let txModalOpen = false;
// 창이 볼 줄 바꾸기 (null = 거래 내역 탭) — 바뀌면 아래 목록을 새로 그리게
// rows = 창이 볼 줄 (null = 거래 내역 탭에 받은 줄) · label = 아래 목록 설명 · table = 창 뒤의 표 · src = 어디서 연 것인지 (늦게 온 답 거르기)
function txUseRows(rows, label = '', table = '#trades-tbody', src = '') {
    if (txState.rows !== rows) document.getElementById('tx-mini')?.removeAttribute('data-key');
    Object.assign(txState, { rows, label, table, src });
}

// 거래 내역 탭의 줄 → 받은 줄로 창을 바로 열고, 그 코인의 기간 전부를 받아 바꿔 끼움
async function openTradesTabChart(key) {
    const r = tradeRows.find(x => txKey(x) === key);
    if (!r) return;
    const src = `tx:${r.currency}:${tradeDays}`, label = `최근 ${tradeDays}일 전부`;
    txUseRows(tradeRows.filter(x => x.currency === r.currency), label, '#trades-tbody', src);
    selectTrade(key, 'table');
    try {
        const d = await (await fetch(`/api/trade-history/coin?currency=${encodeURIComponent(r.currency)}&days=${tradeDays}`)).json();
        if (!d.success || txState.src !== src || !d.rows?.length) return;
        txUseRows(d.rows, label, '#trades-tbody', src);
        renderTxChart();
    } catch (e) { /* 받은 줄로 그대로 */ }
}
function openTxModal() {
    const el = document.getElementById('tx-modal');
    if (!el) return;
    if (el.parentElement !== document.body) document.body.appendChild(el);   // 탭 안에 두면 창이 가려질 수 있어 맨 바깥으로
    bootstrap.Modal.getOrCreateInstance(el).show();   // 전에 옮기거나 키운 자리 · 크기는 makeModalMovable 이 열 때 맞춤
    txModalOpen = true;                 // show() 직후엔 창이 이미 자리를 잡아 차트 폭을 잴 수 있음
}

// ── 창 옮기기 · 크기 바꾸기 · 차트↔목록 구분선 (거래 차트 창 · 크게 보기 창 공통) ──
// 제목 줄을 끌면 옮겨지고 오른쪽 아래 모서리(.tx-resize)를 끌면 크기가 바뀜 · 구분선(.tx-split)을 위아래로 끌면 차트 · 목록 높이 · 모두 이 PC에 기억, 두 번 누르면 원래대로
function readStore(key, def) {
    try { const v = JSON.parse(localStorage.getItem(key) || 'null'); return v ?? def; } catch (e) { return def; }
}
function writeStore(key, v) {
    try { v === null ? localStorage.removeItem(key) : localStorage.setItem(key, JSON.stringify(v)); } catch (e) { /* 무시 */ }
}

function makeModalMovable(modal, boxKey) {
    if (!modal) return;
    const dlg = modal.querySelector('.modal-dialog'), content = modal.querySelector('.modal-content');
    const head = modal.querySelector('.modal-header'), grip = modal.querySelector('.tx-resize');
    // b = { left, top, w, h } (px) · null 이면 원래(가운데 · 기본 크기)
    const apply = (b) => {
        if (!b) {
            dlg.classList.remove('is-free', 'is-sized');
            ['left', 'top', 'width'].forEach(k => dlg.style.removeProperty(k));
            content.style.removeProperty('height');
            return;
        }
        // 화면 밖으로 나가지 않게 (작아진 창에서 열어도 제목 줄은 보이게)
        const vw = window.innerWidth, vh = window.innerHeight;
        const w = Math.min(Math.max(480, b.w), vw - 16), h = b.h ? Math.min(Math.max(360, b.h), vh - 16) : null;
        const left = Math.min(Math.max(8, b.left), vw - w - 8), top = Math.min(Math.max(8, b.top), vh - 60);
        dlg.classList.add('is-free');
        dlg.style.left = `${left}px`;
        dlg.style.top = `${top}px`;
        dlg.style.width = `${w}px`;
        if (h) content.style.height = `${h}px`; else content.style.removeProperty('height');
        dlg.classList.toggle('is-sized', !!h);
    };
    const now = () => { const r = content.getBoundingClientRect(); return { left: r.left, top: r.top, w: r.width, h: r.height }; };
    const drag = (handle, onMove, skip) => handle?.addEventListener('pointerdown', (e) => {
        if (e.button !== 0 || (skip && skip(e))) return;
        e.preventDefault();
        const start = now(), x0 = e.clientX, y0 = e.clientY;
        try { handle.setPointerCapture(e.pointerId); } catch (err) { /* 무시 */ }
        document.body.classList.add('tx-dragging');
        const move = (ev) => apply(onMove(start, ev.clientX - x0, ev.clientY - y0));
        const up = () => {
            handle.removeEventListener('pointermove', move);
            document.body.classList.remove('tx-dragging');
            writeStore(boxKey, now());
        };
        handle.addEventListener('pointermove', move);
        handle.addEventListener('pointerup', up, { once: true });
        handle.addEventListener('pointercancel', up, { once: true });
    });
    drag(head, (st, dx, dy) => ({ ...st, left: st.left + dx, top: st.top + dy }), (e) => e.target.closest('button, a, input, select'));
    drag(grip, (st, dx, dy) => ({ ...st, w: st.w + dx, h: st.h + dy }));
    head?.addEventListener('dblclick', (e) => { if (e.target.closest('button')) return; writeStore(boxKey, null); apply(null); });
    modal.addEventListener('show.bs.modal', () => apply(readStore(boxKey, null)));   // 열 때 전에 둔 자리 · 크기
    window.addEventListener('resize', () => { if (dlg.classList.contains('is-free')) apply(now()); });
}

// 구분선: chartVar · listVar(CSS 변수)에 높이를 넣음 · listSel = 목록 칸 (창 높이를 정해 둔 경우 남은 높이를 채움)
function makeModalSplit(modal, key, def, chartVar, listVar, listSel) {
    const bar = modal?.querySelector('.tx-split');
    if (!bar) return;
    const read = () => ({ ...def, ...(readStore(key, null) || {}) });
    const apply = (sp) => { modal.style.setProperty(chartVar, `${Math.round(sp.chart)}px`); modal.style.setProperty(listVar, `${Math.round(sp.list)}px`); };
    apply(read());
    bar.addEventListener('pointerdown', (e) => {
        if (e.button !== 0) return;
        e.preventDefault();
        const start = read(), y0 = e.clientY;
        const sized = modal.querySelector('.modal-dialog')?.classList.contains('is-sized');
        // 창 높이를 정해 둔 경우: 목록이 남은 높이를 채우므로 차트만 늘이고 줄임 (목록 최소 100px)
        const maxChart = sized ? Math.max(160, start.chart + (modal.querySelector(listSel)?.clientHeight || 200) - 100) : 900;
        try { bar.setPointerCapture(e.pointerId); } catch (err) { /* 무시 */ }
        document.body.classList.add('tx-dragging');
        let cur = start;
        const move = (ev) => {
            const chart = Math.min(maxChart, Math.max(160, start.chart + ev.clientY - y0));
            cur = { chart, list: sized ? start.list : Math.max(100, start.list - (chart - start.chart)) };   // 창 높이가 자동이면 합은 그대로
            apply(cur);
        };
        const up = () => {
            bar.removeEventListener('pointermove', move);
            document.body.classList.remove('tx-dragging');
            writeStore(key, cur);
        };
        bar.addEventListener('pointermove', move);
        bar.addEventListener('pointerup', up, { once: true });
        bar.addEventListener('pointercancel', up, { once: true });
    });
    bar.addEventListener('dblclick', () => { writeStore(key, null); apply({ ...def }); });
}

makeModalMovable(document.getElementById('tx-modal'), 'strabot.txModalBox');
makeModalSplit(document.getElementById('tx-modal'), 'strabot.txSplit', { chart: 380, list: 230 }, '--tx-chart-h', '--tx-list-h', '.tx-mini');
document.getElementById('tx-modal')?.addEventListener('shown.bs.modal', () => { txModalOpen = true; renderTxChart(); });
document.getElementById('tx-modal')?.addEventListener('hidden.bs.modal', () => { txModalOpen = false; });

// 창 아래 목록: 지금 코인의 매수 · 매도 (최신순) — 줄을 누르면 차트에 크게, 화살표를 누르면 이 줄로
function renderTxMini(mine) {
    const box = document.getElementById('tx-mini');
    if (!box) return;
    const key = `${txState.sym}|${mine.length}|${mine[0] ? txKey(mine[0]) : ''}`;
    if (box.dataset.key !== key) {
        box.dataset.key = key;
        const buys = mine.filter(r => r.kind === '매수').length;
        box.innerHTML = `<div class="tx-mini-head"><b>${escapeHtml(coinKoreanName(txState.sym))} 거래 ${mine.length}건</b><small>매수 ${buys}번 · 매도 ${mine.length - buys}번${txState.label ? ` · ${escapeHtml(txState.label)}` : ''}</small></div>
            <div class="tx-mini-scroll"><table class="table table-sm table-hover mb-0 data-table"><thead class="table-light"><tr><th>체결시간</th><th>종류</th><th class="text-end">거래단가</th><th class="text-end">거래금액</th><th class="text-end">손익</th><th>봇 · 이유</th></tr></thead><tbody>${
            mine.map(r => {
                const buy = r.kind === '매수', pr = r.profit;
                const has = !buy && pr !== null && pr !== undefined && pr !== '';
                const pct = has && Number(r.settle) - Number(pr) > 0 ? Number(pr) / (Number(r.settle) - Number(pr)) * 100 : null;
                return `<tr data-tx-mini="${escapeHtml(txKey(r))}" tabindex="0"><td class="text-nowrap">${formatKstTime(r.time)}</td>
                    <td class="${buy ? 'pnl-up' : 'pnl-down'} fw-semibold">${r.kind}</td>
                    <td class="text-end text-nowrap">${formatPrice(r.price)}</td>
                    <td class="text-end text-nowrap">${r.amount ? formatKrw(r.amount) : '-'}</td>
                    <td class="text-end text-nowrap">${has ? `<span class="${pnlClass(Number(pr))}">${Number(pr) > 0 ? '+' : ''}${formatKrw(Number(pr))}</span>${pct !== null && isFinite(pct) ? `<span class="tx-pct ${pct >= 0 ? 'is-up' : 'is-down'}">${pct >= 0 ? '▲' : '▼'} ${Math.abs(pct).toFixed(1)}%</span>` : ''}` : '<span class="text-muted">-</span>'}</td>
                    <td class="tx-why-cell">${tradeReasonHtml(r)}</td></tr>`;
            }).join('')}</tbody></table></div>`;
    }
    box.querySelectorAll('tr[data-tx-mini]').forEach(tr => tr.classList.toggle('tx-sel', tr.dataset.txMini === txState.sel));
}

document.addEventListener('click', (e) => {
    const u = e.target.closest('[data-tx-unit]');
    if (u) { txState.unit = u.dataset.txUnit; txState.unitAuto = false; renderTxChart(); return; }
    const row = e.target.closest('#trades-tbody tr[data-tx-key]');
    if (row) { openTradesTabChart(row.dataset.txKey); return; }
    const mini = e.target.closest('#tx-mini tr[data-tx-mini]');
    if (mini) selectTrade(mini.dataset.txMini, 'mini');
});
document.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const row = e.target.closest?.('#trades-tbody tr[data-tx-key]');
    if (row) { e.preventDefault(); openTradesTabChart(row.dataset.txKey); return; }
    const mini = e.target.closest?.('#tx-mini tr[data-tx-mini]');
    if (mini) { e.preventDefault(); selectTrade(mini.dataset.txMini, 'mini'); }
});

// 지금 조건(기간 · 종류 · 코인)에 맞는 거래내역 전부를 CSV로 — 받은 쪽만이 아니라 서버가 전부 모아 줌 (엑셀에서 한글이 깨지지 않게 BOM 포함)
function downloadTradesCsv() {
    if (!tradeCountTotal()) {
        showNotification('저장할 거래내역이 없습니다', 'info');
        return;
    }
    const p = tradeQueryParams();
    p.delete('limit');
    if (tradeKind !== 'ALL') p.set('kind', tradeKind);
    const link = document.createElement('a');
    link.href = `/api/trade-history/csv?${p}`;
    link.click();
}

// ── 전체코인 분석: 매수·매도 버튼 ──
let buyTarget = null;

function setupMarketOrders() {
    const onOrderClick = async (e) => {
        const buyBtn = e.target.closest('.btn-market-buy');
        const sellBtn = e.target.closest('.btn-market-sell');
        if (buyBtn) {
            const coin = marketCoins.find(c => c.currency === buyBtn.dataset.currency);
            if (coin) openBuyModal(coin);
        } else if (sellBtn) {
            // 매도는 보유코인 분석과 같은 확인 창 (보유 정보가 없으면 한 번 불러옴)
            let asset = holdingsAssets.find(a => a.currency === sellBtn.dataset.currency);
            if (!asset) {
                try {
                    const data = await (await fetch('/api/holdings')).json();
                    if (data.success) holdingsAssets = data.holdings.assets;
                } catch (err) { /* 아래에서 안내 */ }
                asset = holdingsAssets.find(a => a.currency === sellBtn.dataset.currency);
            }
            if (asset) openSellModal(asset);
            else showNotification('보유 정보를 불러오지 못했습니다. 잠시 후 다시 시도해 주십시오.', 'error');
        }
    };
    document.getElementById('markets-tbody')?.addEventListener('click', onOrderClick);
    document.getElementById('screen-tbody')?.addEventListener('click', onOrderClick);
    const modalEl = document.getElementById('buy-modal');
    if (!modalEl) return;
    modalEl.querySelectorAll('[data-amount]').forEach(btn => btn.addEventListener('click', () => {
        document.getElementById('buy-amount').value = btn.dataset.amount;
        modalEl.querySelectorAll('[data-amount]').forEach(b => b.classList.toggle('active', b === btn));
        updateBuyPreview();
    }));
    document.getElementById('buy-amount').addEventListener('input', () => {
        modalEl.querySelectorAll('[data-amount]').forEach(b => b.classList.remove('active'));
        updateBuyPreview();
    });
    document.getElementById('buy-confirm').addEventListener('click', submitBuy);
}

async function openBuyModal(coin) {
    buyTarget = { ...coin, krw: null };
    document.getElementById('buy-title').textContent = `${coin.korean_name}(${coin.currency}) 매수`;
    document.getElementById('buy-price').textContent = formatPrice(coin.current_price);
    document.getElementById('buy-amount').value = '';
    document.getElementById('buy-error').textContent = '';
    document.querySelectorAll('#buy-modal [data-amount]').forEach(b => b.classList.remove('active'));

    // 유의·주의·상폐 예정·입출금 중단이면 크게 경고
    const risks = [];
    const notices = coin.notices || [];
    const delist = notices.find(n => n.type === 'delisting');
    if (delist) risks.push(`거래지원 종료(상장폐지) 예정 코인입니다${delist.ends_at ? ` (${delist.ends_at})` : ''}.`);
    if (coin.warning) risks.push('업비트가 지정한 투자유의 종목입니다.');
    if (coin.cautions && coin.cautions.length) risks.push(`투자주의 종목입니다 (${coin.cautions.join(', ')}).`);
    if (notices.some(n => n.type === 'suspend')) risks.push('입출금이 일시 중단된 코인입니다.');
    const riskEl = document.getElementById('buy-risk');
    riskEl.innerHTML = risks.length ? '<i class="bi bi-exclamation-octagon-fill me-1"></i><strong>주의가 필요한 코인입니다.</strong> ' : '';
    riskEl.append(risks.join(' '));
    riskEl.classList.toggle('d-none', !risks.length);

    document.getElementById('buy-krw').textContent = '확인 중…';
    updateBuyPreview();
    bootstrap.Modal.getOrCreateInstance(document.getElementById('buy-modal')).show();
    try {
        const data = await (await fetch('/api/krw-balance')).json();
        buyTarget.krw = data.success ? data.krw : null;
        document.getElementById('buy-krw').textContent = data.success ? formatKrw(Math.floor(data.krw)) : (data.error || '확인 실패');
    } catch (err) {
        document.getElementById('buy-krw').textContent = '확인 실패';
    }
    updateBuyPreview();
}

function updateBuyPreview() {
    const c = buyTarget;
    if (!c) return;
    const amount = Number(document.getElementById('buy-amount').value) || 0;
    document.getElementById('buy-qty').textContent = amount > 0 && c.current_price
        ? `약 ${(amount / c.current_price).toLocaleString(undefined, { maximumFractionDigits: 8 })} ${c.currency}` : '-';
    let problem = '';
    if (amount <= 0) problem = '매수할 금액을 입력해 주십시오.';
    else if (amount < MIN_ORDER_KRW) problem = '최소 주문금액은 5,000원입니다.';
    else if (c.krw !== null && amount * (1 + UPBIT_FEE) > c.krw) problem = '주문 가능한 원화보다 많습니다 (수수료 포함).';
    document.getElementById('buy-hint').textContent = problem;
    document.getElementById('buy-confirm').disabled = !!problem;
}

async function submitBuy() {
    const c = buyTarget;
    const btn = document.getElementById('buy-confirm');
    const amount = Math.floor(Number(document.getElementById('buy-amount').value) || 0);
    btn.disabled = true;
    btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span> 주문 중...';
    document.getElementById('buy-error').textContent = '';
    try {
        const data = await (await fetch('/api/markets/buy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ currency: c.currency, amount }),
        })).json();
        if (data.error_code === 'LICENSE_REQUIRED') {       // 사는 주문만 계정이 필요합니다 (팔기는 그대로)
            bootstrap.Modal.getOrCreateInstance(document.getElementById('buy-modal')).hide();
            licenseRefused(data);
            return;
        }
        if (!data.success) throw new Error(data.error || '매수 실패');
        bootstrap.Modal.getOrCreateInstance(document.getElementById('buy-modal')).hide();
        showNotification(`${c.korean_name} ${amount.toLocaleString()}원 시장가 매수 주문을 보냈습니다`, 'success');
        heldCurrencies = null;  // 보유 표시 새로
        const before = Number(holdingsAssets.find(x => x.currency === c.currency)?.balance) || 0;
        setTimeout(() => loadMarkets(true), 1500);
        if (holdingsAssets.length) reloadHoldingsAfterOrder(qtyChanged(c.currency, before));
    } catch (error) {
        document.getElementById('buy-error').textContent = error.message;
    } finally {
        btn.innerHTML = '시장가 매수';
        updateBuyPreview();
    }
}

// ── 여러 코인 선택 → 일괄 시장가 매수/매도 ──
const selections = { markets: new Set(), holdings: new Set() };
let batchState = null;   // { side, items: [{coin, ...}], done }

// 표별: 선택 가능한 코인 목록 (지금 보이는 줄만 '전체 선택' 대상)
function selectableCoins(kind) {
    return kind === 'markets'
        ? marketCoins.filter(c => matchesQuery(c, marketsQuery))
        : holdingsAssets.filter(a => !a.is_delisted && matchesHoldingsQuery(a));
}

function syncSelection(kind) {
    const tbody = document.getElementById(`${kind}-tbody`);
    const set = selections[kind];
    tbody?.querySelectorAll('.row-sel').forEach(cb => { cb.checked = set.has(cb.dataset.currency); });
    const visible = selectableCoins(kind).map(c => c.currency);
    const picked = visible.filter(c => set.has(c)).length;
    const all = document.getElementById(`${kind}-sel-all`);
    if (all) {
        all.checked = visible.length > 0 && picked === visible.length;
        all.indeterminate = picked > 0 && picked < visible.length;
    }
    const bar = document.getElementById(`${kind}-selbar`);
    if (bar) bar.classList.toggle('d-none', set.size === 0);
    const count = document.getElementById(`${kind}-sel-count`);
    if (count) count.textContent = set.size;
}

function setupBatchOrders() {
    for (const kind of ['markets', 'holdings']) {
        document.getElementById(`${kind}-tbody`)?.addEventListener('change', (e) => {
            const cb = e.target.closest('.row-sel');
            if (!cb) return;
            if (cb.checked) selections[kind].add(cb.dataset.currency);
            else selections[kind].delete(cb.dataset.currency);
            syncSelection(kind);
        });
        document.getElementById(`${kind}-sel-all`)?.addEventListener('change', (e) => {
            const visible = selectableCoins(kind).map(c => c.currency);
            if (e.target.checked && selections[kind].size + visible.length > 30) {
                showNotification('한 번에 최대 30개까지 주문할 수 있습니다. 검색으로 줄여서 골라 주십시오.', 'info');
            }
            visible.forEach(c => (e.target.checked ? selections[kind].add(c) : selections[kind].delete(c)));
            syncSelection(kind);
        });
    }
    document.querySelectorAll('[data-batch-clear]').forEach(btn => btn.addEventListener('click', () => {
        selections[btn.dataset.batchClear].clear();
        syncSelection(btn.dataset.batchClear);
    }));
    document.querySelectorAll('[data-batch]').forEach(btn => btn.addEventListener('click', () => openBatchModal(btn.dataset.batch, btn.dataset.side)));
    document.getElementById('batch-confirm')?.addEventListener('click', submitBatch);
}

async function openBatchModal(kind, side) {
    const picked = [...selections[kind]];
    if (!picked.length) return;
    if (picked.length > 30) {
        showNotification('한 번에 최대 30개까지 주문할 수 있습니다.', 'error');
        return;
    }
    const source = kind === 'markets' ? marketCoins : holdingsAssets;
    let coins = picked.map(c => source.find(x => x.currency === c)).filter(Boolean);

    if (side === 'sell') {
        // 매도는 실제 보유 정보(수량·평균가)가 필요 → 보유 목록 기준
        if (!holdingsAssets.length) {
            try {
                const data = await (await fetch('/api/holdings')).json();
                if (data.success) holdingsAssets = data.holdings.assets;
            } catch (e) { /* 아래에서 안내 */ }
        }
        const held = coins.map(c => holdingsAssets.find(a => a.currency === c.currency && !a.is_delisted)).filter(Boolean);
        const skipped = coins.length - held.length;
        if (!held.length) {
            showNotification('고른 코인 중 보유한 코인이 없습니다.', 'info');
            return;
        }
        if (skipped) showNotification(`보유하지 않은 ${skipped}개는 매도에서 빠집니다.`, 'info');
        coins = held;
    }

    batchState = { side, kind, coins, ratio: 1, ratios: {}, amount: 0, krw: null, done: false };
    document.getElementById('batch-title').textContent = `${side === 'buy' ? '선택 매수' : '선택 매도'} (${coins.length}개)`;
    document.getElementById('batch-error').textContent = '';
    const confirm = document.getElementById('batch-confirm');
    confirm.classList.remove('d-none');
    confirm.className = `btn ${side === 'buy' ? 'btn-danger' : 'btn-primary'}`;
    confirm.textContent = side === 'buy' ? '시장가 일괄 매수' : '시장가 일괄 매도';
    document.getElementById('batch-cancel').textContent = '취소';

    const controls = document.getElementById('batch-controls');
    if (side === 'buy') {
        controls.innerHTML = `
            <div class="d-flex justify-content-between small mb-2"><span class="text-muted">주문 가능 원화</span><strong id="batch-krw">확인 중…</strong></div>
            <label class="form-label small text-muted mb-1" for="batch-amount">코인당 매수 금액 (원)</label>
            <div class="d-flex gap-2">
                <div class="btn-group btn-group-sm" role="group">
                    ${[10000, 50000, 100000, 500000].map(v => `<button type="button" class="btn btn-outline-secondary" data-batch-amount="${v}">${v / 10000}만</button>`).join('')}
                </div>
                <input type="number" class="form-control form-control-sm" id="batch-amount" min="5000" step="1000" style="max-width: 180px;" inputmode="numeric">
            </div>`;
        controls.querySelectorAll('[data-batch-amount]').forEach(b => b.addEventListener('click', () => {
            document.getElementById('batch-amount').value = b.dataset.batchAmount;
            controls.querySelectorAll('[data-batch-amount]').forEach(x => x.classList.toggle('active', x === b));
            renderBatchTable();
        }));
        document.getElementById('batch-amount').addEventListener('input', () => {
            controls.querySelectorAll('[data-batch-amount]').forEach(x => x.classList.remove('active'));
            renderBatchTable();
        });
    } else {
        controls.innerHTML = `
            <div class="small text-muted mb-1">코인마다 파는 비율</div>
            <div class="btn-group btn-group-sm" role="group">
                ${[0.01, 0.03, 0.05, 0.1, 0.25, 0.5, 0.75, 1].map(r => `<button type="button" class="btn btn-outline-secondary${r === 1 ? ' active' : ''}" data-batch-ratio="${r}">${Math.round(r * 100)}%</button>`).join('')}
            </div>`;
        controls.querySelectorAll('[data-batch-ratio]').forEach(b => b.addEventListener('click', () => {
            batchState.ratio = Number(b.dataset.batchRatio);
            batchState.ratios = {};  // 공통 비율로 다시 맞춤
            controls.querySelectorAll('[data-batch-ratio]').forEach(x => x.classList.toggle('active', x === b));
            renderBatchTable();
        }));
    }
    renderBatchTable();
    bootstrap.Modal.getOrCreateInstance(document.getElementById('batch-modal')).show();

    if (side === 'buy') {
        try {
            const data = await (await fetch('/api/krw-balance')).json();
            batchState.krw = data.success ? data.krw : null;
            document.getElementById('batch-krw').textContent = data.success ? formatKrw(Math.floor(data.krw)) : (data.error || '확인 실패');
        } catch (e) {
            document.getElementById('batch-krw').textContent = '확인 실패';
        }
        renderBatchTable();
    }
}

// 주의가 필요한 코인 표시 (상폐 예정·유의·주의·입출금 중단)
function coinRiskText(c) {
    const n = c.notices || [];
    const risks = [];
    if (n.some(x => x.type === 'delisting')) risks.push('상폐 예정');
    if (c.warning) risks.push('유의');
    if (c.cautions && c.cautions.length) risks.push('주의');
    if (n.some(x => x.type === 'suspend')) risks.push('입출금 중단');
    return risks.join('·');
}

function renderBatchTable() {
    const s = batchState;
    const head = document.getElementById('batch-head');
    const tbody = document.getElementById('batch-tbody');
    const total = document.getElementById('batch-total');
    tbody.innerHTML = '';
    let problem = '';

    if (s.side === 'buy') {
        s.amount = Math.floor(Number(document.getElementById('batch-amount')?.value) || 0);
        head.innerHTML = '<th>코인</th><th>주의</th><th class="text-end">현재가</th><th class="text-end">매수 금액</th><th class="text-end">예상 수량</th><th>결과</th>';
        for (const c of s.coins) {
            const tr = document.createElement('tr');
            tr.dataset.currency = c.currency;
            const risk = coinRiskText(c);
            tr.innerHTML = `<td class="text-nowrap"><strong class="bn"></strong> <small class="text-muted">${c.currency}</small></td>
                <td>${risk ? `<span class="badge bg-danger-subtle text-danger">${risk}</span>` : ''}</td>
                <td class="text-end">${formatPrice(c.current_price)}</td>
                <td class="text-end">${s.amount ? formatKrw(s.amount) : '-'}</td>
                <td class="text-end">${s.amount && c.current_price ? (s.amount / c.current_price).toLocaleString(undefined, { maximumFractionDigits: 8 }) : '-'}</td>
                <td class="batch-result small"></td>`;
            tr.querySelector('.bn').textContent = c.korean_name;
            tbody.appendChild(tr);
        }
        const sum = s.amount * s.coins.length;
        total.innerHTML = `<span>합계 (${s.coins.length}개 × ${formatKrw(s.amount)})</span><span>${formatKrw(sum)} <small class="text-muted fw-normal">+ 수수료 약 ${formatKrw(sum * UPBIT_FEE)}</small></span>`;
        if (!s.amount) problem = '코인당 매수 금액을 정해 주십시오.';
        else if (s.amount < MIN_ORDER_KRW) problem = '코인당 최소 주문금액은 5,000원입니다.';
        else if (s.krw !== null && sum * (1 + UPBIT_FEE) > s.krw) problem = '합계가 주문 가능한 원화보다 많습니다 (수수료 포함).';
    } else {
        head.innerHTML = '<th>코인</th><th class="text-end">비율</th><th class="text-end">매도 수량</th><th class="text-end">예상 받을 금액</th><th class="text-end">예상 손익</th><th>결과</th>';
        for (const a of s.coins) {
            const tr = document.createElement('tr');
            tr.dataset.currency = a.currency;
            const pct = batchSellRatio(a) * 100;
            tr.innerHTML = `<td class="text-nowrap"><strong class="bn"></strong> <small class="text-muted">${a.currency}</small></td>
                <td class="text-end">
                    <div class="input-group input-group-sm batch-ratio-group ms-auto">
                        <input type="number" class="form-control text-end batch-ratio-input${a.currency in s.ratios ? ' is-custom' : ''}"
                               min="0.01" max="100" step="1" value="${+pct.toFixed(2)}" aria-label="${a.currency} 매도 비율">
                        <span class="input-group-text">%</span>
                    </div>
                </td>
                <td class="text-end b-qty"></td><td class="text-end b-net"></td><td class="text-end b-pnl"></td>
                <td class="batch-result small"></td>`;
            tr.querySelector('.bn').textContent = a.korean_name;
            const input = tr.querySelector('.batch-ratio-input');
            input.addEventListener('input', () => {
                // 이 코인만 비율 변경 (0.01~100%)
                const v = Math.min(Math.max(Number(input.value) || 0, 0), 100);
                s.ratios[a.currency] = v / 100;
                input.classList.add('is-custom');
                updateBatchSell();
            });
            tbody.appendChild(tr);
        }
        updateBatchSell();
        return;
    }
    document.getElementById('batch-hint').textContent = s.done ? '' : problem;
    document.getElementById('batch-confirm').disabled = !!problem || s.done;
}

// 선택 매도: 코인별 비율 (직접 바꾼 코인은 그 값, 아니면 위에서 고른 공통 비율)
function batchSellRatio(a) {
    const s = batchState;
    return a.currency in s.ratios ? s.ratios[a.currency] : s.ratio;
}

// 선택 매도 표의 수량·금액·손익·합계를 다시 계산 (입력칸은 다시 그리지 않아 입력 중 커서가 유지됨)
function updateBatchSell() {
    const s = batchState;
    let sum = 0, pnlSum = 0, valid = 0;
    for (const a of s.coins) {
        const tr = document.querySelector(`#batch-tbody tr[data-currency="${a.currency}"]`);
        if (!tr) continue;
        const qty = sellAvailable(a) * batchSellRatio(a);
        const gross = qty * a.current_price;
        const net = gross * (1 - UPBIT_FEE);
        const pnl = net - qty * a.avg_buy_price;
        const tooSmall = gross < MIN_ORDER_KRW;
        a._batchSkip = tooSmall;
        if (!tooSmall) { sum += net; pnlSum += pnl; valid++; }
        tr.classList.toggle('text-muted', tooSmall);
        tr.querySelector('.b-qty').textContent = qty.toLocaleString(undefined, { maximumFractionDigits: 8 });
        tr.querySelector('.b-net').textContent = tooSmall ? '5,000원 미만 · 제외' : formatKrw(net);
        const pnlCell = tr.querySelector('.b-pnl');
        pnlCell.className = `text-end b-pnl ${tooSmall ? '' : pnlClass(pnl)}`;
        pnlCell.textContent = tooSmall ? '-' : `${pnl > 0 ? '+' : ''}${formatKrw(pnl)}`;
    }
    document.getElementById('batch-total').innerHTML = `<span>합계 (${valid}개, 수수료 0.05% 제외)</span><span>${formatKrw(sum)} <small class="${pnlClass(pnlSum)}">(${pnlSum > 0 ? '+' : ''}${formatKrw(pnlSum)})</small></span>`;
    const problem = valid ? '' : '최소 주문금액(5,000원) 이상인 코인이 없습니다.';
    document.getElementById('batch-hint').textContent = s.done ? '' : problem;
    document.getElementById('batch-confirm').disabled = !!problem || s.done;
}

async function submitBatch() {
    const s = batchState;
    const btn = document.getElementById('batch-confirm');
    const orders = s.side === 'buy'
        ? s.coins.map(c => ({ currency: c.currency, side: 'buy', amount: s.amount }))
        : s.coins.filter(a => !a._batchSkip).map(a => (batchSellRatio(a) >= 1
            ? { currency: a.currency, side: 'sell', ratio: 1 }
            : { currency: a.currency, side: 'sell', quantity: Math.floor(sellAvailable(a) * batchSellRatio(a) * 1e8) / 1e8 }));
    btn.disabled = true;
    btn.innerHTML = `<span class="spinner-border spinner-border-sm me-1"></span> 주문 중... (${orders.length}개)`;
    document.getElementById('batch-error').textContent = '';
    try {
        const data = await (await fetch('/api/orders/batch', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ orders }),
        })).json();
        if (data.error_code === 'LICENSE_REQUIRED') {       // 사는 주문만 계정이 필요합니다 (팔기는 그대로)
            bootstrap.Modal.getOrCreateInstance(document.getElementById('batch-modal')).hide();
            licenseRefused(data);
            return;
        }
        if (!data.success) throw new Error(data.error || '일괄 주문 실패');

        // 코인별 결과를 표에 표시
        for (const r of data.results) {
            const cell = document.querySelector(`#batch-tbody tr[data-currency="${r.currency}"] .batch-result`);
            if (!cell) continue;
            cell.className = `batch-result small ${r.success ? 'text-success' : 'text-danger'}`;
            cell.textContent = r.success ? '✓ 주문 완료' : `✗ ${r.message}`;
        }
        s.done = true;
        document.querySelectorAll('#batch-tbody .batch-ratio-input').forEach(i => { i.disabled = true; });
        btn.classList.add('d-none');
        document.getElementById('batch-cancel').textContent = '닫기';
        document.getElementById('batch-hint').textContent = '';
        showNotification(`일괄 ${s.side === 'buy' ? '매수' : '매도'}: ${data.total}개 중 ${data.ok}개 주문 완료`, data.ok === data.total ? 'success' : 'info');

        selections[s.kind].clear();
        syncSelection(s.kind);
        heldCurrencies = null;
        setTimeout(() => { if (marketCoins.length) loadMarkets(true); }, 1500);
        reloadHoldingsAfterOrder();
    } catch (error) {
        document.getElementById('batch-error').textContent = error.message;
        btn.innerHTML = s.side === 'buy' ? '시장가 일괄 매수' : '시장가 일괄 매도';
        btn.disabled = false;
    }
}

// ── 조건 검색 탭: 공개된 조건(숫자 수정 가능)에 맞는 코인 찾기. 매매 권유가 아님 ──
// 데이터: 전체코인 시세(marketCoins) + 일봉 30일(periodLows: 종가·고가·거래대금) + 오늘 저가·어제 종가(시세)

// 평소 하루 변동: 최근 종가들의 하루 등락률 절대값 중앙값 (%)
function typicalDailyMove(closes) {
    const moves = [];
    for (let i = 1; i < closes.length; i++) moves.push(Math.abs(closes[i] / closes[i - 1] - 1) * 100);
    if (!moves.length) return null;
    moves.sort((x, y) => x - y);
    return moves[Math.floor(moves.length / 2)];
}

// 조건 계산용: 지난 종가 + 현재가 (오래된 순, 마지막이 지금)
function closesNow(c, d) {
    return d.day_closes && d.day_closes.length ? [...d.day_closes, c.current_price] : null;
}

// 단순 이동평균: arr의 end 번째(포함)까지 n개 평균
function smaAt(arr, n, end) {
    if (end + 1 < n) return null;
    let sum = 0;
    for (let i = end - n + 1; i <= end; i++) sum += arr[i];
    return sum / n;
}

// RSI (와일더 방식, 기본 14일). 값이 모자라면 null
function rsiOf(closes, n = 14) {
    if (!closes || closes.length < n + 1) return null;
    let gain = 0, loss = 0;
    for (let i = 1; i <= n; i++) {
        const ch = closes[i] - closes[i - 1];
        if (ch > 0) gain += ch; else loss -= ch;
    }
    gain /= n; loss /= n;
    for (let i = n + 1; i < closes.length; i++) {
        const ch = closes[i] - closes[i - 1];
        gain = (gain * (n - 1) + Math.max(ch, 0)) / n;
        loss = (loss * (n - 1) + Math.max(-ch, 0)) / n;
    }
    if (loss === 0) return gain === 0 ? 50 : 100;
    return 100 - 100 / (1 + gain / loss);
}

// 볼린저 밴드 (n일, k배 표준편차) — 마지막 값 기준
function bollingerOf(closes, n = 20, k = 2) {
    if (!closes || closes.length < n) return null;
    const w = closes.slice(-n);
    const mid = w.reduce((x, y) => x + y, 0) / n;
    const sd = Math.sqrt(w.reduce((x, y) => x + (y - mid) ** 2, 0) / n);
    return { mid, upper: mid + k * sd, lower: mid - k * sd };
}

// 이동평균 교차: 최근 within일 안에 짧은 선이 긴 선을 위(up) 또는 아래(down)로 지났는지. 지난 날 수 반환
function crossWithin(closes, short, long, within, dir) {
    const n = closes.length;
    for (let back = 0; back < within; back++) {
        const i = n - 1 - back;
        const s1 = smaAt(closes, short, i), l1 = smaAt(closes, long, i);
        const s0 = smaAt(closes, short, i - 1), l0 = smaAt(closes, long, i - 1);
        if ([s1, l1, s0, l0].some(v => v === null)) return null;
        if (dir === 'up' ? (s0 <= l0 && s1 > l1) : (s0 >= l0 && s1 < l1)) return { back, s: s1, l: l1 };
    }
    return null;
}

// 선 넘기: 최근 within일 안에 값(valAt)이 기준선(lineAt)을 위로(up)/아래로(down) 지났는지. 지난 날 수 반환
function lineCrossWithin(n, within, valAt, lineAt, dir) {
    for (let back = 0; back < within; back++) {
        const i = n - 1 - back;
        if (i < 1) return null;
        const v1 = valAt(i), l1 = lineAt(i), v0 = valAt(i - 1), l0 = lineAt(i - 1);
        if ([v1, l1, v0, l0].some(v => v === null || v === undefined)) return null;
        if (dir === 'up' ? (v0 <= l0 && v1 > l1) : (v0 >= l0 && v1 < l1)) return { back, v: v1, l: l1 };
    }
    return null;
}
const bandLineAt = (closes, days, k, side) => (i) => {
    const b = bollingerOf(closes.slice(0, i + 1), days, k);
    return b ? b[side] : null;
};

// ── 2026-10 추가 조건용 도우미 (파이썬 conditions.py 와 같은 계산) ──
// 긴 기간(최대 120봉) 종가 + 지금 가격
function longNow(c, d, key = 'day_closes_long') {
    const a = d[key];
    return a && a.length ? [...a, c.current_price] : null;
}
// 지수이동평균 (처음 n개 평균에서 시작), 모자란 앞부분은 null
function emaSeries(arr, n) {
    const out = new Array(arr.length).fill(null);
    if (arr.length < n) return out;
    let e = 0;
    for (let i = 0; i < n; i++) e += arr[i];
    e /= n;
    out[n - 1] = e;
    const k = 2 / (n + 1);
    for (let i = n; i < arr.length; i++) { e = arr[i] * k + e * (1 - k); out[i] = e; }
    return out;
}
// MACD(12,26,9): [MACD 선, 시그널 선]
function macdSeries(closes, fast = 12, slow = 26, sig = 9) {
    const ef = emaSeries(closes, fast), es = emaSeries(closes, slow);
    const macd = ef.map((a, i) => (a !== null && es[i] !== null ? a - es[i] : null));
    const start = macd.findIndex(v => v !== null);
    const signal = new Array(closes.length).fill(null);
    if (start >= 0) emaSeries(macd.slice(start), sig).forEach((v, j) => { signal[start + j] = v; });
    return [macd, signal];
}
// 스토캐스틱: [%K(원 %K 의 3일 평균), %D(%K 의 3일 평균)]
function stochSeries(highs, lows, closes, n = 14, smooth = 3) {
    const raw = new Array(closes.length).fill(null);
    for (let i = n - 1; i < closes.length; i++) {
        let hh = -Infinity, ll = Infinity;
        for (let j = i - n + 1; j <= i; j++) { if (highs[j] > hh) hh = highs[j]; if (lows[j] < ll) ll = lows[j]; }
        raw[i] = hh > ll ? (closes[i] - ll) / (hh - ll) * 100 : 50;
    }
    const smaOpt = (arr, m) => arr.map((_, i) => {
        if (i < m - 1) return null;
        let sum = 0;
        for (let j = i - m + 1; j <= i; j++) { if (arr[j] === null) return null; sum += arr[j]; }
        return sum / m;
    });
    const k = smaOpt(raw, smooth);
    return [k, smaOpt(k, smooth)];
}
// 평균 진폭 ATR (와일더 방식) — 끝난 봉들로
function atrOf(highs, lows, closes, n = 14) {
    if (closes.length < n + 1) return null;
    const trs = [];
    for (let i = 1; i < closes.length; i++) trs.push(Math.max(highs[i], closes[i - 1]) - Math.min(lows[i], closes[i - 1]));
    let a = trs.slice(0, n).reduce((x, y) => x + y, 0) / n;
    for (const tr of trs.slice(n)) a = (a * (n - 1) + tr) / n;
    return a;
}
// 긴 기간 고가·저가·종가 + 오늘(지금까지): 오늘 고가는 따로 없어 지금 가격, 저가는 오늘 저가
function hlcNow(c, d) {
    const hs = d.day_highs_long, ls = d.day_lows_long, cs = d.day_closes_long;
    if (!hs || !ls || !cs || !cs.length || hs.length !== cs.length || ls.length !== cs.length) return null;
    const price = c.current_price;
    return [[...hs, price], [...ls, Math.min(price, c.today_low || price)], [...cs, price]];
}
function alignedOf(closes, p) {
    const n = closes.length - 1;
    const s = smaAt(closes, p.short, n), m = smaAt(closes, p.mid, n), l = smaAt(closes, p.long, n);
    return s !== null && m !== null && l !== null && s > m && m > l ? [s, m, l] : null;
}

// 연속 상승(dir=1)/하락(dir=-1) 일수 (지금 가격 포함)
function streakOf(closes, dir) {
    let k = 0;
    for (let i = closes.length - 1; i > 0; i--) {
        if (Math.sign(closes[i] - closes[i - 1]) === dir) k++; else break;
    }
    return k;
}

// '최고가 대비' 조건의 기간(개월): 1~24로 맞춤 (예전에 저장한 '년' 값도 개월로 바꿔 읽음)
function highMonths(p) {
    const m = p.months ?? (p.years ? p.years * 12 : 12);
    return Math.min(Math.max(Math.round(m) || 12, 1), 24);
}
function monthsToWeeks(months) {
    return Math.min(Math.round(months * 52 / 12), 104);
}

// ── 2026-10 패턴 조건용 도우미 (파이썬 conditions.py 와 같은 계산) ──
