// from = 'rule' 이면 매매 규칙(이 봇) 숫자, 아니면 분석 화면 숫자로 설명·예시를 보여 줌
function openCondExplain(id, from = '') {
    if (id.startsWith('set:')) return openSetExplain(id);
    document.getElementById('cx-proof').classList.add('d-none');
    document.getElementById('cx-ex-card').classList.remove('d-none');
    const preset = SCREEN_PRESETS.find(p => p.id === id);
    if (!preset) return;
    const inBuy = ruleList('buy').find(r => r.id === id), inSell = ruleList('sell').find(r => r.id === id);
    const p = from === 'rule' ? ruleParams(preset, inBuy || inSell) : screenParamsOf(preset);
    const ex = COND_EXPLAIN[id];
    document.getElementById('cx-title').textContent = preset.title;
    document.getElementById('cx-icon').innerHTML = `<i class="bi ${preset.icon}"></i>`;
    const sd = preset.custom ? 'state' : signalDir(preset.id);
    document.getElementById('cx-tags').innerHTML = `${basisTagHtml(preset, p)}${preset.custom ? '<span class="my-cond-badge">내 조건</span>' : ''}`
        + (sd === 'state' ? '' : `<span class="sig-chip is-${sd} is-static" title="신호 모아보기에서 ${sd === 'up' ? '상승' : '하락'} 신호로 셉니다">${sd === 'up' ? '▲ 상승 신호' : '▼ 하락 신호'}</span>`);
    renderCondRel(id);
    renderCxSummary(ex?.summary || (preset.custom ? '내가 문장으로 설명해서 만든 조건입니다.' : ''));
    let sketch = '';
    try { sketch = ex?.sketch ? ex.sketch(p) : ''; } catch (e) { sketch = ''; }
    const sk = document.getElementById('cx-sketch');
    sk.innerHTML = sketch || '<div class="cx-nosketch"><i class="bi bi-card-text"></i>이 조건은 그림 대신 아래 설명으로 보여 드립니다.</div>';
    document.getElementById('cx-desc').previousElementSibling.innerHTML = '<i class="bi bi-sliders"></i>지금 숫자로 보면';
    document.getElementById('cx-desc').textContent = condDesc(preset, p);
    const botName = (botsList.find(b => b.id === currentBotId) || {}).name || '이 봇';
    const where = [inBuy && '매수 칸', inSell && (isPartialSet(inSell) ? '매도 칸(세트)' : '매도 칸')].filter(Boolean);
    document.getElementById('cx-bot').innerHTML = `
        <div class="cx-use"><span class="role-badge role-buy is-static">매수 칸</span>${preset.startBuy
            ? "<b>[시작]하자마자</b> 지금 맞는 코인을 거래 많은 순으로 최대 보유 수까지 사고, 그 뒤로는 새로 맞게 된 코인만 삽니다. 다른 조건과 '그리고'로 묶으면 거르기로만 씁니다"
            : '이 조건에 <b>새로 들어온</b> 코인을 삽니다 ([시작] 때 이미 맞던 코인은 안 삽니다)'}</div>
        <div class="cx-use"><span class="role-badge role-sell is-static">매도 칸</span>봇이 산 코인이 이 조건에 맞으면 팝니다${id === 'spike_pump' ? ' — <b>세트</b>로 넣으면 일부만 팔고 싸지면 다시 삽니다' : id === 'surge_24h' ? ' — <b>세트</b>로 넣으면 꺾일 때 일부만 팔고 싸지면 다시 삽니다' : ''}</div>
        <div class="cx-use-note ${where.length ? 'is-on' : ''}"><i class="bi ${where.length ? 'bi-check-circle-fill' : 'bi-dash-circle'}"></i>${escapeHtml(botName)}: ${where.length ? `지금 <b>${where.join(' · ')}</b>에 넣어 두었습니다` : '지금은 쓰지 않습니다'}</div>`;
    renderCondExamples(preset, p);
    const actions = document.getElementById('cx-actions');
    actions.innerHTML = `${id === 'spike_pump' ? '<button type="button" class="btn btn-outline-success" data-open-verify><i class="bi bi-bar-chart-line me-1"></i>세트 검증 보기</button>' : ''}${id === 'surge_24h' ? '<button type="button" class="btn btn-outline-success" data-explain="set:surge_rebuy"><i class="bi bi-arrow-repeat me-1"></i>세트 보기</button>' : ''}
        <button type="button" class="btn btn-outline-primary" data-cx-screen="${id}"><i class="bi bi-grid-3x3-gap me-1"></i>현재 이 조건의 코인들 보기</button>
        <button type="button" class="btn btn-primary" data-bs-dismiss="modal">확인</button>`;
    bootstrap.Modal.getOrCreateInstance(document.getElementById('cond-explain-modal')).show();
}

