// 지난 자료 검증 (2026-10-07, strahub-research/probe24: 일봉 2년 241종 · 4시간봉 1년 74종, 같은 때 모든 코인 평균과 비교)
const PATTERN_PROOF = {
    shooting_star: '지난 검증: 일봉에서 나온 뒤 20일 동안 같은 때 다른 코인들보다 평균 1% 더 내렸습니다(앞·뒤 기간 모두). 35개 패턴 중 꾸준히 맞은 3개 중 하나입니다.',
    measured_down: '지난 검증: 나온 뒤 같은 때 다른 코인들보다 일봉 20일 1%, 4시간봉 7일 2% 더 내렸습니다(앞·뒤 기간 모두). 35개 패턴 중 꾸준히 맞은 3개 중 하나입니다.',
    diamond_bottom: '지난 검증: 나온 뒤 같은 때 다른 코인들보다 일봉 20일 0.8%, 4시간봉 7일 0.8% 더 올랐습니다(앞·뒤 기간 모두). 35개 패턴 중 꾸준히 맞은 3개 중 하나입니다.',
    measured_up: '지난 검증: 오히려 나온 뒤 같은 때 다른 코인들보다 일봉 10~20일 2% 정도 덜 올랐습니다. 뚫고 오른 뒤 되돌아오는 일이 많았습니다.',
    asc_scallop: '지난 검증: 오히려 나온 뒤 같은 때 다른 코인들보다 일봉 5~20일 2% 정도 덜 올랐습니다. 뚫고 오른 뒤 되돌아오는 일이 많았습니다.',
    three_rising_valleys: '지난 검증: 오히려 나온 뒤 같은 때 다른 코인들보다 1% 정도 덜 올랐습니다(일봉 · 4시간봉 모두).',
    hs_bottom: '지난 검증: 오히려 나온 뒤 같은 때 다른 코인들보다 일봉 10~20일 3~4% 덜 올랐습니다.',
};
for (const id of Object.keys(COND_EXPLAIN)) {
    if (!SCREEN_PRESETS.some(x => x.id === id) || !COND_EXPLAIN[id].summary.endsWith(PATTERN_NOTE)) continue;
    COND_EXPLAIN[id].summary += ` ${PATTERN_PROOF[id] || '지난 검증(일봉 2년 · 4시간봉 1년): 이 모양이 나온 뒤에도 같은 때 다른 코인들과 뚜렷한 차이가 없었습니다.'}`;
}

// 조건 · 패턴 · 세트 설명 맨 위 (2026-10-08): 한 덩어리 문장 대신
//  패턴 = [모양] · [뜻] 줄 + 지난 검증 판정 상자(초록 꾸준히 맞음 / 노랑 오히려 반대 / 회색 차이 없음) + '보장 없음' 한 줄
//  그 밖 = 첫 문장 굵게 + 나머지 문장은 점 목록
function renderCxSummary(text) {
    const box = document.getElementById('cx-summary');
    if (!box) return;
    const split = (x) => x.split(/(?<=[.!?])\s+(?=\S)/).map(v => v.trim()).filter(Boolean);
    const note = PATTERN_NOTE.trim();
    if (text.includes(note)) {
        const [body, proofRaw = ''] = text.split(note).map(v => v.trim());
        const [shape, ...meaning] = split(body);
        const detail = proofRaw.replace(/^지난 검증(\([^)]*\))?:\s*/, '');
        const tone = /꾸준히 맞은/.test(detail) ? 'ok' : /^오히려/.test(detail) ? 'warn' : 'none';
        const head = { ok: '꾸준히 맞았습니다', warn: '오히려 반대로 나왔습니다', none: '뚜렷한 차이가 없었습니다' }[tone];
        const icon = { ok: 'bi-check-circle-fill', warn: 'bi-exclamation-triangle-fill', none: 'bi-dash-circle-fill' }[tone];
        const lines = split(detail).filter(v => !/^35개 패턴 중/.test(v) && !/^이 모양이 나온 뒤에도/.test(v));
        box.innerHTML = `<div class="cxs-rows">
                <div class="cxs-row"><span class="cxs-k"><i class="bi bi-bounding-box"></i>모양</span><span class="cxs-v">${escapeHtml(shape || '')}</span></div>
                ${meaning.length ? `<div class="cxs-row"><span class="cxs-k"><i class="bi bi-lightbulb"></i>뜻</span><span class="cxs-v">${escapeHtml(meaning.join(' '))}</span></div>` : ''}
            </div>
            <div class="cxs-proof is-${tone}"><i class="bi ${icon}"></i><div><b>지난 검증 · ${head}</b>
                ${lines.length ? `<span>${escapeHtml(lines.join(' '))}</span>` : ''}<small>일봉 2년 · 4시간봉 1년 · 같은 때 다른 코인들과 비교</small></div></div>
            <p class="cxs-note"><i class="bi bi-info-circle"></i>${escapeHtml(note)}</p>`;
        return;
    }
    const [lead, ...rest] = split(text);
    box.innerHTML = `${lead ? `<p class="cxs-lead">${escapeHtml(lead)}</p>` : ''}${rest.length ? `<ul class="cxs-list">${rest.map(v => `<li>${escapeHtml(v)}</li>`).join('')}</ul>` : ''}`;
}

// 지금 이 조건에 맞는 코인: 분석 화면과 같은 계산 + 같은 추이 그래프 (최대 4개)
function renderCondExamples(preset, p) {
    const box = document.getElementById('cx-examples');
    const cnt = document.getElementById('cx-count');
    if (!marketCoins.length) { box.innerHTML = '<div class="cx-empty">시세를 불러오는 중입니다. 잠시 뒤 다시 열어 주십시오.</div>'; cnt.textContent = ''; return; }
    let hits = [];
    try { hits = runScreen(preset, p); } catch (e) { hits = []; }
    // 보유코인 분석에서 열었으면 오른쪽 목록과 같게 '보유 코인 중'으로 (전체 개수는 옆에)
    const total = hits.length;
    const mine = screenScope === 'holdings';
    if (mine) hits = hits.filter(screenInScope);
    const key = preset.sortKey, dir = preset.sortDir === 'asc' ? 1 : -1;
    hits.sort((a, b) => ((a[key] ?? Infinity * dir) - (b[key] ?? Infinity * dir)) * dir);
    cnt.textContent = mine ? `보유 코인 중 ${hits.length}개 (전체 코인 ${total}개)` : `${hits.length}개`;
    if (!hits.length) { box.innerHTML = `<div class="cx-empty">지금은 ${mine ? '보유 코인 중 ' : ''}이 조건에 맞는 코인이 없습니다.</div>`; return; }
    box.innerHTML = '';
    for (const h of hits.slice(0, 4)) {
        const card = document.createElement('div');
        card.className = 'cx-ex';
        card.innerHTML = `<div class="cx-ex-head"><b></b><small></small><span class="${pnlClass(h.change_rate)}">${formatChangeRate(h.change_rate)}</span></div><div class="cx-ex-chart"></div>`;
        card.querySelector('b').textContent = h.korean_name || h.currency;
        card.querySelector('small').textContent = h.currency;
        const cell = card.querySelector('.cx-ex-chart');
        let chart = null;
        const fn = SCREEN_CHARTS[preset.id] || preset.chart;
        try { chart = fn ? fn(h, p, condDataFor(h, p) || {}) : null; } catch (e) { chart = null; }      // 목록과 같은 봉 · 같은 자료
        if (chart) { chart.dataset.basis = basisLabel(preset, p); cell.appendChild(chart); } else fillSparkCell(cell, h, preset.spark, false);
        box.appendChild(card);
    }
}

// ── 그림이 없던 조건 22개: 쉬운 설명 + 모양 그림 (2026-10-12) ──
const cxRect = (x, y, w, h, fill, extra = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="${fill}" ${extra}/>`;
const cxSub = (y = 84, h = 56) => cxRect(16, y, 328, h, '#f8fafc');           // 아래 지표 칸 바탕
const cxArrowV = (x, y1, y2, color, label, side = 'start') => `<line x1="${x}" y1="${y1}" x2="${x}" y2="${y2}" stroke="${color}" stroke-width="1.6" marker-end="url(#cxa)"/>`
    + `<defs><marker id="cxa" markerWidth="7" markerHeight="7" refX="3.5" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 Z" fill="${color}"/></marker></defs>`
    + (label ? cxText(x + (side === 'start' ? 8 : -8), (y1 + y2) / 2 + 4, label, color, side) : '');
const cxMacd = (up) => {
    // 위: 가격 · 아래: MACD(청록) · 시그널(주황) · 막대(차이)
    const price = up ? [[16, 40], [80, 52], [140, 62], [200, 58], [260, 44], [334, 30]] : [[16, 60], [80, 46], [140, 36], [200, 40], [260, 54], [334, 68]];
    const macd = up ? [[16, 128], [80, 124], [140, 118], [200, 110], [250, 100], [334, 92]] : [[16, 96], [80, 100], [140, 106], [200, 114], [250, 124], [334, 132]];
    const sig = up ? [[16, 118], [80, 120], [140, 118], [200, 114], [250, 108], [334, 102]] : [[16, 106], [80, 104], [140, 106], [200, 110], [250, 116], [334, 122]];
    const bars = Array.from({ length: 14 }, (_, i) => {
        const x = 24 + i * 22, d = up ? (i - 7) * 1.6 : (7 - i) * 1.6, h = Math.abs(d) + 1;
        return cxRect(x, d >= 0 ? 112 - h : 112, 10, h, d >= 0 ? 'rgba(200,74,49,.35)' : 'rgba(18,97,196,.35)', 'rx="1"');
    }).join('');
    return cxSvg(cxLine(price, CX.ink, 2) + cxText(24, 18, '가격', CX.mute, 'start') + cxSub(78, 66) + bars
        + cxLine(macd, CX.teal, 2.2) + cxLine(sig, CX.warm, 2) + cxDot(up ? 214 : 214, up ? 113 : 112, up ? CX.up : CX.down)
        + cxText(24, 143, 'MACD', CX.teal, 'start') + cxText(68, 143, '시그널', '#b45309', 'start')
        + cxText(214, 74, up ? 'MACD가 시그널을 위로' : 'MACD가 시그널을 아래로', up ? CX.up : CX.down));
};
const cxCoinRow = (n, on, label = (i) => '', x0 = 22, y = 60) => Array.from({ length: n }, (_, i) => {
    const x = x0 + i * 33, hit = on(i);
    return `<circle cx="${x + 12}" cy="${y}" r="12" fill="${hit ? '#fde68a' : '#f1f5f9'}" stroke="${hit ? CX.warm : '#cbd5e1'}" stroke-width="1.6"/>` + cxText(x + 12, y + 4, label(i), hit ? '#92400e' : CX.mute);
}).join('');

