// 검증 그래프: [전체 보기] 또는 두 번 클릭 → 처음 크기로
document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-sv-zoom-reset]');
    if (!b) return;
    const c = svCharts[b.closest('.sv-chart')?.querySelector('canvas')?.id];
    c?.resetZoom();
    b.classList.add('d-none');
    b.previousElementSibling?.classList.remove('d-none');
});
document.addEventListener('dblclick', (e) => {
    const cv = e.target.closest('.sv-chart canvas');
    if (!cv || !svCharts[cv.id]) return;
    svCharts[cv.id].resetZoom();
    cv.parentElement.querySelector('[data-sv-zoom-reset]')?.classList.add('d-none');
    cv.parentElement.querySelector('.sv-zoom span')?.classList.remove('d-none');
});

