function condSearchText(p) {
    let d = '';
    try { d = typeof p.desc === 'function' ? p.desc(screenParamsOf(p)) : (p.desc || ''); } catch (e) { d = ''; }
    return `${p.title} ${String(d).replace(/<[^>]*>/g, '')} ${COND_EN[p.id] || ''}`.toLowerCase();
}
