function vennSvg(mode, color) {
    const fill = (on) => (on ? `${color}` : '#e2e8f0');
    const a = mode === 'any', both = 'url(#mh-both)';
    return `<svg viewBox="0 0 220 120" class="mh-venn" role="img" aria-label="${a ? '또는' : '그리고'} 그림">
        <defs><clipPath id="mh-clip-${mode}"><circle cx="85" cy="60" r="48"/></clipPath></defs>
        <circle cx="85" cy="60" r="48" fill="${a ? fill(true) : '#f1f5f9'}" fill-opacity="${a ? 0.55 : 1}" stroke="${color}" stroke-width="1.5"/>
        <circle cx="135" cy="60" r="48" fill="${a ? fill(true) : '#f1f5f9'}" fill-opacity="${a ? 0.55 : 1}" stroke="${color}" stroke-width="1.5"/>
        <circle cx="135" cy="60" r="48" fill="${color}" fill-opacity="${a ? 0.25 : 0.85}" clip-path="url(#mh-clip-${mode})"/>
        <text x="58" y="64" class="mh-t">A</text><text x="155" y="64" class="mh-t">B</text>
        <text x="110" y="64" class="mh-t ${a ? '' : 'is-on'}" text-anchor="middle">${a ? '' : '둘 다'}</text>
    </svg>`;
}
function openMatchHelp(side) {
    const h = MATCH_HELP[side] || MATCH_HELP.buy;
    let el = document.getElementById('match-help-modal');
    if (!el) {
        el = document.createElement('div');
        el.className = 'modal fade';
        el.id = 'match-help-modal';
        el.tabIndex = -1;
        el.innerHTML = `<div class="modal-dialog modal-dialog-centered modal-lg"><div class="modal-content mh-content">
            <div class="modal-header"><h5 class="modal-title" id="mh-title"></h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="닫기"></button></div>
            <div class="modal-body" id="mh-body"></div>
            <div class="modal-footer"><button type="button" class="btn btn-primary" data-bs-dismiss="modal">확인</button></div></div></div>`;
        document.body.appendChild(el);
        el.addEventListener('click', (e) => { const t = e.target.closest('[data-mh-tab]'); if (t) openMatchHelp(t.dataset.mhTab); });
    }
    const color = { target: '#7c3aed', buy: '#c84a31', sell: '#1261c4' }[side] || '#6366f1';
    const now = ruleMatch(side) === 'all' ? 'all' : 'any';
    el.querySelector('#mh-title').innerHTML = `<i class="bi bi-diagram-3 me-2"></i>'또는'과 '그리고' — ${h.name} 칸`;
    el.querySelector('#mh-body').innerHTML = `
        <div class="rel-help-tabs">${Object.entries(MATCH_HELP).map(([k, v]) => `<button type="button" class="${k === side ? 'active' : ''}" data-mh-tab="${k}">${v.name} 칸</button>`).join('')}</div>
        <div class="mh-grid">
            ${['any', 'all'].map(m => `<section class="mh-card${m === now ? ' is-now' : ''}" style="--mh:${color}">
                <div class="mh-head"><b>${m === 'any' ? '또는' : '그리고'}</b><span>${m === 'any' ? h.any : h.all}</span>${m === now ? '<em>지금 설정</em>' : ''}</div>
                ${vennSvg(m, color)}
                <p>${m === 'any' ? h.anyText : h.allText}</p>
                <div class="mh-eg"><small>예: A = ${escapeHtml(h.eg[0])} · B = ${escapeHtml(h.eg[1])}</small><b>→ ${escapeHtml(m === 'any' ? h.egAny : h.egAll)}</b></div>
            </section>`).join('')}
        </div>
        <section class="mh-note"><i class="bi bi-intersect"></i><div><b>겹치는 코인은?</b><p>${h.overlap}</p></div></section>
        <section class="mh-note is-tip"><i class="bi bi-lightbulb"></i><div><b>알아 두실 점</b><p>${h.tip}</p></div></section>`;
    bootstrap.Modal.getOrCreateInstance(el).show();
}
document.addEventListener('click', (e) => {
    const q = e.target.closest('[data-match-help]');
    if (q) { e.preventDefault(); e.stopPropagation(); openMatchHelp(q.dataset.matchHelp); }
}, true);

// ── 조건에 지금 맞는 코인 목록 (조건 모음의 숫자 · › 단추) ──
function openCondCoins(id) {
    const preset = SCREEN_PRESETS.find(p => p.id === id);
    if (!preset) return;
    let rows = [];
    try { rows = runScreen(preset, screenParamsOf(preset, false)); } catch (e) { rows = []; }
    let el = document.getElementById('cond-coins-modal');
    if (!el) {
        el = document.createElement('div');
        el.className = 'modal fade';
        el.id = 'cond-coins-modal';
        el.tabIndex = -1;
        el.innerHTML = `<div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable"><div class="modal-content pick-modal cc-modal">
            <div class="modal-header"><h5 class="modal-title" id="cc-title"></h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="닫기"></button></div>
            <div class="pm-bar"><div class="pm-search"><i class="bi bi-search"></i><input type="search" class="form-control form-control-sm" id="cc-q" placeholder="코인명 · 심볼 (초성 가능)" autocomplete="off"></div>
                <span class="pm-count" id="cc-count"></span></div>
            <div class="cc-desc" id="cc-desc"></div>
            <div class="modal-body p-0"><table class="table table-sm table-hover mb-0 pm-table"><thead class="table-light"><tr>
                <th>코인</th><th class="text-end">현재가</th><th class="text-end">전일 대비</th><th class="text-end">거래대금(24시간)</th></tr></thead>
                <tbody id="cc-body"></tbody></table></div>
            <div class="modal-footer"><small class="text-muted me-auto">지금 시세 기준이며, 조건 모음의 숫자와 같은 계산입니다.</small><button type="button" class="btn btn-primary" data-bs-dismiss="modal">확인</button></div>
        </div></div>`;
        document.body.appendChild(el);
        el.addEventListener('input', (e) => { if (e.target.id === 'cc-q') renderCondCoins(); });
    }
    el._rows = rows;
    el.querySelector('#cc-title').innerHTML = `<i class="bi ${preset.icon} me-2"></i>${escapeHtml(preset.title)} <small class="text-muted">· 지금 맞는 코인</small>`;
    el.querySelector('#cc-desc').textContent = condDesc(preset, screenParamsOf(preset, false));
    el.querySelector('#cc-q').value = '';
    renderCondCoins();
    bootstrap.Modal.getOrCreateInstance(el).show();
}
function renderCondCoins() {
    const el = document.getElementById('cond-coins-modal');
    if (!el) return;
    const q = el.querySelector('#cc-q').value.trim();
    const all = (el._rows || []).slice().sort((a, b) => (b.trade_value_24h || 0) - (a.trade_value_24h || 0));
    const rows = all.filter(c => !q || matchesQuery(c, q));
    el.querySelector('#cc-count').innerHTML = `<b>${all.length}</b>개${q ? ` 중 ${rows.length}개` : ''}`;
    const body = el.querySelector('#cc-body');
    body.innerHTML = rows.length ? rows.map(c => `<tr><td class="pm-coin" data-pm-logo="${escapeHtml(c.currency)}"><b>${escapeHtml(c.korean_name || c.currency)}</b> <small class="text-muted">${escapeHtml(c.currency)}</small></td>
        <td class="text-end">${c.current_price ? formatPrice(c.current_price) : '-'}</td>
        <td class="text-end ${pnlClass(c.change_rate)}">${formatChangeRate(c.change_rate)}</td>
        <td class="text-end">${c.trade_value_24h ? formatTradeValue(c.trade_value_24h) : '-'}</td></tr>`).join('')
        : `<tr><td colspan="4" class="text-center text-muted py-4">${marketCoins.length ? '지금 이 조건에 맞는 코인이 없습니다' : '코인 시세를 불러오는 중입니다. 잠시 뒤 다시 열어 주십시오.'}</td></tr>`;
    body.querySelectorAll('[data-pm-logo]').forEach(td => td.prepend(createCoinLogo(td.dataset.pmLogo)));
}
document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-cond-coins]');
    if (b && b.textContent !== '…') { e.preventDefault(); e.stopPropagation(); openCondCoins(b.dataset.condCoins); }
}, true);
document.addEventListener('keydown', (e) => {
    const b = e.target.closest?.('[data-cond-coins]');
    if (b && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); openCondCoins(b.dataset.condCoins); }
});

function openCondGroupHelp(key) {
    const g = [...COND_GROUPS, COND_SET_GROUP].find(x => x.key === key), d = COND_GROUP_HELP[key];
    if (!g || !d) return;
    let el = document.getElementById('cg-help-modal');
    if (!el) {
        el = document.createElement('div');
        el.className = 'modal fade';
        el.id = 'cg-help-modal';
        el.tabIndex = -1;
        el.innerHTML = `<div class="modal-dialog modal-dialog-centered rel-help-dialog"><div class="modal-content">
            <div class="modal-header"><h5 class="modal-title" id="cg-help-title"></h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="닫기"></button></div>
            <div class="modal-body" id="cg-help-body"></div>
            <div class="modal-footer"><button type="button" class="btn btn-primary" data-bs-dismiss="modal">확인</button></div></div></div>`;
        document.body.appendChild(el);
    }
    const names = key === 'set' ? (RULE_SETS || []).map(x => x.title)
        : g.ids.map(id => SCREEN_PRESETS.find(p => p.id === id)?.title).filter(Boolean);
    const isPat = key.startsWith('pat_');   // 패턴 묶음끼리 · 기본 묶음끼리만 위 탭으로 오감
    const tabs = [...COND_GROUPS.filter(x => COND_GROUP_HELP[x.key] && x.key.startsWith('pat_') === isPat), ...(isPat ? [] : [COND_SET_GROUP])];
    el.querySelector('#cg-help-title').innerHTML = `<span class="me-2">${g.icon}</span>${escapeHtml(g.title)}`;
    el.querySelector('#cg-help-body').innerHTML = `
        <div class="rel-help-tabs">${tabs.map(x => `<button type="button" class="${x.key === key ? 'active' : ''}" data-cg-help-go="${x.key}">${x.title}</button>`).join('')}</div>
        ${helpBodyHtml({ ...d, extra: names.length ? `<section class="hp-sec"><h6>들어 있는 조건 ${names.length}개</h6><div class="hp-chips is-list">${names.map(n => `<span>${escapeHtml(n)}</span>`).join('')}</div></section>` : '',
            foot: '조건마다 자세한 뜻은 조건 칸의 ? 를 눌러 보십시오' })}`;
    bootstrap.Modal.getOrCreateInstance(el).show();
}
document.addEventListener('click', (e) => {
    const q = e.target.closest('[data-cg-help]');
    if (q) { e.preventDefault(); e.stopPropagation(); openCondGroupHelp(q.dataset.cgHelp); return; }
    const go = e.target.closest('[data-cg-help-go]');
    if (go) openCondGroupHelp(go.dataset.cgHelpGo);
}, true);                                                   // 묶음 접기보다 먼저
document.addEventListener('keydown', (e) => {
    const q = e.target.closest?.('[data-cg-help]');
    if (q && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); e.stopPropagation(); openCondGroupHelp(q.dataset.cgHelp); }
}, true);

// 접은 묶음은 화면마다 따로 기억 (이 브라우저에만)
const condGroupClosed = { screen: new Set(), palette: new Set() };
try {
    const saved = JSON.parse(localStorage.getItem('condGroupClosed') || '{}');
    for (const k of Object.keys(condGroupClosed)) (saved[k] || []).forEach(x => condGroupClosed[k].add(x));
} catch (e) { /* 저장소를 못 쓰면 모두 펼침 */ }
function saveCondGroupClosed() {
    try { localStorage.setItem('condGroupClosed', JSON.stringify({ screen: [...condGroupClosed.screen], palette: [...condGroupClosed.palette] })); } catch (e) { /* 무시 */ }
}

// 목록 → [묶음 제목, 조건, 조건, 묶음 제목, …]. 접힌 묶음은 제목만 (검색 중이면 모두 펼침)
function condGroupRows(presets, scope, enabled = true, forceOpen = false) {
    if (!enabled) return presets;
    const rows = [];
    const used = new Set();
    const groups = COND_GROUPS.map(g => ({ g, items: g.ids.map(id => presets.find(p => p.id === id)).filter(Boolean) }));
    groups.forEach(x => x.items.forEach(p => used.add(p.id)));
    groups.push({ g: COND_OTHER_GROUP, items: presets.filter(p => !used.has(p.id)) });
    for (const { g, items } of groups) {
        if (!items.length) continue;
        const closed = !forceOpen && condGroupClosed[scope].has(g.key);
        const hasActive = scope === 'screen' && screenOn && items.some(p => p.id === screenPresetId);
        rows.push({ groupHead: true, g, n: g.key === 'pick' ? null : condGroupCoinCount(items, scope), closed, hasActive });
        if (!closed) rows.push(...items);
    }
    return rows;
}

// 묶음 머리의 숫자 = 그 묶음 조건 중 하나라도 지금 맞는 코인 수 (겹치면 한 번만). 조건 개수는 헷갈려서 쓰지 않음
// 시세를 아직 못 받았으면 null (숫자 안 보임)
function condGroupCoinCount(items, scope) {
    if (!marketCoins.length) return null;
    const hit = new Set();
    for (const p of items) {
        let rows = [];
        try { rows = runScreen(p, scope === 'palette' ? screenParamsOf(p, false) : null); } catch (e) { rows = []; }
        for (const c of rows) if (scope !== 'screen' || screenInScope(c)) hit.add(c.currency);
    }
    return hit.size;
}

function condGroupHeadHtml(row, scope) {
    const { g, n, closed, hasActive } = row;
    const countHtml = n === null || n === undefined ? ''
        : `<span class="cg-count${n ? '' : ' is-zero'}" title="이 묶음 조건 중 하나라도 지금 맞는 코인 ${n}개">${n}<small>개</small></span>`;
    return `<button type="button" class="cond-group-head${closed ? ' is-closed' : ''}${hasActive ? ' has-active' : ''}" data-cond-group="${g.key}" data-group-scope="${scope}"
            aria-expanded="${!closed}" title="눌러서 ${closed ? '펼치실' : '접으실'} 수 있습니다.">
        <i class="bi bi-chevron-down cg-chev" aria-hidden="true"></i><span class="cg-icon" aria-hidden="true">${g.icon}</span>
        <span class="cg-title">${g.title}</span>${COND_GROUP_HELP[g.key] ? `<span class="cg-q" role="button" tabindex="0" data-cg-help="${g.key}" title="${escapeHtml(g.tip || '눌러서 자세히 보실 수 있습니다.')}" aria-label="${g.title} 설명">?</span>` : ''}<span class="cg-fill"></span>
        ${hasActive ? '<span class="cg-active" title="고른 조건이 이 묶음 안에 있습니다"></span>' : ''}${countHtml}
    </button>`;
}

document.addEventListener('click', (e) => {
    const h = e.target.closest('[data-cond-group]');
    if (!h) return;
    e.preventDefault();
    const set = condGroupClosed[h.dataset.groupScope];
    if (set.has(h.dataset.condGroup)) set.delete(h.dataset.condGroup); else set.add(h.dataset.condGroup);
    saveCondGroupClosed();
    if (h.dataset.groupScope === 'screen') renderScreenList(); else renderBotRuleSelects();
});

// ── 봇 현황 · 보유 코인 캔들차트: 고른 코인의 캔들 + 산 가격(초록 선) + 산 때(초록 화살표) ──
let bdHoldSym = '';
let bdHoldUnit = '15';
let bdHoldChart = null;       // { key, chart, series, line, loadedAt, entry }
const HOLD_UNITS = [['1', '1분'], ['5', '5분'], ['10', '10분'], ['15', '15분'], ['30', '30분'], ['60', '1시간'], ['240', '4시간'], ['day', '일'], ['week', '주'], ['month', '월']];
const HOLD_REFRESH_MS = 30000;

function renderHoldChart(pos) {
    const box = document.getElementById('bd-hold-chart');
    if (!box) return;
    if (!pos) {
        bdHoldChart?.chart?.remove();
        bdHoldChart = null;
        box.innerHTML = '<div class="db-empty"><i class="bi bi-bar-chart"></i>코인을 사면 여기에 캔들차트가 나옵니다</div>';
        return;
    }
    const key = `${currentBotId}|${pos.symbol}|${bdHoldUnit}`;
    if (bdHoldChart?.key === key) {
        // 같은 코인: 산 가격이 바뀌었으면(다시 사서 평균이 바뀜) 선만 옮기고, 30초마다 캔들 새로
        if (bdHoldChart.entry !== pos.entry_price) setHoldEntry(pos);
        if (Date.now() - bdHoldChart.loadedAt > HOLD_REFRESH_MS) loadHoldCandles(pos, key);
        return;
    }
    bdHoldChart?.chart?.remove();
    bdHoldChart = null;
    const cur = pos.symbol.replace('KRW-', '');
    const name = marketCoins.find(c => c.currency === cur)?.korean_name || cur;
    box.innerHTML = `<div class="hc-head"><b></b><small>${cur}</small>
            <div class="hc-units" role="group" aria-label="캔들 단위">${HOLD_UNITS.map(([u, t]) => `<button type="button" class="${u === bdHoldUnit ? 'active' : ''}" data-hold-unit="${u}">${t}</button>`).join('')}</div></div>
        <div class="hc-chart"><div class="db-empty"><span class="spinner-border spinner-border-sm"></span> 캔들 불러오는 중…</div></div>
        <div class="hc-legend"><span class="lg-entry">━ 산 가격</span><span class="lg-buy">▲ 산 때</span></div>`;
    box.querySelector('.hc-head b').textContent = name;
    if (typeof LightweightCharts === 'undefined') {
        box.querySelector('.hc-chart').innerHTML = '<div class="db-empty">캔들차트를 불러오지 못했습니다 (인터넷 연결 확인)</div>';
        return;
    }
    bdHoldChart = { key, loadedAt: 0 };
    loadHoldCandles(pos, key);
}

async function loadHoldCandles(pos, key) {
    bdHoldChart.loadedAt = Date.now();
    let candles = null;
    try {
        const r = await (await fetch(`/api/candles?market=${encodeURIComponent(pos.symbol)}&unit=${bdHoldUnit}`)).json();
        if (r.success) candles = r.candles;
    } catch (e) { /* 아래에서 안내 */ }
    if (bdHoldChart?.key !== key) return;                     // 그 사이 다른 코인을 고름
    const el = document.querySelector('#bd-hold-chart .hc-chart');
    if (!el) return;
    if (!candles?.length) {
        if (!bdHoldChart.chart) el.innerHTML = '<div class="db-empty">캔들을 받지 못했습니다. 잠시 뒤 다시 보여 드립니다</div>';
        bdHoldChart.loadedAt = Date.now() - HOLD_REFRESH_MS + 5000;   // 5초 뒤 다시 시도
        return;
    }
    const KST = 9 * 3600;
    const data = candles.map(c => ({ time: c[0] + KST, open: c[1], high: c[2], low: c[3], close: c[4] }));
    if (!bdHoldChart.chart) {
        el.innerHTML = '';
        const chart = LightweightCharts.createChart(el, {
            height: Math.max(220, bdChartH - 34), layout: { background: { color: '#ffffff' }, textColor: '#475569', fontSize: 11 },
            grid: { vertLines: { color: '#f1f5f9' }, horzLines: { color: '#f1f5f9' } },
            timeScale: { timeVisible: bdHoldUnit !== 'day', secondsVisible: false, borderColor: '#e2e8f0', rightOffset: 6 }, rightPriceScale: { borderColor: '#e2e8f0' },
            crosshair: { mode: 0 }, localization: { priceFormatter: (p) => formatPrice(p).replace('원', '') },
        });
        bdHoldChart.chart = chart;
        bdHoldChart.series = chart.addCandlestickSeries({ upColor: '#c84a31', downColor: '#1261c4', borderVisible: false, wickUpColor: '#c84a31', wickDownColor: '#1261c4' });
        bdHoldChart.series.setData(data);
        chart.timeScale().fitContent();
        // 숨은 탭에서 만들면 폭이 0이라 캔들이 한쪽에 몰림 → 폭이 크게 바뀌면 다시 꽉 차게
        let lastW = el.clientWidth;
        new ResizeObserver(() => {
            if (!el.clientWidth) return;
            chart.applyOptions({ width: el.clientWidth });
            if (Math.abs(el.clientWidth - lastW) > 80) chart.timeScale().fitContent();
            lastW = el.clientWidth;
        }).observe(el);
    } else {
        bdHoldChart.series.setData(data);
    }
    bdHoldChart.data = data;
    setHoldEntry(pos);
}

// 산 가격 = 초록 가로선, 산 때 = 그 봉 아래 초록 화살표 (차트 기간 밖이면 선만)
function setHoldEntry(pos) {
    const hc = bdHoldChart;
    if (!hc?.series) return;
    if (hc.line) hc.series.removePriceLine(hc.line);
    hc.line = hc.series.createPriceLine({ price: pos.entry_price, color: '#16a34a', lineWidth: 1, lineStyle: 0, axisLabelVisible: true, title: '산 가격' });
    hc.entry = pos.entry_price;
    const markers = [];
    if (pos.opened_at && hc.data?.length) {
        const x = Math.floor(new Date(pos.opened_at).getTime() / 1000) + 9 * 3600;   // opened_at 은 이 PC 시간(한국)
        if (x >= hc.data[0].time) {
            let t = hc.data[0].time;
            for (const d of hc.data) { if (d.time <= x) t = d.time; else break; }
            markers.push({ time: t, position: 'belowBar', color: '#16a34a', shape: 'arrowUp', text: '매수' });
        }
    }
    hc.series.setMarkers(markers);
}

document.addEventListener('click', (e) => {
    const u = e.target.closest('[data-hold-unit]');
    if (u) {
        bdHoldUnit = u.dataset.holdUnit;
        if (bdLast) renderBotHoldings(bdLast.status?.positions || []);
        return;
    }
    const row = e.target.closest('#bd-hold-tbody [data-hold-sym]');
    if (!row || (row.dataset.holdSym === bdHoldSym && bdChartView === 'coin')) return;
    pickHoldCoin(row.dataset.holdSym);
});
document.addEventListener('keydown', (e) => {
    const row = e.target.closest?.('#bd-hold-tbody [data-hold-sym]');
    if (row && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); row.click(); }
});

// 조건 목록의 [모든 코인 보기]: 고른 조건을 꺼서 아무 조건 없이 전체 보기
document.addEventListener('click', (e) => {
    if (!e.target.closest('[data-screen-all]') || !screenOn) return;
    setScreenOn(false);
    renderScreenList();
});

// 봇이 하나도 없으면: 오른쪽 현황·단계 칸을 숨기고 만들기 안내만 (지운 봇의 숫자·그래프가 남지 않게)
function renderBotsEmpty() {
    const main = document.querySelector('#bots .bots-main');
    if (!main) return;
    const empty = !botsList.length;
    main.classList.toggle('is-empty', empty);
    if (!empty) return;
    currentBotId = null;
    bdLast = null;
    bdChartKey = '';
    bdDonutKey = '';
    bdChart?.destroy(); bdChart = null;
    bdDonut?.destroy(); bdDonut = null;
    bdHoldChart?.chart?.remove(); bdHoldChart = null;
    bdHoldSym = '';
}

// ── 봇 현황 · 매매 내역: 표 + 코인을 누르면 매수·매도가 표시된 캔들차트 ──
let bdLogTab = 'trades';
const TC_UNITS = [['1', '1분', 1], ['5', '5분', 5], ['10', '10분', 10], ['15', '15분', 15], ['30', '30분', 30], ['60', '1시간', 60], ['240', '4시간', 240], ['day', '일', 1440], ['week', '주', 10080], ['month', '월', 43200]];
let tcState = null;          // { sym, trades, unit, chart }

const tradeTimeText = (t) => {
    const d = new Date(t);
    return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
};

function tradeRowsHtml(list, withCoin = true) {
    return `<table class="table table-sm db-trade-table mb-0"><thead><tr><th>시간</th>${withCoin ? '<th>코인</th>' : ''}<th>구분</th>
        <th class="text-end">가격</th><th class="text-end">금액</th><th class="text-end">손익</th><th>이유</th></tr></thead><tbody>${
        list.map((t, i) => {
            const cur = String(t.symbol || '').replace('KRW-', '');
            const name = marketCoins.find(c => c.currency === cur)?.korean_name || cur;
            const buy = t.side === 'buy';
            const p = t.profit;
            return `<tr ${withCoin ? `data-trade-sym="${escapeHtml(t.symbol || '')}" role="button" tabindex="0" title="${escapeHtml(name)} 매수·매도 차트 보기"` : ''}>
                <td class="text-nowrap">${tradeTimeText(t.time)}</td>
                ${withCoin ? `<td class="text-nowrap"><span class="tr-logo" data-logo="${escapeHtml(cur)}"></span><b>${escapeHtml(name)}</b> <small class="text-muted">${escapeHtml(cur)}</small></td>` : ''}
                <td><span class="tr-side ${buy ? 'is-buy' : 'is-sell'}">${buy ? '매수' : '매도'}</span></td>
                <td class="text-end">${formatPrice(t.price)}</td>
                <td class="text-end">${formatKrw(t.total)}</td>
                <td class="text-end ${p === null || p === undefined ? '' : pnlClass(p)}">${p === null || p === undefined ? '-' : `${p > 0 ? '+' : ''}${formatKrw(p)}`}</td>
                <td class="tr-why">${escapeHtml(t.reason || '')}</td></tr>`;
        }).join('')}</tbody></table>`;
}

function fillTradeLogos(box) {
    box.querySelectorAll('[data-logo]').forEach(el => { if (!el.firstChild) el.appendChild(createCoinLogo(el.dataset.logo)); });
}

// 봇 총 자산 칸: 그 거래 직후 코인 가치 + 남은 원화, 배지 = 그때 봇 수익률 (판 손익 포함 · 손익 전 금액 대비)
function botPnlHtml(r) {
    if (r.bot_total === null || r.bot_total === undefined) return '<span class="text-muted">-</span>';
    const rate = r.bot_pnl_rate;
    const badge = rate === null || rate === undefined ? ''
        : ` <span class="tx-pct ${rate >= 0 ? 'is-up' : 'is-down'}">${rate >= 0 ? '▲' : '▼'} ${Math.abs(rate).toFixed(2)}%</span>`;
    const tip = `코인 ${formatKrw(r.bot_coins)} + 원화 ${formatKrw(r.bot_cash)}`;
    return `<span class="bd-total" title="${tip}">${formatKrw(r.bot_total)}</span>${badge}`;   // 코인 · 원화 나눠 보기는 마우스를 올렸을 때만
}

// 봇 기록 한 건 → 거래 내역 줄 모양 (total = 정산금액: 살 땐 수수료 포함해 낸 돈, 팔 땐 수수료 빼고 받은 돈)
function botTradeRow(t, botName) {
    const cur = String(t.symbol || '').replace('KRW-', ''), buy = t.side === 'buy';
    const fee = Number(t.fee) || 0, total = Number(t.total) || 0;
    return { time: t.time, order_time: t.time, currency: cur, market: 'KRW', kind: buy ? '매수' : '매도',
             volume: t.qty ?? null, price: t.price ?? null, amount: total ? (buy ? total - fee : total + fee) : null,
             fee, settle: total, avg_cost: buy ? t.avg_cost : null, bot_pnl: t.bot_pnl, bot_pnl_rate: t.bot_pnl_rate, bot_total: t.bot_total, bot_coins: t.bot_coins, bot_cash: t.bot_cash,   // 산 뒤 평균 (서버가 전체 기록으로 셈)
             bot: botName, reason: t.reason || '', buy_reason: t.buy_reason, profit: t.profit, sym: t.symbol };
}
let bdTxRows = [];

async function openBotTradeChart(key, sym) {
    const botId = currentBotId, botName = (botsList.find(b => b.id === botId) || {}).name || '';
    const src = `bot:${botId}:${sym}`, label = `${botName || '이 봇'}의 매매 전부`;
    txUseRows(bdTxRows.filter(r => r.sym === sym), label, '#bd-trades tbody', src);
    selectTrade(key, 'table');
    try {
        const r = await (await fetch(`/api/bots/${botId}/trades?symbol=${encodeURIComponent(sym)}`)).json();
        const all = (r.trades || []).map(t => botTradeRow(t, botName)).reverse();   // 최신순
        if (!all.length || txState.src !== src) return;
        txUseRows(all, label, '#bd-trades tbody', src);
        renderTxChart();
    } catch (e) { /* 표에 있던 줄로 그대로 */ }
}

// 매매 내역 검색: 비어 있으면 최근 기록(상세 응답), 글자가 있으면 이 봇 기록 전부에서 코인명 · 심볼 · 초성 · 이유로 거름
let bdRecentTrades = [];
const bdAllTrades = { bot: '', at: 0, list: null, busy: false };
async function bdAllTradesLoad() {
    const bot = currentBotId;
    if (!bot || bdAllTrades.busy) return;
    if (bdAllTrades.bot === bot && bdAllTrades.list && Date.now() - bdAllTrades.at < 30000) return;
    bdAllTrades.busy = true;
    try {
        const r = await (await fetch(`/api/bots/${bot}/trades`)).json();
        if (bot !== currentBotId || !r.success) return;
        Object.assign(bdAllTrades, { bot, at: Date.now(), list: (r.trades || []).slice().reverse() });   // 최신순
    } catch (e) { /* 검색은 최근 기록에서만 */ } finally { bdAllTrades.busy = false; }
}
function bdLogQuery() { return document.getElementById('bd-log-search')?.value.trim() || ''; }
function bdTradeMatch(t, q) {
    const cur = String(t.symbol || '').replace('KRW-', '');
    return matchesQuery({ currency: cur, korean_name: coinKoreanName(cur) }, q)
        || String(t.reason || '').includes(q) || String(t.buy_reason || '').includes(q);
}
// 매매 내역 새로고침: 봇 상세(최근 기록)와, 검색 중이면 기록 전부를 지금 다시 받음
document.getElementById('bd-log-refresh')?.addEventListener('click', async (e) => {
    const btn = e.currentTarget, bot = currentBotId;
    if (!bot || btn.disabled) return;
    btn.disabled = true;
    btn.querySelector('i')?.classList.add('spin');
    try {
        const d = await (await fetch(`/api/bots/${bot}`)).json();
        if (bot !== currentBotId) return;
        bdAllTrades.at = 0;
        if (bdLogQuery()) await bdAllTradesLoad();
        const box = document.getElementById('bd-trades');
        if (box) box.dataset.key = '';
        if (d.success) renderBotDetail(d);
        showNotification(`매매 내역을 다시 읽었습니다 (${new Date().toLocaleTimeString('ko-KR', { hour12: false })})`, 'success');
    } catch (err) {
        showNotification('매매 내역을 다시 읽지 못했습니다: ' + err.message, 'error');
    } finally {
        btn.disabled = false;
        btn.querySelector('i')?.classList.remove('spin');
    }
});
document.getElementById('bd-log-search')?.addEventListener('input', async () => {
    const box = document.getElementById('bd-trades');
    if (box) box.dataset.key = '';
    if (bdLogQuery()) await bdAllTradesLoad();
    renderBotTrades(bdRecentTrades);
});

function renderBotTrades(list) {
    const box = document.getElementById('bd-trades');
    if (!box) return;
    bdRecentTrades = list;
    const q = bdLogQuery();
    if (q) {
        if (bdAllTrades.bot !== currentBotId || !bdAllTrades.list) bdAllTradesLoad().then(() => { if (bdLogQuery()) { box.dataset.key = ''; renderBotTrades(bdRecentTrades); } });
        list = ((bdAllTrades.bot === currentBotId && bdAllTrades.list) || list).filter(t => bdTradeMatch(t, q));
    }
    const key = `${marketCoins.length > 0}|${currentBotId}|${q}|` + list.map(t => `${t.time}|${t.symbol}|${t.side}|${t.bot_total}`).join(',');   // 시세가 오면 코인 이름으로 다시
    if (box.dataset.key === key && box.firstChild) return;        // 3초마다 같은 내용이면 다시 그리지 않음 (스크롤 유지)
    box.dataset.key = key;
    const botName = (botsList.find(b => b.id === currentBotId) || {}).name || '';
    const rows = bdTxRows = list.map(t => botTradeRow(t, botName));   // 거래 내역 탭과 같은 줄
    box.innerHTML = list.length
        ? `<table class="table table-hover mb-0 data-table bd-tx-table"><thead class="table-light">${TX_HEAD.replace('</tr>',
            '<th class="text-end" title="그 거래를 한 순간에 기록한 이 봇의 돈 전체 = 가진 코인 평가액 + 매수 가능 금액 (기록이라 바뀌지 않습니다). 배지는 그 순간의 수익률">봇 총 자산 <small class="text-muted fw-normal">거래 순간</small></th></tr>')}</thead><tbody>${rows.map(r =>
            `<tr data-trade-sym="${escapeHtml(r.sym || '')}" data-tx-key="${escapeHtml(txKey(r))}" class="${txState.rows && txState.sel === txKey(r) ? 'tx-sel' : ''}" role="button" tabindex="0" title="누르면 창이 떠서 ${escapeHtml(coinKoreanName(r.currency))} 캔들차트에 이 거래를 보여 드립니다.">${txRowCells(r)}<td class="text-end bd-cum">${botPnlHtml(r)}</td></tr>`).join('')}</tbody></table>`
        : (q ? `<div class="db-empty"><i class="bi bi-search"></i>'${escapeHtml(q)}'에 맞는 기록이 없습니다</div>` : '<div class="db-empty"><i class="bi bi-receipt"></i>아직 사고판 기록이 없습니다</div>');
    if (q && list.length) box.insertAdjacentHTML('afterbegin', `<div class="bd-log-found">'${escapeHtml(q)}' 검색 결과 <b>${list.length.toLocaleString()}</b>건 <small>(이 봇 기록 전부에서)</small></div>`);
    fillTradeLogos(box);
    fitTxResult(box.querySelector('table'));
}

function setLogTab(tab) {
    if (!document.getElementById('bot-decisions')) tab = 'trades';     // 판단 기록 탭은 없앰 — 늘 매매 내역
    bdLogTab = tab;
    document.querySelectorAll('#bd-log-tabs [data-log-tab]').forEach(b => b.classList.toggle('active', b.dataset.logTab === tab));
    document.getElementById('bd-trades')?.classList.toggle('d-none', tab !== 'trades');
    document.getElementById('bot-decisions')?.classList.toggle('d-none', tab !== 'decisions');
    document.getElementById('bd-log-search')?.classList.toggle('d-none', tab !== 'trades');
    document.getElementById('bd-log-refresh')?.classList.toggle('d-none', tab !== 'trades');
    const hint = document.getElementById('bd-log-hint');
    if (hint) hint.textContent = tab === 'trades' ? '이 봇이 사고판 기록 · 줄을 누르면 그 거래를 캔들차트 창으로' : '무엇을 왜 사고팔았는지 · 사지 않고 건너뛴 이유까지 (실행 중일 때만)';
}

// 거래가 모두 들어가는 가장 촘촘한 캔들 단위 (캔들 200개 안에)
function autoTradeUnit(trades) {
    const ts = trades.map(t => new Date(t.time).getTime());
    const span = Math.max(...ts) - Math.min(...ts);             // 첫 거래 ~ 마지막 거래
    const need = Math.max(span * 1.4, 2 * 3600e3);
    return (TC_UNITS.find(([, , m]) => 200 * m * 60e3 >= need) || TC_UNITS[TC_UNITS.length - 1])[0];
}

async function openTradeChart(sym) {
    const cur = sym.replace('KRW-', '');
    const name = marketCoins.find(c => c.currency === cur)?.korean_name || cur;
    document.getElementById('tc-title').textContent = name;
    document.getElementById('tc-sub').textContent = `${cur} · ${(botsList.find(b => b.id === currentBotId) || {}).name || '이 봇'}의 매매`;
    const logo = document.getElementById('tc-logo');
    logo.innerHTML = '';
    logo.appendChild(createCoinLogo(cur));
    document.getElementById('tc-chart').innerHTML = '<div class="db-empty"><span class="spinner-border spinner-border-sm"></span> 불러오는 중…</div>';
    document.getElementById('tc-list').innerHTML = '';
    document.getElementById('tc-stats').innerHTML = '';
    document.getElementById('tc-note').textContent = '';
    bootstrap.Modal.getOrCreateInstance(document.getElementById('trade-chart-modal')).show();
    let trades = [];
    try {
        const r = await (await fetch(`/api/bots/${currentBotId}/trades?symbol=${encodeURIComponent(sym)}`)).json();
        trades = r.trades || [];
    } catch (e) { /* 아래에서 안내 */ }
    tcState?.chart?.remove();
    tcState = { sym, trades, unit: trades.length ? autoTradeUnit(trades) : '15', chart: null };
    const buys = trades.filter(t => t.side === 'buy'), sells = trades.filter(t => t.side === 'sell');
    const realized = sells.reduce((s, t) => s + (Number(t.profit) || 0), 0);
    document.getElementById('tc-stats').innerHTML = `<span>매수 <b>${buys.length}</b>번</span><span>매도 <b>${sells.length}</b>번</span>`
        + `<span>판 것 손익 <b class="${pnlClass(realized)}">${realized > 0 ? '+' : ''}${formatKrw(realized)}</b></span>`;
    const list = document.getElementById('tc-list');
    list.innerHTML = trades.length ? tradeRowsHtml([...trades].reverse(), false) : '<div class="db-empty">이 코인의 거래 기록이 없습니다</div>';
    drawTradeChart();
}

async function drawTradeChart() {
    const st = tcState;
    if (!st) return;
    document.getElementById('tc-units').innerHTML = TC_UNITS.map(([u, t]) => `<button type="button" class="${u === st.unit ? 'active' : ''}" data-tc-unit="${u}">${t}</button>`).join('');
    const el = document.getElementById('tc-chart');
    const mins = TC_UNITS.find(([u]) => u === st.unit)[2];
    // 거래가 보이게 끝 시각을 정함: 마지막 거래 뒤로 여유를 두되 지금보다 늦지 않게
    let to = '';
    if (st.trades.length) {
        const last = Math.max(...st.trades.map(t => new Date(t.time).getTime()));
        const end = Math.min(Date.now(), last + 200 * mins * 60e3 * 0.3);
        if (Date.now() - end > mins * 60e3) to = new Date(end).toISOString().slice(0, 19) + 'Z';
    }
    let candles = null;
    try {
        const r = await (await fetch(`/api/candles?market=${encodeURIComponent(st.sym)}&unit=${st.unit}${to ? `&to=${to}` : ''}`)).json();
        if (r.success) candles = r.candles;
    } catch (e) { /* 아래에서 안내 */ }
    if (tcState !== st) return;
    if (!candles?.length || typeof LightweightCharts === 'undefined') {
        el.innerHTML = '<div class="db-empty">캔들을 받지 못했습니다. 잠시 뒤 다시 열어 주십시오</div>';
        return;
    }
    st.chart?.remove();
    el.innerHTML = '';
    const KST = 9 * 3600;
    const data = candles.map(c => ({ time: c[0] + KST, open: c[1], high: c[2], low: c[3], close: c[4] }));
    const chart = LightweightCharts.createChart(el, {
        height: 380, layout: { background: { color: '#ffffff' }, textColor: '#475569', fontSize: 11 },
        grid: { vertLines: { color: '#f1f5f9' }, horzLines: { color: '#f1f5f9' } },
        timeScale: { timeVisible: st.unit !== 'day', secondsVisible: false, borderColor: '#e2e8f0', rightOffset: 4 }, rightPriceScale: { borderColor: '#e2e8f0' },
        crosshair: { mode: 0 }, localization: { priceFormatter: (p) => formatPrice(p).replace('원', '') },
    });
    st.chart = chart;
    const series = chart.addCandlestickSeries({ upColor: '#c84a31', downColor: '#1261c4', borderVisible: false, wickUpColor: '#c84a31', wickDownColor: '#1261c4' });
    series.setData(data);
    const first = data[0].time, lastBar = data[data.length - 1].time + mins * 60;
    const snap = (x) => { let t = data[0].time; for (const d of data) { if (d.time <= x) t = d.time; else break; } return t; };
    let hidden = 0;
    const markers = [];
    for (const t of st.trades) {
        const x = Math.floor(new Date(t.time).getTime() / 1000) + KST;
        if (x < first || x >= lastBar) { hidden += 1; continue; }
        const buy = t.side === 'buy';
        markers.push({ time: snap(x), position: buy ? 'belowBar' : 'aboveBar', color: buy ? '#c84a31' : '#1261c4', shape: buy ? 'arrowUp' : 'arrowDown',
                       text: buy ? '매수' : (t.profit === null || t.profit === undefined ? '매도' : `매도 ${t.profit >= 0 ? '+' : '−'}${Math.abs(t.profit) < 1e5 ? Math.round(Math.abs(t.profit)).toLocaleString() : formatKrwShort(Math.abs(t.profit))}원`) });
    }
    markers.sort((a, b) => a.time - b.time);
    series.setMarkers(markers);
    chart.timeScale().fitContent();
    const mk = String(st.sym).startsWith('KRW-') ? st.sym : `KRW-${st.sym}`;
    const botPos = (bdLast?.status?.positions || []).find(p => p.symbol === mk);
    if (botPos?.entry_price) addAvgBuyLine(series, Number(botPos.entry_price), '봇 산 가격');
    else myAvgBuy(mk).then(avg => { if (tcState === st) addAvgBuyLine(series, avg); });
    new ResizeObserver(() => { if (el.clientWidth) chart.applyOptions({ width: el.clientWidth, height: el.clientHeight || 380 }); }).observe(el);
    document.getElementById('tc-note').textContent = hidden ? `이 단위로는 거래 ${hidden}건이 차트 범위 밖입니다 (더 긴 단위를 골라 보십시오)` : '';
}

document.addEventListener('click', (e) => {
    const tab = e.target.closest('[data-log-tab]');
    if (tab) { setLogTab(tab.dataset.logTab); return; }
    const u = e.target.closest('[data-tc-unit]');
    if (u && tcState) { tcState.unit = u.dataset.tcUnit; drawTradeChart(); return; }
    const row = e.target.closest('#bd-trades [data-tx-key]');
    if (row) openBotTradeChart(row.dataset.txKey, row.dataset.tradeSym);   // 거래 내역 탭과 같은 차트 창
});
document.addEventListener('keydown', (e) => {
    const row = e.target.closest?.('#bd-trades [data-tx-key]');
    if (row && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); openBotTradeChart(row.dataset.txKey, row.dataset.tradeSym); }
});
document.getElementById('trade-chart-modal')?.addEventListener('hidden.bs.modal', () => { tcState?.chart?.remove(); tcState = null; });

// ── 시작할 때 한꺼번에 사기 (시뮬레이션, ② 매수 칸): 0 = 안 함, N개, -1 = 전체 ──
function seedFormValue() {
    const v = parseInt(document.getElementById('seed-top')?.value, 10);
    return Number.isFinite(v) ? v : 0;
}
function setSeedForm(v, save = true) {
    const box = document.getElementById('seed-top');
    if (box) box.value = String(v);
    renderSeedBox();
    ['rule-summary', 'bot-detail-summary', 'builder-summary'].forEach(id => {   // '봇이 할 일' 요약도 바로
        const el = document.getElementById(id);
        if (el && el.innerHTML) el.innerHTML = botRulesSummaryHtml();
    });
    if (save) debouncedAutoSave();
}
// 살 수 있는 코인 수 어림 (스테이블·유의 종목·상장폐지 예정 빼고 — 봇과 같은 기준)
function seedEligibleCount() {
    return marketCoins.filter(c => c.current_price && !isStableCoin(c) && !c.warning
        && !(c.notices || []).some(n => n?.type === 'delisting')).length;
}
// '시작할 때 한꺼번에 사기'는 시험용 보조 기능: 평소엔 접어 두고 링크만. 개수를 정해 둔 봇이면 펼친 채로
function renderSeedVisibility() {
    const open = IS_SIM && String(seedFormValue()) !== '0';   // 예전에 개수를 정해 둔 봇만 (끌 수 있게)
    document.getElementById('seed-box')?.classList.toggle('d-none', !open);
}
document.addEventListener('click', (e) => {
    if (e.target.closest('#seed-close')) setSeedForm(0);
});

function renderSeedBox() {
    renderSeedVisibility();
    const v = seedFormValue();
    const presets = ['0', '10', '30', '50', '100', '-1'];
    document.querySelectorAll('#seed-box [data-seed]').forEach(b => {
        const on = b.dataset.seed === String(v);
        b.classList.toggle('active', on);
        b.setAttribute('aria-pressed', String(on));
    });
    const custom = document.getElementById('seed-custom');
    if (custom && document.activeElement !== custom) custom.value = presets.includes(String(v)) ? '' : String(v);
    custom?.closest('.seed-custom')?.classList.toggle('is-on', !presets.includes(String(v)));
    const info = document.getElementById('seed-info');
    if (!info) return;
    const bot = botsList.find(b => b.id === (builder.botId || currentBotId));
    const done = bot?.seeded
        ? '<div class="seed-done"><i class="bi bi-check-circle-fill me-1"></i>이 봇은 이미 한꺼번에 샀습니다. 바꾼 개수는 봇 현황의 <b>[새로 시작]</b>을 누르면 적용됩니다 (산 코인은 팔고 기록은 보관).</div>'
        : '';
    if (!v) {
        info.innerHTML = '봇을 <b>시작할 때</b> 거래대금 상위 코인을 최대 투입 금액으로 똑같이 나눠 한 번에 삽니다. 매도 규칙(예: 순간 급등 세트)을 빨리 시험할 때 씁니다.' + done;
        info.classList.remove('is-warn');
        return;
    }
    const all = seedEligibleCount();
    const n = v < 0 ? all : (all ? Math.min(v, all) : v);
    const budget = moneyValue('initial-balance') || Number(currentStatus?.sim_account?.krw || 0);
    const each = n ? budget / n : 0;
    const low = each && each < 5000;
    info.innerHTML = `시작하면 거래대금 상위 <b>${v < 0 ? `전체${all ? ` ${all}개` : ''}` : `${n}개`}</b>를 `
        + `${moneyValue('initial-balance') ? `최대 투입 금액 ${formatKrw(budget)}` : `가상 원화 ${formatKrw(budget)}`}으로 똑같이 나눠 <b>한 번만</b> 삽니다`
        + `${each ? ` · 코인당 약 <b>${formatKrw(each)}</b>` : ''}<br>`
        + '<span class="text-muted">스테이블·유의 종목 제외 · 매수 조건 없이도 시작 · 최대 보유 수 제한 없음 · 손절·익절이 켜져 있으면 먼저 팔릴 수 있습니다 · 다시 사려면 봇 현황의 [새로 시작]</span>'
        + done + (low ? '<div class="seed-warn"><i class="bi bi-exclamation-triangle-fill me-1"></i>코인당 5,000원(최소 주문 금액)보다 적어서 못 사는 코인이 생깁니다. 성과 탭 위 기본 정보에서 최대 투입 금액을 늘리거나 개수를 줄여 주십시오.</div>' : '');
}
document.addEventListener('click', (e) => {
    const b = e.target.closest('#seed-box [data-seed]');
    if (b) setSeedForm(parseInt(b.dataset.seed, 10));
});
document.addEventListener('change', (e) => {
    if (e.target.id !== 'seed-custom') return;
    const v = Math.round(Number(e.target.value));
    if (Number.isFinite(v) && v >= 1) setSeedForm(Math.min(300, v));
});
document.addEventListener('input', (e) => { if (e.target.id === 'initial-balance') renderSeedBox(); });
document.addEventListener('change', (e) => {
    if (['initial-balance', 'position-size', 'max-positions', 'max-order-krw'].includes(e.target.id) && startBuyTitles().length) renderBotRuleSelects();
});

// 한꺼번에 사기가 켜진 시뮬레이션이면 매수 조건 없이도 시작할 수 있음
function seedOnInForm() {
    return IS_SIM && seedFormValue() !== 0;
}

// '코인 성격' 조건(startBuy, 예: 급등이 잦던 코인): '그리고'로 다른 매수 조건과 묶지 않으면 봇을 시작할 때 지금 맞는 코인을 삼
// (봇은 원래 '새로 들어온' 코인만 사는데, 잘 안 바뀌는 성격은 새로 들어오기를 기다리면 거의 사지 않으므로) → 그 조건 이름들
// 시작할 때 사기 안내: 실제로 몇 개를 얼마씩 사는지 (예산 ÷ 코인당 금액, 최대 보유 수, 지금 맞는 코인 수 중 작은 것)
// 지금 맞는 코인 중 이 봇의 매매대상 · 사지 않을 코인으로 거른 것 (전에는 전체 코인으로 세어 '고른 5개' 봇도 115개로 보였음, 2026-10-15)
function inBotTargets(hits) {
    const ex = new Set((botRules.exclude || []).map(x => String(x).toUpperCase().replace('KRW-', '')));
    // 봇(bot_engine._universe · _allow)과 같게: 유의 종목 · 상장폐지 예정 · 스테이블은 이 모드에서 풀어 두지 않았으면 뺌 (2026-10-15)
    const al = skipAllowOf(botRules)[APP_MODE] || {};
    const delisting = (c) => (c.notices || []).some(n => n?.type === 'delisting');
    let out = hits.filter(c => !ex.has(c.currency)
        && (al.allow_warning || !c.warning) && (al.allow_delist || !delisting(c)) && (al.include_stable || !isStableCoin(c)));
    const sets = [];
    for (const r of ruleList('target')) {
        if (r.id === 'pick_coins') { sets.push(new Set(pickCoins().map(x => String(x).toUpperCase().replace('KRW-', '')))); continue; }
        const p = SCREEN_PRESETS.find(x => x.id === r.id);
        if (r.id === 'held_coins') {                             // 보유 코인: 실제 계좌 모드만 화면이 알 수 있음 (시뮬레이션 보유는 봇이 셈)
            if (!IS_SIM) sets.push(new Set(marketCoins.filter(c => c.held).map(c => c.currency)));
            continue;
        }
        if (!p) continue;
        try { sets.push(new Set(runScreen(p, { ...screenParamsOf(p), ...(r.params || {}) }).map(c => c.currency))); } catch (e) { /* 건너뜀 */ }
    }
    if (!sets.length) return out;
    const all = ruleMatch('target') === 'all';
    return out.filter(c => (all ? sets.every(s => s.has(c.currency)) : sets.some(s => s.has(c.currency))));
}

function startBuyNoticeHtml(preset, params) {
    const num = (id) => Number(document.getElementById(id)?.value) || 0;
    // 굴리는 돈: 배분을 % 로 정한 봇은 서버가 계산한 기준(봇이 산 코인 + 원화), 금액으로 정한 봇은 그 금액 (2026-10-08 % 봇이 '예산 0원'으로 보이던 것)
    const sb = Number(bdLast?.summary?.size_base) || 0;
    // 봇이 실제로 쓰는 기준(서버 size_base = min(운용 한도, 산 코인 + 원화))을 먼저. 시뮬레이션은 봇마다 정해진 돈이라 폼의 금액과 다름,
    // 금액 봇은 폼 금액이 계좌 원화보다 커도 원화만큼만 삼 (2026-10-17, 전에는 폼 금액으로 셈해 시뮬레이션에서 10배 작게 보였음)
    const form = moneyValue('initial-balance');
    const budget = IS_SIM ? (sb || boardPerBot || Number(currentStatus?.sim_account?.krw || 0))
        : budgetUnit === 'pct' ? sb : (sb ? Math.min(form || sb, sb) : form);
    const pct = num('position-size') || 10, maxPos = num('max-positions') || 3, maxOrder = moneyValue('max-order-krw') || 0;
    // 봇과 같은 계산 (risk_manager.calculate_position_size): 코인당 금액을 정했으면 그 금액,
    // '한 코인에 전부'(1회 100% · 최대 1개)면 30% 제한 없이 거의 전부, 그 밖에는 비율 · 잔고의 30%까지 (2026-10-15 100%가 30%로 보이던 것)
    const orderKrw = moneyValue('order-krw') || 0;
    let each;
    if (orderKrw > 0) each = maxOrder > 0 ? Math.min(orderKrw, maxOrder) : orderKrw;
    else if (pct >= 100 && maxPos === 1) each = Math.min(budget * 0.995, maxOrder > 0 ? maxOrder : Infinity);
    else each = Math.min(budget * pct / 100, budget * 0.3, maxOrder > 0 ? maxOrder : Infinity);
    each = Math.max(5000, each);
    let hits = null, hitList = [];
    try { hitList = marketCoins.length ? inBotTargets(runScreen(preset, params)) : []; hits = marketCoins.length ? hitList.length : null; } catch (e) { hits = null; }
    // 봇과 같게: 이미 가진 코인 수만큼 자리를 빼고, 쓸 수 있는 원화로 셈 (bot_engine._buy_fresh · _live_budget_left)
    const held = Number(bdLast?.summary?.holding) || 0;
    const room = Math.max(0, maxPos - held);
    const left = Math.min(budget, Number(bdLast?.summary?.cash) || budget);
    let byBudget = left ? Math.floor(left / (each * 1.003)) : 0;
    // 마지막 한 자리는 남은 돈으로 삼 (봇과 같음: 20% × 5개면 수수료 때문에 4개로 보이던 것) — 코인당 금액을 정한 봇은 아님
    if (!(orderKrw > 0) && left && byBudget === room - 1 && left - byBudget * each * 1.003 >= Math.max(5000, each * 0.5)) byBudget += 1;
    const n = Math.max(0, Math.min(byBudget, room, hits ?? Infinity));
    const limit = n === byBudget && byBudget < Math.min(room, hits ?? Infinity) ? `쓸 수 있는 돈 ${formatKrw(left)} ÷ 코인당 ${formatKrw(each)}`
        : n === room ? (held ? `최대 보유 ${maxPos}개 중 남은 ${room}자리` : `최대 보유 수 ${maxPos}개`) : '지금 맞는 코인 수';
    const tooSmall = (spikeRule() || surgeRule()) && each * 0.3 < 5000;
    const waitBox = `<label class="sb-wait" title="평균선 바로 위에서 켜 곧바로 다시 팔게 되는 일을 피하고 싶을 때 켭니다. 대신 켠 뒤 내려오지 않고 그대로 오르면 그 상승은 놓칩니다.">`
        + `<input type="checkbox" class="form-check-input" data-start-wait${botRules.start_wait ? ' checked' : ''}> 켤 때는 사지 않고, 새로 맞게 될 때만 삽니다 <small>(예: 평균선 아래로 내려갔다가 다시 뚫고 올라올 때)</small></label>`;
    if (botRules.start_wait) {
        return `<div class="rule-startbuy is-wait"><i class="bi bi-hourglass-split"></i><b>켤 때 사지 않음</b> 지금 맞는 ${hits ?? ''}${hits !== null ? '개' : '코인'}는 사지 않고, `
            + `이 조건에 <b>새로 맞게 되는 코인</b>만 코인당 <b>${formatKrw(each)}</b>씩 삽니다`
            + startBuyCoinsHtml(hitList, 0) + waitBox + `</div>`;
    }
    return `<div class="rule-startbuy"><i class="bi bi-lightning-charge-fill"></i><b>시작하자마자</b> 지금 맞는 ${hits ?? ''}${hits !== null ? '개 중 ' : '코인 중 '}`
        + `거래 많은 순 <b>약 ${n}개</b>를 코인당 <b>${formatKrw(each)}</b>씩 현재가로 삽니다 <span class="sb-why">(${limit}로 정해짐 — 늘리려면 위험 관리의 돈 관리에서 '1회 매수' 비율을 낮추거나 최대 보유를 늘립니다)</span>`
        + ` · '그리고'로 묶으면 거르기만`
        + startBuyCoinsHtml(hitList, n)
        + waitBox
        + (tooSmall ? `<div class="sb-warn">코인당 금액이 작아서 세트가 30%를 팔 때 최소 주문 금액(5,000원)보다 작아집니다. 세트를 쓰려면 코인당 약 17,000원 이상으로 정해 주십시오.</div>` : '')
        + `</div>`;
}

// 시작할 때 사기 안내 아래: 지금 맞는 코인 (거래 많은 순 — 앞 n개는 켜면 삼) · 고른 코인 중 아직 안 맞는 것은 '기다림'
function startBuyCoinsHtml(hitList, n) {
    const mine = new Set(((bdLast?.status?.positions) || (bdLast?.positions) || []).map(x => String(x.symbol || '').replace('KRW-', '')));
    const sorted = [...hitList].filter(c => !mine.has(c.currency)).sort((a, b) => (b.trade_value_24h || 0) - (a.trade_value_24h || 0));
    const nameOf = (c) => escapeHtml(c.korean_name || c.currency);
    const gap = (c) => (typeof c.s_gap_ma === 'number' ? ` <small>${c.s_gap_ma >= 0 ? '+' : ''}${c.s_gap_ma.toFixed(1)}%</small>` : '');
    const MAX = 12;
    let html = sorted.slice(0, MAX).map((c, i) => `<span class="sb-coin ${i < n ? 'is-buy' : 'is-full'}" title="${i < n ? '켜면 삼' : botRules.start_wait ? '켤 때는 사지 않음' : '자리가 없어 사지 않음'}">${nameOf(c)}${gap(c)}</span>`).join('');
    if (sorted.length > MAX) html += `<span class="sb-coin is-more">외 ${sorted.length - MAX}개</span>`;
    const hit = new Set(sorted.map(c => c.currency));
    const waiting = pickCoins().map(x => String(x).toUpperCase().replace('KRW-', '')).filter(x => !hit.has(x));
    const byCur = new Map(marketCoins.map(c => [c.currency, c]));
    const wait = waiting.map(x => `<span class="sb-coin is-wait" title="아직 조건에 맞지 않아 기다림">${escapeHtml(byCur.get(x)?.korean_name || x)}</span>`).join('');
    if (!html && !wait) return '';
    return `<div class="sb-coins">${html ? `<span class="sb-coins-lbl">지금 맞음</span>${html}` : ''}`
        + `${wait ? `<span class="sb-coins-lbl">기다림</span>${wait}` : ''}</div>`;
}

document.addEventListener('change', (e) => {
    if (!e.target.matches('[data-start-wait]')) return;
    if (e.target.checked) botRules.start_wait = true; else delete botRules.start_wait;
    saveBotRules();
    renderBotRuleSelects();
});

// ── 성과 탭 '현재 설정' 카드: 서버에 저장된 이 모드의 설정을 한눈에 (d = /api/bots/<id> 응답) ──
function renderBotSettingsCard(d) {
    const box = document.getElementById('bd-set-card');
    if (!box || !d?.bot) return;
    const b = d.bot, tr = b.trade_rules || {}, rk = b.risk_config || {}, s = d.summary || {};
    const esc = escapeHtml, won = (v) => formatKrw(Number(v) || 0);
    const num = (v) => Number(v) || 0;
    const list = (side) => ruleList(side, tr);
    const matchOf = (side) => (side === 'target' ? (tr.target_match === 'any' ? 'any' : 'all') : (tr[`${side}_match`] === 'all' ? 'all' : 'any'));   // 저장된 규칙 기준
    const match = (side) => (matchOf(side) === 'all' ? '그리고' : '또는');
    const condRow = (r, side) => {
        const preset = SCREEN_PRESETS.find(p => p.id === r.id);
        if (side === 'sell' && isPartialSet(r)) {
            const set = RULE_SETS.find(x => x.cond === r.id);
            return `<li title="${esc(set?.flow || '')}"><span class="bs-c bs-${side}">${esc(set?.title || preset?.title || r.id)}</span><em>보유의 ${num(r.portion) || 30}% 팔고 다시 삼</em></li>`;
        }
        if (r.id === 'pick_coins') return `<li><span class="bs-c bs-${side}">직접 고른 코인</span><span class="bs-tags">${((r.params?.coins || []).length ? r.params.coins : ['없음']).map(x => `<em>${esc(x)}</em>`).join('')}</span></li>`;
        if (!preset) return `<li><span class="bs-c is-missing">찾지 못한 조건</span><small>${esc(r.id)} (지운 내 조건일 수 있습니다)</small></li>`;
        let desc = '', short = '';
        try {
            const pv = ruleParams(preset, r);
            desc = condDesc(preset, pv);
            // 짧게: '평균선 40봉 · 평균선과 1% 넘게 아래' (긴 설명은 마우스를 올리면)
            short = (preset.params || []).filter(q => q.key !== 'tf' && pv[q.key] !== undefined && pv[q.key] !== ''
                    && !(Number(pv[q.key]) === 0 && /넘게/.test(q.unit || '')))          // '0% 넘게'처럼 뜻 없는 0 은 뺌
                .map(q => `${q.label ? `${q.label} ` : ''}${pv[q.key]}${q.unit || ''}`).join(' · ');
            if (TF_PRESETS.has(preset.id) && tfOf(pv) !== 'day') short = `${TF_LABEL[tfOf(pv)]} · ${short}`;
        } catch (e) { /* 설명 없이 */ }
        return `<li title="${esc(desc)}"><span class="bs-c bs-${side}">${esc(preset.title)}</span>${short ? `<span class="bs-tags">${short.split(' · ').map(x => `<em>${esc(x)}</em>`).join('')}</span>` : ''}</li>`;
    };
    const conds = (side, empty) => {
        const rs = list(side);
        if (!rs.length) return `<p class="bs-empty-t">${empty}</p>`;
        return `${rs.length > 1 ? `<div class="bs-match">${match(side) === '그리고' ? '모두 만족할 때' : '하나라도 맞을 때'} (${match(side)})</div>` : ''}<ul class="bs-conds">${rs.map(r => condRow(r, side)).join('')}</ul>`;
    };
    // 값: '·' 로 이어진 글자는 태그를 하나씩 (긴 값이 태그 안에서 꺾이지 않게)
    const tags = (v) => (String(v).startsWith('<span class="bs-tags">') ? String(v)            // 이미 태그 묶음
        : /<|>/.test(String(v)) || !String(v).includes(' · ') ? `<b>${v}</b>`
        : `<span class="bs-tags">${String(v).split(' · ').map(x => `<b>${x}</b>`).join('')}</span>`);
    const kv = (k, v, sub = '') => `<div class="bs-kv"><span>${k}</span>${tags(v)}${sub ? `<small>${sub}</small>` : ''}</div>`;
    const off = '<span class="bs-off">안 씀</span>';

    // 돈 관리 (봇 risk_manager 와 같은 갈래)
    const order = num(rk.order_krw), cap = num(rk.max_order_krw), pct = num(rk.position_size_percent), maxPos = num(rk.max_positions);
    const each = order > 0 ? `코인마다 ${won(Math.max(5000, cap > 0 ? Math.min(order, cap) : order))}`
        : pct >= 100 && maxPos === 1 ? '굴리는 돈 거의 전부 (한 코인)'
        : `굴리는 돈의 ${Math.min(pct, 30)}%${pct > 30 ? ` (정한 ${pct}% → 한 번에 30%까지)` : ''}`;
    const eachKrw = num(s.size_base) > 0 ? (order > 0 ? (cap > 0 ? Math.min(order, cap) : order)
        : pct >= 100 && maxPos === 1 ? num(s.size_base) * 0.995 : Math.min(num(s.size_base) * pct / 100, num(s.size_base) * 0.3)) : 0;
    const alloc = IS_SIM ? `${won(num(s.budget) || boardPerBot)} (시뮬레이션은 봇마다 같은 돈)`
        : num(s.budget_pct) > 0 ? `계좌의 ${num(s.budget_pct)}%` : num(s.budget) > 0 ? `${won(s.budget)} (정한 금액)` : '0% (새로 사지 않음)';
    const allow = skipAllowOf(tr)[APP_MODE] || {};
    const allowTxt = [allow.include_stable ? '스테이블' : '', allow.allow_warning ? '유의 종목' : '', allow.allow_delist ? '상장폐지 예정' : ''].filter(Boolean);
    const ex = tr.exclude || [];
    const startBuy = !(matchOf('buy') === 'all' && list('buy').length > 1)
        && list('buy').some(r => SCREEN_PRESETS.find(p => p.id === r.id)?.startBuy);
    const style = BOT_STYLES[b.style];

    box.innerHTML = `<div class="bs-grid">
        <section class="bs-sec"><h6><i class="bi bi-info-circle"></i>기본</h6>
            ${kv('모드', IS_SIM ? '시뮬레이션' : EX_NAME)}
            ${kv('성격', style ? `<i class="bi ${style.icon}"></i> ${style.label}` : '정하지 않음')}
            ${kv('매수 · 매도', `<span class="bs-tags">${b.trade_rules?.buy_on === false ? '<b><span class="bs-off">매수 꺼짐</span></b>' : '<b>매수 켜짐</b>'}${b.trade_rules?.sell_on === false ? '<b><span class="bs-off">매도 꺼짐 (손절만)</span></b>' : '<b>매도 켜짐</b>'}</span>`)}
            ${kv('배분', alloc, num(s.budget_now) > 0 ? `지금 약 ${won(s.budget_now)}` : '')}
            ${(b.seed_coins || []).length ? kv('처음에 사 둘 코인', esc(b.seed_coins.join(', ')), s.seeded ? '이미 샀습니다' : '시작하면 한 번') : ''}
            ${b.dca ? kv('나눠 사기', `${esc(b.dca.coin)} · ${num(b.dca.every_days)}일마다 ${won(b.dca.krw)}`, '팔지 않고 모음') : ''}
        </section>
        <section class="bs-sec"><h6><i class="bi bi-bullseye"></i>매매대상</h6>
            ${conds('target', '모든 코인')}
            ${kv('사지 않을 코인', ex.length ? esc(ex.join(', ')) : '없음')}
            ${kv('자동 제외', allowTxt.length ? `${['스테이블', '유의 종목', '상장폐지 예정'].filter(x => !allowTxt.includes(x)).join(' · ') || '없음'}` : '스테이블 · 유의 종목 · 상장폐지 예정', allowTxt.length ? `풀어 둔 것: ${allowTxt.join(' · ')}` : '')}
        </section>
        <section class="bs-sec"><h6><i class="bi bi-cart-plus"></i>매수 조건</h6>
            ${conds('buy', '매수 조건 없음')}
            ${startBuy ? kv('켤 때', tr.start_wait ? '사지 않음 · 새로 맞게 될 때만' : '지금 맞는 코인을 바로 삼') : ''}
        </section>
        <section class="bs-sec"><h6><i class="bi bi-cash-coin"></i>매도 조건</h6>
            ${conds('sell', '매도 조건 없음 (손절 · 익절 · 트레일링으로만)')}
        </section>
        <section class="bs-sec"><h6><i class="bi bi-wallet2"></i>돈 관리</h6>
            ${kv('1회 매수', each, eachKrw ? `지금 약 ${won(eachKrw)}` : '')}
            ${kv('최대 보유', `${maxPos}개`)}
            ${cap > 0 && !(order > 0) ? kv('1회 최대', won(cap)) : ''}
        </section>
        <section class="bs-sec"><h6><i class="bi bi-shield-check"></i>안전장치</h6>
            ${kv('손절', num(rk.stop_loss_percent) > 0 ? `−${num(rk.stop_loss_percent)}%` : off)}
            ${kv('익절', num(rk.take_profit_percent) > 0 ? `+${num(rk.take_profit_percent)}%` : off)}
            ${kv('트레일링', num(rk.trailing_stop_percent) > 0 ? `최고가에서 −${num(rk.trailing_stop_percent)}%` : off)}
            ${kv('하루 손실 한도', num(rk.daily_loss_limit_percent) > 0 ? `${num(rk.daily_loss_limit_percent)}%` : off, num(rk.daily_loss_limit_percent) > 0 ? '넘으면 그날은 새로 사지 않음' : '')}
        </section>
    </div>`;
    const sub = document.getElementById('bd-set-sub');
    if (sub) sub.textContent = `저장된 ${IS_SIM ? '시뮬레이션' : EX_NAME} 설정 · 바꾸려면 [규칙 고치기]`;
}
// 현재 설정 카드 접기 · 펼치기 (이 PC에 기억)
(function () {
    const sec = document.getElementById('bd-set-sec'), head = document.getElementById('bd-set-fold-head');
    if (!sec || !head) return;
    const apply = (f) => {
        sec.classList.toggle('is-folded', f);
        head.setAttribute('aria-expanded', String(!f));
        const t = document.querySelector('#bd-set-fold span');
        if (t) t.textContent = f ? '펼치기' : '접기';
    };
    let folded = false;
    try { folded = localStorage.getItem('bdSetFolded') === '1'; } catch (e) { /* 저장소 없음 */ }
    apply(folded);
    const toggle = () => {
        const f = !sec.classList.contains('is-folded');
        apply(f);
        try { localStorage.setItem('bdSetFolded', f ? '1' : '0'); } catch (e) { /* 무시 */ }
    };
    head.addEventListener('click', toggle);
    head.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); } });
})();

function startBuyTitles(rules = botRules) {
    const list = ruleList('buy', rules);
    if (ruleMatch('buy') === 'all' && list.length > 1) return [];
    return list.map(r => SCREEN_PRESETS.find(p => p.id === r.id)).filter(p => p?.startBuy).map(p => p.title);
}


// 맨 위 메뉴 줄 높이 → CSS --nav-h (화면 폭에 따라 줄바꿈되면 높이가 바뀜)
(function trackNavHeight() {
    const bar = document.querySelector('.navbar');
    if (!bar) return;
    const root = document.documentElement.style;
    const set = () => {
        root.setProperty('--nav-h', `${bar.offsetHeight}px`);
        // 봇 화면이 처음 놓이는 자리(메뉴 줄 아래 간격) → 붙는 자리를 같게 해서 내려도 움직이지 않게
        const layout = document.querySelector('.bots-layout');
        const top = layout?.getBoundingClientRect().top;
        if (layout && layout.offsetParent !== null) root.setProperty('--stick-gap', `${Math.max(0, Math.round(top + window.scrollY - bar.offsetHeight))}px`);
    };
    set();
    if (typeof ResizeObserver !== 'undefined') new ResizeObserver(set).observe(bar);
    window.addEventListener('resize', set);
    document.getElementById('bots-tab')?.addEventListener('shown.bs.tab', set);
})();

// ── 업비트 ⇄ 시뮬레이션 모드 토글 + 가상 계좌 ──
document.querySelectorAll('.app-mode-seg [data-app-mode]').forEach(btn => btn.addEventListener('click', async () => {
    const mode = btn.dataset.appMode;
    if (mode === APP_MODE) return;
    document.querySelectorAll('.app-mode-seg button').forEach(b => { b.disabled = true; });
    try {
        const d = await (await fetch('/api/app-mode', { method: 'POST', headers: { 'Content-Type': 'application/json' },
                                                         body: JSON.stringify({ mode }) })).json();
        if (!d.success) throw new Error(d.error || '모드를 바꾸지 못했습니다');
        rememberViewForModeSwitch();
        location.reload();
    } catch (e) {
        showNotification(e.message, 'error');
        document.querySelectorAll('.app-mode-seg button').forEach(b => { b.disabled = false; });
    }
}));

let lastSimAccount = null;
// 전체 봇 보드가 받은 계좌 숫자로 위쪽 '가상 계좌' 배지도 같이 (같은 시세로 셈한 같은 값을 보이게)
function syncSimBadgeFromBoard(acc) {
    if (!IS_SIM || !lastSimAccount || !acc || !(Number(acc.total) > 0)) return;
    const init = Number(lastSimAccount.initial_krw) || 0;
    const total = Number(acc.total);
    renderSimAccount({ ...lastSimAccount, total, krw: acc.krw, coin_value: acc.coins,
                       profit: init ? total - init : lastSimAccount.profit, profit_rate: init ? (total - init) / init * 100 : lastSimAccount.profit_rate });
}

function renderSimAccount(a) {
    lastSimAccount = a;
    const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    const profit = Number(a.profit || 0), rate = Number(a.profit_rate || 0);
    set('app-sim-total', `${formatKrw(a.total)} (${rate >= 0 ? '+' : ''}${rate.toFixed(2)}%)`);
    set('sim-initial', formatKrw(a.initial_krw));
    set('sim-krw', formatKrw(a.krw));
    set('sim-coins', formatKrw(a.coin_value));
    set('sim-total', formatKrw(a.total));
    const pe = document.getElementById('sim-profit');
    if (pe) { pe.textContent = `${profit >= 0 ? '+' : ''}${formatKrw(profit)} (${rate >= 0 ? '+' : ''}${rate.toFixed(2)}%)`; pe.className = pnlClass(profit); }
    set('sn-hint-sim', formatKrw(a.total));
}

async function loadSimAccount() {
    try {
        const d = await (await fetch('/api/sim-account')).json();
        if (!d.success) return;
        renderSimAccount(d.sim_account);
        const inp = document.getElementById('sim-initial-input');
        if (inp && !inp.dataset.touched) inp.value = formatMoneyText(d.sim_account.initial_krw);
    } catch (e) { console.error('가상 계좌 불러오기 오류', e); }
}
loadSimAccount();
document.getElementById('set-sim-tab')?.addEventListener('shown.bs.tab', loadSimAccount);
document.getElementById('sim-initial-input')?.addEventListener('input', (e) => { e.target.dataset.touched = '1'; });
document.getElementById('btn-sim-reset')?.addEventListener('click', async () => {
    const krw = moneyValue('sim-initial-input');
    if (!krw) { showNotification('초기자본을 넣어 주십시오', 'error'); return; }
    // 확인은 화면 안에서: 한 번 누르면 '한 번 더', 5초 안에 다시 누르면 실행 (브라우저 확인 창은 막혀 있으면 조용히 취소됨)
    const btn = document.getElementById('btn-sim-reset');
    if (btn.dataset.armed !== '1') {
        btn.dataset.armed = '1';
        btn.dataset.label = btn.innerHTML;
        btn.innerHTML = `<i class="bi bi-exclamation-triangle-fill me-1"></i>한 번 더 누르면 ${krw.toLocaleString()}원으로 초기화`;
        clearTimeout(btn._armTimer);
        btn._armTimer = setTimeout(() => { btn.dataset.armed = ''; btn.innerHTML = btn.dataset.label; }, 5000);
        return;
    }
    clearTimeout(btn._armTimer);
    btn.dataset.armed = '';
    btn.innerHTML = btn.dataset.label;
    try {
        const d = await (await fetch('/api/sim-account', { method: 'POST', headers: { 'Content-Type': 'application/json' },
                                                           body: JSON.stringify({ action: 'reset', initial_krw: krw }) })).json();
        showNotification(d.message || d.error, d.success ? 'success' : 'error');
        if (d.success) {
            delete document.getElementById('sim-initial-input').dataset.touched;
            renderSimAccount(d.sim_account);
            loadBots(false);
            updateStatus();
            transferRows = []; transfersLoadedDays = 0; tradeRows = []; tradeTotal = 0; tradeNext = null;   // 거래내역 화면에 남은 예전 기록도 비움
            try { localStorage.removeItem(TRADE_CACHE_KEY); } catch (e) { /* 무시 */ }
        }
    } catch (e) { showNotification('초기화 오류: ' + e.message, 'error'); }
});

// ── 보유코인 표: 봇의 '순간 급등'·'하루 급등' 일부 팔고 다시 사기 진행 상태 (조건이 아니라 봇이 지금 하는 일) ──
let spikeStates = new Map();       // 'BTC' → [{kind, phase, bot_name, sold_price, left, deadline, peak, running}]
let spikeStatesKey = '';
function spikeStateHtml(currency) {
    const items = spikeStates.get(currency);
    if (!items?.length) return '';
    const when = (t) => new Date(t * 1000).toLocaleString([], { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
    return items.map(x => {
        const bot = `${x.bot_name}${x.running ? '' : ' (멈춤)'}`;
        const surge = x.kind === 'surge';
        const set = surge ? 'set:surge_rebuy' : 'set:spike_rebuy';
        const what = surge ? '하루 급등' : '급등';
        if (x.phase === 'waiting') {
            const tip = `${bot}: ${what} 때 일부를 ${formatPrice(x.sold_price)}에 팔았습니다. `
                + `${x.left.map(formatPrice).join(' · ')}까지 내려오면 나눠 다시 사고, ${when(x.deadline)}까지 안 내려오면 그때 가격에 삽니다.`;
            return `<button type="button" class="spike-state-chip is-wait" data-explain="${set}" title="${escapeHtml(tip)}">`
                + `<i class="bi bi-arrow-repeat"></i> ${surge ? '하루 급등 · ' : ''}다시 사기 대기 · 판 가격 ${formatPrice(x.sold_price)}</button>`;
        }
        const tip = surge
            ? `${bot}: 24시간 동안 크게 오른 걸 잡았습니다. 최고 ${formatPrice(x.peak)}에서 꺾이면 일부를 팝니다 (48시간 안에 안 꺾이면 팔지 않습니다).`
            : `${bot}: 순간 급등을 잡았습니다. 최고 ${formatPrice(x.peak)}에서 꺾이면 일부를 팝니다.`;
        return `<button type="button" class="spike-state-chip is-sell" data-explain="${set}" title="${escapeHtml(tip)}">`
            + (surge ? '<i class="bi bi-graph-up-arrow"></i> 하루 급등 · 꺾이면 일부 팔기</button>' : '<i class="bi bi-fire"></i> 급등 감지 · 꺾이면 일부 팔기</button>');
    }).join('');
}
async function loadSpikeStates() {
    try {
        const d = await (await fetch('/api/bots/spike-active')).json();
        if (!d.success) return;
        const map = new Map();
        for (const x of d.items || []) {
            const cur = x.symbol.replace('KRW-', '');
            if (!map.has(cur)) map.set(cur, []);
            map.get(cur).push(x);
        }
        const key = JSON.stringify(d.items || []);
        if (key === spikeStatesKey) return;
        spikeStatesKey = key;
        spikeStates = map;
        if (holdingsAssets.length) renderHoldingsRows();
    } catch (e) { /* 다음에 다시 */ }
}
loadSpikeStates();
setInterval(() => { if (!document.hidden) loadSpikeStates(); }, 15000);

// ── 모드를 바꿔 새로 불러와도 보던 화면 그대로: 메인 탭 · 설정 메뉴 · 스크롤 위치 ──
function rememberViewForModeSwitch() {
    const tab = document.querySelector('#main-tabs .nav-link.active')?.id;
    const pane = document.querySelector('.settings-nav .nav-link.active')?.id;
    try { sessionStorage.setItem('viewAfterModeSwitch', JSON.stringify({ tab, pane, y: window.scrollY })); } catch (e) { /* 없으면 기본 화면 */ }
}
function restoreViewAfterModeSwitch() {
    let v = null;
    try { v = JSON.parse(sessionStorage.getItem('viewAfterModeSwitch') || 'null'); sessionStorage.removeItem('viewAfterModeSwitch'); } catch (e) { v = null; }
    if (!v) return;
    const tab = v.tab && document.getElementById(v.tab);
    if (tab) bootstrap.Tab.getOrCreateInstance(tab).show();
    const pane = v.pane && document.getElementById(v.pane);
    if (pane) bootstrap.Tab.getOrCreateInstance(pane).show();
    if (v.y) setTimeout(() => window.scrollTo({ top: v.y, behavior: 'instant' }), 400);
}

// ── 급등 지켜보기: 봇이 가진 코인 중 '순간 급등' 세 조건에 가장 가까운 3개 (1분마다) — 표 모양 (머리줄에 기준) ──
function spikeWatchHtml(spike, name) {
    const w = spike?.watch, st = spike?.settings;
    if (!w || !st?.enabled) return '';
    if (!w.ready) return `<div class="sp-empty"><i class="bi bi-hourglass-split me-1"></i>실시간 체결로 코인별 '평소 거래대금'을 모으는 중입니다 — 봇 프로그램을 켜고 1시간 뒤부터 지켜봅니다</div>`;
    const pctf = (v) => `${v >= 0 ? '+' : ''}${Number(v).toFixed(1)}%`;
    const multf = (v) => `${Number(v).toFixed(1)}배`;
    const cell = (v, t, fmt, ok = true) => {
        const pct = t > 0 ? Math.max(0, Math.min(100, v / t * 100)) : 0;
        const met = v >= t && ok;
        return `<div class="sw-cell${met ? ' is-met' : ''}" title="지금 ${fmt(v)} / 급등 기준 ${fmt(t)}${ok ? '' : ' (1분 거래대금 1천만 원 미만이라 안 셈)'}">
            <span class="sw-track"><span style="width:${pct.toFixed(0)}%"></span></span><span class="sw-val">${fmt(v)}</span></div>`;
    };
    const dots = (n) => `<span class="sw-dots" title="세 조건 중 ${n}개 맞음">${[0, 1, 2].map(i => `<i class="${i < n ? 'on' : ''}"></i>`).join('')}<b>${n}/3</b></span>`;
    const items = w.items || [];
    const head = `<div class="sw-grid sw-headrow"><span>코인</span><span>1시간 상승 <em>기준 ${pctf(st.rise_1h)}</em></span>
        <span>1분 상승 <em>기준 ${pctf(st.rise)}</em></span><span>거래대금 <em>평소의 ${multf(st.mult)}</em></span><span>맞은 조건</span></div>`;
    const rows = items.map(x => `<div class="sw-grid sw-line${x.met === 3 ? ' is-hit' : ''}">${name(x.symbol)}
        ${cell(x.rise_1h, st.rise_1h, pctf)}${cell(x.rise, st.rise, pctf)}${cell(x.mult, st.mult, multf, x.value >= 10000000)}${dots(x.met)}</div>`).join('');
    const best = w.best;
    const bestTime = best ? new Date(best.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '';
    return `<div class="sw-table">${head}${rows || '<div class="sp-empty">가진 코인의 방금 1분 체결이 없습니다</div>'}</div>`
        + (best ? `<div class="sw-best"><i class="bi bi-trophy"></i><span>켠 뒤 가장 가까웠던 순간 <b>${bestTime}</b></span>${name(best.symbol)}
            <span class="sw-best-v">1시간 ${pctf(best.rise_1h)} · 1분 ${pctf(best.rise)} · 거래 ${multf(best.mult)}</span>${dots(best.met)}</div>` : '');
}

// ── 계정 (권한표): 실제 주문(업비트 모드의 봇 시작·사기)만 로그인 필요. 시뮬레이션·팔기는 계정 없이 ──
// 서버 응답의 error_code 'LICENSE_REQUIRED' → 안내 창 (CONFIRM_LIVE 와 같은 방식)
let licenseStatus = null;
const PLAN_NAME = { beta: '베타', paid: '유료', free: '무료' };

function renderLicense(s) {
    licenseStatus = s;
    const set = (id, text) => { const el = document.getElementById(id); if (el) el.textContent = text; };
    const tone = s.state === 'ok' ? ((s.offline || s.needs_login) ? 'wait' : 'ok')
        : s.state === 'off' ? (s.needs_login ? 'bad' : 'off') : 'bad';
    set('acct-status-text', s.message || '');
    set('acct-status-sub', s.email ? `${s.email}${s.plan ? ` · ${PLAN_NAME[s.plan] || s.plan}` : ''}` : '');
    const dot = document.getElementById('acct-dot');
    if (dot) dot.className = `acct-dot is-${tone}`;
    const notice = document.getElementById('acct-notice');
    if (notice) { notice.textContent = s.notice || ''; notice.classList.toggle('d-none', !s.notice); }
    document.getElementById('acct-login-form')?.classList.toggle('d-none', !!s.logged_in);
    document.getElementById('acct-logged-in')?.classList.toggle('d-none', !s.logged_in);
    document.querySelectorAll('[data-signup-link]').forEach(a => { if (s.signup_url) a.href = s.signup_url; });
    document.querySelectorAll('[data-account-link]').forEach(a => { if (s.account_url) a.href = s.account_url; });
    const emailBox = document.getElementById('acct-email');
    if (emailBox && !emailBox.value && s.email) emailBox.value = s.email;      // 다시 로그인: 이메일은 채워 둠
    // 왼쪽 메뉴 한 줄 요약·불빛
    const hint = document.getElementById('sn-hint-account');
    if (hint) {
        hint.textContent = !s.enforced ? (s.logged_in ? `${s.email} · 잠금 꺼짐` : '개발 실행 · 잠금 꺼짐')
            : s.needs_login ? '다시 로그인 필요' : s.state === 'ok' ? s.email : s.state === 'off' ? '로그인 안 함' : '확인 필요';
        hint.classList.toggle('is-warn', !!s.enforced && (!!s.needs_login || (!s.can_trade_live && !IS_SIM)));
    }
    setDot('sn-dot-account', !s.enforced && !s.logged_in ? 'off' : tone, s.message || '');
    renderPlanInfo(s);
}

// 요금제: 계정 화면 한 줄 · 위 모드 스위치 잠금 표시 · 실제 모드에서 못 사는 요금제면 맨 위 띠
const EX_LABEL = { upbit: '업비트', bithumb: '빗썸' };
function renderPlanInfo(s) {
    const ent = s.ent || { modes: [], live_bots: 0, features: [] };
    const name = s.plan_name || PLAN_NAME[s.plan] || '';
    // 계정 화면: 요금제 줄
    let line = document.getElementById('acct-plan');
    const sub = document.getElementById('acct-status-sub');
    if (!line && sub) { sub.insertAdjacentHTML('afterend', '<div class="acct-plan" id="acct-plan"></div>'); line = document.getElementById('acct-plan'); }
    if (line) {
        const until = s.plan_until ? ` · ${new Date(s.plan_until * 1000).toLocaleDateString('ko-KR')}까지` : '';
        line.innerHTML = !s.enforced ? '<span class="acct-plan-chip is-dev">개발 실행</span> 요금제 잠금이 꺼져 있습니다 (모든 기능)'
            : name ? `<span class="acct-plan-chip is-${escapeHtml(s.plan || '')}">${escapeHtml(name)}</span>${escapeHtml(until)} · 실제 주문 `
                + (ent.modes.length ? `${ent.modes.map(m => EX_LABEL[m] || m).join(' · ')} · 실제 봇 ${ent.live_bots ?? '제한 없이'}${ent.live_bots != null ? '개까지' : ''}` : '없음 (시뮬레이션은 전부)')
                + (s.pricing_url ? ` · <a href="${escapeHtml(s.pricing_url)}" target="_blank" rel="noopener noreferrer">무료 안내 <i class="bi bi-box-arrow-up-right"></i></a>` : '')
                + (s.feedback_url ? ` · <a href="${escapeHtml(s.feedback_url)}" target="_blank" rel="noopener noreferrer">개선 요청 보내기 <i class="bi bi-chat-square-text"></i></a>` : '')
            : '';
        line.classList.toggle('d-none', !line.innerHTML);
    }
    // 위 모드 스위치: 요금제에 없는 거래소는 자물쇠 (들어가는 것은 됨 — 보유 확인 · 팔기)
    document.querySelectorAll('.app-mode-switch [data-app-mode]').forEach(btn => {
        const m = btn.dataset.appMode;
        const locked = !!s.enforced && m !== 'sim' && !ent.modes.includes(m);
        btn.classList.toggle('is-locked', locked);
        btn.querySelector('.mode-lock')?.remove();
        if (locked) btn.insertAdjacentHTML('beforeend', '<i class="bi bi-lock-fill mode-lock" aria-label="요금제 필요"></i>');
    });
    // 지금 실제 모드인데 이 거래소로 살 수 없는 요금제면 맨 위 띠
    let band = document.getElementById('plan-band');
    const locked = !!s.enforced && !IS_SIM && !ent.modes.includes(APP_MODE);
    if (locked && !band) {
        document.querySelector('.navbar')?.insertAdjacentHTML('afterend', '<div class="plan-band" id="plan-band" role="status"></div>');
        band = document.getElementById('plan-band');
    }
    if (band) {
        band.classList.toggle('d-none', !locked);
        if (locked) {
            const ex = EX_LABEL[APP_MODE] || APP_MODE;
            band.innerHTML = `<i class="bi bi-lock-fill"></i><span>${s.logged_in ? `지금 요금제(${escapeHtml(name || '무료')})로는 ${ex}에서 새로 사거나 봇을 시작할 수 없습니다.` : `${ex} 실제 주문은 StraBot 계정 로그인이 필요합니다 (무료).`}
                가진 코인 보기 · 팔기는 그대로 할 수 있습니다.</span>
                ${s.pricing_url ? `<a class="btn btn-sm plan-band-btn" href="${escapeHtml(s.pricing_url)}" target="_blank" rel="noopener noreferrer">무료 안내</a>` : ''}
                ${s.logged_in ? '' : '<button type="button" class="btn btn-sm plan-band-btn is-ghost" data-open-account>로그인</button>'}`;
        }
    }
}

async function loadLicense() {
    try {
        const d = await (await fetch('/api/license/status')).json();
        if (d.success) renderLicense(d);
    } catch (e) { console.error('계정 상태 불러오기 오류', e); }
}

// 거절 응답이면 안내 창을 띄우고 true
function licenseRefused(data) {
    if (!data || data.error_code !== 'LICENSE_REQUIRED') return false;
    if (data.license) renderLicense(data.license);
    const reason = document.getElementById('license-reason');
    if (reason) reason.textContent = data.error || '실제 주문은 StraBot 계정으로 로그인해야 쓸 수 있습니다.';
    const st = data.license || licenseStatus || {};
    document.querySelectorAll('[data-pricing-link]').forEach(a => { if (st.pricing_url) a.href = st.pricing_url; });
    document.querySelector('#license-modal [data-signup-link]')?.classList.toggle('d-none', !!st.logged_in);   // 로그인했으면 가입 단추 대신 요금제
    const modalEl = document.getElementById('license-modal');
    if (modalEl) bootstrap.Modal.getOrCreateInstance(modalEl).show();
    else showNotification(data.error || '계정 로그인이 필요합니다', 'error');
    return true;
}

function openAccountSettings() {
    const main = document.getElementById('settings-tab');
    if (main && !main.classList.contains('active')) bootstrap.Tab.getOrCreateInstance(main).show();
    const tab = document.getElementById('set-account-tab');
    if (tab) bootstrap.Tab.getOrCreateInstance(tab).show();
    setTimeout(() => document.getElementById(licenseStatus?.logged_in ? 'btn-acct-refresh' : 'acct-email')?.focus(), 300);
}

async function licensePost(path, body, btn, busyText) {
    const label = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = `<span class="spinner-border spinner-border-sm me-1"></span> ${busyText}`; }
    try {
        const d = await (await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/json' },
                                             body: JSON.stringify(body || {}) })).json();
        if (d.state) renderLicense(d);
        return d;
    } catch (e) {
        return { success: false, error: `요청하지 못했습니다: ${e.message}` };
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = label; }
    }
}

document.getElementById('acct-login-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const err = document.getElementById('acct-login-error');
    const email = document.getElementById('acct-email').value.trim();
    const pw = document.getElementById('acct-password');
    err.textContent = '';
    if (!email || !pw.value) { err.textContent = '이메일과 비밀번호를 넣어 주십시오.'; return; }
    const d = await licensePost('/api/license/login', { email, password: pw.value },
                                document.getElementById('btn-acct-login'), '로그인 중...');
    pw.value = '';                                  // 비밀번호는 화면에도 남기지 않음
    if (d.success) showNotification('로그인했습니다', 'success');
    else err.textContent = d.error || '로그인하지 못했습니다.';
});
document.getElementById('btn-acct-refresh')?.addEventListener('click', async (e) => {
    const d = await licensePost('/api/license/refresh', {}, e.currentTarget, '확인 중...');
    showNotification(d.message || d.error || '', d.success ? 'success' : 'error');
});
document.getElementById('btn-acct-logout')?.addEventListener('click', async (e) => {
    if (!(await uiConfirm({ title: '로그아웃하시겠습니까?', okText: '로그아웃', icon: 'bi-box-arrow-right', message: '· 업비트 모드의 봇 시작·사기를 쓸 수 없게 됩니다 (다시 로그인하면 됩니다)\n'
        + '· 실행 중인 봇은 멈추지 않고, 새로 사기만 멈춥니다 (팔기·손절은 계속합니다)\n· 시뮬레이션은 그대로 쓸 수 있습니다' }))) return;
    const d = await licensePost('/api/license/logout', {}, e.currentTarget, '로그아웃 중...');
    showNotification(d.message || d.error || '', d.success ? 'info' : 'error');
});
document.getElementById('license-open-account')?.addEventListener('click', () => {
    bootstrap.Modal.getOrCreateInstance(document.getElementById('license-modal')).hide();
    openAccountSettings();
});
document.getElementById('set-account-tab')?.addEventListener('shown.bs.tab', loadLicense);
loadLicense();
setInterval(loadLicense, 10 * 60 * 1000);           // 자동 갱신 결과·만료를 화면에 반영

// ── 봇 현황 · 백테스트: 코인 · 봉 · 기간 → 필요한 캔들만 받아(이 PC에 저장) 봇 규칙을 다시 돌려 봄 → 자산 변화 · 캔들(▲▼) · 거래 표 ──
const BT_UNITS = [['1', '1분'], ['5', '5분'], ['10', '10분'], ['15', '15분'], ['30', '30분'], ['60', '1시간'], ['240', '4시간'], ['day', '일'], ['week', '주'], ['month', '월']];
const BT_PRESETS = [[7, '1주'], [30, '1개월'], [90, '3개월'], [180, '6개월'], [365, '1년']];
const btState = { botId: null, unit: '60', days: 30, limits: {}, job: null, result: null, sel: null, chart: null, series: null, priceLine: null, data: null };

function btDateStr(d) {
    const k = new Date(d.getTime() + 9 * 3600e3);                 // 한국 날짜
    return k.toISOString().slice(0, 10);
}

function btSetPeriod(days) {
    const lim = btState.limits[btState.unit] || 365;
    days = Math.min(days, lim);
    btState.days = days;
    const end = new Date();
    document.getElementById('bt-end').value = btDateStr(end);
    document.getElementById('bt-start').value = btDateStr(new Date(end.getTime() - (days - 1) * 86400e3));
    btRenderControls();
}

function btRenderControls() {
    const lim = btState.limits[btState.unit] || 365;
    document.getElementById('bt-units').innerHTML = BT_UNITS.map(([u, t]) => `<button type="button" class="${u === btState.unit ? 'active' : ''}" data-bt-unit="${u}">${t}</button>`).join('');
    document.getElementById('bt-presets').innerHTML = BT_PRESETS.map(([d, t]) => `<button type="button" class="${d === btState.days ? 'active' : ''}${d > lim ? ' disabled' : ''}" data-bt-days="${d}" ${d > lim ? 'disabled' : ''}>${t}</button>`).join('');
    document.getElementById('bt-limit').textContent = `(이 봉은 최대 ${lim >= 365 ? `${Math.round(lim / 365 * 10) / 10}년` : `${lim}일`})`;
}

// 백테스트 탭을 열 때 · 봇을 바꿀 때: 이 봇에서 빠질 규칙 · 기본 금액
async function btEnsure() {
    if (!currentBotId || bdTab !== 'backtest' || !botsList.some(b => b.id === currentBotId)) return;   // 봇 목록을 받기 전엔 기다림
    const list = document.getElementById('bt-coin-list');
    if (list && !list.children.length && marketCoins.length) {
        list.innerHTML = marketCoins.map(c => `<option value="${escapeHtml(c.currency)}">${escapeHtml(c.korean_name || '')}</option>`).join('');
    }
    // 단위 · 기간 단추는 늘 먼저 그림 (봇 정보를 못 받아도 비어 보이지 않게)
    if (!document.getElementById('bt-start').value) btSetPeriod(btState.days || 30);
    else btRenderControls();
    if (btState.botId === currentBotId) return;
    btState.botId = currentBotId;
    btState.result = null;
    document.getElementById('bt-result').classList.add('d-none');
    document.getElementById('bt-progress').classList.add('d-none');
    const coin = document.getElementById('bt-coin');
    if (!coin.value) coin.value = 'BTC';
    try {
        const res = await fetch(`/api/bots/${currentBotId}/backtest/check`);
        const d = await res.json().catch(() => null) || { success: false, old: true };   // JSON이 아니면 예전 프로그램
        if (btState.botId !== currentBotId) return;
        if (!d.success) {
            btState.botId = null;                              // 다음에 탭을 열 때 다시 물어봄
            document.getElementById('bt-skip').textContent = d.old && res.status === 404
                ? 'StraBot을 껐다 켜야 백테스트를 쓸 수 있습니다 (프로그램이 예전 것으로 돌고 있습니다)' : (d.error || '봇 정보를 받지 못했습니다. 잠시 뒤 다시 열어 주십시오');
            return;
        }
        btState.limits = d.limits || {};
        document.getElementById('bt-krw').value = Math.round(d.budget || 1000000);
        const box = document.getElementById('bt-skip');
        box.classList.toggle('is-ok', !d.skipped.length && d.buy.length > 0);
        const notes = (d.notes || []).length
            ? '<div class="bt-notes"><b>어림해서 돌리는 규칙</b><ul>' + d.notes.map(n => `<li>${escapeHtml(n.title)} — ${escapeHtml(n.note)}</li>`).join('') + '</ul></div>' : '';
        if (!d.buy.length) {
            box.innerHTML = '<b>백테스트로 돌릴 수 있는 매수 조건이 없습니다.</b>' + (d.skipped.length ? '<ul>' + d.skipped.map(s => `<li>${escapeHtml(s.title)} — ${escapeHtml(s.why)}</li>`).join('') + '</ul>' : '');
        } else if (d.skipped.length) {
            box.innerHTML = '<b>아래 규칙은 이번 백테스트에서 빠집니다</b> (나머지 규칙만으로 계산합니다)<ul>'
                + d.skipped.map(s => `<li>${s.side === 'buy' ? '매수' : '매도'} · ${escapeHtml(s.title)} — ${escapeHtml(s.why)}</li>`).join('') + '</ul>' + notes;
        } else {
            box.innerHTML = `<i class="bi bi-check-circle"></i> 이 봇의 규칙을 모두 백테스트할 수 있습니다 — 매수: ${escapeHtml(d.buy.join(', '))}${d.sell.length ? ` · 매도: ${escapeHtml(d.sell.join(', '))}` : ''}${(d.partial || []).length ? ' · 급등 일부 팔기 · 다시 사기' : ''} · 손절·익절·추적 손절 포함` + notes;
        }
        document.getElementById('bt-run').disabled = !d.buy.length;
    } catch (e) {
        btState.botId = null;                                  // 다음에 탭을 열 때 다시 물어봄
    }
    btSetPeriod(btState.days || 30);
}

async function btRun() {
    const coin = String(document.getElementById('bt-coin').value || '').trim();
    const sym = coin.toUpperCase().replace('KRW-', '');
    const hit = marketCoins.find(c => c.currency === sym) || marketCoins.find(c => matchesQuery(c, coin))
        || (/^[A-Z0-9]{1,15}$/.test(sym) ? { currency: sym, korean_name: sym } : null);
    if (!hit) { showNotification('코인을 목록에서 골라 주십시오 (예: BTC, 리플)', 'error'); return; }
    document.getElementById('bt-coin').value = hit.currency;
    const body = { market: `KRW-${hit.currency}`, unit: btState.unit, start: document.getElementById('bt-start').value,
                   end: document.getElementById('bt-end').value, krw: Number(document.getElementById('bt-krw').value) || null };
    const btn = document.getElementById('bt-run');
    btn.disabled = true;
    const prog = document.getElementById('bt-progress'), bar = document.getElementById('bt-progress-bar'), text = document.getElementById('bt-progress-text');
    prog.classList.remove('d-none');
    bar.style.width = '0%';
    text.textContent = '시작하는 중…';
    try {
        const r = await (await fetch(`/api/bots/${currentBotId}/backtest`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })).json();
        if (!r.success) throw new Error(r.error === '알 수 없는 동작' ? 'StraBot을 껐다 켜야 백테스트를 쓸 수 있습니다 (프로그램이 예전 것으로 돌고 있습니다)' : (r.error || '시작하지 못했습니다'));
        const botId = currentBotId;
        btState.job = r.job;
        for (;;) {
            await new Promise(res => setTimeout(res, 700));
            if (btState.job !== r.job) return;
            const j = await (await fetch(`/api/backtest/${r.job}`)).json();
            if (!j.success) throw new Error(j.error || '진행 상황을 받지 못했습니다');
            bar.style.width = `${Math.round((j.progress || 0) * 100)}%`;
            text.textContent = j.text || '';
            if (j.stage === 'error') throw new Error(j.error || '백테스트에 실패했습니다');
            if (j.stage === 'done') {
                if (botId === currentBotId) btRender(j.result, hit);
                break;
            }
        }
        prog.classList.add('d-none');
    } catch (e) {
        text.textContent = '';
        prog.classList.add('d-none');
        showNotification('백테스트: ' + e.message, 'error');
    } finally {
        btn.disabled = false;
    }
}

function btPct(v) { return v === null || v === undefined ? '-' : `${v > 0 ? '+' : ''}${v.toFixed(2)}%`; }

function btRender(r, coinInfo) {
    btState.result = r;
    btState.sel = null;
    document.getElementById('bt-result').classList.remove('d-none');
    const k = r.kpis;
    const kp = (main, label, value, sub, cls = '') => `<div class="sv-kpi${main ? ' is-main' : ''}"><span>${label}</span><b class="${cls}">${value}</b><small>${sub}</small></div>`;
    // 같은 돈 기준: 봇이 처음 산 금액으로 '봇대로' 와 '그냥 들고 있기' 수익률을 똑같이 계산하고 차이만 따로
    const base = k.same_cost;
    const botPnl = k.final - r.start_krw;
    const won = (v) => `${v > 0 ? '+' : ''}${formatKrw(v)}`;
    let cards;
    if (base) {
        const botPct = botPnl / base * 100, holdPct = k.same_pnl / base * 100, gap = botPct - holdPct, gapWon = botPnl - k.same_pnl;
        cards = [
            kp(false, '봇 적용', btPct(botPct), `손익 ${won(botPnl)}${k.open ? ' (마지막 코인은 끝 가격으로 셈)' : ''}`, pnlClass(botPct)),
            kp(false, '봇 미적용', btPct(holdPct), `손익 ${won(k.same_pnl)} · 같은 때 같은 금액을 사서 끝까지`, pnlClass(holdPct)),
            kp(true, '차이 (봇 적용 − 봇 미적용)', `${gap > 0 ? '+' : ''}${gap.toFixed(2)}%`,
               Math.abs(gapWon) < 1 ? '거의 같습니다' : `봇이 ${formatKrw(Math.abs(gapWon))} ${gapWon > 0 ? '더 벌었습니다' : '덜 벌었습니다'}`, pnlClass(gap)),
            kp(false, '거래 (매수 · 매도)', `${k.buys} · ${k.sells}번`, k.win_rate === null ? '판 것이 없습니다' : `이긴 매도 ${Math.round(k.win_rate)}% · 판 것 손익 ${won(k.realized)}`),
            kp(false, '기준 금액', formatKrw(base), `봇이 처음 산 금액 · 전체 ${formatKrw(r.start_krw)} 기준으로는 봇 ${btPct(k.return_pct)} · 코인 값 ${btPct(k.hold_pct)}`),
        ];
    } else {
        cards = [
            kp(true, '봇 적용', btPct(k.return_pct), '이 기간에 봇이 산 적이 없습니다'),
            kp(false, '코인 값 변화', btPct(k.hold_pct), '처음 가격 → 끝 가격', pnlClass(k.hold_pct)),
            kp(false, '거래', '0번', '조건에 맞은 때가 없었습니다'),
        ];
    }
    document.getElementById('bt-kpis').innerHTML = cards.join('');
    const name = coinInfo?.korean_name || r.market.replace('KRW-', '');
    const unitName = (BT_UNITS.find(([u]) => u === r.unit) || [, r.unit])[1];
    document.getElementById('bt-curve-sub').textContent = k.same_cost
        ? `봇 적용 vs 봇 미적용 (봇의 첫 매수와 같은 때 같은 금액 ${formatKrw(k.same_cost)}을 사서 끝까지 · 나머지 돈은 둘 다 현금)`
        : '이 기간에 봇이 산 적이 없어 두 선이 같습니다';
    document.getElementById('bt-chart-title').textContent = `${name} · ${unitName}봉`;
    document.getElementById('bt-chart-sub').textContent = `${formatKstTime(r.start).slice(0, 10)} ~ ${formatKstTime(r.end).slice(0, 10)} · 봉 ${r.candles.length.toLocaleString()}개 · 거래 ${r.trades.length}건`;
    // 자산 변화: 봇 vs 들고 있기
    const labels = r.curve.map(x => formatKstTime(new Date(x.t * 1000).toISOString()).slice(2, 16));
    svLineChart('bt-curve', labels, [
        { label: '봇 적용', data: r.curve.map(x => x.bot), borderColor: '#0f766e', backgroundColor: 'rgba(15,118,110,0.08)', fill: true, pointRadius: 0, borderWidth: 2, tension: 0.15 },
        { label: '봇 미적용', data: r.curve.map(x => x.hold), borderColor: '#94a3b8', borderDash: [5, 4], pointRadius: 0, borderWidth: 1.5, tension: 0.15 },
    ], (v) => `${(v / 10000).toLocaleString(undefined, { maximumFractionDigits: 1 })}만`);   // 차이가 작아도 눈금이 겹치지 않게
    btRenderTable();
    btDrawChart();
    // 봇이 본 일: 급등 감지 · 건너뜀 · 지켜보기 끝 (사고팔지 않은 판단까지)
    const ev = document.getElementById('bt-events'), evs = r.events || [];
    ev.classList.toggle('d-none', !evs.length);
    ev.querySelector('summary').textContent = `봇이 본 일 ${evs.length}건 — 급등 감지 · 건너뛴 판단까지`;
    ev.querySelector('ul').innerHTML = evs.slice().reverse().map(e => `<li><span>${formatKstTime(e.time)}</span>${escapeHtml(e.text)}</li>`).join('');
    const skipped = (r.skipped?.length ? ` · 빠진 규칙 ${r.skipped.length}개(${r.skipped.map(s => s.title).join(', ')})` : '')
        + (r.notes?.length ? ` · 어림한 규칙: ${r.notes.map(n => n.title).join(', ')}` : '');
    document.getElementById('bt-foot').textContent = `${r.pages_fetched ? `업비트에서 ${r.pages_fetched.toLocaleString()}번 받아 이 PC에 저장했습니다` : '모두 이 PC에 저장된 캔들로 계산했습니다'} · 수수료 ${r.costs.fee}% · 체결 미끄러짐 ${r.costs.slip}% 반영 · `
        + `봉이 끝나는 순간마다 한 번 확인(손절·익절은 봉 안 저가·고가로)${skipped}${r.excluded ? ' · 이 코인은 봇의 제외 코인이라 사지 않았습니다' : ''} · 과거 결과일 뿐 앞으로의 수익을 보장하지 않습니다`;
}

function btRenderTable() {
    const r = btState.result;
    const tb = document.getElementById('bt-tbody');
    if (!r.trades.length) {
        tb.innerHTML = '<tr><td colspan="6" class="text-center text-muted py-4">이 기간에는 조건에 맞아 사고판 일이 없습니다</td></tr>';
        return;
    }
    tb.innerHTML = r.trades.map((t, i) => {
        const buy = t.side === 'buy', p = t.profit;
        const tip = !buy && t.buy_reason ? ` title="산 이유: ${escapeHtml(t.buy_reason)}"` : '';
        return `<tr data-bt-i="${i}" tabindex="0" class="${btState.sel === i ? 'tx-sel' : ''}">
            <td class="text-nowrap">${formatKstTime(t.time)}</td>
            <td><span class="tr-side ${buy ? 'is-buy' : 'is-sell'}">${buy ? '매수' : '매도'}</span></td>
            <td class="text-end">${formatPrice(t.price)}</td>
            <td class="text-end">${formatKrw(t.total)}</td>
            <td class="text-end ${p === null || p === undefined ? '' : pnlClass(p)}">${p === null || p === undefined ? '-' : `${p > 0 ? '+' : ''}${formatKrw(p)}`}</td>
            <td class="tr-why"${tip}>${escapeHtml(t.reason || '')}</td></tr>`;
    }).reverse().join('');                                   // 최근 거래가 위로
}

function btDrawChart() {
    const r = btState.result, el = document.getElementById('bt-chart');
    btState.chart?.remove();
    Object.assign(btState, { chart: null, series: null, priceLine: null });
    if (typeof LightweightCharts === 'undefined') { el.innerHTML = '<div class="db-empty">캔들차트를 불러오지 못했습니다 (인터넷 연결 확인)</div>'; return; }
    el.innerHTML = '';
    const KST = 9 * 3600;
    btState.data = r.candles.map(c => ({ time: c[0] + KST, open: c[1], high: c[2], low: c[3], close: c[4] }));
    const chart = LightweightCharts.createChart(el, {
        height: el.clientHeight || 360, layout: { background: { color: '#ffffff' }, textColor: '#475569', fontSize: 11 },
        grid: { vertLines: { color: '#f1f5f9' }, horzLines: { color: '#f1f5f9' } },
        timeScale: { timeVisible: r.unit !== 'day', secondsVisible: false, borderColor: '#e2e8f0', rightOffset: 4 }, rightPriceScale: { borderColor: '#e2e8f0' },
        crosshair: { mode: 0 }, localization: { priceFormatter: (p) => formatPrice(p).replace('원', '') },
    });
    btState.chart = chart;
    btState.series = chart.addCandlestickSeries({ upColor: '#c84a31', downColor: '#1261c4', borderVisible: false, wickUpColor: '#c84a31', wickDownColor: '#1261c4' });
    btState.series.setData(btState.data);
    chart.timeScale().fitContent();
    chart.subscribeClick(btChartClick);
    new ResizeObserver(() => { if (el.clientWidth) chart.applyOptions({ width: el.clientWidth, height: el.clientHeight }); }).observe(el);
    btMarkers();
}

// 거래 시각(판단한 순간 = 봉이 끝난 순간) → 그 봉의 시작 (차트 시각)
function btBarOf(t) {
    const x = Math.floor(new Date(t.time).getTime() / 1000) - 1 + 9 * 3600;      // 봉이 끝난 순간 → 그 봉
    const d = btState.data;
    let lo = 0, hi = d.length - 1;
    if (!d.length || x < d[0].time) return null;
    while (lo < hi) { const m = (lo + hi + 1) >> 1; if (d[m].time <= x) lo = m; else hi = m - 1; }
    return d[lo].time;
}

function btMarkers() {
    const r = btState.result, s = btState.series;
    if (!s) return;
    const sel = btState.sel;
    const markers = r.trades.map((t, i) => {
        const buy = t.side === 'buy', on = i === sel;
        const color = buy ? (sel !== null && !on ? '#eab3a7' : '#c84a31') : (sel !== null && !on ? '#a9c3e8' : '#1261c4');
        return { id: `bt${i}`, time: btBarOf(t), position: buy ? 'belowBar' : 'aboveBar', color, shape: buy ? 'arrowUp' : 'arrowDown',
                 size: on ? 2.4 : 1, text: on ? `${buy ? '매수' : '매도'} ${formatPrice(t.price).replace('원', '')}` : '' };
    }).filter(m => m.time !== null);
    markers.sort((a, b) => a.time - b.time || (a.id === `bt${sel}`) - (b.id === `bt${sel}`));
    s.setMarkers(markers);
    if (btState.priceLine) { s.removePriceLine(btState.priceLine); btState.priceLine = null; }
    const hint = document.getElementById('bt-hint');
    if (sel === null) {
        hint.textContent = '화살표를 누르면 아래 표에서 그 거래를 찾아 줍니다 · 표의 줄을 누르면 차트에 크게 표시됩니다';
        return;
    }
    const t = r.trades[sel], buy = t.side === 'buy';
    btState.priceLine = s.createPriceLine({ price: t.price, color: buy ? '#c84a31' : '#1261c4', lineWidth: 1, lineStyle: 2, axisLabelVisible: true, title: buy ? '매수가' : '매도가' });
    hint.innerHTML = '<b></b><span class="tx-hint-why"></span> <span class="text-muted">· 표의 줄을 한 번 더 누르면 해제</span>';
    hint.querySelector('b').textContent = `${formatKstTime(t.time)} ${buy ? '매수' : '매도'} ${formatPrice(t.price)} · ${formatKrw(t.total)}${t.profit !== null && t.profit !== undefined ? ` · ${t.profit > 0 ? '+' : ''}${formatKrw(t.profit)}` : ''}`;
    hint.querySelector('.tx-hint-why').textContent = ` · ${t.reason}`;
    // 화면 밖이면 그 봉이 보이게
    const bar = btBarOf(t), i = btState.data.findIndex(d => d.time === bar);
    const ts = btState.chart.timeScale(), vr = ts.getVisibleLogicalRange();
    if (i >= 0 && vr && (i < vr.from + 2 || i > vr.to - 2)) {
        const w = Math.max(40, vr.to - vr.from);
        ts.setVisibleLogicalRange({ from: i - w * 0.6, to: i + w * 0.4 });
    }
}

function btSelect(i, from) {
    if (from === 'table' && btState.sel === i) i = null;
    btState.sel = i;
    document.querySelectorAll('#bt-tbody tr.tx-sel').forEach(tr => tr.classList.remove('tx-sel', 'tx-flash'));
    const tr = i === null ? null : document.querySelector(`#bt-tbody tr[data-bt-i="${i}"]`);
    if (tr) {
        tr.classList.add('tx-sel');
        if (from === 'chart') { void tr.offsetWidth; tr.classList.add('tx-flash'); tr.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); }
    }
    btMarkers();
}

// 차트를 누름: 화살표면 그 거래, 아니면 누른 봉 안의 거래 (여러 건이면 누를 때마다 다음 것)
function btChartClick(param) {
    if (!param || !btState.result) return;
    const id = typeof param.hoveredObjectId === 'string' && param.hoveredObjectId.startsWith('bt') ? Number(param.hoveredObjectId.slice(2)) : null;
    if (id !== null && !Number.isNaN(id)) { btSelect(id, 'chart'); return; }
    if (param.time === undefined) return;
    const inBar = btState.result.trades.map((t, i) => [t, i]).filter(([t]) => btBarOf(t) === param.time).map(([, i]) => i);
    if (!inBar.length) return;
    const at = inBar.indexOf(btState.sel);
    btSelect(inBar[(at + 1) % inBar.length], 'chart');
}

document.addEventListener('click', (e) => {
    const u = e.target.closest('[data-bt-unit]');
    if (u) { btState.unit = u.dataset.btUnit; btSetPeriod(btState.days || 30); return; }
    const p = e.target.closest('[data-bt-days]');
    if (p && !p.disabled) { btSetPeriod(Number(p.dataset.btDays)); return; }
    if (e.target.closest('#bt-run')) { btRun(); return; }
    const row = e.target.closest('#bt-tbody tr[data-bt-i]');
    if (row) btSelect(Number(row.dataset.btI), 'table');
});
document.addEventListener('keydown', (e) => {
    const row = e.target.closest?.('#bt-tbody tr[data-bt-i]');
    if (row && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); btSelect(Number(row.dataset.btI), 'table'); }
});
document.addEventListener('change', (e) => {
    if (e.target.id === 'bt-start' || e.target.id === 'bt-end') { btState.days = null; btRenderControls(); }
});

// ── 봇 현황 탭: 성과(숫자 4칸 · 수익 추이) · 보유 코인 · 매매 내역 · 봇이 할 일 · 백테스트 ──
let bdTab = (() => { try { return localStorage.getItem('bdTab') || 'perf'; } catch (e) { return 'perf'; } })();
function showBdTab(tab) {
    if (tab === 'hold' || !document.querySelector(`[data-bd-pane="${tab}"]`)) tab = 'perf';   // 보유 코인은 성과 탭으로 합침
    bdTab = tab;
    try { localStorage.setItem('bdTab', tab); } catch (e) { /* 무시 */ }
    if (!builderOpen()) markBotNav(0);                   // 위 탭 줄(성과 · 보유 코인 · 매매 내역 · 백테스트)에 지금 탭 표시
    document.querySelectorAll('[data-bd-pane]').forEach(p => p.classList.toggle('d-none', p.dataset.bdPane !== tab));
    // 숨어 있던 동안 크기를 못 잡은 그래프를 다시 맞춤
    requestAnimationFrame(() => window.dispatchEvent(new Event('resize')));
    if (tab === 'backtest') btEnsure();
    if (tab === 'log') requestAnimationFrame(() => fitTxResult(document.querySelector('#bd-trades table')));
    if (tab === 'perf' && bdLast && (!bdLast.bot?.id || bdLast.bot.id === currentBotId)) { bdHoldKey = ''; renderBotHoldings(bdLast.status?.positions || []); }
}
document.addEventListener('click', (e) => {
    const b = e.target.closest('#bd-tabs [data-bd-tab]');
    if (b) showBdTab(b.dataset.bdTab);
});
// 탭 이름 옆 숫자: 보유 코인 수 (봇 현황을 그릴 때마다) — 매매 내역 탭 숫자는 없앰
function updateBdTabCounts(summary) {
    const set = (id, n) => { const el = document.getElementById(id); if (el) el.textContent = n ? String(n) : ''; };
    set('bd-tab-n-hold', summary?.holding || 0);
}
showBdTab(bdTab);

// 조건 목록 카드가 위 메뉴 바로 밑에 붙어 따라오도록: 메뉴 높이를 CSS 변수로 (화면 폭에 따라 메뉴가 두 줄이 됨)
(function trackNavHeight() {
    const nav = document.querySelector('.navbar');
    if (!nav) return;
    const set = () => document.documentElement.style.setProperty('--sb-top', `${nav.offsetHeight + 12}px`);
    set();
    window.addEventListener('resize', set);
    if (window.ResizeObserver) new ResizeObserver(set).observe(nav);
})();


// ── 요약 줄(보유코인 분석 · 봇 화면 · 전체 봇 보드): 값이 바뀔 때 칸 너비가 줄었다 늘었다 하며 뒤 칸들이 움직이지 않게 ──
// 칸마다 지금까지 가장 넓었던 너비를 최소 너비로 기억 (넓어질 필요가 있으면 넓어짐). 창 크기가 바뀌면 처음부터 다시 잼
(function steadySummaryRows() {
    if (typeof ResizeObserver === 'undefined') return;
    const items = [];
    const widest = new WeakMap();
    const ro = new ResizeObserver((entries) => {
        for (const e of entries) {
            const el = e.target;
            if (!el.offsetParent) continue;                       // 숨은 화면은 보일 때
            const w = Math.ceil(el.getBoundingClientRect().width);
            if (w > (widest.get(el) || 0)) { widest.set(el, w); el.style.minWidth = `${w}px`; }
        }
    });
    document.querySelectorAll('.mk-stat, .bbs-sub > span').forEach(el => { items.push(el); ro.observe(el); });
    let t = null;
    window.addEventListener('resize', () => {
        clearTimeout(t);
        t = setTimeout(() => items.forEach(el => { el.style.minWidth = ''; widest.delete(el); }), 200);
    });
})();

// ── 선택 칸을 '코인 겹쳐 보기'와 같은 단추 + 목록으로 (수익률 추이: 코인 고르기 · 비교) ──
// 원래 <select>는 숨겨 두고 값 · change 는 그대로 씀 → 기존 동작 그대로. 목록이 바뀌면(보유 코인 갱신) 따라 다시 그림
function selectAsDropdown(select, { title, sub, right } = {}) {
    if (!select || select.dataset.dd) return;
    select.dataset.dd = '1';
    select.classList.add('d-none');
    const wrap = document.createElement('div');
    wrap.className = 'dropdown pnl-coins-dd';
    wrap.innerHTML = `<button type="button" class="btn btn-sm pnl-coins-btn dropdown-toggle" data-bs-toggle="dropdown" aria-expanded="false"></button>
        <div class="dropdown-menu p-0 pnl-coins-menu"></div>`;
    select.after(wrap);
    const btn = wrap.querySelector('button'), menu = wrap.querySelector('.dropdown-menu');
    btn.setAttribute('aria-label', select.getAttribute('aria-label') || title || '');
    const render = () => {
        const opts = [...select.options];
        const cur = opts.find(o => o.value === select.value) || opts[0];
        btn.textContent = cur ? cur.textContent : '';
        menu.innerHTML = `<div class="pcm-head"><b>${escapeHtml(title || '')}</b>${sub ? `<small>${escapeHtml(sub)}</small>` : ''}</div>`
            + `<div class="pcm-list">${opts.map(o => `<button type="button" class="pcm-item pcm-pick${o.value === select.value ? ' is-on' : ''}" data-dd-value="${escapeHtml(o.value)}">`
                + `<i class="bi bi-check2 pcm-check"></i><span>${escapeHtml(o.textContent)}</span>${right ? right(o.value) : ''}</button>`).join('')}</div>`;
    };
    menu.addEventListener('click', (e) => {
        const it = e.target.closest('[data-dd-value]');
        if (!it) return;
        select.value = it.dataset.ddValue;
        select.dispatchEvent(new Event('change', { bubbles: true }));
        bootstrap.Dropdown.getOrCreateInstance(btn).hide();
        render();
    });
    new MutationObserver(render).observe(select, { childList: true, subtree: true, characterData: true });
    select.addEventListener('change', render);
    // 값만 코드로 바뀌는 경우(크게 보기 창 맞추기 등)도 열 때 다시 그림
    btn.addEventListener('show.bs.dropdown', render);
    wrap.addEventListener('show.bs.dropdown', render);
    render();
}
(function styleRateSelects() {
    const coinRate = (v) => {
        const a = holdingsAssets.find(x => x.currency === v);
        return a ? `<b class="${pnlClass(a.pnl_rate)}">${formatChangeRate(a.pnl_rate)}</b>` : '';
    };
    const coin = { title: '코인 고르기', sub: '전체 또는 보유 코인 하나 · 평가금액 순', right: coinRate };
    const bench = { title: '비교 대상', sub: '같은 기간 이렇게 샀다면 (그래프 처음 값에서 출발)' };
    selectAsDropdown(document.getElementById('pnl-coin-select'), coin);
    selectAsDropdown(document.getElementById('pnl-bench-select'), bench);
    selectAsDropdown(document.getElementById('pnl-big-coin'), coin);
    selectAsDropdown(document.getElementById('pnl-big-bench'), bench);
})();
syncPnlAlignBtns();


// ── 그래프가 있는 창마다 '전체 화면' 단추 (누르면 화면 가득 → 같은 자리에 '축소'로 바뀜) ──
// 옮기기 · 크기 바꾸기가 되는 창은 축소하면 제목 줄 두 번 누르기처럼 원래 크기 · 가운데로
// ── 그래프 크게 보기 (새 창): 크게 보기가 따로 없던 그래프들에 같은 단추 하나 · 원래 그래프가 바뀌면 큰 창도 따라 바뀜 ──
// [캔버스 id, 창 제목, 단추를 붙일 칸(없으면 가장 가까운 카드)]
const BIG_CHARTS = [
    ['mk-breadth-chart', '시장 분위기 추이'], ['mk-dist-chart', '분포'], ['mk-movers-chart', '상위 · 하위'], ['mk-share-chart', '거래대금 비중'],
    ['bd-chart', '봇 수익률 변화'], ['bd-donut', '봇 보유 비중', '.db-donut'], ['bb-donut', '봇별 배분 비율', '.bb-donut'],
    ['bt-curve', '백테스트 자산 변화'], ['hd-ins-coins', '코인별 손익'], ['hd-share-chart', '보유 비중'],
];
function attachChartExpand() {
    for (const [id, title, boxSel] of BIG_CHARTS) {
        const cv = document.getElementById(id);
        const box = cv && (boxSel ? cv.closest(boxSel) : cv.closest('.ip-card, .db-card, .card'));
        if (!box || box.querySelector(`[data-chart-big="${id}"]`)) continue;
        box.classList.add('has-chart-expand');
        box.insertAdjacentHTML('beforeend', `<button type="button" class="btn btn-sm pnl-expand chart-expand-btn" data-chart-big="${id}" title="${escapeHtml(title)}을(를) 새 창에서 크게 보실 수 있습니다." aria-label="${escapeHtml(title)} 크게 보기"><i class="bi bi-arrows-angle-expand"></i></button>`);
    }
}
const chartBig = { id: null, chart: null, timer: null };
// 큰 창 그래프의 글자: 축 · 범례 · 말풍선을 키우고, 그래프 안에 직접 쓰는 글자(조각 % · 막대 값)는 1.5배 (bigPx)
function bigIf(on, o) { return on ? bigFontOptions(o) : o; }        // 큰 창 전용 그래프(수익률 추이 · 봇별 비교 크게 보기)도 같은 글자 크기로
function bigPx(chart, px) { return chart?.canvas?.id === 'chart-big-canvas' ? Math.round(px * 1.5) : px; }
function bigFontOptions(o) {
    const font = (f, size) => ({ ...(typeof f === 'object' && f ? f : {}), size });
    o.scales = Object.fromEntries(Object.entries(o.scales || {}).map(([k, sc]) => [k, {
        ...sc, ticks: { ...(sc.ticks || {}), font: font(sc.ticks?.font, 14) },
        ...(sc.title ? { title: { ...sc.title, font: font(sc.title.font, 14) } } : {}),
        ...(sc.pointLabels ? { pointLabels: { ...sc.pointLabels, font: font(sc.pointLabels.font, 14) } } : {}),
    }]));
    o.plugins = { ...(o.plugins || {}) };
    if (o.plugins.legend) o.plugins.legend = { ...o.plugins.legend, labels: { ...(o.plugins.legend.labels || {}), font: font(o.plugins.legend.labels?.font, 15), boxWidth: 18, padding: 14 } };
    o.plugins.tooltip = { ...(o.plugins.tooltip || {}), titleFont: { size: 15, weight: '700' }, bodyFont: { size: 14 }, footerFont: { size: 13 }, padding: 12 };
    if (o.plugins.title) o.plugins.title = { ...o.plugins.title, font: font(o.plugins.title.font, 16) };
    return o;
}
function chartBigData(src) {
    return { labels: [...(src.data.labels || [])], datasets: (src.data.datasets || []).map(d => ({ ...d, data: [...(d.data || [])] })) };
}
function openChartBig(id) {
    const [, title] = BIG_CHARTS.find(x => x[0] === id) || [id, '그래프'];
    const src = Chart.getChart(document.getElementById(id));
    if (!src) { showNotification('그래프를 아직 그리지 않았습니다. 잠시 뒤 다시 눌러 주십시오.', 'info'); return; }
    let el = document.getElementById('chart-big-modal');
    if (!el) {
        el = document.createElement('div');
        el.className = 'modal fade';
        el.id = 'chart-big-modal';
        el.tabIndex = -1;
        el.innerHTML = `<div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content">
            <div class="modal-header"><h5 class="modal-title" id="chart-big-title"></h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="닫기"></button></div>
            <div class="modal-body"><div class="chart-big-box"><canvas id="chart-big-canvas"></canvas></div><small class="text-muted" id="chart-big-note"></small></div>
        </div></div>`;
        document.body.appendChild(el);
        addModalFullscreen(el);
        el.addEventListener('hidden.bs.modal', () => { clearInterval(chartBig.timer); chartBig.chart?.destroy(); chartBig.chart = null; chartBig.id = null; });
        el.addEventListener('shown.bs.modal', () => chartBig.chart?.resize());
    }
    chartBig.chart?.destroy();
    clearInterval(chartBig.timer);
    chartBig.id = id;
    el.querySelector('#chart-big-title').innerHTML = `<i class="bi bi-arrows-angle-expand me-2"></i>${escapeHtml(title)}`;
    el.querySelector('#chart-big-note').textContent = '원래 화면의 그래프와 같은 내용이며, 바뀌면 이 창도 몇 초 안에 따라 바뀝니다.';
    const raw = src.config._config || src.config;
    const round = ['doughnut', 'pie'].includes(raw.type);
    const options = { ...(raw.options || {}), responsive: true, maintainAspectRatio: false, animation: false };
    if (round) options.plugins = { ...(options.plugins || {}), legend: { display: true, position: 'right', labels: { boxWidth: 18, font: { size: 15 } } } };   // 도넛은 큰 창에서 이름표를 옆에
    bigFontOptions(options);
    chartBig.chart = new Chart(el.querySelector('#chart-big-canvas'), { type: raw.type, data: chartBigData(src), options, plugins: raw.plugins || [] });
    // 원래 그래프가 다시 그려지거나 값이 바뀌면 따라감
    chartBig.timer = setInterval(() => {
        const now = Chart.getChart(document.getElementById(id));
        if (!now || !chartBig.chart) return;
        chartBig.chart.data = chartBigData(now);
        chartBig.chart.update('none');
    }, 2500);
    bootstrap.Modal.getOrCreateInstance(el).show();
}
document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-chart-big]');
    if (b) { e.preventDefault(); e.stopPropagation(); openChartBig(b.dataset.chartBig); }
}, true);
document.addEventListener('DOMContentLoaded', attachChartExpand);
setTimeout(attachChartExpand, 0);

function addModalFullscreen(modal) {
    if (!modal || modal.dataset.maxBtn) return;
    const head = modal.querySelector('.modal-header');
    const close = head?.querySelector('.btn-close');
    if (!head || !close) return;
    modal.dataset.maxBtn = '1';
    const box = document.createElement('div');
    box.className = 'pnl-big-win modal-max-win';
    box.innerHTML = '<button type="button" class="btn btn-sm" data-modal-max title="전체 화면 (화면 가득)"><i class="bi bi-arrows-fullscreen"></i><span>전체 화면</span></button>'
        + '<button type="button" class="btn btn-sm" data-modal-restore title="원래 크기로"><i class="bi bi-fullscreen-exit"></i><span>축소</span></button>';
    close.before(box);
    const dlg = modal.querySelector('.modal-dialog'), content = modal.querySelector('.modal-content');
    const movable = !!modal.querySelector('.tx-resize');
    const fit = () => {
        Object.assign(dlg.style, { left: '8px', top: '8px', width: `${window.innerWidth - 16}px` });
        content.style.height = `${window.innerHeight - 16}px`;
    };
    const restore = () => {
        dlg.classList.remove('is-max');
        if (movable) { head.dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); return; }
        dlg.classList.remove('is-free', 'is-sized');
        ['left', 'top', 'width'].forEach(k => dlg.style.removeProperty(k));
        content.style.removeProperty('height');
    };
    box.addEventListener('click', (e) => {
        if (e.target.closest('[data-modal-max]')) { dlg.classList.add('is-free', 'is-sized', 'is-max'); fit(); }
        if (e.target.closest('[data-modal-restore]')) restore();
    });
    window.addEventListener('resize', () => { if (dlg.classList.contains('is-max')) fit(); });
    modal.addEventListener('hidden.bs.modal', () => { if (dlg.classList.contains('is-max')) restore(); });
}
['tx-modal', 'trade-chart-modal', 'spike-verify-modal', 'cond-explain-modal'].forEach(id => addModalFullscreen(document.getElementById(id)));


// ── 모든 표 위에 행 수: '총 N개' (거래 기록은 '건', 나눠 불러오는 표는 '총 N건 · M건 표시') ──
// 안내 문구 줄(칸 합침) · '더 보기' 줄 · 구분 줄은 세지 않음. 표 내용이 바뀌면 저절로 다시 셈
(function tableRowCounts() {
    let raf = 0;
    const isRow = (tr) => !tr.querySelector('td[colspan]') && !tr.classList.contains('tx-more') && !tr.classList.contains('table-secondary');
    const update = () => {
        raf = 0;
        document.querySelectorAll('table').forEach(tb => {
            const body = tb.tBodies[0];
            if (!body || !tb.tHead) return;
            const n = [...body.rows].filter(isRow).length;
            const unit = /시간|체결/.test(tb.tHead.textContent) ? '건' : '개';
            const total = Number(tb.dataset.total || 0);
            const text = total > n ? `총 <b>${total.toLocaleString()}</b>${unit} · ${n.toLocaleString()}${unit} 표시` : `총 <b>${n.toLocaleString()}</b>${unit}`;
            let cap = tb.querySelector(':scope > caption.tbl-count');
            if (!cap) {
                if (tb.caption) return;                                   // 다른 설명 caption 이 있으면 건드리지 않음
                cap = document.createElement('caption');
                cap.className = 'tbl-count';
                tb.prepend(cap);
            }
            if (cap.innerHTML !== text) cap.innerHTML = text;
        });
    };
    const queue = () => { if (!raf) raf = requestAnimationFrame(update); };
    new MutationObserver((ms) => {
        // 행 수 표시 자체가 바뀐 것은 무시 (무한 반복 방지)
        if (ms.every(m => (m.target.nodeType === 1 ? m.target : m.target.parentElement)?.closest?.('caption.tbl-count'))) return;
        queue();
    }).observe(document.body, { childList: true, subtree: true });
    queue();
})();

// ── 전체코인 · 보유코인 분석의 왼쪽 조건 목록 접기 · 펼치기 (두 화면 같이, 이 PC에 기억) ──
(() => {
    const aside = document.getElementById('screen-aside');
    if (!aside) return;
    const fold = document.getElementById('aside-fold');
    const set = (on, save = true) => {
        aside.classList.toggle('is-collapsed', on);
        fold?.setAttribute('aria-expanded', String(!on));
        if (save) { try { localStorage.setItem('screenAsideCollapsed', on ? '1' : '0'); } catch (e) { /* 무시 */ } }
        setTimeout(() => window.dispatchEvent(new Event('resize')), 220);     // 표 · 그래프 폭 다시 맞춤
    };
    let start = false;
    try { start = localStorage.getItem('screenAsideCollapsed') === '1'; } catch (e) { /* 무시 */ }
    set(start, false);
    fold?.addEventListener('click', () => set(true));
    document.getElementById('aside-folded-bar')?.addEventListener('click', () => set(false));
})();

// ── 브라우저 '뒤로 · 앞으로' = 봇 안에서 바로 전 화면으로 (2026-10-08) ──
// 화면이 바뀔 때마다(위 메뉴 · 안쪽 탭 · 봇 고르기 · 보드 · 단계) 지금 모습을 기록에 쌓고, 뒤로 가면 그 모습으로 되돌림.
// 처음 열고 사용자가 아무것도 누르기 전에는 쌓지 않고 덮어씀 (불러오며 저절로 바뀐 것까지 '뒤로'에 남지 않게)
(() => {
    let last = null, restoring = false, timer = null, acted = false;
    const mainTabs = () => document.getElementById('main-tabs');
    const snap = () => {
        const main = mainTabs()?.querySelector('.nav-link.active')?.id || '';
        const subs = [...document.querySelectorAll('.nav-link.active[data-bs-toggle="tab"][id]')].map(b => b.id).filter(id => !mainTabs()?.contains(document.getElementById(id)));
        const board = !document.getElementById('bots-board')?.classList.contains('d-none');
        const b = builderOpen();
        return { main, subs, board, bot: currentBotId || '', builder: b, step: b ? builder.step : 0, bd: bdTab };
    };
    const record = () => {
        if (restoring) return;
        clearTimeout(timer);
        timer = setTimeout(() => {                                  // 한 번 누름에 여러 번 바뀌어도(봇 고르기 + 단계) 기록은 하나
            if (restoring) return;
            const s = snap(), k = JSON.stringify(s);
            if (k === last) return;
            const i = Number(history.state?.i) || 0;                // 몇 번째 봇 화면인지 (0 = 처음 연 화면)
            if (last === null || !acted) history.replaceState({ strabot: s, i }, '');
            else history.pushState({ strabot: s, i: i + 1 }, '');
            last = k;
        }, 60);
    };
    const showTab = (id) => {
        const btn = id && document.getElementById(id);
        if (btn && !btn.classList.contains('active')) bootstrap.Tab.getOrCreateInstance(btn).show();
    };
    const apply = (s) => {
        showTab(s.main);
        if (s.main === 'bots-tab') {
            if (s.board) openBoard();
            else if (s.builder && s.bot) openBuilder(s.bot, { step: s.step || 2 });
            else {
                if (s.bot && s.bot !== currentBotId) selectBot(s.bot);
                closeBoard();
                builderToOverview();
                showBdTab(s.bd || 'perf');
            }
        }
        (s.subs || []).forEach(showTab);
    };
    window.addEventListener('popstate', (e) => {
        const s = e.state?.strabot;
        if (!s) return;
        document.querySelectorAll('.modal.show').forEach(m => bootstrap.Modal.getInstance(m)?.hide());   // 열린 창은 닫고
        restoring = true;
        try { apply(s); } catch (err) { console.warn('뒤로 가기 되돌리기 실패', err); }
        setTimeout(() => { restoring = false; last = JSON.stringify(snap()); }, 400);   // 탭 바뀜(사라지는 효과)이 끝난 뒤
    });
    ['pointerdown', 'keydown'].forEach(ev => document.addEventListener(ev, () => { acted = true; }, { capture: true, once: true }));
    // 키보드 백스페이스 = 뒤로 (글 쓰는 칸에서는 글자 지우기 그대로). 처음 연 화면에서는 아무것도 안 함 (사이트를 나가지 않게)
    document.addEventListener('keydown', (e) => {
        if (e.key !== 'Backspace' || e.altKey || e.ctrlKey || e.metaKey || e.shiftKey || e.defaultPrevented) return;
        const t = e.target;
        if (t?.closest?.('input, textarea, select, [contenteditable]:not([contenteditable="false"])')) return;
        e.preventDefault();
        const open = document.querySelector('.modal.show');
        if (open) { bootstrap.Modal.getInstance(open)?.hide(); return; }   // 떠 있는 창이 있으면 그것부터 닫기
        if ((Number(history.state?.i) || 0) > 0) history.back();
    });
    document.addEventListener('shown.bs.tab', record);
    // 화면을 바꾸는 함수들 뒤에 기록 걸기
    const hook = (name) => {
        const f = window[name];
        if (typeof f !== 'function') return;
        window[name] = function (...args) { const r = f.apply(this, args); record(); return r; };
    };
    ['selectBot', 'setBoardOpen', 'setBuilderStep', 'showBdTab', 'builderToOverview'].forEach(hook);
    record();
})();


// ── 말풍선 설명 (2026-10-09): 브라우저 기본 설명(작고 흐린 글씨) 대신 또렷한 말풍선 — 단추 · 링크 · 누를 수 있는 것에만 ──
(() => {
    const tip = document.createElement('div');
    tip.className = 'ui-tip';
    tip.setAttribute('role', 'tooltip');
    document.body.appendChild(tip);
    let cur = null, timer = null;
    const SEL = 'button[title], a[title], [role="button"][title], .btn[title], [data-tip]';
    const hide = () => { clearTimeout(timer); tip.classList.remove('show'); cur = null; };
    const place = (el) => {
        const r = el.getBoundingClientRect(), t = tip.getBoundingClientRect();
        let top = r.bottom + 8, below = true;
        if (top + t.height > window.innerHeight - 6) { top = r.top - t.height - 8; below = false; }
        const left = Math.max(6, Math.min(window.innerWidth - t.width - 6, r.left + r.width / 2 - t.width / 2));
        tip.style.top = `${top}px`;
        tip.style.left = `${left}px`;
        tip.classList.toggle('is-above', !below);
        tip.style.setProperty('--ax', `${Math.max(10, Math.min(t.width - 10, r.left + r.width / 2 - left))}px`);
    };
    document.addEventListener('mouseover', (e) => {
        const el = e.target.closest?.(SEL);
        if (!el || el === cur) return;
        if (el.hasAttribute('title')) {                         // 브라우저 기본 설명이 같이 뜨지 않게 옮겨 둠 (코드가 다시 정하면 그때 또 옮김)
            const t = el.getAttribute('title');
            el.removeAttribute('title');
            if (t) el.dataset.tip = t;
        }
        const text = el.dataset.tip;
        if (!text) return;
        cur = el;
        clearTimeout(timer);
        timer = setTimeout(() => {
            if (cur !== el || !document.body.contains(el)) return;
            tip.textContent = text;
            tip.classList.add('show');
            place(el);
        }, 250);
    });
    document.addEventListener('mouseout', (e) => { if (cur && !cur.contains(e.relatedTarget)) hide(); });
    ['scroll', 'mousedown', 'keydown'].forEach(ev => window.addEventListener(ev, hide, true));
})();
document.addEventListener('click', (e) => { if (e.target.closest('[data-open-account]')) openAccountSettings(); });   // 맨 위 요금제 띠의 [로그인]


// ── 작은 코인 정리: 5,000원어치가 안 돼 팔 수 없는 코인 → 5,300원어치 더 사서 합친 뒤 전부 팖 ──
async function openDustSweep() {
    const openBtn = document.getElementById('btn-dust-open');
    if (openBtn?.disabled) return;
    const label = openBtn?.innerHTML;
    if (openBtn) { openBtn.disabled = true; openBtn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>작은 코인 찾는 중…'; }
    try { await openDustSweepInner(); }
    catch (e) { console.error('작은 코인 정리 창 오류', e); showNotification(`작은 코인 정리 창을 열지 못했습니다: ${e.message || e}`, 'error'); }
    finally { if (openBtn) { openBtn.disabled = false; openBtn.innerHTML = label; } }
}
async function openDustSweepInner() {
    document.getElementById('dust-modal')?.remove();
    document.querySelectorAll('.modal-backdrop').forEach(b => { if (!document.querySelector('.modal.show')) b.remove(); });   // 남은 어두운 막 정리
    let d, status = 0;
    try { const r = await fetch('/api/holdings/dust'); status = r.status; d = await r.json(); } catch (e) { d = null; }
    if (!d?.success) {
        showNotification(status === 404 ? '프로그램을 다시 켜야 쓸 수 있는 기능입니다 (화면을 새로고침해 주십시오)' : (d?.error || '작은 코인을 불러오지 못했습니다'), 'error');
        return;
    }
    const wrap = document.createElement('div');
    wrap.className = 'modal fade';
    wrap.id = 'dust-modal';
    wrap.tabIndex = -1;
    const live = d.mode !== 'sim';
    const rows = d.coins.map(c => `<tr><td><input type="checkbox" class="form-check-input" data-dust-coin="${escapeHtml(c.currency)}" checked></td>
        <td><b>${escapeHtml(c.name)}</b> <small class="text-muted">${escapeHtml(c.currency)}</small></td>
        <td class="text-end">${formatKrw(c.value)}</td><td class="text-end dust-st" data-dust-st="${escapeHtml(c.currency)}">—</td></tr>`).join('');
    wrap.innerHTML = `<div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable"><div class="modal-content">
        <div class="modal-header"><h5 class="modal-title"><i class="bi bi-stars me-2"></i>작은 코인 정리</h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="닫기"></button></div>
        <div class="modal-body">
            <p class="small mb-2">거래소는 5,000원 미만 주문을 받지 않아 그대로는 팔 수 없습니다. 고른 코인마다 <b>${formatKrw(d.topup)}어치를 더 사서 합친 뒤 가진 것을 전부 팝니다.</b>
                코인 하나씩 차례로 해서, 원화는 한 번에 ${formatKrw(Math.ceil(d.need_krw))}만 있으면 됩니다 (지금 주문가능 ${formatKrw(d.krw)}).
                수수료는 코인마다 약 ${formatKrw(d.fee_each)}입니다.</p>
            ${live ? `<div class="alert alert-warning py-2 small mb-2"><i class="bi bi-exclamation-triangle me-1"></i>${escapeHtml(EX_NAME)} 계좌의 실제 돈으로 주문합니다. 사고파는 사이 값이 움직이면 몇 원 차이가 날 수 있습니다.</div>` : ''}
            ${d.coins.length ? `<table class="table table-sm align-middle mb-0"><thead><tr><th><input type="checkbox" class="form-check-input" id="dust-all" checked></th><th>코인</th><th class="text-end">지금 값</th><th class="text-end">결과</th></tr></thead><tbody>${rows}</tbody></table>`
                : '<div class="text-muted small p-3">5,000원어치가 안 되는 코인이 없습니다.</div>'}
        </div>
        <div class="dust-prog d-none" id="dust-prog"><div class="dust-prog-bar"><i id="dust-prog-fill"></i></div><span id="dust-prog-text"></span></div>
        <div class="modal-footer"><span class="me-auto small" id="dust-progress"></span>
            <button type="button" class="btn btn-light" data-bs-dismiss="modal" id="dust-close">닫기</button>
            <button type="button" class="btn btn-primary" id="dust-run"${d.coins.length ? '' : ' disabled'}><i class="bi bi-stars me-1"></i>골라서 정리하기</button></div>
    </div></div>`;
    document.body.appendChild(wrap);
    wrap.addEventListener('hidden.bs.modal', () => { wrap.remove(); loadHoldings?.(); });
    wrap.addEventListener('change', (e) => {
        if (e.target.id === 'dust-all') wrap.querySelectorAll('[data-dust-coin]').forEach(c => { c.checked = e.target.checked; });
    });
    const prog = wrap.querySelector('#dust-progress');
    let armed = false;                                    // 실제 돈: 같은 창에서 한 번 더 눌러 확인 (창 위에 창은 뒤에 가려 안 보임)
    wrap.addEventListener('change', () => {
        if (!armed) return;
        armed = false;
        const b = wrap.querySelector('#dust-run');
        b.className = 'btn btn-primary'; b.innerHTML = '<i class="bi bi-stars me-1"></i>골라서 정리하기';
        prog.textContent = '';
    });
    wrap.querySelector('#dust-run')?.addEventListener('click', async (e) => {
        const coins = [...wrap.querySelectorAll('[data-dust-coin]:checked')].map(c => c.dataset.dustCoin);
        const btn = e.currentTarget;
        if (!coins.length) { prog.innerHTML = '<span class="text-danger">정리할 코인을 골라 주십시오</span>'; return; }
        if (live && !armed) {
            armed = true;
            btn.className = 'btn btn-danger';
            btn.innerHTML = `<i class="bi bi-check2-circle me-1"></i>네, ${coins.length}개 정리 시작`;
            prog.innerHTML = `<span class="text-danger fw-semibold"><i class="bi bi-exclamation-triangle me-1"></i>${escapeHtml(EX_NAME)} 실제 돈으로 ${coins.length}개 코인을 사고팝니다. 맞으면 한 번 더 눌러 주십시오.</span>`;
            return;
        }
        btn.disabled = true;
        btn.className = 'btn btn-primary';
        btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>정리하는 중…';
        prog.textContent = '시작하는 중…';
        wrap.querySelectorAll('[data-dust-coin]').forEach(c => {
            const cell = wrap.querySelector(`[data-dust-st="${CSS.escape(c.dataset.dustCoin)}"]`);
            if (cell && c.checked) { cell.textContent = '기다리는 중'; cell.className = 'text-end dust-st text-muted'; }
        });
        wrap.querySelector('#dust-prog')?.classList.remove('d-none');
        wrap.querySelectorAll('[data-dust-coin], #dust-all').forEach(c => { c.disabled = true; });
        const r = await (await fetch('/api/holdings/dust-sweep', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ coins }) })).json().catch(() => ({}));
        if (!r.success) {
            prog.innerHTML = `<span class="text-danger">${escapeHtml(r.error || '정리를 시작하지 못했습니다')}</span>`;
            btn.disabled = false; btn.innerHTML = '<i class="bi bi-stars me-1"></i>골라서 정리하기'; armed = false;
            return;
        }
        const fill = wrap.querySelector('#dust-prog-fill'), ptext = wrap.querySelector('#dust-prog-text');
        const tick = async () => {
            const s = await (await fetch('/api/holdings/dust-sweep')).json().catch(() => ({}));
            const job = s.job;
            if (!job) { setTimeout(tick, 800); return; }
            (job.items || []).forEach(it => {
                const cell = wrap.querySelector(`[data-dust-st="${CSS.escape(it.currency)}"]`);
                if (!cell) return;
                const now = job.current && job.current.currency === it.currency;
                cell.innerHTML = now ? `<span class="spinner-border spinner-border-sm me-1"></span>${escapeHtml(job.current.step)}…` : (it.ok ? '✓ 정리됨' : escapeHtml(it.message || ''));
                cell.className = `text-end dust-st ${now ? 'text-primary' : it.ok ? 'text-success' : 'text-danger'}`;
                cell.title = it.message || '';
                if (now) cell.closest('tr')?.scrollIntoView({ block: 'nearest' });
            });
            const pct = job.total ? Math.round(job.done / job.total * 100) : 0;
            if (fill) fill.style.width = `${pct}%`;
            const okN = (job.items || []).filter(i => i.ok).length, badN = (job.items || []).filter(i => !i.ok && i.message).length;
            if (ptext) ptext.textContent = `${job.done} / ${job.total}개 처리 · 정리 ${okN}개${badN ? ` · 못 함 ${badN}개` : ''}`;
            prog.textContent = job.finished ? '끝났습니다' : (job.current ? `${job.current.currency} ${job.current.step}…` : '진행 중…');
            if (!job.finished) { setTimeout(tick, 600); return; }
            btn.innerHTML = '<i class="bi bi-check2 me-1"></i>끝났습니다';
            showNotification(`작은 코인 정리: ${okN}개 정리했습니다${badN ? ` (못 한 코인 ${badN}개는 결과 칸에 이유)` : ''}`, okN ? 'success' : 'warning');
        };
        tick();
    });
    new bootstrap.Modal(wrap).show();
}
